struct EdgeMF
{
	int to;
	ll capacity;
	int reverse;
};

void addEdgeForFlow(vector<vector<EdgeMF>>& G, int from, int to, ll capacity, ll reverseCapacity)
{
	G[from].push_back({ to, capacity, (int)G[to].size() });
	G[to].push_back({ from, reverseCapacity, (int)G[from].size() - 1 });
}

void bfsForFlowD(vector<vector<EdgeMF>>& G, vector<int>& distance, int s)
{
	queue<int> q;
	distance[s] = 0;
	q.push(s);
	while (!q.empty())
	{
		auto v = q.front();
		q.pop();
		for (auto& e : G[v])
		{
			if (e.capacity > 0 && distance[e.to] < 0)
			{
				distance[e.to] = distance[v] + 1;
				q.push(e.to);
			}
		}
	}
}

ll dfsForFlowD(vector<vector<EdgeMF>>& G, vector<int>& distance, vector<int>& researched, int u, int t, ll f)
{
	if (u == t)
	{
		return f;
	}

	for (auto& i = researched[u]; i < (int)G[u].size(); ++i)
	{
		auto& e = G[u][i];
		if (e.capacity <= 0 || distance[u] >= distance[e.to])
		{
			continue;
		}

		auto d = dfsForFlowD(G, distance, researched, e.to, t, min(f, e.capacity));
		if (d > 0)
		{
			e.capacity -= d;
			G[e.to][e.reverse].capacity += d;
			return d;
		}
	}

	return 0;
}

ll calcMaxFlowD(vector<vector<EdgeMF>>& G, int s, int t)
{
	auto f = 0ll;
	while (true)
	{
		vector<int> distance((int)G.size(), -1);
		bfsForFlowD(G, distance, s);
		if (distance[t] < 0)
		{
			break;
		}
		vector<int> researched((int)G.size());
		while (true)
		{
			auto d = dfsForFlowD(G, distance, researched, s, t, LLONG_MAX);
			if (d <= 0)
			{
				break;
			}
			f += d;
		}
	}

	return f;
}

