class FordFulkerson {
public:
    struct edge {int to, cap, rev;};
    vector<vector<edge>> G;
    vector<bool> used;
    FordFulkerson(int n) {
        G = vector<vector<edge>>(n);
        used = vector<bool>(n);
    }

    void add(int from, int to, int cap) {
        G[from].push_back({to,cap,(int)G[to].size()});
        G[to].push_back({from,0,(int)G[from].size()-1});
    }

    int dfs(int v, int t, int f) {
        if (v == t) return f;
        used[v] = true;
        for (int i = 0;i < G[v].size(); i++) {
            edge &e = G[v][i];
            //到達先が未使用かつ辺容量が残っている
            if (!used[e.to] && e.cap) {
                int d = dfs(e.to, t, min(f,e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(int s, int t) {
        int flow = 0;
        for (;;) {
            fill(used.begin(),used.end(),false);
            int f = dfs(s,t,INF);
            if (f == 0) return flow;
            flow += f;
        }
    }
};

void solve() {
    int h, w; cin >> h >> w;
    FordFulkerson ff(h+w);
    int st, en;
    rep (i, h) {
        string s; cin >> s;
        rep (j, w) {
            if (s[j] == 'S') {
                st = i;
                ff.add(h+j, i, INF);
            } else if (s[j] == 'T') {
                en = i;
                ff.add(h+j, i, INF);
            } else if (s[j] == 'o') {
                ff.add(i, h+j, 1);
                ff.add(h+j, i, 1);
            }
        }
    }
    int ans = ff.max_flow(st, en);
    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
}

