inline int min(int x,int y)
{
	return x<y?x:y;
}
inline void ins(int x,int y,int z)
{
	next[++tot]=first[x];
	first[x]=tot;
	en[tot]=y;
	w[tot]=z;
}
inline void insert(int x,int y,int z)
{
	ins(x,y,z),ins(y,x,0);
}
int sap(int x,int y)
{
	if(x==t) return y;
	int use=0;
	for(int i=cur[x];i;i=next[i])
		if(w[i] && dis[x]==dis[en[i]]+1)
		{
			cur[x]=i;
			int p=min(w[i],sap(en[i],y-use));
			w[i]-=p,w[i^1]+=p,use+=p;
			if(use==y || dis[s]>sum) return use;
		}
	cur[x]=first[x];
	if(!--gap[dis[x]]) dis[s]=sum+1;
	gap[++dis[x]]++;
	return use;
}
