      int pos = i*w+j;
      add_edge(i*w+j+w*h,pos,1);
      if(mp[i][j] == '.')continue;
      cnt++;
      if(mp[i][j] == 'S') s = pos;
      if(mp[i][j] == 'T') { t = pos+w*h;continue;}

      for(int k=0;k<h;k++)
	if(k!=i&&mp[k][j]!='.')add_edge(pos,(k*w+j)+w*h,100000);

      for(int k=0;k<w;k++)
	if(k!=j&&mp[i][k]!='.')add_edge(pos,(i*w+k)+w*h,100000);
    }

  int ans = max_flow(s,t);
  if(ans>=cnt-1)cout<<-1<<endl;
  else cout<<ans<<endl;
  return 0;
}

