template<typename T>
struct FordFulkerson {
    struct Edge {
        int to, rev;
        T cap;
        Edge () {}
        Edge (int to, int rev, T cap) : to(to), rev(rev), cap(cap) {}
    };

    vector<vector<Edge>> G;
    vector<int> used;
    const T INF;
    int timestamp;

    FordFulkerson(int size) : INF(numeric_limits<T>::max()), timestamp(0) {
        G.resize(size);
        used.assign(size, -1);
    }

    void add_edge(int from, int to, T cap) {
        G[from].emplace_back(to, (int)G[to].size(), cap);
        G[to].emplace_back(from, (int)G[from].size() - 1, 0);
    }

    T dfs(int v, int t, T flow) {
        if (v == t) return (flow);
        used[v] = timestamp;
        for (auto &e : G[v]) {
            if (used[e.to] < timestamp && e.cap > 0) {
                T d = dfs(e.to, t, min(flow, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return (d);
                }
            }
        }
        return (0);
    }

    T max_flow(int s, int t) {
        T flow = 0;
        for (T f; (f = dfs(s, t, INF)) > 0; timestamp++) {
            flow += f;  
        }
        return (flow);
    }
};

int main() {
    int H, W;
    cin >> H >> W;
    vector<string> A(H); cin >> A;
    FordFulkerson<int> g(H * W * 2);
    int start, goal;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int pos = (i * W + j) * 2;
            if (A[i][j] == 'S') start = pos + 1;
            if (A[i][j] == 'T') goal = pos;
            g.add_edge(pos, pos + 1, 1);
            if (A[i][j] == '.') continue;
            for (int k = 0; k < 2; k++) {
                for (int l = 1; l <= max(H, W); l++) {
                    int ny = i + l * dy[k], nx = j + l * dx[k];
                    if (ny >= H || nx >= W) break;
                    if (A[ny][nx] == '.') continue;
                    int npos = (ny * W + nx) * 2;
                    g.add_edge(pos + 1, npos, 1);
                    g.add_edge(npos + 1, pos, 1);
                    if (pos + 1 == start && A[ny][nx] == 'T' ||
                        pos + 1 == goal && A[ny][nx] == 'S') {
                        cout << -1 << endl;
                        return (0);
                    }
                }
            }
        }
    }
    cout << g.max_flow(start, goal) << endl;
    return (0);
}

#include "bits/stdc++.h"
using namespace std;

struct edge { int to, cap, rev; };

vector<edge> G[210];
int level[210];
int iter[210];
int INF = 1000000;

void add_edge(int from, int to, int cap) {
	G[from].push_back({ to, cap, (int)G[to].size() });
	G[to].push_back({ from, cap, (int)G[from].size() - 1 });
}

void add_multi_edge(int v1, int v2, int cap) {
	G[v1].push_back({ v2, cap, (int)G[v2].size() });
	G[v2].push_back({ v1, cap, (int)G[v1].size() - 1 });
}

void BFS(int S) {
	memset(level, -1, sizeof(level));
	queue<int> Q;
	level[S] = 0;
	Q.push(S);
	while (!Q.empty()) {
		int V = Q.front(); Q.pop();
		for (edge E : G[V]) {
			if (E.cap > 0 && level[E.to] < 0) {
				level[E.to] = level[V] + 1;
				Q.push(E.to);
			}
		}
	}
}

int DFS(int V, int T, int F) {
	if (V == T) return F;
	for (int& i = iter[V]; i < G[V].size(); i++) {
		edge& E = G[V][i];
		if (E.cap > 0 && level[V] < level[E.to]) {
			int D = DFS(E.to, T, min(F, E.cap));
			if (D > 0) {
				E.cap -= D;
				G[E.to][E.rev].cap += D;
				return D;
			}
		}
	}
	return 0;
}

int max_flow(int S, int T) {
	int flow = 0;
	while (1) {
		BFS(S);
		if (level[T] < 0) return flow;
		memset(iter, 0, sizeof(iter));
		int F;
		while ((F = DFS(S, T, INF)) > 0) {
			flow += F;
		}
	}
}

