    for (int j = 0; j < w; j++) {
      if (field[i][j] == 'S') start = idx(i, j, OUT);
      if (field[i][j] == 'T') target = idx(i, j, IN);
    }
  }

  if ((line(start) == line(target)) || (col(start) == col(target))) {
    cout << "-1" << endl;
    return 0;
  } 

  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      addEdge(idx(i, j, IN), idx(i, j, OUT), 1);
      if (field[i][j] != '.') {
        for (int k = 0; k < h; k++) {
          if (k == i) continue;
          if (field[k][j] != '.') addEdge(idx(i, j, OUT), idx(k, j, IN), 1);
