bool dinic_bfs(int n)            //利用bfs分层 
{
	queue<int> qt;
    memset(l,0,sizeof(l));
    qt.push(0);
    l[0]=1;
    int u,v;
    while (!qt.empty()) 
	{
        u=qt.front();
        qt.pop();
        for(v=1;v<=n;v++) 
		{
            if (!l[v]&&cap[u][v]>flow[u][v])     //对可以流通的边进行层次划分 
			{
                l[v]=l[u]+1;
                qt.push(v);
            }
        }
    }
    return l[n]!= 0;         //判断汇点是否在层次图中 
} 
int dinic_dfs(int u,int acap,int n)         //利用dfs进行增广 
{
    int tmp=acap;      //表示该节点可往下增加的流量 
    int v,t;
    if (u==n)
        return acap;
    for (v=1;v<=n&&tmp;v++) 
	{
        if (l[u]+1==l[v]) 
		{
            if (cap[u][v]>flow[u][v]) 
			{
                t=dinic_dfs(v,min(tmp,cap[u][v]-flow[u][v]),n);
                flow[u][v]+=t;         //修改流量 
                flow[v][u]-=t;          //修改反向边流量 
                tmp-=t;
            }
        }
    }
    return acap-tmp;
}
