//Ford-Fulkerson 法による最大流
//verified GRL_6_A
//http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3029333#1

class MaximumFlow {
  struct Edge {
    int to;
    long long capacity;
    int id;
    Edge(int to, long long cap, int id)
        : to(to), capacity(cap), id(id){};
    Edge() { Edge(0, 0, -1); }
  };
  using Graph = vector<vector<Edge>>;
  using Flow = vector<unordered_map<int, long long>>;
  //typedef vector<vector<LL>> Flow;
  int n;
  Graph graph;
  Flow flow;
  vector<char> used;

 public:
  MaximumFlow(int n) : n(n), graph(n), flow(n), used(n) {}
  //MaximumFlow(int n) : n(n), graph(n), flow(n, vector<long long>(n)) {}
  void addEdge(int a, int b, long long cap) {
    graph[a].emplace_back(b, cap, graph[b].size());
    graph[b].emplace_back(a, 0, graph[a].size() - 1);
  }
  long long maximumFlow(int s, int t) {
    long long f = 0;
    while (1) {
      fill(used.begin(), used.end(), 0);
      auto res = dfs(s, t, LINF);
      if (res == 0) return f;
      f += res;
    }
  }

 private:
  long long dfs(int now, int t, long long ff) {
    DBG(now, t, ff)
    if (now == t) return ff;
    if (used[now]) return 0;
    used[now] = 1;
    for (int i = 0; i < graph[now].size(); i++) {
      auto &e = graph[now][i];
      if (e.capacity > 0) {
        long long res = dfs(e.to, t, min(ff, e.capacity));
        DBG(now, e.to, e.capacity, res)
        if (res > 0) {
          e.capacity -= res;
          graph[e.to][e.id].capacity += res;
          return res;
        }
      }
    }
    return 0;
  }
};

