  MaximumFlow mf;
  Solver(int h, int w) : h(h), w(w), mf(0){};

  void solve() {
    mf = MaximumFlow(h + w + 2);
    //vertex 0-h-1 : row
    //vertex h-h+w-1: column
    //vertex h+w :  S
    //vertex h+w+1: T
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        char tmp;
        cin >> tmp;
        if (tmp == 'o') {
          mf.addEdge(i, h + j, 1);
          mf.addEdge(h + j, i, 1);
        } else if (tmp == 'S') {
          mf.addEdge(h + w, i, LINF);
          mf.addEdge(h + w, h + j, LINF);
        } else if (tmp == 'T') {
          mf.addEdge(i, h + w + 1, LINF);
          mf.addEdge(h + j, h + w + 1, LINF);
        }
      }
    }
    auto ans = mf.maximumFlow(h + w, h + w + 1);
    cout << (ans > LINF / 2 ? -1 : ans) << endl;
  }
};

