					que.push( to );
				}
				used[ to ] = true;
			}
			Gra.add_edge(now,to,HA_cap);
		}
		for(int i=0;i<H;++i){//(i,w)
			if( fld[i][w] == false ) continue;
			int to = i*W+w;
			if( now == to ) continue;
			if( to != goal ){
