struct edge { LL to, cap, rev; };
struct Maxflow {
	//vec[e.to][e.rev]で逆辺
	vector<vector<edge>>vec;
	Maxflow(LL n):vec(n+1){}
	void addedge(LL from, LL to, LL cap) {
		vec[from].push_back(edge{ to, cap, (LL)vec[to].size() });
		vec[to].push_back(edge{ from, 0, (LL)vec[from].size() - 1 });
	}
	LL dfs(vector<bool> &used, LL v, LL t, LL f) {
		if (v == t)return f;
		used[v] = true;
		rep(i, vec[v].size()) {
			edge& e = vec[v][i];
		if (!used[e.to] && e.cap > 0) {
				LL d = dfs(used, e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					vec[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
	LL ford(LL s, LL t) {
		LL flow = 0;
		for (;;) {
			vector<bool> used(10000, false);
			LL f = dfs(used, s, t, INF);
			if (f == 0)return flow;
			flow += f;
		}
	}
};
