            }else if(S[j] == 'T'){
                d.add_edge(i, t, 1 << 30);
                d.add_edge(h + j, t, 1 << 30);
            }
            d.add_edge(i, h + j, 1);
            d.add_edge(h + j, i, 1);
        }
    }
    ll ans = d.solve(s, t);
    if(ans >= 1 << 30){
        cout << -1 << endl;
    }else{
        cout << ans << endl;
    }
}

