int dfs(int v,int t,int f)
{
  if(v == t) return f; //ゴールについたらfを流す
  used[v] = true; //訪れた場所をtrue

  for(int i=0;i<g[v].size();i++){
    Edge &e = g[v][i];
    if( !used[ e.to ] && e.cap > 0){
      int d = dfs( e.to , t , min(f,e.cap) ); //今までの経路の最小容量
      if(d > 0){
	e.cap -= d; //容量をdだけ引く
	g[ e.to ][ e.rev ].cap += d; //逆流をdだけたす
	return d;
      }
    }
  }

  return 0;
}

int maxFlow(int s,int t)
{
  int flow=0;
  while(1){
    memset(used,0,sizeof(used));
    int f = dfs(s,t,INF);
    if(f == 0) return flow;
    flow += f;
  }
}

void push_one(int node1,int node2,int c){
  g[node1].push_back((Edge){node2,c,g[node2].size()}); //bのベクターの中の番号を逆辺に格納
  g[node2].push_back((Edge){node1,0,g[node1].size()-1});
  return;
}

