void add_edge(int from,int to,int cap){
	// from から to へ容量 cap のエッジを追加
	es[from].push_back(EDGE{to,cap,(int)es[to].size()});
	es[to].push_back(EDGE{from,0,(int)es[from].size()-1});
}

int dfs(int i,int t,int f){
	// ノードiからノードtに流量fを入力したときに実際にtに届く流量を返す
	if(i==t) return f;
	used[i] = true;
	rep(j,es[i].size()){
		EDGE &e = es[i][j];
		if(!used[e.to] && e.cap>0){
			int d = dfs(e.to,t,min(f,e.cap));
			if(d>0){
				e.cap -= d;
				es[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

int max_flow(int s,int t){
	// s から t までの最大流量を求める
	int flow = 0;
	while(true){
		memset(used,0,sizeof(used));
		int d = dfs(s,t,INF);
		if(d==0)return flow;
		flow += d;
	}
