                g[i].emplace_back(h + j, 1, g[h + j].size());
                g[h + j].emplace_back(i, 1, g[i].size() - 1);
            } else if (c == 'S') {
                add_edge(h + w, i, inf);
                add_edge(h + w, h + j, inf);
            } else {
                add_edge(i, h + w + 1, inf);
                add_edge(h + j, h + w + 1, inf);
            }
        }
    }

    auto ret = max_flow(h + w, h + w + 1);
    if (ret == inf) ret = -1;
