template<typename A, size_t N, typename T>
void Fill(A (&array)[N], const T &val){
    fill( (T*)array, (T*)(array+N), val );
}

struct Edge {
    int to;  // 辺の行き先
    ll cap; // 辺の容量 
    int rev; // G[e.to][e,rev]は逆辺の構造体にアクセスする
};

vector<Edge> G[MAX];
bool used[MAX];

void add_edge(int from, int to, ll cap) { // from-to間の流量をcapで設定、お互いにアクセス可能にする
    Edge e1, e2;
    e1.to = to; e1.cap = cap; e1.rev = (int)(G[to].size()); 
    e2.to = from; e2.cap = cap; e2.rev = (int)(G[from].size()); // 有向グラフにする時はe2.cap=0にする
    G[from].push_back(e1);
    G[to].push_back(e2);
}

ll dfs(int s, int t, ll f) { // sからtへ行くルートの最大流量、これ以上ルートがないとき0
    if (s == t) return f;

    used[s] = true;
    REP (i, G[s].size()) {
        Edge& e = G[s][i];
        if (!used[e.to] && e.cap > 0) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }

    return 0;
}

ll ford_fulkerson(int s, int t) { // sからtへの最大流量を返す
    ll flow = 0;
    while (1) {
        Fill(used, false);
        int f = dfs(s, t, INF);
        if (f == 0) return flow;
        flow += f;
    }
}

int H, W;
string A[MAX];

inline int x_of(int x) { return x; }
inline int y_of(int y) { return y + W; }

ll solve() {
    int s = H+W+1, t = H+W+2;

    int x = -1, y = -1;
    REP (h, H) REP (w, W) {
        if (A[h][w] == 'S') {
            add_edge(s, x_of(w), INF);
            add_edge(s, y_of(h), INF);
        } else if (A[h][w] == 'T') {
            add_edge(x_of(w), t, INF);
            add_edge(y_of(h), t, INF);
        } else if  (A[h][w] != '.') {
            add_edge(x_of(w), y_of(h), 1);
        }
    }

    ll ans = ford_fulkerson(s, t);
    if (ans >= INF) return -1;
    return ans;
}

int main() {
    cin >> H >> W;
    REP (i, H) cin >> A[i];
    cout << solve() << endl;
}

