			if (s[i][j] == 'o')	flow.add_edge(i, H + j, 1),flow.add_edge(j+H,i,1);
			else if (s[i][j] == 'S')flow.add_edge(S, i, INF), flow.add_edge(S, H + j, INF);
			else if (s[i][j] == 'T')flow.add_edge(i, T, INF), flow.add_edge(H+j, T, INF);
		}
	}
	ans = flow.max_flow(S,T);
	if (ans >= INF)ans = -1;
