struct Edge {
   Edge(long s_, long t_, long cap_, long rev_)
      : s(s_), t(t_), cap(cap_), rev(rev_) {}
   long s, t, cap, rev;
};
std::vector<Edge> graph[40000];
void addEdge(long s, long t, long cap) {
   long x = graph[s].size();
   long y = graph[t].size();
   graph[s].push_back(Edge(s, t, cap, y));
   graph[t].push_back(Edge(t, s, 0, x));
}
bool used[40000];
void init() {
   for(long i = 0; i < 40000; ++i) {
      used[i] = false;
   }
}
long dfs(long s, long t, long f) {
   if( s == t ) return f;
   used[s] = true;
   for(Edge& e : graph[s]) {
      if( used[e.t] ) continue;
      if( e.cap == 0 ) continue;
      long x = dfs(e.t, t, std::min(f, e.cap));
      if( x == 0 ) continue;
      e.cap -= x;
      graph[e.t][e.rev].cap += x;
      return x;
   }
   return 0;
}
long maxFlow(long s, long t) {
   long res = 0;
   loop {
      init();
      long f = dfs(s, t, (1LL << 60));
      res += f;
      if( f == 0 ) break;
   }
   return res;
}

