bool Clear(vector<bool>& used_x, vector<bool>& used_y, int n, int m) {
	for (int i = 0; i < n; ++i) {
		used_x[i] = false;
	}
	for (int j = 0; j < m; ++j) {
		used_y[j] = false;
	}
	return true;			
}

bool Go(vector<vector<int>>& a,
		vector<vector<int>>& b,
		vector<bool>& used_x,
		vector<bool>& used_y,
		int n, int m,
		int cur_dim, int cur,
		int t_x, int t_y) {
	if (cur_dim == 0) {
		if (cur == t_x) {
			return true;
		}

		used_x[cur] = true;
		for (int i = 0; i < m; ++i) {
			if (!used_y[i] && a[cur][i] > 0) {
				--a[cur][i];
				++b[i][cur];
				if (Go(a, b, used_x, used_y, n, m, 1, i, t_x, t_y)) {
					return true;
				}
				++a[cur][i];
				--b[i][cur];
			}
		}
	} else {
		if (cur == t_y) {
			return true;
		}

		used_y[cur] = true;
		for (int i = 0; i < n; ++i) {
			if (!used_x[i] && b[cur][i] > 0) {
				--b[cur][i];
				++a[i][cur];
				if (Go(a, b, used_x, used_y, n, m, 0, i, t_x, t_y)) {
					return true;
				}
				++b[cur][i];
				--a[i][cur];
			}
		}	
	}

	return false;
}

