const int N=105,V=222,INF=1e9;
int n,m,S,T,B0,BB[V],B[V][3];
void link(int u,int v,int r1,int r2)
{
	B[++B0][1]=v,B[B0][2]=r1,B[B0][0]=BB[u],BB[u]=B0;
	if(r2!=-1) link(v,u,r2,-1);
}
int ans,h[V],vh[V];
int aug(int v=S,int flow=INF)
{
	if(v==T) return flow;
	int use=0;
	efo(i,v,u)
		if(B[i][2] && h[v]==h[u]+1)
		{
			int f=aug(u,min(B[i][2],flow-use));
			B[i][2]-=f,B[i^1][2]+=f,use+=f;
			if(use==flow) return use;
		}
	if(!--vh[h[v]]) h[S]=n+m+3;
	++vh[++h[v]];
	return use;
}
int main()
{
	scanf("%d %d\n",&n,&m);
	S=0,T=n+m+1,B0=1;
