			if(ch=='S' || ch=='T' || ch=='o')
			{
				link(i,n+j,1,1);
				if(ch=='S') link(S,i,INF,0),link(S,n+j,INF,0);
				if(ch=='T') link(i,T,INF,0),link(n+j,T,INF,0);
			}
		}
		scanf("\n");
	}
	vh[0]=n+m+2;
	while(h[S]<=n+m+2) ans+=aug();
	printf("%d",ans>=INF?-1:ans);
	return 0;
}

