#include<bits/stdc++.h>
using namespace std;

const long long INF = (1ll << 30);

struct Dinic {
  typedef long long flow_type;
  struct edge {
    int src, dst;
    flow_type capacity, flow;
    size_t rev;
  };
  int n;
  vector<vector<edge>> adj;
  Dinic(int n) : n(n), adj(n) { }
  void add_edge(int src, int dst, flow_type capacity) {
    adj[src].push_back({src, dst, capacity, 0, adj[dst].size()});
    adj[dst].push_back({dst, src, 0, 0, adj[src].size()-1});
  }
  flow_type max_flow(int s, int t) {
    vector<int> level(n), iter(n);
    function<int(void)> levelize = [&]() { // foward levelize
      level.assign(n, -1); level[s] = 0;
      queue<int> Q; Q.push(s);
      while (!Q.empty()) {
        int u = Q.front(); Q.pop();
        if (u == t) break;
        for (auto &e: adj[u]) {
          if (e.capacity > e.flow && level[e.dst] < 0) {
            Q.push(e.dst);
            level[e.dst] = level[u] + 1;
          }
        }
      }
      return level[t];
    };
    function<flow_type(int, flow_type)> augment = [&](int u, flow_type cur) {
      if (u == t) return cur;
      for (int &i = iter[u]; i < adj[u].size(); ++i) {
        edge &e = adj[u][i], &r = adj[e.dst][e.rev];
        if (e.capacity > e.flow && level[u] < level[e.dst]) {
          flow_type f = augment(e.dst, min(cur, e.capacity - e.flow));
          if (f > 0) {
            e.flow += f;
            r.flow -= f;
            return f;
          }
        }
      }
      return flow_type(0);
    };
    for (int u = 0; u < n; ++u) // initialize
      for (auto &e: adj[u]) e.flow = 0;

    flow_type flow = 0;
    while (levelize() >= 0) {
      fill(iter.begin(), iter.end(), 0);
      for (flow_type f; (f = augment(s, INF)) > 0; )
        flow += f;
    }
    return flow;
  }
};


int main(){

    int h, w; cin >> h >> w;

    //0 := start, h + w + 1 := goal
    Dinic G(h + w + 2);

    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            char c; cin >> c;
            if(c == '.') continue;

            G.add_edge(i + 1, h + j + 1, 1LL);
            G.add_edge(h + j + 1, i + 1, 1LL);

            if(c == 'S'){
                G.add_edge(0, i + 1, INF);
                G.add_edge(0, h + j + 1, INF);
            }

            if(c == 'T'){
                G.add_edge(i, h + w + 1, INF);
                G.add_edge(h + j + 1, h + w + 1, INF);
            }
        }
    }

    if(G.max_flow(0, h + w + 1) >= INF) cout << -1 << endl;
    else cout << G.max_flow(0, h + w + 1) << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll H, W;
const ll INF = 1ll << 60;

ll N;
vector<vector<ll>> Cap;
// S, T, row 0, ..., row H-1, column 0, ..., column W-1
const ll Src = 0, Tgt = 1;
ll row(ll y) { return 2 + y; }
ll column(ll x) { return 2 + H + x; }
typedef pair<ll, ll> VCap;
ll R;

int main() {
  cin >> H >> W;
  N = 2 + H + W;
  Cap.resize(N);
  for (auto &cap : Cap) cap.resize(N);
  for (ll y = 0; y < H; ++y)
    for (ll x = 0; x < W; ++x) {
      char c;
      cin >> c;
      if (c == 'S')
        Cap[Src][row(y)] = Cap[Src][column(x)] = INF;
      else if (c == 'T')
        Cap[row(y)][Tgt] = Cap[column(x)][Tgt] = INF;
      else if (c == 'o')
        Cap[row(y)][column(x)] = Cap[column(x)][row(y)] = 1;
    }
  while (true) {
    ll flow = -1;
    vector<ll> parent;
    {
      queue<VCap> que;
      vector<bool> visited;
      visited.resize(N);
      parent.resize(N, -1);
      que.push(VCap(Src, INF));
      visited[Src] = true;
      while (!que.empty()) {
        ll v, cap;
        tie(v, cap) = que.front();
        que.pop();
        if (v == Tgt) {
          flow = cap;
          break;
        }
        for (ll w = 0; w < N; ++w) {
          if (!visited[w] && Cap[v][w] > 0) {
            que.push(VCap(w, min(cap, Cap[v][w])));
            parent[w] = v;
            visited[w] = true;
          }
        }
      }
    }
    if (flow < 0) break;
    R += flow;
    for (ll v = Tgt; v != Src; v = parent[v]) {
      ll u = parent[v];
      Cap[u][v] -= flow;
      Cap[v][u] += flow;
    }
  }
  cout << (R >= INF ? -1 : R) << endl;
  return 0;
}

