struct FordFulkerson {
  struct Edge{
    int from,to,capacity,flow;
    int calcRest(bool isRev) {
      return isRev ? flow : capacity-flow;
    }
    int getNext(bool isRev) {
      return isRev ? from : to;
    }
  };
  static const int MAX_E=40000;
  static const int MAX_V=300;
  static const int INF=1000000;
  bool visited[MAX_V];
  Edge edgeInstances[MAX_E];
  std::vector<Edge*> edges[MAX_V][2]; // 1 => reverse edge
  FordFulkerson() {E=0;}
  int E;

  void addEdge(Edge edge) {
    edgeInstances[E] = edge;
    edges[edge.from][0].push_back(&edgeInstances[E]);
    edges[edge.to][1].push_back(&edgeInstances[E]);
    E++;
  }

  int calcMaxFlow(int s, int t) {
    int max_flow=0;
    while(true) {
      std::memset(visited,0,sizeof(visited));
      int flow=findFlow(s,t,INF);
      max_flow += flow;
      if(flow==0) {
        break;
      }
    }
    return max_flow;
  }

  int findFlow(int current, int destination, int flow) {
    visited[current] = true;
    if(current == destination) return flow;

    for(int j=0;j<2;++j) {
      bool revEdge = j == 1;
      std::vector<Edge*>& edgeList=edges[current][j];
      for(int i=0;i<edgeList.size();++i) {
        Edge& edge = *edgeList[i];
        int rest = edge.calcRest(revEdge), next = edge.getNext(revEdge);
        if(visited[next]) continue;
        if(rest > 0){
          int max_flow = findFlow(next, destination, std::min(rest,flow));
          edge.flow += revEdge ? -max_flow: max_flow;
          if(max_flow>0) {
            return max_flow;
          }
        }
      }
    }
    return 0;
  }
};
int H,W;
char S[110];
FordFulkerson fordFulkerson;
int main() {
  scanf("%d%d", &H, &W);
  for(int i=0;i<H;++i){
    memset(S,0,sizeof(S));
    scanf("%s", S);
    for(int j=0;j<W;++j) {
      int idh=i+1,idw=j+101;
      if (S[j]=='o') {
        fordFulkerson.addEdge({idh,idw,1,0});
        fordFulkerson.addEdge({idw,idh,1,0});
      } else if(S[j]=='S') {
        fordFulkerson.addEdge({0,idw,FordFulkerson::INF,0});
        fordFulkerson.addEdge({0,idh,FordFulkerson::INF,0});
      } else if(S[j]=='T') {
        fordFulkerson.addEdge({idw,201,FordFulkerson::INF,0});
        fordFulkerson.addEdge({idh,201,FordFulkerson::INF,0});
      }
    }
  }
  int answer = fordFulkerson.calcMaxFlow(0,201);
  if (answer>=FordFulkerson::INF) {
    answer=-1;
  }
  printf("%d\n", answer);
  return 0;
}

