ll dfs(ll v, ll t, ll f) {
	if (v == t)return f;
	used[v] = 1;
	for (int i = 0; i < G[v].size(); i++) {
		edge e = G[v][i];
		if (used[e.to] == 0 && e.cap > 0) {
			ll d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				G[v][i].cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

void add_edge(ll from, ll to, ll cap) {
	edge fe = { to,cap,(int)G[to].size() };
	edge toe = { from,0,(int)G[from].size() };
	G[from].pb(fe);
	G[to].pb(toe);
}

ll max_flow(int s, int t) {
	ll flow = 0;
	while (1) {
		memset(used, 0, sizeof(used));
		ll f = dfs(s, t, inf);
		if (f == 0)return flow;
		flow += f;
	}
}

