        d.addEdge(S, j, INF);
        si = i, sj = j;
      } else if (a == 'T') {
        d.addEdge(i + N, T, INF);
        d.addEdge(j, T, INF);
        ti = i, tj = j;
      } else if (a == 'o') {
        d.addEdge(i + N, j, 1);
        d.addEdge(j, i + N, 1);
      }
    }
  }

  if (si == ti || sj == tj) {
    cout << -1 << endl;
    return 0;
  }

  cout << d.maxFlow(S, T) << endl;
  return 0;
}

