      }
      if(s[j]=='S'){
        graph.add_edge(h+w,i,INF);
        graph.add_edge(h+w,h+j,INF);
      }
      if(s[j]=='T'){
        graph.add_edge(i,h+w+1,INF);
        graph.add_edge(h+j,h+w+1,INF);
      }
    }
  }

  ll ans=graph.max_flow(h+w,h+w+1);

  if(ans>=INF)std::cout<<-1<<"\n";
  else std::cout<<ans<<"\n";

