    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (s[i][j] == 'o') {
                a[i][j] = id;
                id++;
            } else if (s[i][j] == 'S') {
                xx ^= i, yy ^= j;
                a[i][j] = id;
                st = id;
                id++;
            } else if (s[i][j] == 'T') {
                xx ^= i, yy ^= j;
                a[i][j] = id;
                fn = id;
                id++;
            }
        }
    }
    if (xx * yy == 0) {
        cout << -1 << endl;
        return 0;
    }
    mcmf<int, int> nt(id * 2, st + id, fn);
    for (int i = 0; i < id; i++) {
        nt.add(i, i + id, 1);
    }
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (a[i][j] == -1) continue;
            for (int k = i + 1; k < h; k++) {
                if (a[k][j] != -1) {
                    nt.add(a[i][j] + id, a[k][j], 1);
                    nt.add(a[k][j] + id, a[i][j], 1);
                }
            }
            for (int k = j + 1; k < w; k++) {
                if (a[i][k] != -1) {
                    nt.add(a[i][j] + id, a[i][k], 1);
                    nt.add(a[i][k] + id, a[i][j], 1);
                }
            }
        }
    }
    cout << nt.max_flow_min_cost().first << endl;
    return 0;
}

