// 0-based numbering; O(E*V^2);
template<class Numeric> struct Dinic {
    struct edge {
        int to; Numeric cap; int rev;
        edge(int t, Numeric c, int r){
            to = t; cap = c; rev = r;
        }
        void print() {
            cout << to << "\t" << cap << "\t" << rev << endl;
        }
    };
    vector< vector<edge> > g; vector<int> iter, level;
    int N; Numeric INF;
    Dinic(int n) {
        N = n; g.resize(N); iter.resize(N); level.resize(N);
        INF = numeric_limits<Numeric>::max();
    }
    void add(int from, int to, Numeric cap) {
        g[from].push_back(edge(to, cap, (int) g[to].size()));
        g[to].push_back(edge(from, 0, (int) g[from].size()-1));
    }
    void bfs(int s){
        level.assign(N,-1);
        queue<int> q;
        level[s] = 0; q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for(int i = 0; i < (int) g[v].size(); i++){
                edge &e = g[v][i];
                if (e.cap > 0 and level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }
    Numeric dfs(int v, int t, Numeric f) {
        if (v == t) return f;
        for (int i = iter[v]; i < (int) g[v].size(); i++) {
            edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]){
                Numeric d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    Numeric solve(int s, int t) {
        Numeric flow = 0;
        while(true){
            bfs(s);
            if (level[t] < 0) return flow;
            iter.assign(N, 0);
            Numeric f;
            while ((f = dfs(s, t, INF)) > 0){
                flow += min(f, INF-flow);
                if (flow == INF) return flow;
            }
        }
    }
};

int main() {
    int h, w; cin >> h >> w;
    queue<int> x, y;
    int n = h + w;
    Dinic<int> f(n+2);
    for (int i = 0; i < h; i++) {
        string s; cin >> s;
        for (int j = 0; j < w; j++) {
            if (s[j] == 'o') {
                f.add(i, h+j, 1);
                f.add(h+j, i, 1);
            }
            if (s[j] == 'S') {
                f.add(n, i, f.INF);
                f.add(n, h+j, f.INF);
            }
            if (s[j] == 'T') {
                f.add(i, n+1, f.INF);
                f.add(h+j, n+1, f.INF);
            }
        }
    }
    int ans = f.solve(n, n+1);
    if (ans == f.INF) cout << -1 << endl;
    else cout << ans << endl;
    return 0;
}

