      int d = dfs( e.to , t , min(f,e.cap) ); //今までの経路の最小容量
      if(d > 0){
	e.cap -= d; //容量をdだけ引く
	g[ e.to ][ e.rev ].cap += d; //逆流をdだけたす
	return d;
      }
    }
  }

  return 0;
}

int maxFlow(int s,int t)
{
  int flow=0;
  while(1){
    memset(used,0,sizeof(used));
    int f = dfs(s,t,INF);
    if(f == 0) return flow;
    flow += f;
  }
}

