#include <bits/stdc++.h>
using i64 = long long;

constexpr i64 inf = 1000000000000000;

struct Edge {
    int to;
    i64 cap;
    int rev;
    Edge(int t, i64 c, int r) : to(t), cap(c), rev(r) {}
};

std::vector<std::deque<Edge>> g;
std::vector<int> level, iter;

void add_edge(int from, int to, i64 cap) {
    g[from].emplace_back(to, cap, g[to].size());
    g[to].emplace_back(from, 0, g[from].size() - 1);
}

void bfs(int s) {
    for (auto &el : level) el = -1;
    level[s] = 0;

    std::deque<int> q { s };

    while (!q.empty()) {
        auto curr = q.front();
        q.pop_front();
        for (auto &e : g[curr]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[curr] + 1;
                q.push_back(e.to);
            }
        }
    }
}

i64 dfs(int v, int t, i64 f) {
    if (v == t) return f;

    for (int i = iter[v]; i < (int)g[v].size(); i++) {
        iter[v] = i;
        auto &e = g[v][i];

        if (e.cap > 0 && level[v] < level[e.to]) {
            i64 d = dfs(e.to, t, std::min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                g[e.to][e.rev].cap += d;
                return d;
            }
        }
    }

    return 0;
}

i64 max_flow(int s, int t) {
    i64 flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0) return flow;

        for (auto &el : iter) el = 0;

        i64 f = dfs(s, t, inf);
        while (f > 0) {
            flow += f;
            f = dfs(s, t, inf);
        }
    }
}

int main() {
    int h, w;
    std::cin >> h >> w;
    std::string in;
    g.resize(h + w + 2);
    level.resize(h + w + 2);
    iter.resize(h + w + 2);

    for (int i = 0; i < h; i++) {
        std::cin >> in;
        for (int j = 0; j < w; j++) {
            char c = in[j];
            if (c == 'o') {
                add_edge(i, h + j, 1);
                add_edge(h + j, i, 1);
            } else if (c == 'S') {
                add_edge(h + w, i, inf);
                add_edge(h + w, h + j, inf);
            } else if (c == 'T') {
                add_edge(i, h + w + 1, inf);
                add_edge(h + j, h + w + 1, inf);
            }
        }
    }

    auto ret = max_flow(h + w, h + w + 1);
    if (ret > h * w) ret = -1;
    std::cout << ret << std::endl;

    return 0;
}

