int DFS(int u, int val)
{
    if (u == T || val == 0)
        return val;
    int X = 0;
    for (;key[u]!=e[u].end();++key[u]) {
        int i = *key[u];
        int v = _u[i/2]  + _v[i/2] - u;
        if (d[v] == d[u] + 1) {
            int k = DFS(v,min(val,cf[i]));
            X += k;
            cf[i] -= k;
            cf[i^1] += k;
            val -= k;
        }
        if (val == 0)
            break;
    }
    return X;
}

