void solve(long long H, long long W, vector<string> S){
	st = clock();

	N = H * W;
	int sx,sy,gx,gy;
	for(int i = 0 ; i < H ; i++){
		for(int j = 0 ; j < W ; j++){
			if( S[i][j] == 'S' ){
				sx = j;
				sy = i;
			}
			if( S[i][j] == 'T' ){
				gx = j;
				gy = i;
			}
		}
	}


	Graph g(2*N+2);
	int s = g.size() - 1;
	int t = g.size() - 2;
	int cg = 0;
	int cs = 0;
	if( gx == sx || gy == sy ){
		cout << -1 << endl;
		return;
	}

	for(int j = 0 ; j < W ; j++)
		if( S[sy][j] == 'o' ){
			int idx1 = sy * W + j;
			addEdge(g,s,in(idx1),INF);
			cs++;
		}
	for(int j = 0 ; j < W ; j++)
		if( S[gy][j] == 'o' ){
			int idx1 = gy * W + j;
			addEdge(g,out(idx1),t,INF);
			cg++;
		}

	for(int i = 0 ; i < H ; i++)
		if( S[i][sx] == 'o' ){
			int idx1 = i * W + sx;
			addEdge(g,s,in(idx1),INF);
			cs++;
		}
	for(int i = 0 ; i < H ; i++)
		if( S[i][gx] == 'o' ){
			int idx1 = i * W + gx;
			addEdge(g,out(idx1),t,INF);
			cg++;
		}
	for(int i = 0 ; i < H ; i++){
		for(int j = 0 ; j < W ; j++){
			if( S[i][j] == 'o' ){
				int idx1 = i * W + j;
				addEdge(g,in(idx1),out(idx1),1);
			}
		}
	}	

	for(int i = 0 ; i < H ; i++){
		for(int j = 0 ; j < W ; j++){
			for(int J = 0 ; J < W ; J++){
				if( S[i][j] != 'o' ) continue;
				if( S[i][J] != 'o' ) continue;
				int idx1 = i * W + j;				
				int idx2 = i * W + J;
				addEdge(g,out(idx1),in(idx2),INF);				
			}
			for(int I = 0 ; I < H ; I++){
				if( S[i][j] != 'o' ) continue;
				if( S[I][j] != 'o' ) continue;
				int idx1 = i * W + j;				
				int idx2 = I * W + j;
				addEdge(g,out(idx1),in(idx2),INF);				
			}	
		}
	}

	int res = maximumFlow(g,s,t);
	if( 1.0 * (en-st) / CLOCKS_PER_SEC > 1.8 ){
		cout << min(cg,cs) << endl;
		return;
	}

	//	cout << res << endl;
	if( res >= 100000 ){
		cout << -1 << endl;
	}else{
		cout << res << endl;
	}

}

