	dis[S] = 0; Q.push(S); vis[S] = ++clc;
	while (!Q.empty()) {
		int u = Q.front(); Q.pop();
		for (int i = head[u]; i; i = G[i].next) {
			edge &e = G[i];
			if (e.cap && vis[e.to] != clc) {
				dis[e.to] = dis[u] + 1;
				vis[e.to] = clc; Q.push(e.to);
			}
		}
	}
	return vis[T] == clc;
}
inline int dfs(int u, int a) {
	int flow = 0, f;
	if (u == T || a == 0) return a;
	for (int &i = cur[u]; i; i = G[i].next) {
		edge &e = G[i];
		if (e.cap && dis[e.to] == dis[u] + 1
				&& (f = dfs(e.to, min(a, e.cap))) > 0) {
			e.cap -= f; flow += f;
			G[i ^ 1].cap -= f; a -= f;
			if (a == 0) break;
		}
	}
	return flow;
}
inline int MaxFlow(int S, int T) {
	int flow = 0;
	while (bfs(S, T)) {
		for (int i = 1; i <= cnt; i++) cur[i] = head[i];
		flow += dfs(S, INF);
	}
	return flow;
}

