struct Node;
struct Edge{
	Edge(Node* f, Node* t):from(f), to(t), rest(1){};
	Node* from, *to;
	int rest;
};
struct Node{
	vector<Edge*> inEdges, outEdges;
};
bool flow(Node* start, Node* goal, set<Node*>& visited){
	if(start == goal){
		return true;
	}
	for(Edge* e : start -> outEdges){
		if(e -> rest == 0){ continue; }
		Node* v = e -> to; 
		if(visited.count(v)){ continue; }
		visited.insert(v);
		if(flow(v, goal, visited)){
			e -> rest --;
			return true;
		}
	}
	for(Edge* e : start -> inEdges){
		if(e -> rest != 0){ continue; }
		Node* v = e -> from; 
		if(visited.count(v)){ continue; }
		visited.insert(v);
		if(flow(v, goal, visited)){
			e -> rest ++;
			return true;
		}
	}
	return false;
}
int maxFlow(Node* start, Node* goal){
	int cnt = 0;
	for(;;cnt++){
		set<Node*> visited;
		if(!flow(start, goal, visited)){ break; }
	}
	return cnt;
}

