#include <bits/stdc++.h>
using namespace std;

const int MAXM = 2e5 + 10;
const int MAXN = 2e5 + 10;
const int MAXNODE = 100 + 10;
const int INF = 1e9 + 7;

struct Edge {
	int nxt, v, w;
} e[MAXM];
int head[MAXN], tot;

inline void addEdge (int u, int v, int w) {
	e[++tot] = (Edge){head[u],v,w};
	head[u] = tot;
}

void reset (void) {
	memset(head,-1,sizeof(head));
	tot = -1;
}

int n, m, s, t, node_tot;
int cur[MAXN];
int dis[MAXN];
int gap[MAXN];
queue<int> q;

void maxflow_bfs (void) {
	memcpy(cur,head,sizeof(head));
	memset(dis,-1,sizeof(dis));
	memset(gap,0,sizeof(gap));

	gap[0] = 1;
	dis[t] = 0;
	q.push(t);
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int i = head[u]; ~i; i = e[i].nxt) {
			if (e[i^1].w > 0 && dis[e[i].v] == -1) {
				dis[e[i].v] = dis[u] + 1;
				gap[dis[e[i].v]]++;
				q.push(e[i].v);
			}
		}
	}
}

int maxflow_dfs (int u, int flow) {
	if (u == t) return flow;

	int sum_flow = 0;
	for (int & i = cur[u]; ~i; i = e[i].nxt) {
		if (e[i].w > 0 && dis[u] == dis[e[i].v] + 1) {
			int new_flow = maxflow_dfs(e[i].v, min(flow, e[i].w));
			e[i].w -= new_flow;
			e[i^1].w += new_flow;
			flow -= new_flow;
			sum_flow += new_flow;
			if (!flow) return sum_flow;
		}
	}
	if (--gap[dis[u]] == 0) dis[s] = node_tot;
	gap[++dis[u]]++;
	cur[u] = head[u];

	return sum_flow;
}

int SAP (void) {
	int ret = 0;
	maxflow_bfs();
	while (dis[s] < node_tot) {
		ret += maxflow_dfs(s, INF);
	}
	return ret;
}

