        default:
        case '.':
          break;
      }
    }
  }
  dump(s, t, 1);
  if(s == t) {
    cout << -1 << endl;
    return 0;
  }
  ll res = ecasd.solve(s, t);
  if(res == INF) res = -1;
  cout << res << endl;
}

