    rep(i, h) {
        rep(j, w) {
            cin >> a[i][j];
            if(a[i][j] == 'S') {
                s = i * w + j;
                a[i][j] = 'o';
            }
            if(a[i][j] == 'T') {
                t = i * w + j;
                a[i][j] = 'o';
            }
        }
    }
    //cerr << s << "  " << t << endl;
    if(s % h == t % h || s / h == t / h) {
        cout << -1 << endl;
        return;
    }
    rep(i, h) {
        for(int j = i + 1; j < h; ++j) {
            rep(k, w) {
                if(a[i][k] == 'o' && a[j][k] == 'o') {
                    G.addedge(i * w + k + h * w, j * w + k, INF);
                    G.addedge(j * w + k + h * w, i * w + k, INF);
                }
            }
        }
    }
    rep(i, w) {
        for(int j = i + 1; j < w; ++j) {
            rep(k, h) {
                if(a[k][i] == 'o' && a[k][j] == 'o') {
                    G.addedge(k * w + i + h * w, k * w + j, INF);
                    G.addedge(k * w + j + h * w, k * w + i, INF);
                }
            }
        }
    }
    rep(i, h) {
        rep(j, w) {
            if(a[i][j] == 'o' && i * w + j != s && i * w + j != t) {
                //a[i][j]の葉を取り除く
                G.addedge(id(i, j), id(i, j) + h * w, 1LL);
            }
        }
    }
    Dinic<ll> di;
    cout << di.solve(G, s + h * w, t) << endl;
}

