	fl.addEdge( start, IN_W + v[start].Y, INF );
	fl.addEdge( IN_H + v[goal].X, goal, INF );
	fl.addEdge( IN_W + v[goal].Y, goal, INF );

	ans = fl.maxFlow(start, goal);

	if( ans == INF ) ans = -1;
	cout << ans << endl;

	return 0;
}

#include <iostream>
#include <vector>
#define inf 1000000000

using namespace std;
struct edge{
	int to, cap, rev;
	edge(int a, int b, int c){
		to = a, cap = b, rev = c;
	}
};

int H, W;
char map[105][105];
int sx, sy, tx, ty;
vector<edge> G[205];
int S, T;
bool used[205];

void add_edge(int u, int v, int cap)
{
	G[u].push_back( edge(v, cap, G[v].size()) );
	G[v].push_back( edge(u, 0, G[u].size()-1) );
}

int dfs(int v, int f)
{
	used[v] = true;
	if(v == T) return f;

	int ret;
	for(int i = 0; i < G[v].size(); i++){
		if(used[G[v][i].to] || G[v][i].cap <= 0) continue;
		ret = dfs(G[v][i].to, min(f, G[v][i].cap));
		if(ret > 0){
			G[v][i].cap -= ret;
			G[G[v][i].to][G[v][i].rev].cap += ret;
			return ret;
		}
	}
	return 0;
}

int main(void)
{
	cin >> H >> W;
	for(int y = 1; y <= H; y++){
		for(int x = 1; x <= W; x++){
			cin >> map[x][y];
			if(map[x][y] == 'S'){
				sx = x, sy = y;
				map[x][y] = 'o';
			}
			if(map[x][y] == 'T'){
				tx = x, ty = y;
				map[x][y] = 'o';
			}
		}
	}
	if(sx == tx || sy == ty){
		cout << -1 << endl;
		return 0;
	}

	for(int y = 1; y <= H; y++){
		for(int x = 1; x <= W; x++){
			if(map[x][y] == '.') continue;
			add_edge(x, W+y, 1);
			add_edge(W+y, x, 1);
		}
	}
	S = H+W+1, T = H+W+2;
	add_edge(S, sx, inf), add_edge(S, W+sy, inf), add_edge(tx, T, inf), add_edge(W+ty, T, inf);

	int ans = 0, flow;
	while(1){
		for(int i = 1; i <= T; i++) used[i] = false;
		flow = dfs(S, inf);
		if(flow <= 0) break;
		ans += flow;
	}

	cout << ans << endl;
	return 0;
}

