const int INF=1<<17;

const int M_V=10000;
struct edge {int to,cap,rev;};

struct FordFulkerson{

    vector<edge> G[M_V];
    bool used[M_V];

    void add_edge(int from,int to,int cap){
        G[from].push_back({to,cap,G[to].size()});
        G[to].push_back({from,0,G[from].size()-1});
    }

    int dfs(int v,int t,int f){
        if(v==t) return f;
        used[v]=true;
        for(int i=0;i<G[v].size();i++){
            edge &e=G[v][i];
            if(!used[e.to]&&e.cap>0){
                int d=dfs(e.to,t,min(f,e.cap));
                if(d>0){
                    e.cap-=d;
                    G[e.to][e.rev].cap+=d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(int s,int t){
        int flow=0;
        for(;;){
            memset(used,0,sizeof(used));
            int f=dfs(s,t,INF);
            if(f==0) return flow;
            flow+=f;
        }
    }
};

int main(){
    int H,W;
    cin >> H >> W;
    FordFulkerson FF;
    char a[H][W];
    int s,g;
    P p,q;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            cin >> a[i][j];
            if(a[i][j]=='S'){
                s=i*W+j;
                p=P(i,j);
            }
            if(a[i][j]=='T'){
                g=i*W+j;
                q=P(i,j);
            }
        }
    }
    if(p.first==q.first||p.second==q.second){
        puts("-1");
        return 0;
    }
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            if(a[i][j]  =='.') continue;
            for(int k=j+1;k<W;k++){
                if(a[i][k]!='.'){
                    if(a[i][j]!='S') FF.add_edge(i*W+j,i*W+k,1);
                    if(a[i][k]!='T') FF.add_edge(i*W+k,i*W+j,1);
                }
            }
        }
    }
    for(int i=0;i<W;i++){
        for(int j=0;j<H;j++){
            if(a[j][i]=='.') continue;
            for(int k=j+1;k<H;k++){
                if(a[k][i]!='.'){
                    if(a[j][i]!='S') FF.add_edge(i+j*W,i+k*W,1);
                    if(a[k][i]!='T') FF.add_edge(i+k*W,i+j*W,1);
                }
            }
        }
    }
    cout << FF.max_flow(s,g) << endl;
    return 0;
}

