bool bfs(int src, int sink) {
  memset(pre, -1, sizeof(pre));
  pre[src] = -2;
  queue <int> q;
  q.push(src);
  while(!q.empty()) {
    int u = q.front();
    q.pop();
    if(u == sink) return 1;
    for(auto &i : ad[u]) {
      if(e[i].cap > 0 && pre[e[i].v] == -1) {
        pre[e[i].v] = i;
        q.push(e[i].v);
      }
    }
  }
  return 0;
}
int flowie(int src, int sink) {
  int flow = 0;
  while(bfs(src, sink)) {
    int d = INT_MAX;
    vector <int> node;
    int v = sink;
    do {
      d = min(d, e[pre[v]].cap);
      node.push_back(pre[v]);
      v = e[pre[v]].u;
    }while(v != src);
    for(auto &i : node) e[i].cap -= d, e[i ^ 1].cap += d;
    flow += d;
  }
  if(flow >= INF) return -1;
  else return flow;
}
