struct edge {
	int to, rev;
	ll cap;
	edge(int to, ll cap, int rev) :to(to), cap(cap), rev(rev) {}
};
vector<int> dist;
vector<int> itr;
void add_edge(vector<vector<edge>> &G, int from, int to, ll cap) {
	G[from].emplace_back(to, cap, (int)G[to].size());
	G[to].emplace_back(from, 0, (int)G[from].size() - 1);
}
void bfs(vector<vector<edge>> &G, int s) {
	dist.assign(G.size(), -1);
	queue<int> q;
	dist[s] = 0;
	q.push(s);
	while (!q.empty()) {
		int v = q.front(); q.pop();
		for (auto &e : G[v]) {
			if (e.cap > 0 && dist[e.to] < 0) {
				dist[e.to] = dist[v] + 1;
				q.push(e.to);
			}
		}
	}
}
ll dfs(vector<vector<edge>> &G, int v, int t, ll f) {
	if (v == t) return f;
	for (int &i = itr[v]; i < (int)G[v].size(); i++) {
		edge &e = G[v][i];
		if (e.cap > 0 && dist[v] < dist[e.to]) {
			ll d = dfs(G, e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}
ll max_flow(vector<vector<edge>> &G, int s, int t) {
	int ret = 0;
	ll f = 0;
	while (bfs(G, s), dist[t] >= 0) {
		itr.assign(G.size(), 0);
		while ((f = dfs(G, s, t, 1 << 30)) > 0) ret += f;
	}
	return ret;
}
int main() {
	int H, W;
	cin >> H >> W;
	vector<vector<edge>> G(H + W, vector<edge>());
	int s_h, s_w;
	int t_h, t_w;
	for (int i = 0; i < H; i++) {
		string line;
		cin >> line;
		for (int j = 0; j < W; j++) {
			if (line[j] == 'S') {
				s_h = i;
				s_w = j;
				add_edge(G, i, j + H, 1 << 30);
				add_edge(G, j + H, i, 1 << 30);
			}
			else if (line[j] == 'T') {
				t_h = i;
				t_w = j;
				add_edge(G, i, j + H, 1 << 30);
				add_edge(G, j + H, i, 1 << 30);
			}
			else if (line[j] == 'o') {
				add_edge(G, i, j + H, 1);
				add_edge(G, j + H, i, 1);
			}
		}
	}
	ll f = max_flow(G, s_h, t_h);
	if (f >= 1 << 30) cout << -1 << endl;
