	rep(i,H)rep(j,W){
		if(A[i][j]=='S'){
			sx=i,sy=j;
		}else if(A[i][j]=='T'){
			gx=i,gy=j;
		}
	}
	if(sx==gx||sy==gy){
		p(-1);return;
	}
	vector<vector<ll>> tate(H);
	rep(i,H){
		rep(j,W){
			if(A[i][j]!='.')tate[i].push_back(j);
		}
	}
	vector<vector<ll>> yoko(W);
	rep(j,W){
		rep(i,H){
			if(A[i][j]!='.')yoko[j].push_back(i);
		}
	}

	FordFulkerson<int> g(H*W*2);
	rep(i,H)rep(j,W){
		g.add_edge(i*W+j, i*W+j +H*W, 1);
	}
	rep(i,H)rep(j,W){
		if(A[i][j]=='.')continue;
		for(ll y:tate[i]){
			g.add_edge(i*W+j +H*W, i*W+y, 1e5);
			g.add_edge(i*W+y +H*W, i*W+j, 1e5);
		}
