			g.add_edge(i*W+j +H*W, x*W+j, 1e5);
			g.add_edge(x*W+j +H*W, i*W+j, 1e5);
		}

	}

	ll ans=g.max_flow(sx*W+sy +H*W, gx*W+gy);
	//g.output();
	p(ans);
}

