#define vvld vector<vector<ld> >
#define vll vector<long double>
typedef long long int ll;
typedef long double ld;
using namespace std;

ll MAX_V = 10001;
vvl T = vv(MAX_V, 0, 0, ll);
vvl G = vv(MAX_V, 0, 0, ll);
vvl rG = vv(MAX_V, 0, 0, ll);
vector<set<ll>> P(10001);
vector<set<ll>> M(10001);
ll s=-1, e=-1;
//-------------------------------------------------------------------
struct segtree{
  ll M=1;
  vvld dat = vv(0, 2, 0, ld);
  segtree(ll N, ld num){
    while(M<N) M*=2;
    for(int i=0;i<M*2-1;i++)  dat.push_back(vll{num, (ld)(i-(M-1))});
  }
  void update(ld x, int k, int l=0, int r=-1){
    if(r==-1) r = M;
    k+=M-1;
    dat[k][0] += x;
    while(k>0) {
      k = (k-1)/2;
      if(dat[k*2+1][0]>dat[k*2+2][0]) dat[k] = dat[k*2+1];
      else dat[k] = dat[k*2+2];
    }
  }
  vll query(int a, int b=-1, int k=0, int l=0, int r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return {0, 0};
    if(a<=l && r<=b) return dat[k];
    vll A = query(a, b, k*2+1, l, (l+r)/2);
    vll B = query(a, b, k*2+2, (l+r)/2, r);
    if(A[0]>B[0]) return A;
    else return B;
  }
};
//-------------------------------------------------------------------
segtree seg(10001, 0);
vector<bool> check(10001, false);
map<vector<ll>, bool> look;

bool dfs(ll now, ll from){
  if(now==e||P[now].size()!=0) return true;
  if(from!=-1&&now==s) return false;
  check[now] = true;
  bool ret = false;

  for(int i=0;i<T[now].size();i++){
    ll to = T[now][i];
    if(to==from||check[to]) continue;
    bool tmp;
    if(look.find(vector<ll> {now, T[now][i]})!=look.end()){
      tmp = look.at(vector<ll> {now, T[now][i]});
    }else tmp = dfs(T[now][i], now);
    ret|=tmp;
    if(tmp) P[now].insert(to), M[to].insert(now);
    look.emplace(vector<ll> {now, T[now][i]}, tmp);
  }
  check[now] = false;
  return ret;
}

void flow(ll now, ld f, ll mode){
  if(now==e) return;
  if(mode!=-1) seg.update(f, now);
  ld p = G[now].size();
  for(int i=0;i<G[now].size();i++) flow(G[now][i], f/p, 1);
}
void rflow(ll now, ld f){
  if(now==s) return;
  ld S = 0;
  seg.update(f, now);
  for(int i=0;i<rG[now].size();i++) S+=seg.query(rG[now][i], rG[now][i]+1)[0];
  for(int i=0;i<rG[now].size();i++) rflow(rG[now][i], seg.query(rG[now][i], rG[now][i]+1)[0]/S*f);
}
int main(int argc, char const *argv[]) {
  ll n, m;std::cin >> n >> m;
  std::vector<string> t(n);
  for(int i=0;i<n;i++){
    std::cin >> t[i];
    for(int j=0;j<m;j++){
      if(t[i][j]=='S') s = i*100+j, t[i][j] = 'o';
      if(t[i][j]=='T') e = i*100+j, t[i][j] = 'o';
    }
  }
  for(int i=0;i<n;i++){
    vll num;
    for(int j=0;j<m;j++) if(t[i][j]=='o') num.push_back(i*100+j);
    for(int j=0;j<num.size();j++){
      for(int k=0;k<num.size();k++){
        if(j==k) continue;
        T[num[j]].push_back(num[k]);
      }
    }
  }
  for(int j=0;j<m;j++){
    vll num;
    for(int i=0;i<n;i++) if(t[i][j]=='o') num.push_back(i*100+j);
    for(int i=0;i<num.size();i++){
      for(int k=0;k<num.size();k++){
        if(i==k) continue;
        T[num[i]].push_back(num[k]);
      }
    }
  }
  if((s%100)==(e%100)||(s/100)==(e/100)){
    std::cout << -1 << '\n';
    return 0;
  }
  dfs(s, -1);
  for(int i=0;i<10001;i++){
    for(auto itr=P[i].begin();itr!=P[i].end();itr++) G[i].push_back(*itr);
    for(auto itr=M[i].begin();itr!=M[i].end();itr++) rG[i].push_back(*itr);
  }
  //-------------------------------------------------------------------
  ll c = 0;
  for(int i=0;i<G[s].size();i++) flow(G[s][i], (ld)1, 1);
  while(seg.query(0, 10001)[0]>0){
    vll tmp = seg.query(0, 10001);
    c++;
    flow(tmp[1], -tmp[0], -1);
    rflow(tmp[1], -tmp[0]);
  }
  std::cout << c << '\n';
  return 0;
}

