		for (int i = last[src]; i != -1; i = E[i].nxt) {
			int newCost = cost[src] + 1;
			if (E[i].cap && newCost < cost[E[i].to]) {
				cost[E[i].to] = newCost;
				p[E[i].to] = i;
				q.push(E[i].to);
			}
		}
	}
	return cost[SINK] != oo;
}


int main() {
	memset(last, -1, sizeof last);
	memset(num, -1, sizeof num);
	cin >> h >> w;
	SOURCE = cnt++;
	SINK = cnt++;
	for (int i = 0; i < h; ++i) {
		scanf("%s", g[i]);
		for (int j = 0 ; j < w ; ++j) {
			if (g[i][j] == 'o') {
				add(i + 2, h + j + 2, 1);
				add(h + j + 2, i + 2, 1);
			}
			if (g[i][j] == 'S') {
				add(SOURCE, i + 2, oo);
				add(SOURCE, h + j + 2, oo);
				sx = i;
				sy = j;
			}
			if (g[i][j] == 'T') {
				add(i + 2, SINK, oo);
				add(h + j + 2, SINK, oo);
				tx = i;
				ty = j;
			}
		}
	}
	if (tx == sx || ty == sy) {
		puts("-1");
		return 0;
	}

	int mxFlow = 0;

	while (getPath()) {
		int mn = oo;
		int cur = p[SINK];
		while (cur != -1) {
			mn = min(mn, E[cur].cap);
			cur = p[E[cur].from];
		}
		mxFlow += mn;
		cur = p[SINK];
		while (cur != -1) {
			E[cur].cap -= mn;
			E[cur ^ 1].cap += mn;
			cur = p[E[cur].from];
		}
	}
	cout << mxFlow << endl;
	return 0;
}

