		for (int i = 0; i<used.size(); i++) {
			used[i] = false;
		}
		int f = dfs(s, t, numeric_limits<signed>::max());
		if (f == 0) {
			return flow;//もう何も流せないので今まで流した量の和を返す
		}
		flow += f;
	}

}
