#define inf 2100000000
using namespace std;
struct flow
{
	int first[200010],last[200010],next[200010],des[200010],vol[200010],cop[200010],dis[200010],cur[200010],n,tt;
	void init(int pn)
	{
		n=pn;
		tt=1;
	}
	void adde(int u,int v,int l)
	{
		des[++tt]=v;vol[tt]=l;
		if (!first[u]) first[u]=last[u]=tt;else last[u]=next[last[u]]=tt;
		des[++tt]=u;vol[tt]=0;
		if (!first[v]) first[v]=last[v]=tt;else last[v]=next[last[v]]=tt;
	}
	bool bfs(int s,int t)
	{
		for (int i=1;i<=n;i++) dis[i]=2100000000;
		dis[t]=0;int head=1,tail=0;cop[head]=t;
		while (head!=tail)
		{
			int p=cop[++tail];
			for (int k=first[p];k;k=next[k]) if ((dis[des[k]]==2100000000)&&(vol[k^1]))
			{
				dis[des[k]]=dis[p]+1;
				cop[++head]=des[k];
			}
		}
		return dis[s]!=2100000000;
	}
	int dfs(int s,int t,int minvol=2100000000)
	{
		if (s==t) return minvol;
		int bg=0;
		for (int k=cur[s];k;k=next[k]) if (dis[des[k]]==dis[s]-1)
		{
			cur[s]=k;
			int now=dfs(des[k],t,min(minvol-bg,vol[k]));
			vol[k]-=now;vol[k^1]+=now;bg+=now;
			if (bg==minvol) break;
		}
		return bg;
	}
	int dinic(int s,int t)
	{
		int ans=0;
		while (bfs(s,t))
		{
			for (int i=1;i<=n;i++) cur[i]=first[i];
			ans+=dfs(s,t);
		}
		return ans;
	}
}flow;
