namespace Main {
	const int V = 2 * N + 10;
	const int E = N * N + 10 * N;
	const int inf = 500000000;

	struct Solution: Data {
		struct edge {
			int to;
			int b, f;

			edge (int to_ = -1, int b_ = 0): to(to_), b(b_), f(0) {}

			int r () {
				return b - f;
			}
		};

		int es = 0;
		edge e[2 * E];

		void push (int num, int d) {
			e[num].f += d;
			e[num ^ 1].f -= d;
		}

		vi adj[V];

		void add_edge (int x, int y, int b) {
			e[es] = edge(y, b);
			adj[x].pb(es);
			++es;
			e[es] = edge(x, b);
			adj[y].pb(es);
			++es;
		}

		int st, fn;

		int l[V];

		bool bfs () {
			memset(l, -1, sizeof l);
			vi q(1, st);
			l[st] = 0;
			forn (i, sz(q)) {
				int v = q[i];
				for (auto j: adj[v]) {
					int to = e[j].to;
					if (l[to] == -1 && e[j].r()) {
						q.pb(to);
						l[to] = l[v] + 1;
					}
				}
			}
			return l[fn] != -1;
		}

		int done[V];

		int dfs (int v, int r) {
			if (v == fn) {
				return r;
			}
			for (; done[v] < sz(adj[v]); ++done[v]) {
				int i = adj[v][done[v]];
			int to = e[i].to;
				if (l[to] != l[v] + 1 || !e[i].r()) {
					continue;
				}
				int d = dfs(to, min(r, e[i].r()));
				if (d) {
					push(i, d);
					return d;
				}
			}
			return 0;
		}

		int dinic () {
			int res = 0;
			while (1) {
				if (!bfs()) {
					break;
				}
				memset(done, 0, sizeof done);
				while (int d = dfs(st, inf)) {
					res += d;
				}
			}
			return res;
		}

		void solve () {
			st = n + m;
			fn = n + m + 1;

			es = 0;
			forn (i, n) {
				forn (j, m) {
					if (s[i][j] == 'o') {
						add_edge(i, j + n, 1);
					}
					if (s[i][j] == 'S') {
						add_edge(st, i, inf);
						add_edge(st, j + n, inf);
					}
					if (s[i][j] == 'T') {
						add_edge(i, fn, inf);
						add_edge(j + n, fn, inf);
					}
				}
			}
			ans = dinic();
			if (ans >= inf) {
				ans = -1;
			}
		}

		void clear () {
			*this = Solution();
		}
	};
}


