void add_edge(int u,int v,int cap)
{
	G [u].push_back(edge{v,cap,int(G [v].size())});
	G [v].push_back(edge{u,0,int(G [u].size()) - 1});
}

int dfs(int curr,int f)
{
	if(curr == DST) return f;
	vis [curr] = true;
	for(auto& it : G [curr]) if(vis [it.to] == false && it.cap > 0){
		int d = dfs(it.to,min(f,it.cap));
		if(d == 0) continue;
		it.cap -= d;
		G [it.to] [it.rev].cap += d;
		return d;
	}
	return 0;
}

int max_flow()
{
	int res = 0,f;
	do{
		memset(vis,0,sizeof(vis));
		f = dfs(SRC,INF);
		res += f;
		if(res >= INF) return -1;
	}while(f > 0);

	return res;
}

