struct edge {
  int to;
  int cap;
  edge* rev;
};

vector<edge*> edges[20005];
void addEdge(int from, int to, int cap) {
  edge* fwd = new edge;
  edge* rev = new edge;
  fwd->to = to;
  fwd->cap = cap;
  fwd->rev = rev;
  rev->to = from;
  rev->cap = 0;
  rev->rev = fwd;
  edges[from].push_back(fwd);
  edges[to].push_back(rev);
}

int dp[20005];
int iter[20005];
edge* used[20005];
const int INF = 1 << 14;

int maxFlow(int s, int t) {
  int ret = 0;
  for(int qq = 1; ret < INF; qq++) {
    queue<int> q;
    q.push(s);
    dp[s] = INF;
    dp[t] = 0;
    while(!q.empty() && dp[t] == 0) {
      int curr = q.front();
      q.pop();
      for(edge* out: edges[curr]) {
        if(out->cap == 0) continue;
        if(qq == iter[out->to]) continue;
        dp[out->to] = min(dp[curr], out->cap);
        iter[out->to] = qq;
        used[out->to] = out;
        q.push(out->to);
      }
    }
    if(dp[t] == 0) break;
    ret += dp[t];
    int curr = t;
    while(curr != s) {
      int par = used[curr]->rev->to;
      used[curr]->cap -= dp[t];
      used[curr]->rev->cap += dp[t];
      curr = par;
    }
  }
  return ret;
}

const char START_CHAR = 'S';
const char END_CHAR = 'T';
const char INTERMEDIATE = 'o';
string g[105];

bool canUse(int x, int y) {
  return g[x][y] == START_CHAR || g[x][y] == END_CHAR || g[x][y] == INTERMEDIATE;
}

void solve() {
  int r, c;
  cin >> r >> c;
  for(int i = 0; i < r; i++) {
    cin >> g[i];
  }
  /*
  construction is
  0 to r*c-1 is begin gadget
  r*c to 2*r*c-1 is end gadget
  2*r*c is source
  2*r*c+1 is sink
  */
  for(int i = 0; i < r; i++) {
    for(int j = 0; j < c; j++) {
      if(!canUse(i, j)) continue;
      addEdge(i*c+j, i*c+j + r*c, 1);
      if(g[i][j] == START_CHAR) {
        addEdge(2*r*c, i*c+j + r*c, INF);
      }
      if(g[i][j] == END_CHAR) {
        addEdge(i*c+j, 2*r*c+1, INF);
      }
      for(int k = 0; k < c; k++) {
        if(j != k && canUse(i, k)) addEdge(i*c+j + r*c, i*c+k, INF);
      }
      for(int k = 0; k < r; k++) {
        if(i != k && canUse(k, j)) addEdge(i*c+j + r*c, k*c+j, INF);
      }
    }
  }
  int ret = maxFlow(2*r*c, 2*r*c+1);
  if(ret >= INF) ret = -1;
  cout << ret << "\n";
}

void casesolve() {
  int t;
  cin >> t; cin.ignore();
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << ": ";
    solve();
  }
}

