    while (l <= r) {
        int u = q[l++];
        foru(v, 0, m + n + 1)
            if (f[u][v] < c[u][v] && !check[v]) {
                check[v] = 1;
                pre[v] = u;
                if (v == target) return true;
                q[++r] = v;
            }
    }
    return false;
}

void increase_flow() {
    int v = target, delta = oo;
    while (v != source) {
        int u = pre[v];
        delta = min(delta, c[u][v] - f[u][v]);
        v = u;
    }
    v = target; res += delta;
    while (v != source) {
        int u = pre[v];
        f[u][v] += delta;
        f[v][u] -= delta;
        v = u;
    }
}

