#define out(i,u) for(int i=first[u];i!=-1;i=next[i])
using namespace std;

const int INF=1<<22;

namespace MaxFlow{
	const int maxn=5000+10;//*****
	const int maxm=300000+10;//*****

	int first[maxn],next[maxm],ecnt;

	inline void clear(){ecnt=0;memset(first,-1,sizeof first);}

	struct Edge{
		int u,v,cap,flow;
		Edge(){}
		Edge(int u,int v,int c,int f):u(u),v(v),cap(c),flow(f){}
	}e[maxm];

	inline void add_edge(int u,int v,int c,int f){
//		printf("(%d,%d,%d)\n",u,v,c);
		next[ecnt]=first[u];first[u]=ecnt;e[ecnt++]=Edge(u,v,c,f);
		next[ecnt]=first[v];first[v]=ecnt;e[ecnt++]=Edge(v,u,0,0);
	}

	int S,T;

	int d[maxn];
	queue<int>q;
	inline int BFS()
	{
		rep(i,1,T) d[i]=0;//T编号一定要最大 
		q.push(S);d[S]=1;
		while(!q.empty())
		{
			int u=q.front();q.pop();

			out(i,u)
			{
				int v=e[i].v;
				if(e[i].cap > e[i].flow && !d[v]){
					d[v]=d[u]+1;q.push(v);	
				}
			}
		}
		return d[T];
	}

	int cur[maxn];
	int dfs(int u,int a)
	{
		if(u==T || !a) return a;
		int flow=0,f;
		for(int &i=cur[u];i!=-1;i=next[i])
		{
			int v=e[i].v;
			if(d[v]==d[u]+1 && (f=dfs(v,min(e[i].cap-e[i].flow,a))))	
			{
				e[i].flow+=f;e[i^1].flow-=f;
				flow+=f;a-=f;
				if(!a) break;
			}
		}
		return flow;
	}

	inline int MF()
	{
		int ret=0;
		while(BFS())
		{
			rep(i,1,T) cur[i]=first[i];
			ret+=dfs(S,INF);
		}
		return ret;
	}
}

