class DirectedGraph {
 public:
  void Init(int n) {
    int i;
    n_ = n;
    m_ = 0;
    for (i=0;i<n_;i++)
      a_[i]=-1;
  }
  void AddEdge(int x,int y, int cap) {
    e_[m_].t=y;
    e_[m_].cap=cap;
    e_[m_].next=a_[x];
    a_[x]=m_;
    m_++;
    e_[m_].t=x;
    e_[m_].cap=0;
    e_[m_].next=a_[y];
    a_[y]=m_;
    m_++;
  }

  int search(int x,int limit)
  {
    int i,j,f,now,f1;
    f=0;
    if (limit==0) return 0;
    if (x==t_) return limit;
    for (i=a_[x];i!=-1;i=e_[i].next)
    {
      if ((e_[i].cap>0)&&(dis_[e_[i].t]==dis_[x]+1))
      {
        now=limit-f;
        if (e_[i].cap<now) now=e_[i].cap;
        f1=search(e_[i].t,now);
        if (f1>0)
        {
          f+=f1;
          e_[i].cap-=f1;
          e_[i^1].cap+=f1;
        }
        if (f==limit) break;
      }
    }
    return f;
  }

  int MaxFlow(int s,int t) {
    int i,j,k,ans;
    s_=s;t_=t;
    ans=0;
    while (1)
    {
      memset(dis_,-1,sizeof(dis_));
      vector<int> q;
      q.clear();
      q.push_back(s);
      dis_[s]=0;
      for (i=0;i<q.size();i++)
      {
        for (j=a_[q[i]];j!=-1;j=e_[j].next)
        {
          if ((e_[j].cap>0)&&(dis_[e_[j].t]==-1))
          {
            dis_[e_[j].t]=dis_[q[i]]+1;
            q.push_back(e_[j].t);
          }
          if (dis_[t_]!=-1) break;
        }
        if (dis_[t_]!=-1) break;
      }
      if (dis_[t_]==-1) break;
      ans+=search(s,2000000000);
    }
    return ans;
  }

  void output()
  {
    int i,j;
    for (i=0;i<n_;i++)
      for (j=a_[i];j!=-1;j=e_[j].next)
        printf("%d %d %d\n",i,e_[j].t,e_[j].cap);
  }

  Edge e_[maxm];
  int used_[maxn];
  int a_[maxn];
  int dis_[maxn];
  int n_,m_,s_,t_;
};

