  string m[H];
  REP(i, H) cin >> m[i];

  int s = 2*H*W+1;
  int t = 2*H*W+2;

  REP(i, H) REP(j, W) {
    if (m[i][j] == 'o') {
      int v_in = i * W + j;
      int v_out = i * W + j + H*W;
      addedge(v_in, v_out, 1, 0);
    }
    if (m[i][j] == 'S') {
      int v_in = i * W + j;
      int v_out = i * W + j + H*W;
      addedge(v_in, v_out, INF, 0);
      addedge(s, v_in, INF, 0);     
    }
    if (m[i][j] == 'T') {
      int v_in = i * W + j;
      int v_out = i * W + j + H*W;
      addedge(v_in, v_out, INF, 0);
      addedge(v_out, t, INF, 0);
    }
  }

  REP(i, H) REP(j, W) {
    int v1 = i*W+j + H*W;
    REP(k, W) { if(k != j && m[i][k] != '.')  addedge(v1, i*W+k, INF, 0); }
    REP(k, H) { if(k != i && m[k][j] != '.') addedge(v1, k*W+j, INF, 0); }
  }

  ll ans = dinic(s, t);
  if (ans >= INF/2) ans = -1;
  cout << ans << endl;
  return 0;
}

