typedef long long cost_t;

class Edge {
public:
	int to = -1, from = -1, rev = -1;
	cost_t cost = -1, cap = -1;

	Edge(){
	}

	Edge(int x,cost_t y){
		to = x;
		cost = y;
	}

	Edge(int x, int y, cost_t z){
		from = x;
		to = y;
		cost = z;
	}

	Edge(int x, int y, int r, cost_t z){
		from = x;
		to = y;
		cost = z;
		rev = r;
	}

	Edge(int x, int y, int r, cost_t co, cost_t ca){
		from = x;
		to = y;
		cost = co;
		cap = ca;
		rev = r;
	}

	bool operator< (const Edge& x) const {
		if(cost != x.cost) return cost < x.cost;
		return to < x.to;
	}

	bool operator> (const Edge& x) const {
		if(cost != x.cost) return cost > x.cost;
		return to > x.to;
	}
};

class Graph {
private:
	typedef vector<Edge> Edges;
	//const long long int INF = (long long)1e18;
	vector<Edges> v; 
	int n;
public:
	Graph(int x){
		n = x;
		v = vector<Edges>(x);
	}

	Graph(){}

	Edges& operator[](int x){
		return v[x];
	}

	const Edges& operator[](int x) const {
		return v[x];
	}

	int size() const {
		return n;
	}

	void add_edge(int from, const Edge &e){
		v[from].push_back(e);
	}

	void add_edge(int from, int to, cost_t cost = -1, cost_t cap = -1, int rev = -1){
		add_edge(from,Edge(from,to,rev,cost,cap));
	}

	void add_fedge(int from, int to, cost_t cap = -1){
		add_edge(from,to,-1,cap,-1);
	}

	void add_uedge(int from, int to, cost_t cost = -1){
		add_edge(from,to,cost);
		add_edge(to,from,cost);
	}
};

template<unsigned int size>
class Index{
public:
	array<int,size> sizes;
	Index(int first, ...){
		va_list args;
		va_start(args, first);
		int arg = first;
		for(int i = 0; i < (int)size; ++i) {
			sizes[i] = arg;
			arg = va_arg(args,int);
		}
	}
	int operator()(int first, ...){
		va_list args;
		va_start(args, first);
		int arg = first;
		int res = 0;
		int d = 1;
		for(int i = 0; i < (int)size; ++i) {
			res += arg*d;
			d *= sizes[i];
			arg = va_arg(args,int);
		}
		return res;
	}
};


