cost_t ekMaxFlow(const Graph &g_, int s, int t){
	Graph g = g_;
	assert(s != t);
	int n = g.size();
	for(int i = 0; i < n; ++i) {
		for(int j = 0; j < int(g_[i].size()); j++) {
			auto&& e = g[i][j];
			e.rev = g[e.to].size();
			g.add_edge(e.to,i,-1,0,j);
		}
	}

	cost_t flow = 0;
	while(true){

		vector<Edge*> pre(n,NULL);
		vector<cost_t> cost_min(n,INF);
		[&](){
			queue<int> qu;
			qu.push(s);
			while(!qu.empty()){
				int p = qu.front();
				qu.pop();
				for(auto&& e : g[p]) {
					if(e.cap > 0 and pre[e.to] == NULL){
						pre[e.to] = &e;
						cost_min[e.to] = min(cost_min[p],e.cap);
						qu.push(e.to);
						if(e.to == t) return;
					}
				}
			}
		}();

		if(pre[t] == NULL) return flow;

		int p = t;
		flow += cost_min[t];
		while(p != s){
			pre[p]->cap -= cost_min[t];
			g[pre[p]->to][pre[p]->rev].cap += cost_min[t];
			p = pre[p]->from;
		}
	}
}


