int head[maxp];
void Add(int u, int v, int c) {
    e.push_back(Edge(head[u], v, c)); head[u] = e.size() - 1;
    e.push_back(Edge(head[v], u, 0)); head[v] = e.size() - 1;
}

int N, M;
