int src, sink, cur[maxp], d[maxp], vis[maxp], T;
queue<int> q;
bool bfs() {
    vis[src] = ++T, q.push(src);
    while(!q.empty()) {
	int x = q.front(); q.pop();
	for(int i = head[x]; i; i = e[i].next) {
	    int to = e[i].to;
	    if(vis[to] != T && e[i].cap > e[i].flow) {
		vis[to] = T;
		d[to] = d[x] + 1;
		q.push(to);
	    }
	}
    }
    return vis[sink] == T;
}
int dfs(int x, int a) {
    if(x == sink || !a) return a;
    int flow = 0, f;
    for(int &i = cur[x]; i; i = e[i].next) {
	int to = e[i].to;
	if(d[to] == d[x] + 1 && (f = dfs(to, min(a, e[i].cap - e[i].flow))) > 0){
	    e[i].flow += f;
	    e[i ^ 1].flow -= f;
	    flow += f;
	    a -= f;
	    if(!a) break;
	}
    }
    return flow;
}
int dinic() {
    int flow = 0;
    while(bfs()) {
	memcpy(cur, head, sizeof cur);
	flow += dfs(src, inf);
    }
    return flow;
}

