bool findpath()
{
	deque<lli> p;
	p.push_back(s);
	minn[s]=inf;
	Time[s]=T;
	while(!p.empty())
	{
		lli u=p.front();
		p.pop_front();
		for(auto i: D[u])
		{
			lli v=i.v, id=i.id;
			if(Time[v]!=T&&c[id]>f[id]) 
			{
				Time[v]=T;
				minn[v]=min(minn[u], c[id]-f[id]);
				trace[v]=mp(u, id);
				if(v==t)
				{
					return 1;
				}
				p.push_back(v);
			}
		}
	}
	return 0;
