void addedge(int u, int v, int cap)
{
	edge e1 = *new edge(u, v, cap);
	g[u].push_back(e.size());
	e.push_back(e1);
	edge e2 = *new edge(v, u, 0);
	g[v].push_back(e.size());
	e.push_back(e2);
}

int dfs(int v, int finish, int have)
{
	if (v == finish)
	{
		return have;
	}
	for (; ptr[v] < g[v].size(); ++ptr[v])
	{
		int to = g[v][ptr[v]];
		int ne = e[to].v;
		if ((e[to].cap>0) && (d[v] + 1 == d[ne]))
		{
			int res = 0;
			if (have == -1)
				res = dfs(e[to].v, finish, e[to].cap);
			else
				res = dfs(e[to].v, finish, MIN(have, e[to].cap));
			if (res > 0)
			{
				e[to].cap -= res;
				e[to ^ 1].cap += res;
				return res;
			}
		}
	}
	return 0;
}
vector<int> q;
bool bfs(int start, int finish, int n)
{
	d.clear();
	d.resize(n, -1);
	q.clear();
	q.push_back(start);
	d[start] = 0;
	int l = 0;
	while (l < q.size())
	{
		int v = q[l++];
		FOR(i, 0, g[v].size())
		{
			int to = g[v][i];
			if ((e[to].cap > 0) && (d[e[to].v] == -1))
			{
				d[e[to].v] = d[v] + 1;
				q.push_back(e[to].v);
			}
		}
	}
	return (d[finish] != -1);
}

LL getFlow(int start, int finish, int n)
{
	LL res = 0;
	while (true)
	{
		bool f = bfs(start, finish, n);
		if (!f)
			break;
		ptr.clear();
		ptr.resize(n, 0);
		while (1)
		{
			int k = dfs(start, finish, -1);
			if (k <= 0)
				break;
			res += k;
		}
	}
	return res;
}

