void jia(int aa,int bb,int cc)
{
	tot++;
	nx[tot]=head[aa];
	to[tot]=bb;
	w[tot]=cc;
	head[aa]=tot;
	return;
}
int bfs()
{
	memset(dep,0,sizeof(dep));
	queue<int>q;
	q.push(S);
	dep[S]=1;
	while(!q.empty())
	{
		int kk=q.front();
		q.pop();
		for(int i=head[kk];i;i=nx[i])
		if(w[i]>0)
		{
			int yy=to[i];
			if(dep[yy]) continue;
			dep[yy]=dep[kk]+1;
			q.push(yy);
		}
	}
	return dep[T];
}
int dfs(int rt,int zhi)
{
	if(rt==T) return zhi;
	for(int i=head[rt];i;i=nx[i])
	if(w[i])
	{
		int yy=to[i];
		if(dep[yy]!=dep[rt]+1) continue;
		int tt=dfs(yy,min(zhi,w[i]));
		if(tt)
		{
			w[i]-=tt;
			w[i^1]+=tt;
			return tt;
		}
	}
	return 0;
}
