int dfs(int x,int f){
    if(x==T) return f;
    int w,used=0;
    for(int i=st[x];i;i=vs[i].next)
        if(vs[i].w&&h[vs[i].v]==h[x]+1){
            w=dfs(vs[i].v,min(f-used,vs[i].w));
            vs[i].w-=w;vs[i^1].w+=w;
            used+=w;if(used==f)return f;
        }
    if(!used)h[x]=-1;
    return used;
}

