struct FF{
	struct edge{
		ll to, cap, rev;
	};
	vector<vector<edge>> G;
	vector<bool> used;
	ll n;
	const ll INF = 1<<30;

	FF(ll n) : n(n){
		G.resize(n);
		used.resize(n,false);
	}

	void add_edge(ll from, ll to, ll cap){
		G[from].push_back({to,cap,(ll)G[to].size()});
		G[to].push_back({from,0,(ll)G[from].size()-1});
	}

	ll dfs(ll u, ll t, ll f){
		if(u == t) return f;
		used[u] = true;
		for(auto &e : G[u]){
			if(!used[e.to] && e.cap > 0){
				ll d = dfs(e.to, t, min(f, e.cap));
				if(d > 0){
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	ll max_flow(ll s, ll t){
		ll flow = 0;
		while(1){
			for(ll i=0; i<n; i++) used[i] = false;
			ll add_flow = dfs(s,t,INF);
			if(add_flow == 0) return flow;
			flow += add_flow;
		}
	}
};

char a[101][101];

int main(){
	ll h,w; cin >> h >> w;
	rep(i,h) rep(j,w) cin >> a[i][j];
