			if(a[i][j] == '.') continue;
			if(a[i][j] == 'S') s = i*w+j + h*w;
			if(a[i][j] == 'T') t = i*w+j;
			if(a[i][j] == 'o') flow.add_edge(i*w+j, h*w + i*w+j, 1);
			rep(k,h){
				if(i == k || a[k][j] == 'S' || a[k][j] == '.') continue;
				flow.add_edge(h*w + i*w+j, k*w+j, h*w);
			}
			rep(k,w){
				if(j == k || a[i][k] == 'S' || a[i][k] == '.') continue;
				flow.add_edge(h*w + i*w+j, i*w+k, h*w);
