[[noreturn]] void impossible() {
    PRINTLN("-1");
    EXIT();
}

void solve() {
    Int H = RD();
    Int W = RD();
    auto A = RD_VEC<string>(H);

    Int S = -1;
    Int T = -1;
    Int N = 2*H*W + H + W;
    auto vert_in = [W](Int y, Int x) -> Int {
        return W*y + x;
    };
    auto vert_out = [H,W,vert_in](Int y, Int x) -> Int {
        return H*W + vert_in(y,x);
    };
    auto vert_row = [H,W](Int y) -> Int {
        return 2*H*W + y;
    };
    auto vert_col = [H,W](Int x) -> Int {
        return 2*H*W + H + x;
    };

    vector<vector<Edge>> G(N);
    auto add_edge = [&G](Int a, Int b, Int c) {
        G[a].emplace_back(b, c, SIZE(G[b]));
        G[b].emplace_back(a, 0, SIZE(G[a])-1);
    };

    Int sy=-1, sx=-1;
    Int ty=-1, tx=-1;
    REP(y, H) REP(x, W) {
        char c = A[y][x];
        if(c == '.') continue;

        if(c == 'S') {
            sy=y; sx=x;
            S = vert_out(y,x);
            add_edge(S, vert_row(y), INF);
            add_edge(S, vert_col(x), INF);
        }
        else if(c == 'T') {
            ty=y; tx=x;
            T = vert_in(y,x);
            add_edge(vert_row(y), T, INF);
            add_edge(vert_col(x), T, INF);
        }
        else if(c == 'o') {
            Int v_in  = vert_in(y,x);
            Int v_out = vert_out(y,x);
            add_edge(v_in, v_out, 1);
            add_edge(v_out, vert_row(y), INF);
            add_edge(v_out, vert_col(x), INF);
            add_edge(vert_row(y), v_in, INF);
            add_edge(vert_col(x), v_in, INF);
        }
        else { ASSERT(false); }
    }
    DBG(S, T);
    DBG(G);
    if(sy == ty || sx == tx) impossible();

    vector<bool> visited(N);
    auto dfs = FIX([&](auto&& self, Int v, Int flmax) -> Int {
        if(v == T) return flmax;
        visited[v] = true;

        Int res = 0;
        for(auto& e : G[v]) {
            if(visited[e.to]) continue;
            Int flmax_nex = MIN(e.cap, flmax);
            if(flmax_nex == 0) continue;
            Int fl = self(e.to, flmax_nex);
            flmax -= fl;

            auto& e_rev = G[e.to][e.rev];
            e.cap     -= fl;
            e_rev.cap += fl;
            res += fl;
        }
        return res;
    });

    Int flow = 0;
    for(;;) {
        ALL(fill, visited, false);
        Int fl = dfs(S, INF);
        if(fl == 0) break;
        flow += fl;
    }

    PRINTLN(flow);
}

signed main() {
    Int T = 1; //RD();
    LOOP(T) {
        solve();
    }

    EXIT();
}

