struct Edge {
  int v, c;
  Edge* nxt;
};

const int N = 210;
const int M = 21000;
Edge* a[N];
Edge pool[M], *last;

int pre[N];
Edge* idx[N];

inline Edge* new_edge(int v, int c, Edge* nxt) {
  Edge* p = last++;
  p->v = v;
  p->c = c;
  p->nxt = nxt;
  return p;
}

inline void add_edge(int u, int v, int c) {
  a[u] = new_edge(v, c, a[u]);
  a[v] = new_edge(u, c, a[v]);
}

inline Edge* dual(Edge* p) {
  return pool + ((p - pool) ^ 1);
}

int augment(int s, int t) {
  int aug = INF;
  for (int i = t; i != s; i = pre[i]) {
    aug = min(aug, idx[i]->c);
  }
  for (int i = t; i != s; i = pre[i]) {
    idx[i]->c -= aug;
    dual(idx[i])->c += aug;
  }
  return aug;
}

int maxflow(int s, int t, int n) {
  int ret = 0;
  while (true) {
    queue<int> Q;
    Q.push(s);
    fill(pre, pre + n, -1);
    while (!Q.empty()) {
      int i = Q.front();
      Q.pop();
      for (Edge* it = a[i]; it; it = it->nxt) {
        if (pre[it->v] < 0 && it->c) {
          Q.push(it->v);
          idx[it->v] = it;
          pre[it->v] = i;
        }
      }
    }
    if (pre[t] < 0) break;
    int aug = augment(s, t);
    if (aug == 0) break;
    ret += aug;
  }
  return ret;
}

