  last = pool;
  fill(a, a + t + 1, nullptr);
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      if (str[i][j] == 'S') {
        add_edge(s, i, INF);
        add_edge(s, j + n, INF);
      } else if (str[i][j] == 'T') {
        add_edge(i, t, INF);
        add_edge(j + n, t, INF);
      } else if (str[i][j] == 'o') {
        add_edge(i, n + j, 1);
      }
    }
  }
  int ret = maxflow(s, t, t + 1);
  if (ret >= INF) ret = -1;
  printf("%d\n", ret);
  return 0;
}

