template<int S>
struct Flow
{
vector<Edge> es;
vector<int> edges[S];
void add(int a, int b, int cap){
	//cout << "add " << a << ", " << b << ", " << cap << endl;
	es.push_back(Edge());
	Edge& e=es.back();
	e.a=a;
	e.b=b;
	e.c=cap;
	e.f=0;
	edges[a].push_back(es.size()-1);
	edges[b].push_back(es.size()-1);
}
void init(){
	es.clear();
	for(int i=0;i<S;i++){
		edges[i].clear();
	}
}
int fill(int s, int t, int sz=S){
	int ret=0;
	int pre[S];
	int Q[S];
	while(1){
		memset(pre,-1,sizeof(int)*sz);
		int qs=0;
		Q[0]=s;
		pre[s]=-2;
		int qe=1;
		while(qs<qe&&pre[t]==-1){
			int p=Q[qs++];
			for(int i=0;i<edges[p].size();i++){
				int j=edges[p][i];
				int nex;
				if(es[j].a==p){
					if(es[j].f==es[j].c){
						continue;
					}
					nex=es[j].b;
				}
				else{
					if(es[j].f==0){
						continue;
					}
					nex=es[j].a;
				}
				if(pre[nex]==-1){
					Q[qe++]=nex;
					pre[nex]=j;
				}
			}
		}
		if(pre[t]==-1){
			return ret;
		}
		{
			int p=t;
			int f=INT_MAX;
			while(p!=s){
				int j=pre[p];
				if(es[j].b==p){
					f=min(f,es[j].c - es[j].f);
					p=es[j].a;
				}
				else{
					f=min(f,es[j].f);
					p=es[j].b;
				}
			}
			p=t;
			while(p!=s){
				int j=pre[p];
				if(es[j].b==p){
					es[j].f+=f;
					p=es[j].a;
				}
				else{
					es[j].f-=f;
					p=es[j].b;
				}
			}
			ret+=f;
		}
	}
	// ここには来ない
	return -1;
}
};
