					e.cap -= d;
					vec[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
	LL ford(LL s, LL t) {
		LL flow = 0;
		for (;;) {
			vector<bool> used(10000, false);
			LL f = dfs(used, s, t, INF);
			if (f == 0)return flow;
			flow += f;
		}
	}
};
