            return flow;

        int res = 0;
        for(int& i = cur[u]; i; i = nxt[i]) {
            int aug, v = to[i];
            if(dis[v] == dis[u] + 1 && (aug = dfs(v, min(flow, cap[i])))) {
                res += aug;
                flow -= aug;
                cap[i] -= aug;
                cap[i^1] += aug;
                if(!flow) return res;
            }
        }
        return res;
    }
