                edges.push_back({ INF, 0, j + n + 2 });
                edges.push_back({ INF, j + n + 2, 0 });
            }
            if (grid[i][j] == 'T') {
                edges.push_back({ INF, 1, i + 2 });
                edges.push_back({ INF, i + 2, 1 });

                edges.push_back({ INF, 1, j + n + 2 });
                edges.push_back({ INF, j + n + 2, 1 });
            }
        }
    }

    for (int i = 0; i < edges.size(); i += 2) {
