ll pw(ll a, ll b, ll md) { ll res = 1; while (b) { if (b & 1) { res = (a*res) % md; }a = (a*a) % md; b >>= 1; }return(res); }

ll bfs() {
    queue<pair<ll, ll>> q;
    q.push({ 0, INF });
    vector<bool> used(gr.size());
    vector<ll> par(gr.size());
    ll val = 0;
    used[0] = 1;
    while (!q.empty()) {
        pair<ll, ll> v = q.front();
        q.pop();

        for (auto to : gr[v.first]) {
            ll u = edges[to].u, bal = edges[to].bal;
            if (!used[u] && bal != 0) {
                used[u] = 1;
                ll vl = min(v.second, bal);
                q.push({ u, vl });
                par[u] = to;
                if (u == 1) val = vl;
            }
        }
    }

    if (used[1]) {
        ll v = 1;
        while (v != 0) {
            ll edg = par[v];
            edges[edg].bal -= val;
            edges[edg ^ 1].bal += val;
            v = edges[edg].v;
        }

        return val;
    }
    else {
        return 0;
    }
}

void sol() {
    ll pr = 0;
    ll q = bfs();
    while (q) {
        pr += q;
        q = bfs();
    }

    if (pr == INF) {
        cout << "-1";
    }
    else {
        cout << pr;
    }
}

