				que.push(e[i].y);
			}
		}
	}
	return false;
}

int find(int x,int ed,int mn) {
	if (x==ed||!mn) return mn;
	int ret=0;
	for (int &i=cur[x];i;i=e[i].next) {
		if (e[i].w&&dis[x]+1==dis[e[i].y]) {
			int d=find(e[i].y,ed,std:: min(e[i].w,mn-ret));
			e[i].w-=d,e[i^1].w+=d,ret+=d;
			if (mn==ret) break;
		}
	}
	return ret;
}

