const int N=100007,inf=0x3f3f3f;
struct edge{
	int to,v,nx;
}e[N];
int e0[N],e1[N],h[N],q[N],ep=2,S,T;
bool bfs(){
	for(int i=1;i<=T;++i)h[i]=0,e1[i]=e0[i];
	int ql=0,qr=0;
	h[q[++qr]=S]=1;
	while(ql!=qr){
		int w=q[++ql];
		if(w==T)return 1;
		for(int i=e0[w];i;i=e[i].nx)if(e[i].v){
			int u=e[i].to;
			if(!h[u])h[q[++qr]=u]=h[w]+1;
		}
	}
	return 0;
}
int min(int a,int b){return a<b?a:b;}
int dfs(int w,int f){
	if(w==T)return f;
	int used=0;
	for(int&i=e1[w];i;i=e[i].nx)if(e[i].v){
		int u=e[i].to;
		if(h[u]!=h[w]+1)continue;
		int c=dfs(u,min(f-used,e[i].v));
		e[i].v-=c,e[i^1].v+=c,used+=c;
		if(f==used)return f;
	}
	h[w]=0;
	return used;
}
