/* 使い切り */
class FlowSolver {
	static const CapacityType INF_CAPACITY;
	static const int CANNOT_REACH;
private:
	GraphWithReverse graph_m;

	CapacityType Ford_fulkerson_sub_rec(int from, int sink, CapacityType curr_max_flow, bool* used_p);
	CapacityType Ford_fulkerson_sub(int source, int sink, bool* used_p);

	void Calc_dist(int start, int* dist_p);
