/*---------   FlowSolver   ---------*/
/*----------------------------------*/

const CapacityType FlowSolver::INF_CAPACITY = std::numeric_limits<CapacityType>::max();
const int FlowSolver::CANNOT_REACH = -1;

CapacityType FlowSolver::Ford_fulkerson_sub_rec(int from, int sink, CapacityType curr_max_flow, bool* used_p) {
	if (from == sink) return curr_max_flow;
	used_p[from] = true;

	typedef std::vector<GraphWithReverse::Edge> GraphDataType;
	GraphDataType* data_p = graph_m.Data();
	for (auto&& edge : data_p[from]) {
		if (used_p[edge.to_m] || edge.capacity_m <= 0) continue;
		CapacityType flow = Ford_fulkerson_sub_rec(edge.to_m, sink, std::min(curr_max_flow, edge.capacity_m), used_p);
		if (flow > 0) {
			edge.capacity_m -= flow;
			data_p[edge.to_m][edge.rev_index_m].capacity_m += flow;
			return flow;
		}
	}
	return 0;
}

CapacityType FlowSolver::Ford_fulkerson_sub(int source, int sink, bool* used_p) {
	const int size = graph_m.Size();
	std::fill(used_p, used_p + size, false);
	return Ford_fulkerson_sub_rec(source, sink, INF_CAPACITY, used_p);
}

void FlowSolver::Calc_dist(int start, int* dist_p) {
	typedef std::vector<GraphWithReverse::Edge> GraphDataType;
	const int size = graph_m.Size();
	std::fill(dist_p, dist_p + size, CANNOT_REACH);
	GraphDataType* data_p = graph_m.Data();

	std::queue<int> dist_queue;
	dist_p[start] = 0;
	dist_queue.push(start);
	while (!dist_queue.empty()) {
		int from = dist_queue.front(); dist_queue.pop();
		for (auto&& edge : data_p[from]) {
			if (dist_p[edge.to_m] != CANNOT_REACH || edge.capacity_m <= 0) continue;
			dist_p[edge.to_m] = dist_p[from] + 1;
			dist_queue.push(edge.to_m);
		}
	}
}

CapacityType FlowSolver::Dinic_sub_rec(int from, int sink, CapacityType curr_max_flow, int* done_index_p, int* dist_p) {
	if (from == sink) return curr_max_flow;

	typedef std::vector<GraphWithReverse::Edge> GraphDataType;
	GraphDataType* data_p = graph_m.Data();
	for (int& i = done_index_p[from]; i < data_p[from].size(); ++i) {		// i は done_index_p[from] の別名
		GraphWithReverse::Edge& edge = data_p[from][i];
		if (dist_p[edge.to_m] <= dist_p[from] || edge.capacity_m <= 0) continue;
		CapacityType flow = Dinic_sub_rec(edge.to_m, sink, std::min(curr_max_flow, edge.capacity_m), done_index_p, dist_p);
		if (flow > 0) {
			edge.capacity_m -= flow;
			data_p[edge.to_m][edge.rev_index_m].capacity_m += flow;
			return flow;
		}
	}
	return 0;
}

CapacityType FlowSolver::Dinic_sub(int source, int sink, int* done_index_p, int* dist_p) {
	return Dinic_sub_rec(source, sink, INF_CAPACITY, done_index_p, dist_p);
}

FlowSolver::FlowSolver(const GraphAsList& graph_arg)
	: graph_m(graph_arg.Size()) {
	const int size = graph_arg.Size();

	for (int from = 0; from < size; ++from) {
		for (auto&& edge : graph_arg[from]) {
			graph_m.Add(from, edge.to, edge.cost, false);
		}
	}
}

CapacityType FlowSolver::Ford_fulkerson(int source, int sink) {
	const int size = graph_m.Size();
	bool* used_p = new bool[size];
	std::fill(used_p, used_p + size, false);

	CapacityType sum_flow = 0;
	while (true) {
		CapacityType curr_flow = Ford_fulkerson_sub(source, sink, used_p);
		if (curr_flow == 0) break;
		sum_flow += curr_flow;
	}

	delete[] used_p;
	return sum_flow;
}

CapacityType FlowSolver::Dinic(int source, int sink) {
	const int size = graph_m.Size();
	int* done_index_p = new int[size];
	int* dist_p = new int[size];

	CapacityType sum_flow = 0;
	while (true) {
		Calc_dist(source, dist_p);
		if (dist_p[sink] == CANNOT_REACH) break;
		std::fill(done_index_p, done_index_p + size, 0);
		while (true) {
			CapacityType curr_flow = Dinic_sub(source, sink, done_index_p, dist_p);
			if (curr_flow == 0) break;
			sum_flow += curr_flow;
		}
	}

	delete[] done_index_p;
	delete[] dist_p;
	return sum_flow;
}
