template<class T>
class MaxFlow {
private:
	struct Edge {
		int v;
		int r;
		T c;
	};

private:
	vector<vector<Edge>> g;
	vector<int> d, it;

public:
	MaxFlow(int n) : g(n), d(n), it(n) {}

	void add(int u, int v, T c) {
		int i = g[u].size();
		int j = g[v].size();
		g[u].push_back({ v, j, c });
		g[v].push_back({ u, i, 0 });
	}

	T maxFlow(int s, int t) {
		T sum = 0;
		while (bfs(s, t)) {
			T f;
			while ((f = dfs(s, t, numeric_limits<T>::max())) > 0) {
				sum += f;
			}
		}
		return sum;
	}

private:
	bool bfs(int s, int t) {
		fill(it.begin(), it.end(), 0);
		fill(d.begin(), d.end(), -1);
		d[s] = 0;
		queue<int> q;
		q.push(s);
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (Edge e : g[v]) {
				if (e.c > 0 && d[e.v] == -1) {
					d[e.v] = d[v] + 1;
					q.push(e.v);
				}
			}
		}
		return d[t] >= 0;
	}

	T dfs(int v, int t, T f) {
		if (v == t) {
			return f;
		}
		while (it[v] < g[v].size()) {
			Edge &e = g[v][it[v]++];
			if (e.c > 0 && d[v] < d[e.v]) {
				T ff = dfs(e.v, t, min(f, e.c));
				if (ff > 0) {
					e.c -= ff;
					g[e.v][e.r].c += ff;
					return ff;
				}
			}
		}
		return 0;
	}
};

