using Graph = map<int, map<int, int>>;

int augment(const Graph& G, int T, map<pair<int, int>, int>& flow,
            set<int>& visited, int x, int curFlow)
{
    if (x == T)
        return curFlow;

    if (visited.find(x) != visited.end())
        return 0;

    int result = 0;
    visited.insert(x);

    auto iter = G.find(x);
    if (iter != G.end()) {
        for (const auto& p : iter->second) {
            int y = p.first;
            int cap = p.second;
            int rcap = cap - flow[{x, y}];
            if (rcap > 0) {
                int df = augment(G, T, flow, visited, y, min(curFlow, rcap));
                if (df > 0) {
                    flow[{x, y}] += df;
                    flow[{y, x}] -= df;
                    result = df;
                    break;
                }
            }
        }
    }

    visited.erase(x);
    return result;
}

int maxFlow(const Graph& G, int S, int T)
{
    map<pair<int, int>, int> flow;

    int total = 0;
    int df;
    do {
        set<int> visited;
        df = augment(G, T, flow, visited, S, numeric_limits<int>::max());
        total += df;
    } while (df > 0);

    return total;
}

