struct MaxFlow {
  int n, s, t;
  struct Edge {
    int to, c, f;
    Edge(int to_, int c_, int f_)
      : to(to_), c(c_), f(f_) {}
  };
  vec<Edge, 1> edge;
  vec<int, 2> adjEdge;
  vec<int, 1> dist, ptr;
  MaxFlow(int n_, int s_, int t_)
    : n(n_), s(s_), t(t_) {
    edge = vec<Edge, 1>();
    adjEdge = vec<int, 2>(n);
  }

  void addEdge(int u, int v, int c) {
    adjEdge[u].emplace_back(sz(edge)); edge.emplace_back(v, c, 0);
    adjEdge[v].emplace_back(sz(edge)); edge.emplace_back(u, 0, 0);
  }

  bool bfs() {
    dist = vec<int, 1>(n, INF); dist[s] = 0;
    ptr = vec<int, 1>(n, 0);
    queue<int> q; q.emplace(s);
    while (sz(q)) {
      int u = q.front(); q.pop();
      for (auto& i : adjEdge[u]) {
        if (edge[i].c > edge[i].f && dist[edge[i].to] == INF) {
          dist[edge[i].to] = dist[u] + 1;
          q.emplace(edge[i].to);
        }
      }
    }
    return dist[t] != INF;
  }

  int dfs(int u, int flow) {
    if (u == t) {
      return flow;
    }
    for (; ptr[u] < sz(adjEdge[u]); ++ptr[u]) {
      int i = adjEdge[u][ptr[u]];
      if (edge[i].c == edge[i].f || dist[edge[i].to] != dist[u] + 1) {
        continue;
      }
      int ret = dfs(edge[i].to, min(flow, edge[i].c - edge[i].f));
      if (ret) {
        edge[i].f += ret;
        edge[i ^ 1].f -= ret;
        return ret;
      }
    }
    return 0;
  }

  int get() {
    int ret = 0;
    while (bfs()) {
      int tmp;
      while ((tmp = dfs(s, INF))) {
        ret += tmp;
      }
    }
    return ret;
  }
};

