struct graph {
	// Number of vertices and edges
	int n;

	// Edges
	vector<edge> ee;

	// Graph
	vi g[MAXN];

	// start, finish
	int s, t;

	// Distance for BFS
	int dis[MAXN];

	// Queue for BFS
	int qq[MAXN];

	// Ptr for DFS
	int ptr[MAXN];

	// Adding edge
	void add_edge(int a, int b, int cap){		
		edge e1 = { a, b, cap, 0 };
		edge e2 = { b, a, 0, 0 };
		g[a].pb(SZ(ee));
		ee.pb(e1);
		g[b].pb(SZ(ee));
		ee.pb(e2);
	}	

	// BFS for Dinic
	bool bfs(){
		// Init
		int qh = 0, qt = 0;
		qq[qt++] = s;
		REPN(i, 1, n){
			dis[i] = -1;
		}
		dis[s] = 0;

		// Go
		while (qh < qt) {
			int v = qq[qh++];
			REP(i, 0, SZ(g[v])){
				int ind = g[v][i];
				int to = ee[ind].to;
				if (dis[to] == -1 && ee[ind].flow < ee[ind].cap) {
					qq[qt++] = to;
					dis[to] = dis[v] + 1;
				}
			}
		}

		return dis[t] != -1;
	}

	// DFS for Dinic
	int dfs (int v, int cur_flow){
		if (!cur_flow){
			return 0;
		}
		if (v == t) {
			return cur_flow;
		}
		for (; ptr[v] < SZ(g[v]); ++ptr[v]) {
			int ind = g[v][ptr[v]];
			int to = ee[ind].to;
			if (dis[to] != dis[v] + 1) {
				continue;
			}
			int pushed = dfs(to, min(cur_flow, ee[ind].cap - ee[ind].flow));
			if (pushed) {
				ee[ind].flow += pushed;
				ee[ind ^ 1].flow -= pushed;
				return pushed;
			}
		}
		return 0;
	}

	// Dinic
	int dinic(int _s, int _t) {
		// Init
		s = _s, t = _t;
		REP(i, 0, SZ(ee)){
			ee[i].flow = 0;
		}
		int result = 0;

		// Go
		while(1) {			
			if (!bfs()) { 
				break;
			}
			REPN(i, 1, n){
				ptr[i] = 0;
			}
			while (int pushed = dfs(s, INF)) {
				result += pushed;
				if (result >= LIM) {
					return result;
				}
			}
		}

		return result;
	}
} gg;

