bool bfs(int st,int ed) {
	std:: queue <int> que;
	fill(dis,0); dis[st]=1;
	for (que.push(st);!que.empty();) {
		int x=que.front(); que.pop();
		for (int i=ls[x];i;i=e[i].next) {
