using namespace std;
template <typename T, bool directed>//directedは考えるグラフが有向グラフかどうかをもつ
class Dinic
{
public:
    Dinic(int n) : n(n), capacity(n, vector<T>(n)), edges(n), redges(n) {}
    void add_edge(int src, int dst, T cap)
    {
        capacity[src][dst] = cap;
        capacity[dst][src] = directed ? 0 : cap;
        edges[src].push_back(dst);
        redges[dst].push_back(src);
        if (!directed)
        {
            edges[dst].push_back(src);
            redges[src].push_back(dst);
        }
    }

    T max_flow(int s, int t)
    {
        T flow = 0;
        while (bfs(s, t))
        {
            start.assign(n, 0);
            flow += dfs(t, s, numeric_limits<T>::max());
        }
        return flow;
    }

private:
    int n;
    vector<int> level, start;
    vector<vector<T>> capacity, edges, redges;
    bool bfs(int s, int t)
    {
        level.assign(n, -1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty())
        {
            int v = que.front();
            que.pop();
            for (int nv : edges[v])
                if (capacity[v][nv] > 0 && level[nv] < 0)
                {
                    level[nv] = level[v] + 1;
                    que.push(nv);
                }
        }
        return level[t] != -1;
    }

    T dfs(int v, int s, T limit)
    {
        if (v == s)
            return limit;

        T res = 0;
        for (int &i = start[v]; i < (int)redges[v].size(); ++i)
        {
            int nv = redges[v][i];
            if (capacity[nv][v] > 0 && level[v] == level[nv] + 1)
            {
                T d = dfs(nv, s, min(limit, capacity[nv][v]));
                if (d > 0)
                {
                    capacity[nv][v] -= d;
                    capacity[v][nv] += d;
                    res += d;
                    limit -= d;
                    if (limit == 0)
                        break;
                }
            }
        }
        return res;
    }
};

int main()
{
    int h,w;
    cin>>h>>w;
    vector<string> a(h);
    for(int i = 0; i<h; i++){
      cin>>a[i];
    }
    Dinic<long long, false> dn(h + w + 2);
    for(int i = 0; i<h; i++){
      for(int j = 0; j<w; j++){
        if(a[i][j] == '.'){
          continue;
        }
        if(a[i][j] == 'o'){
          dn.add_edge(i, h+j, 1);
          continue;
        }
        if(a[i][j] == 'S'){
          dn.add_edge(i, h+j, 1);
          dn.add_edge(h+w, i, INF);
          dn.add_edge(h+w, h+j, INF);
          continue;
        }
        if(a[i][j] == 'T'){
          dn.add_edge(i, h+j, 1);
          dn.add_edge(h+w+1, i, INF);
          dn.add_edge(h+w+1, h+j, INF);
          continue;
        }
      }
    }
    cout << dn.max_flow(h+w, h+w+1) << endl;
    return 0;
}

