    for(int j = 0; j < W; j++) {
      if(S[i][j] == 'S') s = to(i, j, false);
      if(S[i][j] == 'T') t = to(i, j, true);

      if(S[i][j] != '.') {
        flow.add_edge(to(i, j, true), to(i, j, false), 1);
        for(int k = 0; k < H; k++) {
          if(i == k) continue;
          if(S[k][j] != '.') {
            flow.add_edge(to(i, j, false), to(k, j, true), INF);
          }
        }
      }
      if(S[i][j] != '.') {
        for(int k = 0; k < W; k++) {
          if(j == k) continue;
          if(S[i][k] != '.') {
            flow.add_edge(to(i, j, false), to(i, k, true), INF);
          }
        }
      }
    }
  }
  auto get = flow.max_flow(s, t);
  if(get >= INF) {
    cout << -1 << endl;
  } else {
    cout << get << endl;
  }
}

