ll flow(pii u, pii v, ll f, map<pii, set<pii>> &g, map<pair<pii, pii>, ll> &cap, set<pii> &r) {	
	if (u == v) return f;
	r.insert(u);
	for (pii t : g[u]) {
		if (r.count(t) or cap[pair<pii, pii>(u, t)] == 0) continue;
		ll d = flow(t, v, min(f, cap[pair<pii, pii>(u, t)]), g, cap, r);
		if (d > 0) {
			cap[pair<pii, pii>(u, t)] -= d;
			cap[pair<pii, pii>(t, u)] += d;
			return d;
		}
	}	
	return 0;
}
ll max_flow(pii s, pii t, map<pii, set<pii>> &g, map<pair<pii, pii>, ll> &cap) {
	ll res = 0;
	while(true) {
		set<pii> r;
		ll f = flow(s, t, INF, g, cap, r);
		if (f) res += f;
		else return res;
	}
}

