void solve() {
	cin >> H >> W;
	rep(i, 0, H) {
		cin >> S[i];
		rep(j, 0, W) {
			if(S[i][j] == 'S') {
				add_edge(0, i + 1, inf);
				add_edge(0, j + H + 1, inf);
			}
			if(S[i][j] == 'T') {
				add_edge(i + 1, W + H + 1, inf);
				add_edge(j + H + 1, W + H + 1, inf);
			}
			if(S[i][j] == 'o') {
				add_edge(i + 1, j + H + 1, 1);
				add_edge(j + H + 1, i + 1, 1);
			}
		}
	}
	int res = max_flow(0, W + H + 1);
	if(res >= inf) cout << "-1\n"; 
	else cout << res << "\n";
}

