template <class T> using V = vector<T>;

const int INF = 2e9;
const int MN = 233;
int h, w;
struct E {
    int to, rev, cap;
    E(int _to, int _rev, int _cap) : to(_to), rev(_rev), cap(_cap) {}
};
V<E> g[MN];
int level[MN], iter[MN];
int n, sv, tv;

void add_edge(int a, int b, int c) {
    g[a].push_back(E(b, int(g[b].size()), c));
    g[b].push_back(E(a, int(g[a].size())-1, 0));
//    cerr << "(" << a << ", " << b << ", " << c << ")\n";
}

int dfs(int v, int f) {
    if (v == tv) return f;
    for (int &i = iter[v]; i < int(g[v].size()); i++) {
        E &e = g[v][i];
        if (!e.cap || level[e.to] <= level[v]) continue;
        int d = dfs(e.to, min(f, e.cap));
        if (!d) continue;
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
    }
    return 0;
}

int exec() {
    int flow = 0;
    while (true) {
        queue<int> que;
        que.push(sv);
        fill(level, level + n, -1);
        level[sv] = 0;
        while (!que.empty()) {
            int v = que.front();
            que.pop();
            for (int i = 0; i < int(g[v].size()); i++) {
                E &e = g[v][i];
                if (!e.cap || level[e.to] != -1) continue;
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
        if (level[tv] == -1) break;
        fill(iter, iter + n, 0);
        while (true) {
            int d = dfs(sv, INF);
            if (!d) break;
            flow += d;
        }
    }
    return flow;
}

