                add_edge(sv, j+h, INF);
                si = i; sj = j;
            } else if (mp[j] == 'T') {
                add_edge(i, tv, INF);
                add_edge(j+h, tv, INF);
                ti = i; tj = j;
            } else if (mp[j] == 'o') {
                add_edge(i, j+h, 1);
                add_edge(j+h, i, 1);
            }
        }
    }
    assert(si >= 0 && sj >= 0 && ti >= 0 && tj >= 0);
    if (si == ti || sj == tj) cout << "-1\n";
    else cout << exec() << endl;
    return 0;
}

