      return 1;
  }}
  return 0;
}

void addEdge(int u, int v, ll c) {
  adjlist[u].push_back(edge {v, (int)adjlist[v].size(), c, 0});
  adjlist[v].push_back(edge {u, (int)adjlist[u].size() - 1, 0, 0});
}

