			}else if(c=='T'){
				add_edge(i,t,INF);
				add_edge(H+j,t,INF);

			}else if(c=='o'){
				add_edge(i,H+j,1);
				add_edge(H+j,i,1);
			}
		}
	}
	int ans = max_flow(s,t);
	if(ans==INF)ans=-1;
	outl(ans);
    return 0;
}

