typedef long long int LL;

const LL MAX_V = 20000;
class Dinic
{
	// 辺を表す構造体（行先、容量、逆辺）
	struct edge { LL to, cap, rev; };

	std::vector<edge>G[MAX_V];	// グラフの隣接リスト表現
	LL level[MAX_V];			// sからの距離
	LL iter[MAX_V];				// どこまで調べ終わったか

public:
	// fromからtoへ向かう容量capの辺をグラフに追加する
	void add_edge(LL from, LL to, LL cap)
	{
		G[from].push_back({ to, cap, G[to].size() });
		G[to].push_back({ from,0,G[from].size() - 1 });
	}

	// sからの最短距離をBFSで計算する
	void bfs(LL s)
	{
		memset(level, -1, sizeof(level));
		std::queue<LL>que;
		level[s] = 0;
		que.push(s);
		while (!que.empty())
		{
			LL v = que.front(); que.pop();
			for (auto i : G[v])
			{
				edge &e = i;
				if (e.cap > 0 && level[e.to] < 0)
				{
					level[e.to] = level[v] + 1;
					que.push(e.to);
				}
			}
		}
	}

	// 増加パスをDFSで探す
	LL dfs(LL v, LL t, LL f)
	{
		if (v == t) { return f; }
		for (LL &i = iter[v]; i < G[v].size(); ++i)
		{
			edge &e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to])
			{
				LL d = dfs(e.to, t, std::min(f, e.cap));
				if (d > 0)
				{
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	// sからtへの最大流を求める
	LL max_flow(LL s, LL t)
	{
		LL flow = 0;
		while (true)
		{
			bfs(s);
			if (level[t] < 0) { return flow; }
			memset(iter, 0, sizeof(iter));
			LL f;
			while ((f = dfs(s, t, INF)) > 0) { flow += f; }
		}
	}
};

