#include <bits/stdc++.h>
using namespace std;
int H, W; 
char A[110][110]; 
int INF = 1919; 
struct edge{
	int to, cap, rev; 
}; 
vector<edge> E[210]; // 0がS, [1,H]が水平, [H+1, H+W]が垂直, H+W+1がT
int level[210]; 
int iter[210]; 
void add_edge(int from, int to, int cap){
	E[from].push_back((edge){to, cap, (int) E[to].size()}); 
	E[to].push_back((edge){from, 0, (int) E[from].size()-1}); 
}
void bfs(int s){
	fill(level, level + H+W+2, -1); 
	queue<int> que; 
	level[s] = 0; 
	que.push(s); 
	while(que.size()){
		int v = que.front(); que.pop(); 
		for(auto i : E[v]){
			edge &e = i; 
			if(e.cap > 0 && level[e.to] < 0){
				level[e.to] = level[v] + 1; 
				que.push(e.to); 
			}
		}
	}
}
int dfs(int v, int t, int f){
	if(v == t) return f; 
	for(int &i = iter[v]; i < (int) E[v].size(); i++){
		edge &e = E[v].at(i); 
		if(e.cap > 0 && level[v] < level[e.to]){
			int d = dfs(e.to, t, min(f, e.cap)); 
			if(d > 0){
				e.cap -= d; 
				E[e.to].at(e.rev).cap += d; 
				return d; 
			}
		}
	}
	return 0; 
}
int max_flow(int s, int t){
	int flow = 0; 
	while(1){
		bfs(s); 
		if(level[t] < 0) return flow; 
		fill(iter, iter + H+W+2, 0); 
		int f; 
		while((f = dfs(s, t, INF)) > 0){
			flow += f; 
		}
	}
}
