			}else if(A[i][j] == 'T'){
				add_edge(i, H+W+1, INF); 
				add_edge(H+j, H+W+1, INF); 				
			}else if(A[i][j] == 'o'){
				add_edge(i, H+j, 1); 
				add_edge(H+j, i, 1); 			
			}
		}
	}
	int ans = max_flow(0, H+W+1); 
	if(ans >= INF) cout << -1 << "\n"; 
	else cout << ans << "\n"; 
}

