template <class T> struct Dinic{
    const T inf;
    struct edge{
        int cd;
        T c;
        size_t rv;
        bool f;
    };
    vector<vector<edge>> v;
    vector<int> m,it;
    Dinic(int n):inf(numeric_limits<T>::max()),v(n){}
    void ad(int dm,int cd,T c){
        v[dm].emplace_back((edge){cd,c,v[cd].size(),0});
        v[cd].emplace_back((edge){dm,c,v[dm].size()-1,1});
    }
    bool bfs(int s,int t){
        m.assign(v.size(),-1);
        queue<int> q;
        m[s]=0;
        q.push(s);
        while(!q.empty()&&m[t]==-1){
            int p=q.front();q.pop();
            for(auto &e:v[p]){
                if(e.c>0&&m[e.cd]==-1){
                    m[e.cd]=m[p]+1;
                    q.push(e.cd);
                }
            }
        }
        return m[t]!=-1;
    }
    T dfs(int i,int t,T f){
        if(i==t) return f;
        for(int j=it[i];j<v[i].size();++j){
            edge &e=v[i][j];
            if(e.c>0&&m[i]<m[e.cd]){
                T d=dfs(e.cd,t,min(f,e.c));
                if(d){
                    e.c-=d;
                    v[e.cd][e.rv].c+=d;
                    return d;
                }
            }
        }
        return 0;
    }
    T mf(int s,int t){
        T fl=0;
        while(bfs(s,t)){
            it.assign(v.size(),0);
            T f=0;
            while((f=dfs(s,t,inf))>0) fl+=f;
        }
        return fl;
    }
};

