    last[y] = e;
    to[e] = x;
    c[e] = 0;
    f[e] = 0;
    e++;
}

/* find augmenting path in residual graph */
bool path(int u, int v)
{   queue<int> Q;
    int C, F;

    for(int i = 0; i < n; i++) p[i] = -1;
    Q.push(u);
    p[u] = u;
    while(!Q.empty())
    {   
        x = Q.front(), Q.pop();
        //cout<<x<<endl;

        if(x == v) return true;
        for(int i=last[x]; i!=-1; i=prevwow[i])
        {   
            //cout<<i<<endl;
            y = to[i];
            F = f[i];
            C = c[i];
            if(p[y] == -1 && C > F)
            {   p[y] = x;
                edge[y] = i;
                Q.push(y);
            }
        }
    }
    return false;
}

/* send flow through augmenting path */
int send(int u, int v)
{   bottleneck = INF;
    int x, y, index, sym;
    y = v;

    while(p[y] != y)
    {   x = p[y];
        index = edge[y];
        bottleneck = (bottleneck > c[index]-f[index] ? c[index]-f[index] : bottleneck);
        y = x;
    }

    y = v;
    while(p[y] != y)
    {   x = p[y];
        index = edge[y];
        f[index] += bottleneck;
        f[index^1] -= bottleneck;
        y = x;
    }

    return bottleneck;
}

