	int head=1,tail=1;
	memset(deep,255,sizeof(deep));
	deep[h[1]=x]=0;
	for (;head<=tail;head++){
		int Now=h[head];
		for (int p=now[Now],son=child[p];p;p=pre[p],son=child[p]){
			if (!~deep[son]&&val[p]){
				deep[h[++tail]=son]=deep[Now]+1;
				if (son==T)	return 1;
			}
		}
	}
	return 0;
}
int dfs(int x,int v){
	if (x==T)	return v;
	int res=0;
	for (int p=now[x],son=child[p];p;p=pre[p],son=child[p]){
		if (deep[son]>deep[x]&&val[p]){
			int k=dfs(son,min(v,val[p]));
			val[p]-=k,v-=k;
			val[p^1]+=k,res+=k;
			if (!v)	break;
		}
	}
	if (!res)	deep[x]=-1;
	return res;
}
