#include "bits/stdc++.h"
using namespace std;
typedef long long ll;

// 最大流O(V^2E)
struct Dinic {
private:
    struct edge {
        int to;
        ll cap;
        int rev;
        bool isrev;
        int idx;
    };

    vector< vector< edge > > graph;
    vector< int > min_cost, iter;


    bool bfs(int s, int t) {
        min_cost.assign(graph.size(), -1);
        queue< int > que;
        min_cost[s] = 0;
        que.push(s);
        while (!que.empty() && min_cost[t] == -1) {
            int p = que.front();
            que.pop();
            for (auto &e : graph[p]) {
                if (e.cap > 0 && min_cost[e.to] == -1) {
                    min_cost[e.to] = min_cost[p] + 1;
                    que.push(e.to);
                }
            }
        }
        return min_cost[t] != -1;
    }

    ll dfs(int idx, const int t, ll flow) {
        if (idx == t) return flow;
        for (int &i = iter[idx]; i < graph[idx].size(); i++) {
            edge &e = graph[idx][i];
            if (e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
                ll d = dfs(e.to, t, min(flow, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    graph[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
public:

    Dinic(int V) : graph(V) {}

    // from から to への容量capの有向辺
    void add_edge(int from, int to, ll cap, int idx = -1) {
        graph[from].push_back({to, cap, (int)graph[to].size(), false, idx});
        graph[to].push_back({from, 0, (int)graph[from].size() - 1, true, idx});
    }


    // from s to t
    ll max_flow(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            iter.assign(graph.size(), 0);
            ll f = 0;
            while ((f = dfs(s, t, 1e9 + 6)) > 0) flow += f;
        }
        return flow;
    }

    void output() {
        for (int i = 0; i < graph.size(); i++) {
            for (auto &e : graph[i]) {
                if (e.isrev) continue;
                auto &rev_e = graph[e.to][e.rev];
                cout << i << "->" << e.to << " (flow: " << rev_e.cap << "/" << e.cap + rev_e.cap << ")" << endl;
            }
        }
    }
};

int main() {
    constexpr long long LLINF = 1e18 + 1;
    int n, m; cin >> n >> m;
    Dinic g(n*m + n + m);
    int start, goal;
    for (int i = 0; i < n; i++) {
        string s; cin >> s;
        for (int j = 0; j < m; j++) {
            if (s[j] == 'o') {
                g.add_edge(i*m + j, n*m + n + j, LLINF);
                g.add_edge(n*m + n + j, i*m + j, 1);
                g.add_edge(i*m + j, n*m + i, LLINF);
                g.add_edge(n*m + i, i*m + j, 1);
            }
            else if (s[j] == 'S' || s[j] == 'T') {
                g.add_edge(i*m + j, n*m + n + j, LLINF);
                g.add_edge(n*m + n + j, i*m + j, LLINF);
                g.add_edge(i*m + j, n*m + i, LLINF);
                g.add_edge(n*m + i, i*m + j, LLINF);
            }

            if (s[j] == 'S') {
                start = i * m + j;
            }
            else if (s[j] == 'T') {
                goal = i * m + j;
            }
        }
    }
    if (start % m == goal % m || start / m == goal / m) {
        puts("-1");
        return 0;
    }
    cout << g.max_flow(start, goal) << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const int MAX_V = 256;
const int INF = 1e8;

char lake[MAX_V][MAX_V];

struct edge {
    int  to;
    int  cap;
    int  rev;
};

vector<vector<edge>> G;
vector<bool> used;

void add_edge(int from, int to, int cap) {
    G[from].emplace_back((edge){to, cap, (int)G[to].size()});
    G[to].emplace_back((edge){from, 0, (int)(G[from].size() - 1)});
}

int dfs(int v, int t, int f) {
    if(v == t) return f;

    used[v] = true;
    for(edge& e : G[v]) {
        if(!used[e.to] && e.cap > 0) {
            int d = dfs(e.to, t, min(f, e.cap));
            if(d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0;
    while(true) {
        fill(used.begin(), used.end(), false);
        int f = dfs(s, t, INF);
        if(f == 0) return flow;  // 増加路が無いならフロー値を返す
        flow += f;
    }
}

int main() {
    int H, W;
    cin >> H >> W;

    int S = H+W;
    int T = H+W+1;

    G.resize(H+W+2);
    used.resize(H+W+2);

    for(int i = 0; i < H; i++) {
        for(int j = 0; j < W; j++) {
            cin >> lake[i][j];

            if(lake[i][j] == 'o') {
                add_edge(i, H+j, 1);
                add_edge(H+j, i, 1);
            }

            if(lake[i][j] == 'S') {
                add_edge(S, i, INF);
                add_edge(S, H+j, INF);
            }

            if(lake[i][j] == 'T') {
                add_edge(i, T, INF);
                add_edge(H+j, T, INF);
            }
        }
    }

    int ans = max_flow(S, T);
    if(ans >= INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
}

#include<iostream>
