      }
};
template<typename T>
static inline constexpr decltype(auto) fix (T&& t) noexcept {
  return fixed_point<T>{forward<T>(t)};
}
template <typename T>
class ford_fulkerson {
  public:
    const T inf = numeric_limits<T>::max();
  private:
    struct edge {
      int to; T cap;
      weak_ptr<edge> rev;
      edge(int to, T cap) : to(to), cap(cap) {}
    };
    const int n, source, sink;
    vector<bool> ckd;
    vector<vector<shared_ptr<edge>>> grh;
    T dfs () {
      return fix ([&](auto dfs, int crr, int f) -> T {
        if (crr == sink) return f;
        ckd[crr] = true;
        for (auto& e : grh[crr]) {
          if (ckd[e->to] || !e->cap) continue;
          T d = dfs(e->to, min(f, e->cap));
          if (d) {
            e->cap -= d;
            e->rev.lock()->cap += d;
            return d;
          }
        }
        return 0;
      })(source, inf);
    }
  public:
    ford_fulkerson (int n, int source, int sink) :
      n(n), source(source), sink(sink), grh(n)
      {}
    void insert(int u, int v, T c) {
      auto e = make_shared<edge>(v, c);
      auto r = make_shared<edge>(u, 0);
      e->rev = r;
      r->rev = e;
      grh[u].push_back(e);
      grh[v].push_back(r);
    }
    T cal() {
      T ret = 0;
      while (true) {
        ckd.assign(n, false);
        T f = dfs();
        if (!f) return ret;
        ret += f;
      }
    }
};
int main() {
  cin.tie(0); cin.sync_with_stdio(false);
  int h, w;
  cin >> h >> w;
  vector<string> str(h);
  int si, sj, ti, tj;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      cin >> str[i][j];
      if (str[i][j] == 'S') si = i, sj = j;
      if (str[i][j] == 'T') ti = i, tj = j;
    }
  }
  int source = si, sink = ti;
  ford_fulkerson<int> ffk(h + w, source, sink);
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      char c = str[i][j];
      if (c == 'o') {
        ffk.insert(i,     h + j, 1);
        ffk.insert(h + j, i,     1);
      }
      if (c == 'S'|| c == 'T') {
        if (c == 'S') si = i, sj = j;
        else ti = i, tj = j;
        ffk.insert(i,     h + j, ffk.inf);
        ffk.insert(h + j, i,     ffk.inf);
      }
    }
  }
  if (si == ti || sj == tj) {
    cout << -1 << endl;
    return 0;
  }
  auto ret = ffk.cal();
  cout << ret << endl;
  return 0;
}

