int m, n, d[maxn], f[maxn][maxn], c[maxn][maxn], s, t;
char lake[maxn][maxn];
vector<int> a[maxn];

bool findPath(int s, int t) {
    queue<int> qu;
    qu.push(s);
    memset(d, 0, sizeof(d));
    while (qu.sz()) {
        int u = qu.front(); qu.pop();
        if (u==t) return true;
        REP(i, a[u].sz()) {
            int v = a[u][i];
            if (d[v]==0 && c[u][v]>f[u][v]) {
                d[v] = u;
                qu.push(v);
            }
        }
    }
    return false;
}

void incFlow() {
    int delta = inf;
    for (int v = t; v!=s; v = d[v]) delta = min(delta, c[d[v]][v] - f[d[v]][v]);
    for (int v = t; v!=s; v = d[v]) {
        f[d[v]][v] += delta;
        f[v][d[v]] -= delta;
    }
}

