            if (lake[i][j]=='o') c[i][m+j] = c[m+j][i] = 1;
            else c[i][m+j] = c[m+j][i] = inf;
        }
        if (lake[i][j]=='S')
            s = i;
        if (lake[i][j]=='T')
            t = m+j;
    }
    while (findPath(s, t))
        incFlow();
    int res = 0;
    REP(i, a[s].sz()) {
        res += f[s][a[s][i]];
    }
    if (res>=inf) printf("-1");
    else printf("%d", res);
}

