vector<bool> isused;

vector<int> getPath_rev(int now, int t)
{
	if(now == t){
		vector<int> res;
		res.push_back(t);
		return res;
	}
	for(int i = 0; i < nodeNum; i++){
		if(graph[now][i] <= 0 || isused[i]) continue;
		isused[i] = true;
		vector<int> res = getPath_rev(i, t);
		isused[i] = false;
		if(res.size() > 0){
			res.push_back(now);
			return res;
		}
	}
	return vector<int>();
}

int getMin(vector<int> path)
{
	int res = mod;
	for(int i = 0; i < path.size() - 1; i++){
		res = min(res, graph[path[i]][path[i + 1]]);
	}
	return res;
}

void updateGraph(vector<int> path, int cost)
{
	for(int i = 0; i < path.size() - 1; i++){
		int from = path[i];
		int to = path[i + 1];
		graph[from][to] -= cost;
		graph[to][from] += cost;
	}
}

int fordFulkerson(int s, int t)
{
	int ans = 0;
	isused = vector<bool>(nodeNum, false);
	isused[s] = true;
	vector<int> path = getPath_rev(s, t);
	reverse(path.begin(), path.end());
	while(path.size() > 0){
		int cost = getMin(path);
		updateGraph(path, cost);
		ans += cost;
		isused = vector<bool>(nodeNum, false);
		isused[s] = true;
		path = getPath_rev(s, t);
		reverse(path.begin(), path.end());
	}
	return ans;
}

