void add(ll from, ll to, ll cap) {
	g[from].push_back(edge { to, cap, (ll)g[to].size() });
	g[to].push_back(edge { from, (ll)0, (ll)g[from].size() - 1 });
}

ll dfs(ll v, ll t, ll f) {
	if (v == t)return f;
	used[v] = true;
	for (int i = 0;i < g[v].size();i++) {
		edge &e = g[v][i];
		if (!used[e.to] && e.cap > 0) {
			ll d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				g[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

ll max_flow(ll s, ll t) {
	ll flow = 0;
	for (;;) {
		fill(used, used + h*w + 2, 0);
		ll f = dfs(s, t, INF);
		if (f == 0)return flow;
		flow += f;
	}
}

