	inline void Add_Edge(int tot, int s, int t, int c)
	{
		To[tot] = t, Next[tot] = Head[s], Head[s] = tot, Cap[tot] = c;
	}
	inline void Add_Link(int s, int t, int c)
	{
		Total += 2, Add_Edge(Total, s, t, c), Add_Edge(Total ^ 1, t, s, 0);
	}
	int DFS(int u, int a)
	{
		if (u == T || a == 0)
			return a;
		int Ans(0);
		for (int &i = Cur[u], v, f;i;i = Next[i])
			if (Dist[v = To[i]] == Dist[u] + 1 && (f = DFS(v, min(a, Cap[i]))) > 0)
			{
				Ans += f, Cap[i] -= f, Cap[i ^ 1] += f;
				if ((a -= f) == 0)
					break;
			}
		return Ans;
	}
	bool BFS()
	{
		memset(Dist, 0, sizeof(Dist));
		queue<int> Q;
		Dist[S] = 1, Q.push(S);
		for (int u;Q.empty() == false;)
		{
			u = Q.front(), Q.pop();
			if (u == T)
				break;
			for (int i = Head[u], v;i;i = Next[i])
				if (Cap[i] && !Dist[v = To[i]])
					Dist[v] = Dist[u] + 1, Q.push(v);
		}
		return Dist[T];
	}
	int Dinic()
	{
		int Ans(0);
		while (BFS())
		{
			for (int i = 1;i <= V;++i)
				Cur[i] = Head[i];
			Ans += DFS(S, INF);
		}
		return Ans;
	}
}
