        {   
            x = p[y];
            index = edge[y];
            bottleneck = (bottleneck > c[index]-f[index] ? c[index]-f[index] : bottleneck);
            y = x;
        }

        y = v;
        while(p[y] != y)
        {   
            x = p[y];
            index = edge[y];
            f[index] += bottleneck;
            f[index^1] -= bottleneck;
            y = x;
        }

        return bottleneck;
    }

    void add(int x,int y, int w){
        e_x.push_back(x);
        e_y.push_back(y);
        e_w.push_back(w);
    }

    long long flow(int s, int t){
        long long res = 0;

        memset(last, -1, sizeof(last));

        e = 0;
        int tmp = e_x.size();
        for (int i=0;i<tmp;i++)
            __add(e_x[i], e_y[i], e_w[i]);

        while(path(s, t)){
            res += send(s, t);
        }
        return res;
    }
}

