constexpr int max_h = 100, max_w = 100, inf = 1e9;

struct Edge
{
    int dest, id, side;
    // weights[id][side] its weight of the edge
};

int h, w, s, t;
bool visited[max_h + max_w + 2];
string pond[max_h];
vector< array< int, 2 > > weights;
vector< Edge > graph[max_h + max_w + 2];

void add_edge(const int p, const int q, const int weight = 1, const bool directed = false)
{
    graph[p].push_back({q, (int)weights.size(), 0});
    graph[q].push_back({p, (int)weights.size(), 1});
    weights.push_back({weight, directed? 0 : weight});
}

vector< Edge > path;

int dfs(const int v, const int amount = inf)
{
    visited[v] = true;
    if (v == t)
        return amount;
    for (const auto& edge : graph[v])
        if (not visited[edge.dest] and weights[edge.id][edge.side])
        {
            path.push_back(edge);
            if (dfs(edge.dest, min(amount, weights[edge.id][edge.side])))
                return min(amount, weights[edge.id][edge.side]);
            path.pop_back();
        }
    return 0;
}

int flow()
{
    int result = 0;
    int amount = 0;
    while ((amount = dfs(s)))
    {
        for (const auto& edge : path)
        {
            weights[edge.id][edge.side] -= amount;
            weights[edge.id][1 - edge.side] += amount;
        }
        result += amount;
        path.clear();
        for (int i = 0; i < h + w + 2; ++i)
            visited[i] = false;
    }
    return result;
}

