		q.pop();
		for(ll i=0;i<g[x].size();i++)
		{
			ll id=g[x][i];
			ll nxt=e[id].b;
			if(e[id].flow<e[id].cap)
			{
				if(d[nxt]==-1)
				{
					d[nxt]=d[x]+1;
					q.push(nxt);
				}
			}
		}
