ll dfs(ll vv,ll flow)
{
	if(!flow) return 0;
	if(vv==t) return flow;
	for(;ptr[vv]<(ll)g[vv].size();++ptr[vv])
	{
		ll id=g[vv][ptr[vv]],
			to=e[id].b;
		if(d[to]!=d[vv]+1) continue;
		ll pushed=dfs(to,min(flow,e[id].cap-e[id].flow));
		if(pushed)
		{
			e[id].flow+=pushed;
			e[id^1].flow-=pushed;
			return pushed;
		}
	}
	return 0;
}
