  inline void Init() {
    memset(fir, 0, sizeof fir);
  }

  inline void Add(int x, int y, int cto, int cback) {
    static int cnt = 1;
    e[++ cnt] = (edge){fir[x], y, cto};
    fir[x] = cnt;
    e[++ cnt] = (edge){fir[y], x, cback};
    fir[y] = cnt;
  }

  inline bool bfs() {
    queue <int> Q;
    memset(dis, -1, sizeof dis);
    dis[T] = 1;
    Q.push(T);
    int x;
    while (!Q.empty()) {
      x = Q.front();
      Q.pop();
      travel(x, i)
	if (e[i ^ 1].cap > 0 && dis[e[i].to] == -1) {
	  dis[e[i].to] = dis[x] + 1;
	  Q.push(e[i].to);
	}
    }
    return dis[S] != -1;
  }

  inline int dfs(int x, int flow) {
    if (!flow || x == T) return flow;
    int tmp, res = 0;
    travel(x, i)
      if (dis[e[i].to] == dis[x] - 1) {
	tmp = dfs(e[i].to, min(flow, e[i].cap));
	flow -= tmp;
	res += tmp;
	e[i].cap -= tmp;
	e[i ^ 1].cap += tmp;
	if (!flow) return res;
      }
    dis[x] = -1;
    return res;
  }

  inline int MaxFlow() {
    int ret = 0;
    while (bfs()) ret += dfs(S, INF);
    return ret;
  }
}
