vector<bool> isused;

vector<int> getPath_rev(int now, int t)
{
	if(now == t){
		vector<int> res;
		res.push_back(t);
		return res;
	}
	for(int i = 0; i < nodeNum; i++){
		if(graph[now][i] <= 0 || isused[i]) continue;
		isused[i] = true;
		vector<int> res = getPath_rev(i, t);
		if(res.size() > 0){
			res.push_back(now);
			return res;
		}
	}
	return vector<int>();
}

int getMin(vector<int> path_rev)
{
	int res = mod;
	for(int i = path_rev.size() - 1; i > 0; i--){
		int from = path_rev[i];
		int to = path_rev[i - 1];
		res = min(res, graph[from][to]);
	}
	return res;
}

void updateGraph(vector<int> path_rev, int cost)
{
	for(int i = path_rev.size() - 1; i > 0; i--){
		int from = path_rev[i];
		int to = path_rev[i - 1];
		graph[from][to] -= cost;
		graph[to][from] += cost;
	}
}

int fordFulkerson(int s, int t)
{
	int ans = 0;
	isused = vector<bool>(nodeNum, false);
	isused[s] = true;
	vector<int> path = getPath_rev(s, t);
	while(path.size() > 0){
		int cost = getMin(path);
		updateGraph(path, cost);
		ans += cost;
		isused = vector<bool>(nodeNum, false);
		isused[s] = true;
		path = getPath_rev(s, t);
	}
	return ans;
}

