inline int id1(int i, int j) {
    return (i * m + j) * 2;
}

inline int id2(int i, int j) {
    return (i * m + j) * 2 + 1;
}

void solve() {
    cin >> n >> m;
    FOR(i, 0, n) {
        string s; cin >> s;
        FOR(j, 0, m) a[i][j] = s[j];
    }
    int s, t;
    FOR(i, 0, n) FOR(j, 0, m) {
        if (a[i][j] == 'S') {
            s = id1(i, j);
        }
        if (a[i][j] == 'T') {
            t = id2(i, j);
        }
    }
    dinic.init(n * m * 2, s, t);
    FOR(i, 0, n) FOR(j, 0, m) if (a[i][j] != '.') {
        FOR(k, 0, m) if (k != j && a[i][k] != '.') {
            dinic.add(id2(i, j), id1(i, k), INF, 0);
        }
        FOR(k, 0, n) if (k != i && a[k][j] != '.') {
            dinic.add(id2(i, j), id1(k, j), INF, 0);
        }
        if (id1(i, j) != s && id2(i, j) != t) {
            dinic.add(id1(i, j), id2(i, j), 1, 0);
        }
        else {
            dinic.add(id1(i, j), id2(i, j), INF, 0);
        }
    }
    int ans = dinic.maxflow();
    if (ans == INF) ans = -1;
    cout << ans << "\n";
}

