namespace network
{
	const int INF=INT_MAX>>1;
	const int V=N*N<<1;
	const int E=(N<<1|1)*V<<1;

	int tov[E],nxt[E],f[E],v[E],r[E];
	int last[V],lab[V];
	int S,T,tot;
	queue<int> q;

	inline void insert(int x,int y,int full,int rev){tov[++tot]=y,f[tot]=full,r[tot]=tot+rev,nxt[tot]=last[x],last[x]=tot;}
	inline void addedge(int x,int y,int full){insert(x,y,full,1),insert(y,x,0,-1);}

	inline bool relabel()
	{
		for (int x=1;x<=n*m<<1;++x) lab[x]=0;
		for (lab[S]=1,q.push(S);!q.empty();q.pop())
			for (int x=q.front(),i=last[x],y;i;i=nxt[i])
				if (!lab[y=tov[i]]&&f[i]-v[i]) lab[y]=lab[x]+1,q.push(y);
		return lab[T];
	}

	int aug(int x,int flow)
	{
		if (x==T) return flow;
		int ret=0;
		for (int i=last[x],y;i;i=nxt[i])
			if (lab[y=tov[i]]==lab[x]+1&&f[i]-v[i])
			{
				int tmp=aug(y,min(flow,f[i]-v[i]));
				if (tmp)
				{
					v[i]+=tmp,v[r[i]]-=tmp;
					ret+=tmp,flow-=tmp;
					if (!flow) break;
				}else lab[y]=0;
			}
		return ret;
	}

	int maxflow()
	{
		int ret=0;
		for (;relabel();) for (int tmp;tmp=aug(S,INF);ret+=tmp);
		return ret;
	}

	bool build()
	{
		for (int i=1;i<=n;++i)
			for (int j=1;j<=m;++j)
				if (pic[i][j]!='.')
				{
					int x=(i-1)*m+j;
					addedge((x<<1)-1,x<<1,1);
					if (pic[i][j]=='S') S=x<<1;
					if (pic[i][j]=='T') T=(x<<1)-1;
					for (int k=1;k<=n;++k)
						if (i!=k&&pic[k][j]!='.')
						{
							int y=(k-1)*m+j;
							addedge(x<<1,(y<<1)-1,INF);
						}
					for (int k=1;k<=m;++k)
						if (j!=k&&pic[i][k]!='.')
						{
							int y=(i-1)*m+k;
							addedge(x<<1,(y<<1)-1,INF);
						}
				}
		int src=S+1>>1,tar=T+1>>1;
		int srcx=(src-1)/m+1,srcy=(src-1)%m+1;
		int tarx=(tar-1)/m+1,tary=(tar-1)%m+1;
		return srcx!=tarx&&srcy!=tary;
	}
};

