void solve() {
	M.resize(H);
	for (int y = 0; y < H; y++) {
		M[y].resize(W);
		for (int x = 0; x < W; x++) {
			if (A[y][x] == 'S') {
				S = PI(y, x);
			}
			if (A[y][x] == 'T') {
				T = PI(y, x);
			}
			if (A[y][x] == '.') {
				M[y][x] = 0;
			}
			else {
				M[y][x] = 1;
			}
		}
	}
	if (S.first == T.first || S.second == T.second) {
		cout << "-1\n";
		return;
	}
	Dinic<LL> D(2 * H * W);
	for (int Y = 0; Y < H; Y++) {
		for (int X = 0; X < W; X++) {
			if (M[Y][X] == 0)continue;
			int C = conv(Y, X);
			D.AddEdge(2 * C, 2 * C + 1, 1);
			for (int y = 0; y < H; y++) {
				if (y == Y)continue;
				if (M[y][X] == 0)continue;
				int c = conv(y, X);
				D.AddEdge(2*C+1,2*c, 1e6);
			}
			for (int x = 0; x < W; x++) {
				if (x == X)continue;
				if (M[Y][x] == 0)continue;
				int c = conv(Y, x);
				D.AddEdge(2*C+1,2*c, 1e6);
			}
		}
	}
	int maxf = D.MaxFlow(2 * conv(S.first, S.second) + 1, 2 * conv(T.first, T.second));
	cout << maxf << "\n";
}

