		{
			if (s[j] == 'o')
				addEdge(i, j + n, 1, 1);
			else if (s[j] == 'S')
			{
				addEdge(vS, i + 0, INF);
				addEdge(vS, j + n, INF);
			}
			else if (s[j] == 'T')
			{
				addEdge(i + 0, vT, INF);
				addEdge(j + n, vT, INF);
			}
		}
	}

	int tot_flow = 0;
	while (tot_flow < INF && calc_dist())
		tot_flow += dfs(vS, INF);

	if (tot_flow >= INF)
		cout << -1 << endl;
	else
		cout << tot_flow << endl;

	return 0;
}

