void bfs(int s){ 
    head=tail=0; 
    q[tail++]=s; level[s]=1; 
    while(head!=tail){ 
        int u=q[head]; 
        for(int i=h[u];i;i=g[i].next){ 
            if(!level[g[i].to]&&g[i].cap){ 
                level[g[i].to]=level[u]+1; 
                q[tail++]=g[i].to; 
            } 
        } 
        head++; 
    } 
} 
