				G.add(o + N + i, in[j][i], 1000000000);
			}
			else if (a[j][i] == 'S')
				G.add(0, o + N + i, 1000000000);
			else if (a[j][i] == 'T')
				G.add(o + N + i, G.N - 1, 1000000000);
	int ans = G();
	printf("%d\n", ans > N * M ? -1 : ans);
	return 0;
}

