const int N=105,Node=N*N*2,Inf=1e9+10;

struct Edge{ int to,next,flow; }way[N*N<<3];

int n,m,s,t,node,nd[N][N][2],mp[N][N],num[Node],tot;

void Build(int u,int v,int flow) { way[++tot]=(Edge){v,num[u],flow}; num[u]=tot; }

void Add(int u,int v,int flow) {
	Build(u,v,flow);
	Build(v,u,0);
}

void Init() {
	scanf("%d%d",&n,&m);
	node=1;
	for (int i=0;i<n;++i)
		for (int j=0;j<m;++j) {
			char ch=getchar();
			while (ch!='.' && ch!='o' && ch!='S' && ch!='T') ch=getchar();
			if (ch=='S') nd[i][j][1]=node,s=node++;
			else if (ch=='T') nd[i][j][0]=node,t=node++;
			else nd[i][j][0]=node++,nd[i][j][1]=node++;
			if (ch=='.') mp[i][j]=0;else mp[i][j]=1;
		}
}

int dis[Node],vis[Node],que[Node];
bool Bfs(int s,int t) {
	for (int i=0;i<node;++i) dis[i]=Inf,vis[i]=0;
	int head=0,tail=0; que[++tail]=s; vis[s]=1;
	while (head!=tail) {
		int u=que[++head];
		for (int i=num[u];i;i=way[i].next) if (way[i].flow) {
			int v=way[i].to;
			if (!vis[v]) {
				dis[v]=dis[u]+1;
				vis[v]=1; 
				que[++tail]=v;
			}
		}
	}
	return dis[t]!=Inf;
}

int cur[Node];
int Dfs(int x,int a,int t) {
	if (!a || x==t) return a;
	int flow=0,f;
	for (int &i=cur[x];i;i=way[i].next) {
		int v=way[i].to;
		if (dis[v]==dis[x]+1 && (f=Dfs(v,min(a,way[i].flow),t))>0) {
			flow+=f; a-=f;
			way[i].flow-=f;
			way[i^1].flow+=f;
			if (!a) break;
		}
	}
	return flow;
}

int Maxflow(int s,int t) {
	int flow=0;
	while (Bfs(s,t)) {
		for (int i=0;i<node;++i) cur[i]=num[i];
		flow+=Dfs(s,Inf,t);
	}
	if (flow==Inf) return -1;
	else return flow;
}

int row[N],col[N];
void Solve() {
	tot=1;
	for (int i=0;i<n;++i) {
		row[i]=node++;
		for (int j=0;j<m;++j) if (mp[i][j]) {
			if (nd[i][j][1]) Add(nd[i][j][1],row[i],Inf);
			if (nd[i][j][0]) Add(row[i],nd[i][j][0],Inf);
		}
	}
	for (int j=0;j<m;++j) {
		col[j]=node++;
		for (int i=0;i<n;++i) if (mp[i][j]) {
			if (nd[i][j][1]) Add(nd[i][j][1],col[j],Inf);
			if (nd[i][j][0]) Add(col[j],nd[i][j][0],Inf);
		}
	}
	for (int i=0;i<n;++i)
		for (int j=0;j<m;++j) if (mp[i][j] && nd[i][j][0] && nd[i][j][1])
			Add(nd[i][j][0],nd[i][j][1],1);
	printf("%d\n",Maxflow(s,t));
}

int main() {
	Init();
	Solve();
	return 0;
}

