#define MAX_V 5050
struct edge { int to, cap, rev;edge(int t, int c, int r) : to(t), cap(c), rev(r) {}};

vector<edge> g[MAX_V];
int level[MAX_V];
int iter[MAX_V];

void addEdge(int from, int to, int cap = 1, bool undir = 0) {
    g[from].eb(to, cap, g[to].size());
    g[to].eb(from, undir ? cap : 0, g[from].size() - 1);
}

void bfs(int s) {
    memset(level, -1, sizeof(level));
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int v = que.front();
        que.pop();
        for (int i = 0; i < g[v].size(); i++) {
            edge &e = g[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < g[v].size(); i++) {
        edge &e = g[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                g[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}
//dinic
int maxFlow(int s, int t) {
    int flow = 0;
    for (;;) {
        bfs(s);
        if (level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
}


