}

int dp[20005];
int iter[20005];
edge* used[20005];
const int INF = 1 << 14;

int maxFlow(int s, int t) {
  int ret = 0;
  for(int qq = 1; ret < INF; qq++) {
    queue<int> q;
    q.push(s);
    dp[s] = INF;
    dp[t] = 0;
    while(!q.empty() && dp[t] == 0) {
      int curr = q.front();
      q.pop();
      for(edge* out: edges[curr]) {
        if(out->cap == 0) continue;
        if(qq == iter[out->to]) continue;
        dp[out->to] = min(dp[curr], out->cap);
        iter[out->to] = qq;
        used[out->to] = out;
        q.push(out->to);
      }
    }
    if(dp[t] == 0) break;
    ret += dp[t];
    int curr = t;
    while(curr != s) {
      int par = used[curr]->rev->to;
      used[curr]->cap -= dp[t];
      used[curr]->rev->cap += dp[t];
      curr = par;
    }
  }
  return ret;
}

