const int maxN = 3e2 + 5;
const int maxM = 1e6 + 5;
const llint INF = 1e9 + 7;

struct edge {
	int u, v, f;
};

class maxFlow {
public:
	int S, T;
	int N;
	vector<edge> E;
	vector<int> vertex[maxN];
	int ptr[maxN];
	int d[maxN];
	int q[maxM], qh, qt;

	void clear(int n) {
		N = n;
		E.clear();
		for (int i = 0; i < maxN; ++i) {
			vertex[i].clear();
			ptr[i] = 0;
		}
	}

	void addEdge2(int u, int v, int cap) {
		vertex[u].push_back(E.size());
		E.push_back({u, v, cap});
		vertex[v].push_back(E.size());
		E.push_back({v, u, 0});
	}

	void addEdge(int u, int v, int cap) {
		addEdge2(u, v, cap);
		addEdge2(v, u, cap);
		//cout << u << " " << v << " " << endl;
	}

	int getMax(int _s, int _t) {
		S = _s, T = _t;
		int res = 0;

		for (;;) {
			for (int i = 0; i <= N; ++i) {
				ptr[i] = 0;
				d[i] = -1;
			}
			if (!bfs()) break;
			while (int pushed = dfs(S, INF)) {
				res = res + pushed;
			}
		}
		return res;
	}

private:
	bool bfs() {
		d[S] = 0;
		qh = qt = 0;
		q[qt++] = S;

		while (qh < qt && d[T] == -1) {
			int u = q[qh++];
			//db(u);
			for (int i = 0; i < vertex[u].size(); ++i) {
				int id = vertex[u][i];
				int v = E[id].v;
				int f = E[id].f;
				//db(v); db(f);
				if (f > 0 && d[v] == -1) {
					d[v] = d[u] + 1;
					q[qt++] = v;
				}
			}
		}

		return d[T] != -1;
	}

	int dfs(int u, int flow) {
		if (flow == 0) return flow;
		if (u == T) return flow;

		for (; ptr[u] < (int) vertex[u].size(); ++ptr[u]) {
			int id = vertex[u][ptr[u]];
			int v = E[id].v;
			int f = E[id].f;

			if (d[v] != d[u] + 1) continue;

			int pushed = dfs(v, min(flow, f));
			if (pushed) {
				E[id].f -= pushed;
				E[id^1].f += pushed;
				return pushed;
			}
		}

		return 0;
	}
} G;

