struct edge {
	ll to;
	ll cap;
	ll rev;
};

vector<edge> G[MAX_V2 + 10];
bool used[MAX_V2 + 10];

void append_edge(ll from, ll to, ll cap) {
	G[from].emplace_back(edge{ to, cap, (ll)G[to].size() });
	G[to].emplace_back(edge{ from, 0, (ll)G[from].size() - 1 });
}

int dfs(ll v, ll t, ll f) {
	if (v == t) return f;
	used[v] = true;
	for (ll i = 0; i < G[v].size(); i++) {
		auto& e = G[v][i];
		if (!used[e.to] && (0 < e.cap)) {
			int d = dfs(e.to, t, min(f, e.cap));
			if (0 < d) {
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

int max_flow(ll s, ll t) {
	ll flow = 0;
	for (;;) {
		memset(used, 0, sizeof(used));
		ll f = dfs(s, t, numeric_limits<ll>::max());
		if (f == 0) return flow;
		flow += f;
	}
}

