int dfs(int s, int t, int f) {
    used[s] = true;
    for (int u = 0; u < h + w; u++) {
        int c = cap[s][u];
        if (used[u] || c == 0) continue;
        if (u == t) {
            f = min(f, c);
            cap[s][u] -= f;
            cap[u][s] += f;
            return f;
        }
        int f1 = dfs(u, t, min(f, c));
        if (f1 > 0) { cap[s][u] -= f1; cap[u][s] += f1; return f1; }
    }
    return 0;
}

