bool dinic_BFS(){
    fill(dist, dist + n + 2, -1);
    dist[S] = 0;
    int qt = 0;
    q[qt++] = S;
    for (int qh = 0; qh < qt; qh++)
    {
        int u = q[qh];
        for (int j = 0; j < G[u].size(); j++)
        {
            Edge &e = G[u][j];
            int v = e.to;
            if (dist[v] < 0 && e.f < e.cap)
            {
                dist[v] = dist[u] + 1;
                q[qt++] = v;
            }
        }
    }
    return dist[T] >= 0;
}

int dinic_DFS(int u, int f)
{
    if (u == T || f == 0) return f;
    for (int &i = work[u]; i < G[u].size(); i++)
    {
        Edge &e = G[u][i];
        if (e.cap <= e.f) continue;
        int v = e.to;
        if (dist[v] == dist[u] + 1)
        {
            int df = dinic_DFS(v, min(f, e.cap - e.f));
            if (df > 0)
            {
                e.f += df;
                G[v][e.rev].f -= df;
                return df;
            }
        }
    }
    return 0;
}

int maxFlow()
{
