#include <bits/stdc++.h>
using namespace std;

struct Network
{
    int N = 2, source = 0, sink = 1;
    struct Edge { int source, target, id, reverse; };
    vector<vector<Edge>> adjacency_lists;
    vector<int> capacities, flows;

    Network() : adjacency_lists(2) {}

    int add_vertex()
    {
        adjacency_lists.push_back({});
        return N++;
    }

    void add_edge(const int source, const int target, const int capacity)
    {
        if (source == target) return;
        const auto id = int(capacities.size());
        const auto reverse = id+1;
        adjacency_lists[source].push_back({source, target, id, reverse});
        adjacency_lists[target].push_back({target, source, reverse, id});
        capacities.insert(end(capacities), {capacity, 0});
        flows.insert(end(flows), {0, 0});
    }

    int maxflow()
    {
        auto seen = vector<bool>(N);
        const function<int(int, int)> dfs = [&](const int v, const int flow)
        {
            if (v == sink) return flow;

            if (seen[v]) return 0;
            else seen[v] = true;

            for (const auto e : adjacency_lists[v])
            {
                const auto residual = capacities[e.id] - flows[e.id];
                if (residual == 0) continue;
                if (const auto x = dfs(e.target, min(flow, residual)))
                {
                    flows[e.id] += x;
                    flows[e.reverse] -= x;
                    return x;
                }
            }
            return 0;
        };

        auto flow = 0;
        while (true)
        {
            fill(begin(seen), end(seen), false);
            const auto delta = dfs(source, numeric_limits<int>::max());
            if (delta > 0) flow += delta;
            else break;
        }
        return flow;
    }
};

int main()
{
    int R, C; cin >> R >> C;

    auto network = Network();

    auto rows = vector<int>(R);
    for (auto r = 0; r < R; r++)
        rows[r] = network.add_vertex();

    auto columns = vector<int>(C);
    for (auto c = 0; c < C; c++)
        columns[c] = network.add_vertex();

    const auto infinity = R + C;
    for (auto r = 0; r < R; r++)
    {
        string row; cin >> row;
        for (auto c = 0; c < C; c++)
        {
            if (row[c] == '.') continue;
            if (row[c] == 'S') network.source = rows[r];
            if (row[c] == 'T') network.sink = columns[c];
            const auto capacity = row[c] == 'o' ? 1 : infinity;
            network.add_edge(rows[r], columns[c], capacity);
            network.add_edge(columns[c], rows[r], capacity);
        }
    }

    const auto mincut = network.maxflow();
    cout << (mincut >= infinity ? -1 : mincut) << endl;
}

