}
int Aug(int x, int a) {
	if (x == T) return a;
	int aug = 0, delta;
	for (int &i = cur[x]; i < Eid[x].size(); i++) {
		Edge &e = E[Eid[x][i]];
		if (e.c && d[e.v] == d[x] + 1) {
			delta = Aug(e.v, min(a, e.c));
			if (delta) {
				e.c -= delta;
				E[Eid[x][i] ^ 1].c += delta;
				aug += delta;
				if (!(a -= delta)) break;
			}
		}
	}
	if (!aug) d[x] = -1;
	return aug;
}
int MaxFlow() {
	int flow = 0;
	while(BFS()) {
		for (int i = 0; i <= T; i++) cur[i] = 0;
		flow += Aug(S, inf);	
	}
	return flow;
}

