    dis[S]=0;q.push(S);
    while(!q.empty()){
        int u=q.front();q.pop();
        for(int i=head[u],v;i;i=e[i].nxt)
            if(e[i].w&&dis[v=e[i].to]>dis[u]+1)
                dis[v]=dis[u]+1,q.push(v);
    }
    return dis[T]<inf;
}
int dfs(int u,int flow){
    if(u==T||!flow)return flow;
    int now=0;
    for(int i=head[u],v;i;i=e[i].nxt)
        if(e[i].w&&dis[v=e[i].to]==dis[u]+1){
            int f=dfs(v,min(flow-now,e[i].w));
            e[i].w-=f;e[i^1].w+=f;now+=f;
        }
    if(!now)dis[u]=-1;
    return now;
}
