const int siz = 2e2 + 10;
const int SIZ = 1e6 + 10;
const int mod = 1e9 + 7;
const int maxx = 2e9;
const int MAXX = 1e18;
const string file = "1";

vector <vector <int> > edges;
int cap[siz][siz], prv[siz];
int s, t;

void add(int u, int v, int c) {
    edges[u].push_back(v);
    edges[v].push_back(u);
    cap[u][v] = c;
    cap[v][u] = c;
}

int bfs() {
    queue <ii> qu;
    memset(prv, -1, sizeof(prv));
    prv[s] = 0;
    qu.push(ii(s, MAXX));

    while (!qu.empty()) {
        int u, f;
        tie(u, f) = qu.front();
        qu.pop();

        if (u == t) {
            return f;
        }

        for (auto &v : edges[u]) {
            if (prv[v] == -1 && cap[u][v]) {
                prv[v] = u;
                qu.push(ii(v, min(f, cap[u][v])));
            }
        }
    }
    return 0;
}

int maxflow() {
    int f = 0;
    while (int nf = bfs()) {
        f += nf;
        int u = t;
        while (u != s) {
            int v = prv[u];
            cap[v][u] -= nf;
            cap[u][v] += nf;
            u = v;
        }
    }
    return f;
}

