struct Ford_Fulkerson{

	struct f_edge {
		ll to;
		ll cap;
		ll fl;
		ll rev;//反対方向の辺の添え字
	};


	ll N;
	ll s, t;
	vector<vector<edge>> g;//グラフ片方向にのみ張る、flowで双方向に構築
	vector<vector<f_edge>> flow;
	ll maxflow;

	vector<bool> see;
	ll dfs(ll v, ll x) {
		see[v] = 1;

		if (v == t) { return x; }

		rep(i,flow[v].size()) {
			auto e = flow[v][i];

			if (see[e.to] == 1) { continue; }
			if (e.cap == e.fl) { continue; }

			ll y = min(x, e.cap - e.fl);

			y = dfs(e.to, y);
			if (y == 0) { continue; }

			flow[v][i].fl += y;
			flow[e.to][e.rev].fl -= y;
			return y;		}

		return 0;
	}

	Ford_Fulkerson(ll N0, vector<vector<edge>> g0, ll s0, ll t0) {
		N = N0;
		g = g0;
		s = s0;
		t = t0;

		flow.resize(N + 1);
		repn(v, N) {
			for (edge e : g[v]) {
				ll w = e.to;
				flow[v].push_back({ w,e.d,0,g[w].size() });
				flow[w].push_back({ v,e.d,0,g[v].size() - 1 });
			}
		}

		maxflow = 0;

		if (s == t) { maxflow = INF; return; }

		while (1) {
			see.assign(N + 1, 0);
			ll f = dfs(s, INF);
			if (f == 0) {return; }
			maxflow += f;
		}

		return;

	}	
};



int main() {

	ll H, W;
	cin >> H >> W;

	vector<vector<char>> a(H + 1, vector<char>(W + 1));

	repn(i, H)repn(j, W) cin >> a[i][j];

	vector<vector<edge>> g(H + W + 1);
	ll s;
	ll t;

	repn(i, H)repn(j, W) {
		if (a[i][j] == 'o') { g[i].push_back({ 0,i,H + j,1 }); }
		else if (a[i][j] == 'S') { g[i].push_back({ 0,i,H + j,INF }); s = i; }
		else if (a[i][j] == 'T') { g[i].push_back({ 0,i,H + j,INF }); t = H + j; }

	}

	Ford_Fulkerson ff(H+W, g, s, t);
	ll ans = ff.maxflow;
	if (ans == INF) { ans = -1; }
	cout << ans << endl;



	system("PAUSE");
}

