const int inf = 1e9;

struct Network {
    static const int maxv = 1e5;
    static const int maxe = 1e6;
    struct Edge { int u,v,cap,next,tag; } E[maxe];
    int ne, head[maxv], head_[maxv], dis[maxv], Q[maxv], du[maxv];

    void init()
    {
        ne = 0;
        memset(head,-1,sizeof(head));
        memset(du,0,sizeof(du));
    }

    void addedge(const int u, const int v, const int c, const int tag=0)
    {
        assert(0 <= u && u < maxv && 0 <= v && v < maxv);
        assert(ne < maxe-1);
        E[ne].u = u; E[ne].v = v; E[ne].cap = c; E[ne].tag = tag;
        E[ne].next = head[u]; head[u] = ne++;
        E[ne].u = v; E[ne].v = u; E[ne].cap = 0; E[ne].tag = 0;
        E[ne].next = head[v]; head[v] = ne++;
    }

    bool bfs(const int src, const int sink)
    {
        memset(dis,-1,sizeof(dis));
        int front,end; front = 0; end = 1; Q[front] = src; dis[src] = 0;
        while (front != end) {
            const int u = Q[front++];
            for (int i = head[u]; i != -1; i = E[i].next) {
                const int v = E[i].v;
                if (E[i].cap && dis[v] == -1) {
                    dis[v] = dis[u]+1; Q[end++] = v;
                }
            }
        }
        return dis[sink] != -1;
    }

    int dfs(const int u, const int sink, const int flow)
    {
        if (u == sink)
            return flow;
        for (int& i = head_[u]; i != -1; i = E[i].next) {
            const int v = E[i].v;
            const int minf = min(E[i].cap, flow);
            int f;
            if (E[i].cap && dis[v]==dis[u]+1 && (f=dfs(v,sink,minf))) {
                E[i].cap -= f; E[i^1].cap += f;
                return f;
            }
        }
        return 0;
    }

    int dinic(const int src, const int sink)
    {
        int flow = 0;
        while (bfs(src,sink)) {
            memcpy(head_,head,sizeof(head));
            int f;
            while (f = dfs(src,sink,inf)) {
                flow += f;
                flow = min(flow,inf);
            }
        }
        return flow;
    }

    int maxflow(const int src, const int sink)
    { return dinic(src,sink); }
} G;

