struct dinit_graph
{
	int n,s,t;
	struct flow_edge
	{
		int v,u;
		ll cap,flow=0ll;
		flow_edge(int v,int u,ll cap):v(v),u(u),cap(cap){}
	};
	vector<vi> graph;
	vector<flow_edge> edge;
	vi lv;
	dinit_graph(int n=0,int s=0,int t=0):n(n),s(s),t(t)
	{
		graph.assign(n+1,vi());
		edge.clear();
	}
	void add(int v,int u,ll w)
	{
		graph[v].push_back(edge.size());
		edge.emplace_back(v,u,w);
		graph[u].push_back(edge.size());
		edge.emplace_back(u,v,0ll);
	}
	bool bfs()
	{
		lv.assign(n+1,-1);
		lv[s]=0;
		queue<int> q;
		q.push(s);
		while(!q.empty())
		{
			int v=q.front();q.pop();
			for(auto id:graph[v])
			{
				int u = edge[id].u;
				if(edge[id].cap>edge[id].flow&&lv[u]==-1)
				{
					lv[u]=lv[v]+1;
					q.push(u);
				}
			}
		}
		if(lv[t]==-1)	return false;
		return true;
	}
	ll dfs(int v,ll push)
	{
		if(v==t)	return push;
		if(push==0ll)	return push;
		for(auto id:graph[v])
		{
			int u = edge[id].u;
			if(lv[u]==lv[v]+1&&edge[id].cap>edge[id].flow)
			{
				ll res = dfs(u,min(push,edge[id].cap-edge[id].flow));
				if(res!=0ll)
				{
					edge[id].flow += res;
					edge[id^1].flow -= res;
					return res;
				}
			}
		}
		return 0ll;
	}
	ll dinic()
	{
		ll mx = 0ll,push;
		while(1)
		{
			if(bfs()==false)	break;
			while((push=dfs(s,inf))!=0ll)
			{
				mx += push;
			}
		}
		return mx;
	}
