bool bfs(){
	memset(level,-1,sizeof level);
	static queue<int> Q;
	level[S]=0;
	Q.push(S);
	while(!Q.empty()){
		int x=Q.front();
		Q.pop();
		for(int i=g[x];~i;i=e[i].next)
			if(e[i].w && level[e[i].to]==-1){
				level[e[i].to]=level[x]+1;
				Q.push(e[i].to);
			}
	}
	return level[T]!=-1;
}

int dfs(int x,int delta){
	if(x==T) return delta;
	int res=0;
	for(int i=g[x];~i;i=e[i].next)
		if(level[e[i].to]==level[x]+1 && e[i].w){
			int temp=dfs(e[i].to,min(delta,e[i].w));
			delta-=temp;
			res+=temp;
			e[i].w-=temp;
			e[i^1].w+=temp;
			if(!delta) return res;
		}
	return res;
}

