using namespace std;

typedef long long ll;
typedef vector<int> VI;
typedef vector<VI> VVI;

const int INF = 1000000000;

struct MaxFlow {
  int N;
  VVI cap, flow;
  VI dad, Q;

  MaxFlow(int N) :
    N(N), cap(N, VI(N)), flow(N, VI(N)), dad(N), Q(N) {}

  void AddEdge(int from, int to, int cap) {
    this->cap[from][to] += cap;
  }

  int BlockingFlow(int s, int t) {
    fill(dad.begin(), dad.end(), -1);
    dad[s] = -2;

    int head = 0, tail = 0;
    Q[tail++] = s;
    while (head < tail) {
      int x = Q[head++];
      for (int i = 0; i < N; i++) {
        if (dad[i] == -1 && cap[x][i] - flow[x][i] > 0) {
          dad[i] = x;
          Q[tail++] = i;
        }
      }
    }

    if (dad[t] == -1) return 0;

    int totflow = 0;
    for (int i = 0; i < N; i++) {
      if (dad[i] == -1) continue;
      int amt = cap[i][t] - flow[i][t];
      for (int j = i; amt && j != s; j = dad[j])
        amt = min(amt, cap[dad[j]][j] - flow[dad[j]][j]);
      if (amt == 0) continue;
      flow[i][t] += amt;
      flow[t][i] -= amt;
      for (int j = i; j != s; j = dad[j]) {
        flow[dad[j]][j] += amt;
        flow[j][dad[j]] -= amt;
      }
      totflow += amt;
    }

    return totflow;
  }

  int GetMaxFlow(int source, int sink) {
    int totflow = 0;
    while (int flow = BlockingFlow(source, sink))
      totflow += flow;
    return totflow;
  }
};

int main(){
    int H, W;
    cin >> H >> W;

    MaxFlow mf(H+W+2);


    for(int y=0;y<H;y++){
        string row;
        cin >> row;
        for(int x=0;x<W;x++){
            if(row[x]=='o'){
                mf.AddEdge(2+y, 2+H+x, 1);
                mf.AddEdge(2+H+x, 2+y, 1);
            }else if(row[x]=='S'){
                mf.AddEdge(0, 2+y, INF);
                mf.AddEdge(2+y, 0, INF);
                mf.AddEdge(0, 2+H+x, INF);
                mf.AddEdge(2+H+x, 0, INF);
            }else if(row[x]=='T'){
                mf.AddEdge(1, 2+y, INF);
                mf.AddEdge(2+y, 1, INF);
                mf.AddEdge(1, 2+H+x, INF);
                mf.AddEdge(2+H+x, 1, INF);
            }
        }
    }

    ll ans = mf.GetMaxFlow(0, 1);
    if (ans >= INF){
        ans = -1;
    }
    cout << ans << endl;

    return 0;
}

