struct dinic_edge
{
  int to; Value cap; int rev;
  dinic_edge(int to, Value cap, int rev): to(to), cap(cap), rev(rev){}
};

template <typename Value>
std::ostream& operator<< (std::ostream& os, const dinic_edge<Value>& e)
