using namespace std;
#define INF 1e9
#define MAX_V 100000
//辺の構造体
struct edge { int to, cap, rev; };

vector<edge> G[MAX_V];
bool used[MAX_V];

//from-to 容量capの辺を追加
void add_edge(int from, int to, int cap) {
    G[from].push_back((edge){to, cap, (int)G[to].size()});   //場所が被るごとに0,1,...がrevに入る
    G[to].push_back((edge){from, 0, (int)G[from].size() - 1});
}

//増加パスをDFS
int dfs(int v, int t, int f) {
    if(v == t) return f;
    used[v] = true;
    for(int i = 0; i < (int)G[v].size(); i++) {
        edge &e = G[v][i];
        if(!used[e.to] && e.cap > 0) {
            int d = dfs(e.to, t, min(f,e.cap));
            if(d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

//s-tの最大流
int max_flow(int s, int t) {
    int flow = 0;
    while(1) {
        memset(used, 0, sizeof(used));
        int f = dfs(s, t, INF);
        if(f == 0) return flow;
        flow += f;
    }
}

