int topQ;

void addEdge(int v, int to, int cap)
{
    ed[edSz] = Edge(to, cap);
    g[v].push_back(edSz++);
    ed[edSz] = Edge(v, 0);
    g[to].push_back(edSz++);
}

void read()
{
    scanf("%d%d", &n, &m);
    S = n + m;
    T = S + 1;
    for (int i = 0; i < n; i++)
    {
        scanf("%s", str);
        for (int j = 0; j < m; j++)
        {
            if (str[j] == '.') continue;
            addEdge(i, n + j, 1);
            addEdge(n + j, i, 1);
            if (str[j] == 'S')
            {
                addEdge(S, i, INF);
                addEdge(S, n + j, INF);
            }
            if (str[j] == 'T')
            {
                addEdge(i, T, INF);
                addEdge(n + j, T, INF);
            }
        }
    }
    n = T + 1;
    return;
}

bool BFS()
{
    for (int i = 0; i < n; i++)
        dist[i] = INF;
    dist[S] = 0;
    topQ = 1;
    q[0] = S;
    for (int k = 0; k < topQ; k++)
    {
        int v = q[k];
        for (int id : g[v])
        {
            Edge e = ed[id];
            if (e.cap <= 0) continue;
            int to = e.to;
            if (dist[to] <= dist[v] + 1) continue;
            dist[to] = dist[v] + 1;
            q[topQ++] = to;
        }
    }
    return dist[T] < INF;
}

int dfs(int v, int flow)
{
    if (v == T || flow == 0) return flow;
    int res = 0;
    for (int &i = idx[v]; i < (int)g[v].size(); i++)
    {
        int id = g[v][i];
        Edge e = ed[id];
        int to = e.to;
        if (dist[to] != dist[v] + 1) continue;
        int df = dfs(to, min(flow, e.cap));
        flow -= df;
        res += df;
        ed[id].cap -= df;
        ed[id ^ 1].cap += df;
        if (flow == 0) return res;
    }
    return res;
}

int Flow()
{
    int res = 0;
    while(BFS())
    {
        for (int i = 0; i < n; i++)
            idx[i] = 0;
        res += dfs(S, INF);
    }
    return res;
}

