                g.add_edge(j + h, h + w + 1, INF);
            }
            if(a[i][j] == 'o'){
                g.add_edge(i, j + h, 1);
                g.add_edge(j + h, i, 1);
            }
        }
    }
    int ans = g.max_flow(h + w, h + w + 1);
    if(ans >= INF) cout << -1 << endl;
