    for(int j=0;j<W;j++){
      if(a[i][j] == 'S'){
        for(int k=0;k<H;k++)
          if(a[k][j] == 'T')out = true;
        for(int k=0;k<W;k++)
          if(a[i][k] == 'T')out = true;
      }
    }
  }
  if(out){
