// double(64bit浮動小数)のn分探索のループ回数の上限(2分探索なら50でも十分かもしれない). long double(80ビットの x87 浮動小数点型?)だと, 2分探索であってもこれだと足りないケースがある気がするので, もうちょっと余裕を持たせた方が良さそう.
constexpr i64 max_loop = 100;

struct max_flow {
    struct edge {
        int to;
        i64 cap, rev;
    };
    vector<vector<edge>> graph;
    vector<bool> done;
    max_flow(int size) : graph(size), done(size) {}
    void add_edge(int from, int to, i64 cap) {
        graph[from].push_back(edge{to, cap, (int)graph[to].size()});
        graph[to].push_back(edge{from, 0, (int)graph[from].size() - 1});
    }
    i64 dfs(int v, int t, i64 f) {
        if (v == t) return f;
        done[v] = true;
        for (auto &e : graph[v]) {
            if (done[e.to] or e.cap <= 0) continue;
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                graph[e.to][e.rev].cap += d;
                return d;
            }
        }
        return 0;
    }
    i64 calc_max_flow(int s, int t) {
        i64 flow = 0;
        while (true) {
            fill(done.begin(), done.end(), false);
            i64 f = dfs(s, t, inf);
            if (f == 0) return flow;
            flow += f;
        }
    }
};

void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 H,W;
    cin >> H >> W;

    vector<string> a(H);
    rep(i,0,H) cin >> a[i];

    i64 sy,sx,ty,tx;
    rep(i,0,H){
        rep(j,0,W){
            if(a[i][j]=='S'){
                sy=i;
                sx=j;
            }
            if(a[i][j]=='T'){
                ty=i;
                tx=j;
            }
        }
    }

    if(sy==ty or sx==tx){
        cout << -1 << endl;
        return;
    }

    i64 s=H+W,t=H+W+1;
    max_flow mf(H+W+2);
    mf.add_edge(s,sy,inf64);
    mf.add_edge(s,sx+H,inf64);
    mf.add_edge(ty,t,inf64);
    mf.add_edge(tx+H,t,inf64);
    rep(i,0,H){
        rep(j,0,W){
            if(a[i][j]!='o') continue;
            mf.add_edge(i,j+H,1);
            mf.add_edge(j+H,i,1);
        }
    }

    cout << mf.calc_max_flow(s,t) << endl;
}

