void add_edge(int u, int v, int c){
  edges[u].push_back(E.size()); E.push_back(Edge{u,v,c});
  edges[v].push_back(E.size()); E.push_back(Edge{v,u,0});  
}

int dfs(int s, int t){
  if(s == t) return 1;
  visited[s] = 1;
  for(int e : edges[s]){
    int v = E[e].v;
    if(E[e].c && !visited[v] && dfs(v,t)){
        path_e.push_back(e);
        return 1;
    }
  }
  return 0;
}

void clear_mf_aux(int &mnE){
  mnE = 1e9;
  path_e.clear();
  CLR(visited);
}

int get_mf(int sink, int tank){
  int mf = 0, mnE;
  clear_mf_aux(mnE);
  while(dfs(sink,tank)){
    for(int e : path_e) mnE = min(mnE, E[e].c);
    for(int e : path_e) E[e].c -= mnE, E[e^1].c += mnE;
    mf += mnE;
    clear_mf_aux(mnE);
  }
  return mf;
}

