	for (int i=1;i<=n;++i) scanf("%s",pic[i]+1);
	flag=network::build();
	if (flag) printf("%d\n",network::maxflow());
	else printf("-1\n");
	//fclose(stdin),fclose(stdout);
	return 0;
}

