    int to,cap,rev;
};
vector<edge> adj[505];
int level[505],iter[505];
void bfs(int s){
    memset(level, -1,sizeof(level));
    queue<int> q; q.push(s); level[s]=0;
    while(!q.empty()){
        int here = q.front(); q.pop();
        for(int i=0;i<adj[here].size();i++){
            edge &e =adj[here][i];
            if(e.cap > 0){
                if(level[e.to] == -1){
                    level[e.to] = level[here]+1;
                    q.push(e.to);
                }
            }
        }
    }
}
int dfs(int t,int here,int f){
    if(t == here)return f;
    for(int &i=iter[here];i<adj[here].size();i++){
        edge & e=adj[here][i];
        if(e.cap > 0 && level[e.to] > level[here]){
            int d =dfs(t,e.to,min(f,e.cap));
            if(d>0){
                e.cap-=d; adj[e.to][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}
int maxFlow(int source,int sink){
    int f=0;
    while(true){
        bfs(source);
        if(level[sink]==-1)return f;
        int r=1;
        memset(iter,0,sizeof(iter));
        while(r){
            r = dfs(sink,source,1e9);
            f+=r;
        }
    }
}
void addEdge(int from,int to,int cap){
    adj[from].push_back({to,cap,(int)adj[to].size()});
    adj[to].push_back({from,cap,(int)adj[from].size()-1});
}
