pair<int,int> mp[10001];

typedef int LL;
int vis[N],ID;

LL dfs(int cur,int snk, LL MX) {
//    cout << cur <<' ' ;
    if (vis[cur] == ID || MX == 0)
        return 0;
    vis[cur] = ID;
    if (cur == snk)
        return MX;
    for (int i = head[cur]; i != -1; i = nxt[i]) {
        int t = to[i];
        LL f = dfs(t,snk, min(MX, cap[i]));
        if (!f)
            continue;
        cap[i] -= f;
        cap[i ^ 1] += f;
        return f;
    }

    return 0;
}
