	vis[s] = 1; int u; Q.push(s);
	while (!Q.empty ()) {
		u = Q.front(); Q.pop();
		for (Edge *now = head[u]; now; now = now -> next) if (now -> res && !vis[now -> to]) {
			d[now -> to] = d[u] + 1;
			vis[now -> to] = 1;
			Q.push (now -> to);
		}
	}
	return vis[t];
}

int Dfs (int u, int f) {
	if (u == t || !f) return f;
	int fellow = 0, D;
	for (Edge *&now = cur[u]; now; now = now -> next) if (d[now -> to] == d[u] + 1 && (D = Dfs (now -> to, min (f, now -> res)))) {
		fellow += D; f -= D;
		now -> res -= D; (pool + ((now - pool) ^ 1)) -> res += D;
		if (!f) break;
	}
	return fellow;
}

