/*
max flowなんだけど、辺の貼り方をしっかり考える.
横と縦に自由に移動することができるので、a[i][j] == 'o'のときは
a[i][j]の葉を取ると、a[i][k]からa[l][j](0<=k<w, 0<=l<h)に移動することができなくなる.
なので、flowをする際の頂点はS, T, 各列と各行の分だけ作る必要がある.(全部のマス目分は必要ない)
SとTは取ることができないので、別途頂点にし、Sからの辺とTへの辺はINFにする必要がある
(どう頑張っても水は流れる).
a[i][j]の葉を取ると、i行目の葉からj列目の葉に移動できなくなるので、i行目の頂点からj列目の
頂点への辺をカットすることができる(逆も成り立つ、すなわち無向辺).
葉を取るコストは1なのでcapを1として辺を貼っておく.
こうしてできたグラフにSからTへのmax flowを求めると答え.
全部のマス目を用意すると、行と列の処理の仕方がわからないので、今回みたいに行全体、列全体に操作できる
ような問題は頂点を行ごと列ごとに持っておくときれいに書けるのかな.
なんにせよフロー面白いわ.
*/

#include <cstdio>
#include <algorithm>
#include <vector>
#include <queue>

using namespace std;

struct TEdge
{
    int u, v, c, f;
    TEdge *rev = nullptr;
};

const int N = 102;
const int NN = N * N * 2 + N * 2;
const int M = N * N * 10;
const int INF = 1e9;

int h, w, nn, m, s, t;
char a[N][N];
TEdge el[M];
vector<TEdge*> g[NN];
TEdge *pre[NN];

bool Bfs(int s, int t)
{
    fill(pre+1, pre+1+nn, nullptr);
    queue<int> q;
    q.push(s);
    while (!q.empty())
    {
        int u = q.front(); q.pop();
        for (auto e: g[u])
            if (!pre[e->v] && e->f < e->c && e->v != s) q.push(e->v), pre[e->v] = e;
    }
    return pre[t] != nullptr;
}

void AddEdge(int u, int v, int c)
{
    el[m]   = {u, v, c, 0, el+m+1};
    el[m+1] = {v, u, 0, 0, el+m};
    g[u].push_back(el+m);
    g[v].push_back(el+m+1);
    m += 2;
}

int EdmondsKarp()
{
    int flow = 0;
    while (Bfs(s, t))
    {
        int maxflow = INF;
        for (auto e = pre[t]; e != nullptr; e = pre[e->u]) maxflow = min(maxflow, e->c - e->f);
        for (auto e = pre[t]; e != nullptr; e = pre[e->u]) e->f += maxflow, e->rev->f -= maxflow;
        flow += maxflow;
    }
    return flow;
}

int Conv(int i, int j, int layer) {return (i-1) * w + j + (layer ? h * w : 0);}
int Row(int i) {return h * w * 2 + i;}
int Col(int i) {return h * w * 2 + h + i;}

void Solve()
{
    for (int i = 1; i <= h; ++i)
        for (int j = 1; j <= w; ++j)
            if (a[i][j] == 'S') s = Conv(i, j, 0); else
            if (a[i][j] == 'T') t = Conv(i, j, 1);

    nn = h * w * 2 + h + w;

    for (int i = 1; i <= h; ++i)
        for (int j = 1; j <= w; ++j)
            if (a[i][j] != '.')
            {
                AddEdge(Conv(i, j, 1), Conv(i, j, 0), 1);
                AddEdge(Conv(i, j, 0), Row(i), INF);
                AddEdge(Conv(i, j, 0), Col(j), INF);
                AddEdge(Row(i), Conv(i, j, 1), INF);
                AddEdge(Col(j), Conv(i, j, 1), INF);
            }
    int mincut = EdmondsKarp();
    if (mincut >= INF) printf("-1");
    else printf("%d",mincut);
}

int main()
{
    scanf("%d %d", &h, &w);
    for (int i = 1; i <= h; ++i) scanf("%s",a[i]+1);
    Solve();
    return 0;
}

