      if(f==0)return flow;
      flow+=f;
    }
  }
  int dfs(int s,int g,int val){
    if(s==g)return val;
    used[s]=true;
    for(auto&e:G[s]){
      if(!used[e.to]&&e.cap>0){
        int d=dfs(e.to,g,min(val,e.cap));
        if(d>0){
          e.cap-=d;
          G[e.to][e.rev].cap+=d;
          return d;
        }
      }
    }
    return 0;
  }
};

