const ll SIZE=205,INF=1e10;
struct MaxFlow{
	struct edge{
		ll to,cap,rev;
		edge(ll to=0,ll cap=0,ll rev=0):to(to),cap(cap),rev(rev){}
	};
	vector <edge> vec[SIZE];
	ll level[SIZE];
	ll iter[SIZE];
	void add(ll s,ll t,ll c){
		ll S=vec[s].size(),T=vec[t].size();
		vec[s].push_back(edge(t,c,T));
		vec[t].push_back(edge(s,0,S));
	}
	void bfs(ll s){
		memset(level,-1,sizeof(level));
		queue <ll> que;
		level[s] = 0;
		que.push(s);
		while (!que.empty()){
			ll v = que.front();que.pop();
			for(ll i=0;i<vec[v].size();i++){
				edge&e=vec[v][i];
				if (e.cap>0&&level[e.to]<0){
					level[e.to]=level[v]+1;
					que.push(e.to);
				}
			}
		}
	}
	ll flow_dfs(ll v,ll t,ll f){
		if (v==t) return f;
		for(ll &i=iter[v];i<vec[v].size();i++){
			edge &e=vec[v][i];
			if (e.cap>0&&level[v]<level[e.to]){
				ll d=flow_dfs(e.to,t,min(f,e.cap));
				if(d>0){
					e.cap-=d;
					vec[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}
	ll max_flow(ll s,ll t){
		ll flow = 0;
		while(1){
			bfs(s);
			if (level[t]<0) return flow;
			memset(iter,0,sizeof(iter));
			while (1){
				ll f=flow_dfs(s,t,INF);
				if(f==0) break;
				flow += f;
			}
		}
	}
};
