// 方針:
// 0-ind
// (H+W+2)個の頂点 S, x0~x(H-1), y0~y(W-1), T を考える。
// a[i][j] が 'o' のとき，xi と yj を容量1の辺で相互に結ぶ。
// a[si][sj] が 'S' のとき， S から xsi 及び ysj に容量INFの辺を張る。
// a[ti][tj] が 'T' のとき， xti 及び ytj から T に容量INFの辺を張る。
// このネットワークの S ->T の 最大フロー = 最小カット が答え。ただし， INF 以上のときは-1とする。
// 頂点Sを0, xi(i:0~H-1)を1+i(1~H), yj(j:0~W-1)をH+1+j(H+1~H+W), TをH+W+1と表す。

ll flow(int u, int v, ll f, vector<set<int>> &g, map<pii, ll> &cap, vb &r) {	
	if (u == v) return f;
	r[u] = true;
	for (int t : g[u]) {
		if (r[t] or cap[pii(u, t)] == 0) continue;
		ll d = flow(t, v, min(f, cap[pii(u, t)]), g, cap, r);
		if (d > 0) {
			cap[pii(u, t)] -= d;
			cap[pii(t, u)] += d;		
			return d;
		}
	}	
	return 0;
}
ll max_flow(int s, int t, vector<set<int>> &g, map<pii, ll> &cap) {
	ll res = 0;
	while(true) {
		vb r(g.size());
		ll f = flow(s, t, INF, g, cap, r);
		if (f) res += f;
		else return res;
	}
}
int main() {
	int H, W; cin >> H >> W;
	vector<set<int>> g(H + W + 2);
	map<pii, ll> cap;
	rep(i, H) rep(j, W) {
		char c; cin >> c;
		if (c == 'S') {
			g[0].insert(1 + i); cap[pii(0, 1 + i)] = INF;
			g[0].insert(H + 1 + j); cap[pii(0, H + 1 + j)] = INF;
		}
		else if (c == 'T') {
			g[1 + i].insert(H + W + 1); cap[pii(1 + i, H + W + 1)] = INF;
			g[H + 1 + j].insert(H + W + 1); cap[pii(H + 1 + j, H + W + 1)] = INF;
		} else if (c == 'o') {
			g[1 + i].insert(H + 1 + j); cap[pii(1 + i, H + 1 + j)] = 1;
			g[H + 1 + j].insert(1 + i); cap[pii(H + 1 + j, 1 + i)] = 1;
		}
	}
	/*
	dbvv(g);
	for (auto p : cap) {
		dbl(p.first); dbl(p.second);
	}
	*/
	ll ans = max_flow(0, H + W + 1, g, cap);
	if (ans >= INF) ans = -1;
	cout << ans << endl;
}

