struct node {
	int i, j, k;

	bool operator ==(const node& A) const {
		return i == A.i&&j == A.j&&k == A.k;
	}
};
struct edge {
	node to;
	int cap, rev;
};
vector<edge>G[102][102][2];
int level[102][102][2], iter[102][102][2];

void add_edge(node from, node to, int cap) {
	G[from.i][from.j][from.k].push_back({to,cap,G[to.i][to.j][to.k].size() });
	G[to.i][to.j][to.k].push_back({ from,0,G[from.i][from.j][from.k].size() - 1 });
}

void bfs(node s) {
	rep(i, 102)rep(j, 102)rep(k,2)level[i][j][k] = -1;
	queue<node>Q;
	level[s.i][s.j][s.k] = 0;
	Q.push(s);
	while (Q.size()) {
		node v = Q.front(); Q.pop();
		rep(i, G[v.i][v.j][v.k].size()) {
			edge e = G[v.i][v.j][v.k][i];
			if (e.cap > 0 && level[e.to.i][e.to.j][e.to.k] < 0) {
				level[e.to.i][e.to.j][e.to.k] = level[v.i][v.j][v.k] + 1;
				Q.push(e.to);
			}
		}
	}
}

int dfs(node v, node t, int f) {
	if (v==t)return f;
	for (int &i = iter[v.i][v.j][v.k]; i < G[v.i][v.j][v.k].size(); i++) {
		edge &e = G[v.i][v.j][v.k][i];
		if (e.cap > 0 && level[v.i][v.j][v.k] < level[e.to.i][e.to.j][e.to.k]) {
			int d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				G[e.to.i][e.to.j][e.to.k][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

int maxflow(node s, node t) {
	int flow = 0;
	while (1) {
		bfs(s);
		if (level[t.i][t.j][t.k] < 0)return flow;
		rep(i, 102)rep(j, 102)rep(k,2)iter[i][j][k] = 0;
		int f;
		while ((f = dfs(s, t, inf)) > 0)flow += f;
	}
}

