void nhap()
{
    cin>>m>>n;
    for (int i=1;i<=m;i++)
    for (int j=1;j<=n;j++)
    {
        char kt;
        cin>>kt;
        if (kt=='o')
        {
            dsk[i].push_back(j+m);
            dsk[j+m].push_back(i);
            c[i][j+m]=c[j+m][i]=1;
        }
        if (kt=='S')
        {
            dsk[0].push_back(i);
            dsk[0].push_back(j+m);
            c[0][i]=c[0][j+m]=oo;
        }
        if (kt=='T')
        {
            dsk[i].push_back(n+m+1);
            dsk[j+m].push_back(n+m+1);
            c[i][n+m+1]=c[j+m][n+m+1]=oo;
        }
    }
}
bool Findpath()
{
    cnt++;
    queue<int> st;
    st.push(0);
    while (!st.empty())
    {
        int u=st.front();
        st.pop();
        if (u==n+m+1) return 1;
        for (int v:dsk[u])
        {
            if (visit[v]==cnt||c[u][v]==f[u][v]) continue;
            visit[v]=cnt;
            parent[v]=u;
            st.push(v);
        }
    }
    return 0;
}
void tangluong()
{
    s[1]=n+m+1;
    int d=1,x=n+m+1;
    while (x!=0)
    {
        x=parent[x];
        s[++d]=x;
    }
    int mn=oo;
    for (int i=2;i<=d;i++)
        mn=min(mn,c[s[i]][s[i-1]]-f[s[i]][s[i-1]]);
    maxflow+=mn;
    for (int i=2;i<=d;i++)
    {
        f[s[i]][s[i-1]]+=mn;
        f[s[i-1]][s[i]]-=mn;
    }
}
