int k=0,h[300001]; 
int lv[300001],iter[300001],head=0,tail=0,q[300001],n,m,p;  
void ae(int from,int to,int cap) 
{ 
    G[++k].next=h[from];h[from]=k;  
    G[k].to=to;G[k].cap=cap;G[k].rev=k+1; 
    G[++k].next=h[to];h[to]=k;  
    G[k].to=from;G[k].cap=0;G[k].rev=k-1; 
}  
void bfs(int s) 
{ 
    head=tail=0; 
    q[tail++]=s;lv[s]=1; 
    while(head!=tail) 
    { 
        int u=q[head]; 
        for(int i=h[u];i;i=G[i].next) 
        { 
            if(!lv[G[i].to]&&G[i].cap) 
            { 
                lv[G[i].to]=lv[u]+1; 
                q[tail++]=G[i].to; 
            } 
        } 
        head++; 
    } 
} 
int dfs(int u,int t,int f){ 
    if(u==t)return f; 
    for(int &i=iter[u];i;i=G[i].next){ 
        if(lv[G[i].to]==lv[u]+1&&G[i].cap){ 
            int d=dfs(G[i].to,t,min(f,G[i].cap)); 
            if(d){ 
                G[i].cap-=d;G[G[i].rev].cap+=d;
				return d; 
            } 
        } 
    } 
    return 0; 
} 
int max_flow(int s,int t) 
{ 
    int flow=0; 
    while(1){    
        for(int i=0;i<=p+1;i++)iter[i]=h[i]; 
        memset(lv,0,sizeof(lv)); 
        bfs(s); 
        if(lv[t]==0)return flow; 
        int d=dfs(s,t,inf); 
        while(d>0){flow+=d;d=dfs(s,t,inf);} 
    } 
} 
