        for (int k = 0; k < w; ++k)
          if (j != k && s[i][k] != '.') din.add((i + h) * w + j, i * w + k, 1);
      }
    }
  if (st.first == go.first || st.second == go.second)
    cout << "-1" << endl;
  else
    cout << din.solve((st.first + h) * w + st.second, go.first * w + go.second)
         << endl;
  return 0;
}

