void add(int from,int to,int cap)
{
    l[++t]=(edge) {to,0,cap};
    G[from].push_back(t);
    l[++t]=(edge) {from,0,0};
    G[to].push_back(t);
}

bool BFS()
{
    memset(v,0,sizeof(v)),v[S]=1,d[S]=0;
    queue<int> q;
    q.push(S);
    int x;
    edge e;

    while(!q.empty())
    {
        x=q.front(),q.pop();
        for(int i=G[x].size()-1; i>=0; i--)
        {
            e=l[G[x][i]];
            if(e.flow<e.cap&&!v[e.to])
                v[e.to]=1,d[e.to]=d[x]+1,q.push(e.to);
        }
    }

    return v[T];
}

int dfs(int x,int A)
{
    if(x==T||!A)
        return A;
    int flow=0,f,sz=G[x].size();
    for(int &i=cur[x]; i<sz; i++)
    {
        edge &e=l[G[x][i]];
        if(d[x]+1==d[e.to]&&(f=dfs(e.to,min(e.cap-e.flow,A))))
        {
            A-=f,flow+=f;
            e.flow+=f,l[G[x][i]^1].flow-=f;
            if(!A)
                break;
        }
    }

    return flow;
}

int max_flow()
{
    int ans=0;
    while(BFS())
    {
        memset(cur,0,sizeof(cur));
        ans+=dfs(S,inf);
    }
    return ans;
}


