    if(v == t) {
      // cout << "flow= " << flow << endl;
      return flow;
    } 
    used[v] = true;
    // cout << "v= " << v << endl;
    for(int i = 0; i < graph[v].size(); i++) {
      edge &e = graph[v][i];
      if(e.cap > 0 && !used[e.to]) {
