int cap[305][305];       
int q[305], *qf, *qb;  
int p[305];            

int Edmonds_Karp(int s, int t)
{
    int f = 0;     
    while (true) 
    {
        memset(p, -1, sizeof(p));
        qf = qb = q;
        p[*qb++ = s] = s;
        while (qf < qb && p[t] == -1)
            for (int i = *qf++, j = 0; j < 305; ++j)
                if (p[j] == -1 && cap[i][j])
                    p[*qb++ = j] = i;
        if (p[t] == -1) break;

        int df = 1e9;
        for (int i = p[t], j = t; i != j; i = p[j = i])
            df = min(df, cap[i][j]);
        for (int i = p[t], j = t; i != j; i = p[j = i])
            cap[i][j] -= df, cap[j][i] += df;
        f += df;
    }
    return f;
}
