class Network{
	private:
	int V;
	struct edge{
		int to,cap,rev;
	};
	vector<vector<edge> > List;
	int DFS(int v,int t,int f,vb& used){
		if(v==t) return f;
		used[v]=1;
		for(int i=0;i<List[v].size();i++){
			edge &e=List[v][i];
			if(!used[e.to]&&e.cap>0){
				int d=DFS(e.to,t,min(f,e.cap),used);
				if(d>0){
					e.cap-=d;
					List[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}
	public:
	Network(int v){
		V=v;
		List=vector<vector<edge> >(v);
	}
	void add_edge(int s,int t,int c){
		List[s].push_back(edge{t,c,(int)List[t].size()});
		List[t].push_back(edge{s,0,(int)List[s].size()-1});
	}
	int MF(int s,int t){
		int ans=0;
		while(1){
			vb used(V);
			int f=DFS(s,t,inf,used);
			if(f==0) return ans;
			ans+=f;
		}
	}
};

