bool bfs(){
	memset(level,-1,sizeof(level));
	queue<int> q;
	q.push(source);
	level[source] = 0;
	int here,there,i;
	Edge x;
	while(!q.empty()){
		here= q.front();
		q.pop();

		for(i=0;i<vt[here].size();++i){
			x = vt[here][i];
			there= x.v;
			int cap = x.cap;
			if(level[there]==-1 && cap>0){
				level[there] = level[here]+1;
				q.push(there);
			}
		}
	}
	return level[sink]!=-1;
}

