	if(here==sink)return mcap;

	for(int &i = work[here];i<vt[here].size();++i){
		Edge x = vt[here][i];
		int there =x.v;
		int cap = x.cap;
		if(level[there]==level[here]+1 && cap>0){
			int flow = dfs(there,min(mcap,cap));
			if(flow>0){
				vt[here][i].cap-=flow;
				vt[there][x.rev].cap+= flow;
