			edge& e = es[ei]; ui v = e.v;
			if (vis[v] || e.c <= e.f) continue;
			vis[v] = 1; dis[v] = dis[u] + 1; q.push(v);
		}
	}
	return vis[t];
}

int dfs(ui u, int a) {
	if (u == t || a == 0) return a;
	int sum = 0, f;
	for (ui& ei = cur[u]; ~ei; ei = es[ei].p) {
		edge& e = es[ei]; ui v = e.v;
		if (dis[u] + 1 != dis[v] || (f = dfs(v, min(a, e.c - e.f))) <= 0)
			continue;
		e.f += f; es[ei ^ 1].f -= f;
		sum += f; a -= f;
		if (!a) break;
	}
	return sum;
}

