using namespace std;

struct edge{
	int to, cap, rev;

	edge(int to, int cap, int rev){
		this->to = to;
		this->cap = cap;
		this->rev = rev;
	}
};

struct dinic{
	int inf = 1e9;
	vector<vector<edge>> e;
	vector<int> level, iter;

	dinic(int n){
		e.resize(n);
		level.resize(n);
		iter.resize(n);
	}

	void addedge(int from, int to, int cap){
		e[from].emplace_back(edge(to, cap, e[to].size()));
		e[to].emplace_back(edge(from, 0, e[from].size() - 1));
	}

	void bfs(int s){
		fill(level.begin(), level.end(), -1);
		queue<int> q;
		level[s] = 0;
		q.push(s);
		while(!q.empty()){
			int v = q.front();
			q.pop();
			for(auto &&ee:e[v]) if(0 < ee.cap && level[ee.to] < 0){
				level[ee.to] = level[v] + 1;
				q.push(ee.to);
			}
		}
	}

	int dfs(int v, int t, int f){
		if(v == t) return f;
		for(int &i = iter[v]; i < e[v].size(); i++){
			edge &ee = e[v][i];
			if(0 < ee.cap && level[v] < level[ee.to]){
				int d = dfs(ee.to, t, min(f, ee.cap));
				if(0 < d){
					ee.cap -= d;
					e[ee.to][ee.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	int max_flow(int s, int t){
		int flow = 0;
		while(true){
			bfs(s);
			if(level[t] < 0) return flow;
			fill(iter.begin(), iter.end(), 0);
			int f;
			while(0 < (f = dfs(s, t, inf))) flow += f;
		}
	}
};

