    q.push(s);
    memset(dis,0x3f,sizeof(dis));
    dis[s]=0;
    while (!q.empty()) {
        int k=q.front();
        q.pop();
        for (int i=head[k];i!=-1;i=edge[i].next) {
            if (edge[i].w==0) continue;
            int kx=edge[i].num;
            if (dis[k]+1<dis[kx]) {
                dis[kx]=dis[k]+1;
                q.push(kx);
            }
        }
    }
    if (dis[t]==INF) return 0;
    return 1;
}
int DFS(int x,int a) {
    if (x==t) return a;
    if (a==0) return 0;
    int flow=0;
    for (int &i=cur[x];i!=-1;i=edge[i].next) {
        int kx=edge[i].num;
        if (dis[kx]!=dis[x]+1) continue;
        int now=DFS(kx,min(a,edge[i].w));
        flow+=now;
        edge[i].w-=now;
        edge[i^1].w+=now;
        a-=now;
        if (a==0) return flow;
    }
    return flow;
}
