using namespace std;

const int maxn = 30010,MAX = 1000000000;

int n,m;

char st[110][110];

struct Edge{
	int to,cap;
	Edge *next,*oppo;
};
Edge *E[maxn],Pr[maxn*40];int cnt=0;
void addedge(int u,int v,int cap){
	Pr[++cnt].to=v;Pr[cnt].cap=cap;Pr[cnt].oppo=&Pr[cnt+1];Pr[cnt].next=E[u];E[u]=&Pr[cnt];
	Pr[++cnt].to=u;Pr[cnt].cap=0;  Pr[cnt].oppo=&Pr[cnt-1];Pr[cnt].next=E[v];E[v]=&Pr[cnt];
}


int s,t;
int H[maxn];

queue<int> Q;

bool Makelevel(){
	for(int i=1;i<=n*m*2+n+m;i++)H[i]=MAX;H[s]=0;
	Q.push(s);
	while(!Q.empty()){int u=Q.front();Q.pop();
		for(Edge *P=E[u];P;P=P->next)
			if(P->cap&&H[P->to]>H[u]+1){
				H[P->to]=H[u]+1;Q.push(P->to);
			}
	}
	return H[t]!=MAX;
}

int extend(int u,int left){int r=0;
	if(u==t)return left;
	for(Edge *P=E[u];P&&r<left;P=P->next)
		if(P->cap&&H[P->to]==H[u]+1){int t;
			t=extend(P->to,min(P->cap,left-r));
			r+=t;P->cap-=t;P->oppo->cap+=t;
		}
	if(!r)H[u]=MAX;
	return r;
}

void Work(){
	int ans=0;
	while(Makelevel()&&ans<=n*m)ans+=extend(s,MAX);
	printf("%d\n",(ans>n*m)?-1:ans);
}

int get(int i,int j){
	return (i-1)*m+j;
}

void Init(){
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)scanf("%s",st[i]+1);
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)if(st[i][j]!='.'){
			if(st[i][j]=='S')s=get(i,j)+n*m;
			if(st[i][j]=='T')t=get(i,j);
			if(st[i][j]!='T'&&st[i][j]!='S')addedge(get(i,j),get(i,j)+n*m,1);
			addedge(get(i,j)+n*m,n*m*2+i,MAX);
			addedge(n*m*2+i,get(i,j),MAX);
			addedge(get(i,j)+n*m,n*m*2+n+j,MAX);
			addedge(n*m*2+n+j,get(i,j),MAX);
		}
}

