int num(int x,int y){
	return (x-1) * h + y;
}
queue <int> q;
void addedge(int u,int v) {
	++edge_cnt;
	nxt[edge_cnt]=first[u];
	first[u]=edge_cnt;
	too[edge_cnt]=v; 
	r[edge_cnt]=1;

	++edge_cnt;
	nxt[edge_cnt]=first[v];
	first[v]=edge_cnt;
	too[edge_cnt]=u;
	r[edge_cnt]=1;
