bool bfs(){
	q.push(s);
	fill(d+1,d+t+1,0);
	d[s]=1;
	while (!q.empty()) {
		int u=q.front();
		q.pop();
		for (int e=first[u]; e; e=nxt[e]) {
			int v=too[e];
			if (d[v]==0 && r[e]>0) d[v]=d[u]+1,q.push(v);
		}
	}
	return d[t]>0;
}
int dfs(int x,int budget){
	if (x==t) return budget;
	int ans=0;
	for (int &e=cur[x]; e; e=nxt[e]) {
		int v=too[e];
		if (d[v]==d[x]+1 && r[e]>0) {
			int ret=dfs(v,min(budget,r[e]));
			ans    += ret;
			r[e]   -= ret;
			r[e^1] += ret;
			budget -= ret;
			if (budget==0) break;
		}
	}
	return ans;
}
