  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (s[i][j] == 'S') {
        g.st = i * w + j + h * w;
      }
      if (s[i][j] == 'T') {
        g.fin = i * w + j;
      }
      g.add(i * w + j, i * w + j + h * w, 1, 0);
    }
  }              
  const int inf = (int) 1e6;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (s[i][j] != '.') {
        for (int k = 0; k < w; k++) {
          if (j != k && s[i][k] != '.') {
            g.add(i * w + j + h * w, i * w + k, inf, 0);
          }
        }
      }
    }
  }
  for (int i = 0; i < w; i++) {
    for (int j = 0; j < h; j++) {
      if (s[j][i] != '.') {
        for (int k = 0; k < h; k++) {
          if (j != k && s[k][i] != '.') {
            g.add(j * w + i + h * w, k * w + i, inf, 0);
          }
        }
      }
    }
  }
  dinic<int> d(g);
