struct edge { long long to, cap, rev;};

void add_edge(long long from, long long to, long long cap, vector<edge> G[]){
    G[from].push_back((edge){to, cap, G[to].size()});
    G[to].push_back((edge){from, 0, G[from].size()-1});
}

long long dfs_flow(long long v, long long t, long long f, vector<bool> &used, vector<edge> G[]){
    if(v==t) return f;
    used[v] = true;
    for(long long i=0; i<G[v].size(); i++){
        edge &e = G[v][i];
        if(!used[e.to] && e.cap > 0){
            long long d = dfs_flow(e.to, t, min(f, e.cap), used, G);
            if(d>0){
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

long long max_flow(long long N, long long s, long long t, vector<edge> G[]){
    long long flow = 0;
    const long long INF = 1e18;
    vector<bool> used(N);
    while(true){
        fill(used.begin(), used.end(), false);
        long long f = dfs_flow(s, t, INF, used, G);
        if(f==0) return flow;
        flow += f;
    }
}

