ll dfs(int s, int t, ll c){
	int i;
	ll f;
	edge e;
	if(s == t){
		return c;
	}
	used[s] = true;
	for(i=(g[s].l_ength()-1); i>=0; --i){
		e = g[s][i];
		if((!used[e.to]) && e.cap > 0ll){
			f = dfs(e.to, t, min(c, e.cap));
