        if (S[i][j] == 'S') {
            D.add_edge(0, 1 + i, inf);
            D.add_edge(0, H + 1 + j, inf);
        }
        if (S[i][j] == 'T') {
            D.add_edge(1 + i, H + W + 1, inf);
            D.add_edge(H + 1 + j, H + W + 1, inf);
        }
        if (S[i][j] == 'o') {
            D.add_edge(1 + i, H + 1 + j, 1);
