            if(s[i][j] == 'S'){
                dinic.AddEdge(0, i, INF);
                dinic.AddEdge(0, j + H, INF);
            }else if(s[i][j] == 'T'){
                dinic.AddEdge(i, H + W + 1, INF);
                dinic.AddEdge(j + H, H + W + 1, INF);
            }else if(s[i][j] == 'o'){
                dinic.AddEdge(i, j + H, 1);
            }
        }
    }
    int maxflow = dinic.GetMaxFlow(0, H + W + 1);
    if(maxflow >= INF){
