inline void add(int a,int b,int w)
{
	e[em].to=b,e[em].w=w,e[em].ne=p[a],p[a]=em++;
	e[em].to=a,e[em].w=0,e[em].ne=p[b],p[b]=em++;
}

bool dfs(int s,int t)
{
	if(s==t)return 1;
	for(int&j=p2[s];j;j=e[j].ne)
		if(tm[e[j].to]!=T&&e[j].w&&dep[e[j].to]==dep[s]+1)
		{
			tm[e[j].to]=T;
			fl[e[j].to]=min(e[j].w,fl[s]);
			if(dfs(e[j].to,t))
			{
				e[j].w-=fl[t];
				e[j^1].w+=fl[t];
				return 1;
			}
		}
	dep[s]=-1;
	return 0;
}

inline int dinic(int s,int t)
{
	int flow=0;
	while(1)
	{
		memset(dep,0,sizeof(dep));
		q[0]=s,qe=1,dep[s]=1;
		++T;
		for(int i=0;i^qe;i++)
		{
			tm[q[i]]=T;
			for(int j=p[q[i]];j;j=e[j].ne)
				if(!dep[e[j].to]&&e[j].w)
				{
					dep[e[j].to]=dep[q[i]]+1;
					q[qe++]=e[j].to;
				}
		}
		if(tm[t]!=T)break;
		for(int i=0;i^qe;i++)
			p2[q[i]]=p[q[i]];
		while(1)
		{
			fl[s]=0x7fffffff;
			++T;
			dfs(s,t);
			if(tm[t]!=T)break;
			flow+=fl[t];
		}
	}
	return flow;
}
