using namespace std;

queue<int> bq;

struct edge{
	int v, flow, C, rev;
};

vector<edge> adj[204];

int level[204], start[204];


void addEdge(int u, int v,int C){
	edge a = { v,0,C,adj[v].size() };
	edge b = { u,0,0,adj[u].size() };
	adj[u].push_back(a);
	adj[v].push_back(b);
}

bool bfs(int s, int t){
	for (int i = 0; i < 204; i++)
		level[i] = -1;
	level[s] = 0;
	bq.push(s);
	while(!bq.empty()){
		int f = bq.front();
		bq.pop();
		for(auto it:adj[f]){
			if(level[it.v]==-1&&it.flow<it.C){
				level[it.v] = level[f] + 1;
				bq.push(it.v);
			}
		}
	}
	if (level[t] == -1)
		return false;
	return true;
}

int dfs(int f, int t, int cflow){
	if (f == t)
		return cflow;
	for (; start[f] < adj[f].size(); start[f]++) {
		edge& ef = adj[f][start[f]];
		if (level[ef.v]==level[f]+1&&ef.flow<ef.C){
			int newflow = min(cflow, ef.C - ef.flow);
			int finalflow = dfs(ef.v, t, newflow);
			if(finalflow>0){
				ef.flow += finalflow;
				adj[ef.v][ef.rev].flow -= finalflow;
				return finalflow;
			}
		}
	}
	return 0;
}

int maxflow(int s, int t){
	int ans = 0;
	while(bfs(s,t)){
		for (int i = 0; i < 204; i++)
			start[i] = 0;
		while (true) {
			int newflow = dfs(s, t, 1000000);
			if (newflow <= 0)
				break;
			ans += newflow;
		}
	}
	return ans;
}

