constexpr int inf = 1e9;

struct edge{
	int to, cap, rev;

	edge(int to, int cap, int rev){
		this->to = to;
		this->cap = cap;
		this->rev = rev;
	}
};

struct dinic{
	vector<vector<edge>> e;
	vector<int> level, iter;

	dinic(int n){
		e.assign(n, vector<edge>());
		level.assign(n, -1);
		iter.assign(n, 0);
	}

	void addedge(int from, int to, int cap = 1){
		e[from].emplace_back(edge(to, cap, e[to].size()));
		e[to].emplace_back(edge(from, 0, e[from].size() - 1));
	}

	void bfs(int s){
		fill(level.begin(), level.end(), -1);
		queue<int> q;
		level[s] = 0;
		q.push(s);
		while(!q.empty()){
			int v = q.front();
			q.pop();
			for(auto&& ee:e[v]) if(ee.cap > 0 && level[ee.to] < 0){
				level[ee.to] = level[v] + 1;
				q.push(ee.to);
			}
		}
	}

	int dfs(int v, int t, int f){
		if(v == t) return f;
		for(int& i = iter[v]; i < e[v].size(); i++){
			edge& ee = e[v][i];
			if(ee.cap > 0 && level[v] < level[ee.to]){
				int d = dfs(ee.to, t, min(f, ee.cap));
				if(d > 0){
					ee.cap -= d;
					e[ee.to][ee.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	int max_flow(int s, int t){
		int flow = 0;
		while(true){
			bfs(s);
			if(level[t] < 0) return flow;
			fill(iter.begin(), iter.end(), 0);
			int f;
			while((f = dfs(s, t, inf)) > 0) flow += f;
		}
	}
};

