                t = i * h + j;
                a[i][j] = 'o';
            }
        }
    }
    if(s % h == t % h || s / h == t / h) {
        cout << -1 << endl;
        return;
    }
    rep(i, h) {
        for(int j = i + 1; j < h; ++j) {
            rep(k, w) {
                if(a[i][k] == 'o' && a[j][k] == 'o') {
                    G.addedge(i * h + k + h * w, j * h + k, INF);
