bool bfs()
{
	int l = 0, r = 0;
	q[r++] = s;
	memset(level, -1, sizeof(level));
	level[s] = 0;

	while(l < r && level[t] == -1)
	{
		int v = q[l++];
		for (int id : G[v])
		{
			int to = E[id].to;
			if (level[to] == -1 && E[id].cap > E[id].flow)
			{
				level[to] = level[v] + 1;
				q[r++] = to;
			}
		}
	}

	return level[t] != -1;
}

int dfs(int v = s, int flow = inf)
{
	if (!flow)
		return 0;
	if (v == t)
		return flow;
	for (; ptr[v] < G[v].size(); ++ptr[v])
	{
		int id = G[v][ptr[v]], to = E[id].to;
		if (level[to] != level[v] + 1)
			continue;
		int pushed = dfs(to, min(flow, E[id].cap - E[id].flow));
		if (pushed)
		{
			E[id].flow += pushed;
			E[id ^ 1].flow -= pushed;
			return pushed;
		}
	}
	return 0;
}

int dinic()
{
	int flow = 0;
	while (bfs())
	{
		memset(ptr, 0, sizeof(ptr));
		while (int pushed = dfs())
			flow += pushed;
	}
	return flow;
}

