		}
		if (!a || !b) {
			--ans;
			used[c(i, j)] = 1;
			for (auto& v : G[i][j]) if (used[c(v)]) U.union_set(c(i, j), c(v));
		} 
	}
	cout << ans << '\n';
	return 0;
}

