template< typename T >
struct FordFulkerson {

	struct FlowEdge {
		int to;
		T cap,rev;
		FlowEdge() {}
		FlowEdge(int to,T cap,T rev):to(to),cap(cap),rev(rev) {}
	};

	vector< vector<FlowEdge> > G;
	vector<int> used;

	FordFulkerson() {}
	FordFulkerson(int n) {
		G.resize(n);
		used.resize(n);
	}

	void add_edge(int from,int to,T cap) {
		G[from].emplace_back(to,cap,(int)G[to].size());
		G[to].emplace_back(from,0,(int)G[from].size()-1);
	}

	T dfs(int v,const int t,T flow) {
		if(v==t) return flow;
		used[v]=1;
		for(auto &e:G[v]) {
				if(!used[e.to]&&e.cap>0) {
				T d=dfs(e.to,t,min(flow,e.cap));
				if(d>0) {
					e.cap-=d;
					G[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}

	T max_flow(int s,int t,T lim) {
		T flow=0;
		while(true) {
			fill(ALL(used),false);
			T d=dfs(s,t,inf);
			if(d==0) return flow;
			flow+=d;
		}
		return flow;
	}

	T max_flow(int s,int t) {
		return max_flow(s,t,inf);
	}
};

