vector<int> adj[maxn];

int pa[maxn];
bool vs[maxn];

bool bfs(int s, int t){
  deque<int> Q;
  Q.push_back(s);
  pa[s] = -1;
  memset(vs, false, sizeof(vs));
  while(!Q.empty()){
    int v = Q.front(); Q.pop_front();
    if(vs[v]) continue;
    vs[v] = true;
    for(int u : adj[v]){
      if(res[v][u] == 0) continue;
      if(vs[u]) continue;
      pa[u] = v;
      Q.push_back(u);
      if(u == t){
	return true;
      }
    }
  }
  return false;
}

int mxflow(int s, int t){
  int ans = 0;
  while(true){
    if(!bfs(s, t)) return ans;
    vector<int> path; path.push_back(t);
    while(path.back() != s){
      path.push_back(pa[path.back()]);
    }
    reverse(path.begin(), path.end());
    ans += 1;
    for(int i=0;i<path.size()-1;i++){
      int a = path[i];
      int b = path[i+1];
      res[a][b] -= 1;
      res[b][a] += 1;
    }
  }
  return ans;
}

