struct Dinitz {
    int n, s, t;
    struct edge {
        int u, v, c, f;
    };
    vector<vector<int> > graph;
    vector<edge> E;
    Dinitz(int n = 0, int s = 0, int t = 0): n (n), s (s), t (t) {
        E.clear();
        graph.assign(n+1, vector<int> ());
    }
    void addEdge(int u, int v, int c) {
        graph[u].push_back(E.size()); E.push_back({u, v, c, 0});
        graph[v].push_back(E.size()); E.push_back({v, u, 0, 0});
    }
    vector<int> dist, ptr;
    bool bfs() {
        dist.assign(n+1, 1e9 + 7); ptr.assign(n+1, 0);
        dist[s] = 0;
        queue<int> wl; wl.push(s);
        while(not wl.empty()) {
            int u = wl.front(); wl.pop();
            for(int i : graph[u]) {
                if(dist[E[i].v] == 1e9 + 7 && E[i].f < E[i].c) {
                    dist[E[i].v] = dist[u] + 1;
                    wl.push(E[i].v);
                }
            }
        }
        return dist[t] != 1e9 + 7;
    }
    int dfs(int u, int flow) {
        if(u == t || not flow) return flow;
        for(int &j = ptr[u]; j < graph[u].size(); j++) {
            int i = graph[u][j];
            if(E[i].f >= E[i].c || dist[E[i].v] != dist[u] + 1) continue;
            int sendFlow = dfs(E[i].v, min(flow, E[i].c - E[i].f));
            if(sendFlow) {
                E[i].f += sendFlow, E[i^1].f -= sendFlow;
                return sendFlow;
            }
        }
        return 0;
    }
    int maxflow() {
        while(bfs()) {
            while(dfs(s, 1e9 + 7));
        }
        int ans = 0;
        for(int i : graph[s]) ans += E[i].f;
        return ans;
    }
} maxflow;

