struct edge {ll to, cap, rev;};
vector<vector<edge>> G;
vector<bool> used;
ll N;

void add_edge (ll from, ll to, ll cap) {
    G[from].push_back({to, cap, (ll)G[to].size()});
    G[to].push_back({from, 0, (ll)G[from].size()-1});
}

ll dfs (ll v, ll t, ll f) {
    if (v == t) return f;
    used[v] = true;
    for (edge &e : G[v]) {
        if (!used[e.to] and e.cap > 0) {
            ll d = dfs (e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }

    return 0;
}

ll max_flow (ll s, ll t, ll N) {
    ll flow = 0;
    while (true) {
        used.assign(N, false);
        ll f = dfs(s, t, inf);
        if (f == 0) return flow;
        flow += f;
    }
}

