int c[maxN][maxN], f[maxN][maxN], m, n, pre[maxN], sr, sc, tr, tc, target, source, check[maxN], q[maxN], res;
char s[maxN];

bool find_flow() {
    foru(i, 0, m + n + 1) check[i] = 0;
    int l = 1, r = 1;
    q[1] = source;
    check[source] = 1;
    while (l <= r) {
        int u = q[l++];
        foru(v, 0, m + n + 1)
            if (f[u][v] < c[u][v] && !check[v]) {
                check[v] = 1;
                pre[v] = u;
                if (v == target) return true;
                q[++r] = v;
            }
    }
    return false;
}

void increase_flow() {
    int v = target, delta = oo;
    while (v != source) {
        int u = pre[v];
        delta = min(delta, c[u][v] - f[u][v]);
        v = u;
    }
    v = target; res += delta;
    while (v != source) {
        int u = pre[v];
        f[u][v] += delta;
        f[v][u] -= delta;
        v = u;
    }
}

int main() {
    scanf("%d %d\n", &m, &n);
