            }
            if (s[j - 1] == 'T') {
                tr = i;
                tc = j + m;
            }
            if (s[j - 1] == 'o') c[i][j + m] = c[j + m][i] = 1;
        }
    }
    source = 0;
    target = m + n + 1;
    c[source][sr] = c[source][sc] = oo;
    c[tr][target] = c[tc][target] = oo;
    while (find_flow()) increase_flow();
    cout << ((res == oo) ? -1 : res);
}

