            if(a[i][j] == 'S') {
                s = i * h + j;
                a[i][j] = 'o';
            }
            if(a[i][j] == 'T') {
                t = i * h + j;
                a[i][j] = 'o';
            }
        }
    }
    if(s % h == t % h || s / h == t / h) {
        cout << -1 << endl;
        return;
    }
    rep(i, h) {
        for(int j = i + 1; j < h; ++j) {
            rep(k, w) {
                if(a[i][k] == 'o' && a[j][k] == 'o') {
                    if(i * h + k != t && j * h + k != t) G.add_undirected_edge(i * h + k, j * h + k, INF);
                }
            }
        }
    }
    rep(i, w) {
        for(int j = i + 1; j < w; ++j) {
            rep(k, h) {
                if(a[k][i] == 'o' && a[k][j] == 'o') {
                    if(k * h + i != t && k * h + j != t) G.add_undirected_edge(k * h + i, k * h + j, INF);
                }
            }
        }
    }
    rep(i, h) {
        rep(j, w) {
            if(a[i][j] == 'o') {
                G.addedge(i * h + j, t, 1LL);
            }
        }
    }
    Dinic<ll> di;
    cout << di.solve(G, s, t) << endl;
}

