char get(){
	char c=getchar();
	for (;c!='.'&&c!='o'&&c!='S'&&c!='T';c=getchar());
	return c;
}
void line(int x,int y,int flow){
	e[++et].l=he[x];he[x]=et;
	e[et].to=y;e[et].flow=flow;
}
void add(int x,int y,int flow){
	line(x,y,flow);line(y,x,flow);
}
int h,t,q[N],d[N];
bool build(){
	for (int i=1;i<=T;i++) d[i]=0;
	h=0;q[t=1]=S;d[S]=1;
	while (h!=t) for (int x=q[++h],y,i=he[x];i;i=e[i].l)
		if (e[i].flow&&!d[y=e[i].to]){
			d[y]=d[x]+1,q[++t]=y;if (y==T) return 1;
		}
	return 0;
}
int dfs(int x,int flow){
	if (x==T) return flow;
	int rest=flow,use,i,y;
	for (i=he[x];i&&rest;i=e[i].l) if (e[i].flow&&
		d[y=e[i].to]==d[x]+1&&(use=dfs(y,min(rest,e[i].flow))))
			e[i].flow-=use,e[i^1].flow+=use,rest-=use;
	if (rest==flow) d[x]=0;return flow-rest;
}
int dinic(){
	int res=0;
	while (build()) res+=dfs(S,inf);
	return res;
}
