const ll inf = 1e18;
const ll mod = 1e9+7;

int dy[] = {0, 0, 1, -1};
int dx[] = {1, -1, 0, 0};

struct edge {
    ll to, cap, rev;
    edge(ll t, ll c, ll r): to(t), cap(c), rev(r){}
};

char field[MAX_V][MAX_V];
vector<edge> G[MAX_V];
ll level[MAX_V];
ll iter[MAX_V];

void add_edge(ll from, ll to, ll cap) {
    G[from].push_back(edge(to, cap, G[to].size()));
    G[to].push_back(edge(from, 0, G[from].size() - 1));
}

void bfs(ll s) {
    memset(level, -1, sizeof(level));
    queue<ll> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        ll v = que.front(); que.pop();
        rep(i, G[v].size()) {
            edge &e = G[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

ll dfs(ll v, ll t, ll f) {
    if (v == t) return f;
    for(i, iter[v], G[v].size()) {
        edge &e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            ll d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

ll max_flow(ll s, ll t) {
    ll flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        ll f;
        while ((f = dfs(s, t, inf)) > 0) {
            flow += f;
        }
    }
}

int main() {
    ll H, W; cin >> H >> W;

    ll si, sj, ti, tj;
    rep(i, H) rep(j, W) {
        cin >> field[i][j];
        if (field[i][j] == 'S') si = i, sj = j;
        if (field[i][j] == 'T') ti = i, tj = j;
    }

    if (si == ti || sj == tj) {
        cout << -1 << endl;
        return 0;
    }

    ll S = si * W + sj, T = ti * W + tj;
    rep(i, H) rep(j, W) if (field[i][j] == '.') {
        add_edge(i * W + j, H * W + i * W + j, 1);

        for(k, i+1, H) if (field[k][j] == '.') {
            add_edge(H * W + i * W + j, k * W + j, inf);
            add_edge(H * W + k * W + j, i * W + j, inf);
        }

        for(k, j+1, W) if (field[i][k] == '.') {
            add_edge(H * W + i * W + j, i * W + k, inf);
            add_edge(H * W + i * W + k, i * W + j, inf);
        }
    }
    cout << max_flow(H * W + S, T) << endl;

    return 0;
}

