const int INF = 1 << 29;

struct Edge
{
    int to, rev;
    int capacity;

    Edge(int to_, int capacity_, int rev_)
            : to(to_), capacity(capacity_), rev(rev_){}
};

int DFS(int current, int target, int flow,
        std::vector<std::vector<Edge>>& connection,
        std::vector<bool>& seenTable)
{
    if (current == target)
        return flow;

    seenTable[current] = true;
    for (auto& e : connection[current])
    {
        if (!seenTable[e.to] && 0 < e.capacity)
        {
            auto d = DFS(e.to, target, std::min(flow, e.capacity), connection, seenTable);
            if (0 < d)
            {
                // d だけ e に流す
                e.capacity -= d;

                // d だけ 逆編から流れる
                connection[e.to][e.rev].capacity += d;

                return d;
            }
        }
    }

    return 0;
}

int MaxFlow(int s, int t, std::vector<std::vector<Edge>>& connection)
{
    std::vector<bool> seenTable(connection.size());

    int flow = 0;
    while (true)
    {
        for (auto i=0; i<seenTable.size(); ++i)
            seenTable[i] = false;

        int f = DFS(s, t, INF, connection, seenTable);
        if (f == 0)
            return flow;
        else
            flow += f;
    }
}

int main()
{
    int H, W;
    std::cin >> H >> W;

    std::vector<std::vector<char>> tile(H, std::vector<char>(W));
    for (auto i=0; i<H; ++i)
        for (auto j=0; j<W; ++j)
            std::cin >> tile[i][j];

    std::vector<std::vector<Edge>> graph;
    graph.resize(H + W + 2);

    const int S = 0;
    const int T = 1;

    // S と T で id を先約してる分ずらす
    auto ToXNode = [&](int x) { return x + H + 2; };
    auto ToYNode = [&](int y) { return y + 2; };
    auto Connect = [&](int from, int to, int capacity)
            {
                graph[from].push_back(Edge(to, capacity, graph[to].size()));
                graph[to].push_back(Edge(from, 0, graph[from].size() - 1));
            };
    for (auto i=0; i<H; ++i)
    {
        for (auto j=0; j<W; ++j)
        {
            // S からや、 T へ直接飛んだら達成不可能(= cap is INF)
            if (tile[i][j] == 'S')
            {
                Connect(S, ToXNode(j), INF);
                Connect(S, ToYNode(i), INF);
            }
            else if (tile[i][j] == 'T')
            {
                Connect(ToXNode(j), T, INF);
                Connect(ToYNode(i), T, INF);
            }

            if (tile[i][j] != '.')
            {
                Connect(ToXNode(j), ToYNode(i), 1);
                Connect(ToYNode(i), ToXNode(j), 1);
            }
        }
    }

    auto result = MaxFlow(S, T, graph);
    if (INF <= result)
        std::cout << -1 << std::endl;
    else
        std::cout << result << std::endl;
}

