template <class T = long long>
struct edge_cap {
	T cap;
	int from;
	int to;
	int rev;  // fromの方の配列で逆辺が何番目に存在するか
};
template <class T = long long>
class Dinic {
   private:
	int ver;  //頂点数
	vector<vector<edge_cap<T>>> edges;
	vector<int> level;
	vector<int> chk;

   public:
	Dinic() = default;
	Dinic(int vertex) : ver(vertex), edges(vertex), level(vertex, -1), chk(vertex, 0) {}

	//辺と逆辺の追加 (0-indexed)
	void update(int from, int to, T cap = 1) {
		edge_cap<T> e;
		e.cap = cap;
		e.from = from;
		e.to = to;
		e.rev = (int)edges[to].size();
		edges[from].push_back(e);

		e.cap = (T)0;
		swap(e.to, e.from);
		e.rev = (int)edges[from].size() - 1;
		edges[to].push_back(e);
	}

	//入力受取 (1-indexed)
	void input(int edge_num, int index = 1) {
		for(int i = 0; i < edge_num; i++) {
			int a;
			int b;
			T cap;
			cin >> a >> b >> cap;
			a -= index;
			b -= index;
			update(a, b, cap);
		}
	}

   private:
	//有効な辺のみを用いた幅優先探索で距離を求める
	void bfs(int s) {
		level.assign(ver, -1);
		level[s] = 0;
		queue<int> q;
		q.push(s);
		while(!q.empty()) {
			int now = q.front();
			q.pop();
			for(auto &e : edges[now]) {
				if(level[e.to] >= 0) continue;
				if(e.cap <= 0) continue;
				level[e.to] = level[now] + 1;
				q.push(e.to);
			}
		}
		return;
	}

	//流せる辺を探す
	T dfs(int now, int t, T f) {
		if(now == t) return f;
		for(int i = chk[now]; i < (int)edges[now].size(); i++) {
			auto &e = edges[now][i];
			if(level[now] + 1 != level[e.to] || e.cap <= 0) {
				chk[now]++;
				continue;
			}
			T k = dfs(e.to, t, min(f, e.cap));
			if(k > 0) {
				e.cap -= k;
				edges[e.to][e.rev].cap += k;
				return k;
			}
			chk[now]++;
		}
		return (T)0;
	}

   public:
	T maxflow(int s, int t) {
		T flow = 0;
		const T INF = 3e16;	 // T == int だとバグる
		while(1) {
			bfs(s);
			if(level[t] < 0) return flow;
			for(int i = 0; i < ver; i++) chk[i] = 0;
			T fl = 1;
			while(fl > 0) {
				fl = dfs(s, t, INF);
				flow += fl;
			}
		}
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout << fixed << setprecision(15);
	srand((unsigned)time(NULL));

	using pii = pair<int, int>;
	INT(h, w);
	VVEC(char, c, h, w);
	vvi a(h, vi(w, 0));
	pii start, goal;
	rep(i, h) rep(j, w) {
		if(c[i][j] == 'S') {
			start = {i, j};
		} else if(c[i][j] == 'T') {
			goal = {i, j};
		}
		if(c[i][j] != '.') {
			a[i][j] = 1;
		}
	}

	Dinic<> din(h * w * 2);

	int n = h * w;
	int n2 = n * 2;

	auto con = [&](int a, int b) { return a * w + b; };

	rep(i, h) rep(j, w) Rep(k, j + 1, w) if(a[i][j] && a[i][k]) {
		din.update(con(i, j) + n, con(i, k), dekai);
		din.update(con(i, k) + n, con(i, j), dekai);
	}

	rep(i, w) rep(j, h) Rep(k, j + 1, h) if(a[j][i] && a[k][i]) {
		din.update(con(j, i) + n, con(k, i), dekai);
		din.update(con(k, i) + n, con(j, i), dekai);
	}

	rep(i, h) rep(j, w) {
		if(a[i][j]) {
			din.update(con(i, j), con(i, j) + n, 1LL);
		}
	}

	ll ans = din.maxflow(con(start.first, start.second) + n, con(goal.first, goal.second));
	if(ans >= dekai) ans = -1;
	drop(ans);
	return 0;
}

