	edge(llint a, llint b, llint c){
		to = a, cap = b, rev = c;
	}
};


llint h, w;
vector<edge> G[205];
llint S, T;
llint level[255], iter[255];

void bfs(llint s)
{
	for(int i = 1; i <= T; i++) level[i] = inf;
	level[s] = 0;

	queue<int> Q;
	Q.push(s);
	while(Q.size()){
		int v = Q.front();
		Q.pop();
		for(int i = 0; i < G[v].size(); i++){
			int u = G[v][i].to;
			if(G[v][i].cap <= 0 || level[u] < inf) continue;
			level[u] = level[v] + 1;
			Q.push(u);
		}
	}
}

llint dfs(int v, llint f)
{
	if(v == T) return f;

	llint ret;
	for(llint &i = iter[v]; i < G[v].size(); i++){
		if(level[v] >= level[G[v][i].to] || G[v][i].cap <= 0) continue;
		ret = dfs(G[v][i].to, min(f, G[v][i].cap));
		if(ret > 0){
			G[v][i].cap -= ret;
			G[G[v][i].to][G[v][i].rev].cap += ret;
			return ret;
		}
	}
	return 0;
}

void add_edge(int s, int t, llint cap)
{
	G[s].push_back(edge(t, cap, G[t].size()));
	G[t].push_back(edge(s, 0, G[s].size()-1));
}

int main(void)
{
	cin >> h >> w;
	S = h+w+1, T = h+w+2;

	char c;
	for(int y = 1; y <= h; y++){
		for(int x = 1; x <= w; x++){
			cin >> c;
			if(c == 'S'){
				add_edge(S, x, inf);
				add_edge(S, y+w, inf);
			}
			if(c == 'T'){
				add_edge(x, T, inf);
				add_edge(y+w, T, inf);
			}
			if(c == 'o'){
				add_edge(x, y+w, 1);
				add_edge(y+w, x, 1);
			}
		}
	}

	llint ans = 0, flow;
	while(1){
		bfs(S);
		if(level[T] >= inf) break;
		for(int i = 1; i <= T; i++) iter[i] = 0;
		while(1){
			flow = dfs(S, inf);
			if(flow <= 0) break;
			ans += flow;
		}
	}
	if(ans > inf/2) cout << -1 << endl;
	else cout << ans << endl;

	return 0;
}

