int flow(int v, int t, int f) {
	if (v == t) {
		return f;
	}
	for (int &i = iter[v]; i < edge[v].size(); i++) {
		Edge &e = edge[v][i];
		if (e.cost > 0 && dis[v] < dis[e.to]) {
			int d = flow(e.to, t, min(f, e.cost));
			if (d > 0) {
				e.cost -= d;
				edge[e.to][e.rev_num].cost += d;
				return d;
			}
		}
	}
	return 0;
}

