    }
  }
  if (sy == gy or sx == gx) {
    cout << -1 << endl;
    return 0;
  }

  auto n = h + w;
  Graph<int> g(n + 2);
  auto S = n, T = n + 1;
  auto inf = numeric_limits<int>::max() / 3;
  g.add_edge(S, sy, inf); // S は壊せない
  g.add_edge(S, sx + h, inf);
