using namespace std;
struct Ford_Flukerson{
  ll INF = 1000000000000000000, MAX_V;
  struct edge{ll to, cap, rev;};
  vector<vector<edge>> G;
  vector<bool> used;
  Ford_Flukerson(ll n){
    MAX_V = n+1;
    G.resize(n+1);
    used.resize(n+1);
  }
  void add_edge(ll from, ll to, ll cap){
    G[from].push_back(edge{to, cap, (ll)G[to].size()});
    G[to].push_back(edge{from, 0, (ll)G[from].size() - 1});
  }
  ll dfs(ll v, ll t, ll f){
    if(v==t) return f;
    used[v] = true;
    for(int i=0;i<G[v].size();i++){
      edge &e = G[v][i];
      if(!used[e.to] && e.cap>0){
        ll d = dfs(e.to, t, min(f, e.cap));
        if(d>0){
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }
  ll max_flow(ll s, ll t){
    ll flow = 0;
    for(;;){
      for(int i=0;i<MAX_V;i++) used[i] = false;
      ll f = dfs(s, t, INF);
      if(f==0) return flow;
      flow += f;
    }
  }
};
int main(int argc, char const *argv[]) {
  ll h, w;std::cin >> h >> w;
  Ford_Flukerson D(300);
  vector<string> dat(h);
  vll s, t;
