      if(dat[i][j]=='T') {
        D.add_edge(i, 202, 10000);
        D.add_edge(j+100, 202, 10000);
        t = vll{i, j};
      }
      if(dat[i][j]!='.'){
        D.add_edge(i, j+100, 1);
        D.add_edge(j+100, i, 1);
      }
    }
  }
  if(s[0]==t[0]||s[1]==t[1]){
    std::cout << -1 << '\n';
    return 0;
  }
  ll ans = D.max_flow(201, 202);
