template<typename T, bool is_directed> class Dinic {
private:
  struct edge {
    int to;
    T capacity;
    int rev;
    edge() {}
    edge (int _to, T _capacity, int _rev) : to(_to), capacity(_capacity), rev(_rev) {}
    void add (int _to, T _capacity, int _rev) {to = _to; capacity = _capacity; rev = _rev;}
  };
  vector<vector<edge>> graph;
  vector<int> level, iter;
public:
  Dinic() {}
  Dinic(int n) : graph(n), level(n), iter(n) {}
  void add(int from, int to, T capacity) {
    if (to == h + w + 1) {
      graph[from].emplace_back(to, capacity, (int) graph[to].size());
      graph[to].emplace_back(from, 0, (int) graph[from].size() - 1);
    } else if (from == h + w) {
      graph[from].emplace_back(to, capacity, (int) graph[to].size());
      graph[to].emplace_back(from, 0, (int) graph[from].size() - 1);
    } else {
      graph[from].emplace_back(to, capacity, (int) graph[to].size());
      graph[to].emplace_back(from, capacity, (int) graph[from].size() - 1);
    }
    //graph[from].emplace_back(to, capacity, (int) graph[to].size());
    //graph[to].emplace_back(from, (is_directed ? 0 : capacity), (int) graph[from].size() - 1);
  }
  void bfs(int s) {
    fill(level.begin(), level.end(), -1);
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while (que.size()) {
      int cur = que.front();
      que.pop();
      for (edge& e : graph[cur]) {
        if (e.capacity > 0 && level[e.to] == -1) {
          level[e.to] = level[cur] + 1;
          que.push(e.to);
        }
      }
    }
  }
  T dfs(int v, int t, T f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < (int) graph[v].size(); i++) {
      edge& e = graph[v][i];
      if (e.capacity > 0 && level[v] < level[e.to]) {
        T d = dfs(e.to, t, min(f, e.capacity));
        if (d == 0) continue;
        e.capacity -= d;
        graph[e.to][e.rev].capacity += d;
        return d;
      }
    }
    return 0;
  }
  T flow(int s, int t, T lim) {
    T fl = 0;
    while (true) {
      bfs(s);
      if (level[t] < 0 || lim == 0) break;
      fill(iter.begin(), iter.end(), 0);
      while (true) {
        T f = dfs(s, t, lim);
        if (f == 0) break;
        fl += f;
        lim -= f;
      }
    }
    return fl;
  }
  T flow(int s, int t) {
    return flow(s, t, numeric_limits<T>::max() >> 1);
  }
};
