                ff.add_edge(j + h + 2, 1, INF);
            } else if (a[i][j] == 'o') {
                ff.add_edge(i + 2, j + h + 2, 1);
                ff.add_edge(j + h + 2, i + 2, 1);
            }
        }
    }
    int ans = ff.flow(0, 1, INF);
