    Dinic<int> g(h * w * 2);

    auto index = [&] (int i, int j) { return (i * w + j); };
    auto outdex = [&] (int i, int j) { return (index(i, j) + h * w); };

    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) {
        if (s[i][j] == '.') continue;
        if (s[i][j] == 'T') { goal = index(i, j); continue; }
        if (s[i][j] == 'S') start = index(i, j);
        if (s[i][j] == 'o') { g.add_edge(index(i, j), outdex(i, j), 1); };
        for (int k = 0; k < h; k++) if (i != k and s[k][j] != '.' and s[k][j] != 'S') {
            if (s[i][j] == 'S') g.add_edge(start, index(k, j), INF);
            else g.add_edge(outdex(i, j), index(k, j), INF);
        }
        for (int k = 0; k < w; k++) if (j != k and s[i][k] != '.' and s[i][k] != 'S') {
            if (s[i][j] == 'S') g.add_edge(start, index(i, k), INF);
            else g.add_edge(outdex(i, j), index(i, k), INF);
        }
    }

    int ans = g.max_flow(start, goal);

    cout << ans << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Network
{
    int N = 2, source = 0, sink = 1;
    struct Edge { int source, target, id, reverse; };
    vector<vector<Edge>> adjacency_lists;
    vector<int> capacities, flows;

    Network() : adjacency_lists(2) {}

    int add_vertex()
    {
        adjacency_lists.push_back({});
        return N++;
    }

    void add_undirected_edge(const int a, const int b, const int capacity)
    {
        add_edge(a, b, capacity);
        add_edge(b, a, capacity);
    }

    void add_edge(const int source, const int target, const int capacity)
    {
        if (source == target) return;
        const auto id = int(capacities.size());
        const auto reverse = id+1;
        adjacency_lists[source].push_back({source, target, id, reverse});
        adjacency_lists[target].push_back({target, source, reverse, id});
        capacities.insert(end(capacities), {capacity, 0});
        flows.insert(end(flows), {0, 0});
    }

    int maxflow()
    {
        auto seen = vector<bool>(N);
        const function<int(int, int)> dfs = [&](const int v, const int flow)
        {
            if (v == sink) return flow;

            if (seen[v]) return 0;
            else seen[v] = true;

            for (const auto e : adjacency_lists[v])
            {
                const auto residual = capacities[e.id] - flows[e.id];
                if (residual == 0) continue;
                if (const auto x = dfs(e.target, min(flow, residual)))
                {
                    flows[e.id] += x;
                    flows[e.reverse] -= x;
                    return x;
                }
            }
            return 0;
        };

        auto flow = 0;
        while (true)
        {
            fill(begin(seen), end(seen), false);
            const auto delta = dfs(source, numeric_limits<int>::max());
            if (delta > 0) flow += delta;
            else break;
        }
        return flow;
    }
};

int main()
{
    int R, C; cin >> R >> C;

    auto network = Network();

    auto rows = vector<int>(R);
    for (auto r = 0; r < R; r++)
        rows[r] = network.add_vertex();

    auto columns = vector<int>(C);
    for (auto c = 0; c < C; c++)
        columns[c] = network.add_vertex();

    const auto infinity = R + C;
    for (auto r = 0; r < R; r++)
    {
        string row; cin >> row;
        for (auto c = 0; c < C; c++)
        {
            if (row[c] == 'o')
                network.add_undirected_edge(rows[r], columns[c], 1);
            else if (row[c] == 'S')
            {
                network.source = rows[r];
                network.add_undirected_edge(rows[r], columns[c], infinity);
            }
            else if (row[c] == 'T')
            {
                network.sink = columns[c];
                network.add_undirected_edge(rows[r], columns[c], infinity);
            }
        }
    }

    const auto mincut = network.maxflow();
    cout << (mincut >= infinity ? -1 : mincut) << endl;
}

