int dfs (int u,int minf) {
    if(u == EN)
        return minf;

    int chan = EN;
    int leff = minf;

    for(int i = head[u];i != -1;i = e[i].next) {
        int v = e[i].v;

        if(dis[v] == dis[u] - 1 && e[i].f) {
            int t = dfs(v,min(leff,e[i].f));
            e[i].f -= t;
            e[i ^ 1].f += t;
            leff -= t;

            if(dis[ST] >= EN + 1)
                return minf - leff;
			if(!leff)
				break;
        }
        if(e[i].f)
            chan = min(chan,dis[v]);
    }

    if(minf == leff) {
        --gap[dis[u]];
        if(gap[dis[u]] == 0)
            dis[ST] = EN + 1;
        dis[u] = chan + 1;
