    }
    f.init(h*w*2);
    for(int i=0;i<h;i++){
        for(int j=0;j<w;j++){
            int id = i*w+j;
            if(brd[i][j] == '.') continue;
            if(brd[i][j] == 'S') source = id;
            if(brd[i][j] == 'T') sink = id;
            f.add_edge(id+h*w, id, 1);
            for(int k=0;k<h;k++){
                if(k != i && brd[k][j] != '.'){
                    f.add_edge(id, k*w+j+h*w, h+w);
                }
            }
            for(int k=0;k<w;k++){
                if(k != j && brd[i][k] != '.'){
                    f.add_edge(id, i*w+k+h*w, h+w);
                }
            }
        }
    }
    int ans = f.max_flow(source, sink+h*w);
    if(ans >= h+w) ans = -1;
    cout << ans << endl;
}

