void make_edge(int u,int v) {
	G[u].emplace_back((int)E.size());
	E.emplace_back(edge{v,1});
	G[v].emplace_back((int)E.size());
	E.emplace_back(edge{u,0});
}
int dis[maxn*maxn*2];
bool bfs(int st,int ed) {
	memset(dis,-1,sizeof dis);
	dis[st] = 0;
	queue<int> q;
	q.push(st);
	while(!q.empty()) {
		int u = q.front();
		q.pop();
		for(int idx : G[u]) {
			int v = E[idx].v , cap = E[idx].cap;
			if(cap > 0 && dis[v] == -1) {
				dis[v] = dis[u] + 1;
				q.push(v);
			}
		}
	}
	return dis[ed] != -1;
}
int cur[maxn*maxn*2];
int dfs(int u,int flow,int ed) {
	if(u == ed)
		return flow;
	else {
		for(;cur[u] < (int)G[u].size();cur[u]++) {
			int idx = G[u][cur[u]];
			int v = E[idx].v , cap = E[idx].cap;
			if(dis[u] + 1 == dis[v] && cap > 0) {
				int now = dfs(v,min(flow,cap),ed);
				if(now != 0) {
					E[idx].cap   -= now;
					E[idx^1].cap += now;
					return now;	
				}
			}
		}
		dis[u] = -1;
		return 0;
	}
}
