bool addEdge(int f, int t, int cap, int rev_cap) {
	if (f / 2 == S) f = (f / 2) * 2; if (f / 2 == T) f = (f / 2) * 2;
	if (t / 2 == S) t = (t / 2) * 2; if (t / 2 == T) t = (t / 2) * 2;
	if (f == t) return true;
	if ((f == 2 * S && t == 2 * T) || (f == 2 * T && t == 2 * S)) {
		return false;
	}

	edge e; e.f = f; e.t = t; e.cap = cap; e.rev_id = g + 1; e.flow = 0;
	edge e_rev; e_rev.f = t; e_rev.t = f; e_rev.cap = rev_cap; e_rev.rev_id = g; e_rev.flow = 0;

	v[f].push_back(g);
	v[t].push_back(g + 1);

	edges[g++] = e;
	edges[g++] = e_rev;
	return true;
}

int q[20004], qs, qf;
int d[20004];
bool BFS() {
	qs = 0; qf = 0;
	q[qf++] = 2 * S;
	memset(d, 0, sizeof(d));
	d[2 * S] = 1;
	while (qs != qf) {
		int x = q[qs++];
		for (int i = 0; i < v[x].size(); i++) {
			edge e = edges[v[x][i]];
			if (d[e.t]) continue;
			if (e.cap - e.flow > 0) {
				q[qf++] = e.t;
				d[e.t] = d[e.f] + 1;
			}
		}
	}
	return d[2 * T] != 0;
}

int myMin(int x, int y) {
	return x < y ? x : y;
}

int f[20004];
int refr[20004];
int DFS(int x, int mn, int prev) {
	f[x] = 1;
	if (x == 2 * T) {
		return mn;
	}
	for (; refr[x] < v[x].size(); refr[x]++) {

		edge e = edges[v[x][refr[x]]];

		if (!f[e.t] && e.cap - e.flow > 0 && d[e.t] == d[e.f] + 1) {
			int h = DFS(e.t, myMin(mn, e.cap - e.flow), e.f);
			if (h != 0) {
				edges[v[x][refr[x]]].flow += h;
				edges[e.rev_id].flow -= h;
				return h;
			}
		}
	}
	return 0;
}

