void BFS(int S){
  memset(level,-1,sizeof(level));
  queue<int> que;
  level[S]=0;
  que.push(S);
  while(!que.empty()){
    int v=que.front();
    que.pop();
    FOR(i,0,(int)G[v].size()){
      edge &E=G[v][i];
      if(E.cap>0&&level[E.to]<0){
        level[E.to]=level[v]+1;
        que.push(E.to);
      }
    }
  }
}
//
int DFS(int V,int T,int F){
  if(V==T){
    return F;
  }
  for(int &i=iter[V];i<(int)G[V].size();i++){
    edge &E=G[V][i];
    if(E.cap>0&&level[V]<level[E.to]){
      int D=DFS(E.to,T,min(F,E.cap));
      if(D>0){
        E.cap-=D;
        G[E.to][E.rev].cap+=D;
        return D;
      }
    }
  }
  return 0;
}
int MAX_FLOW(int SS,int TT){
  int flow=0;
  while(1){
    BFS(SS);
    if(level[TT]<0){
      return flow;
    }
    memset(iter,0,sizeof(iter));
    int F;
    while((F=DFS(SS,TT,INF))>0){
      flow+=F;
    }
  }
}
