struct MaxFlow{
private:
    struct edge{ int to, cap, rev, num; bool isrev; };

    int V;
    vector<vector<edge>> G;
    vector<bool> used;

public:
    vector<int> edges;

    MaxFlow(int _V=0){
        V = _V;
        G.resize(V);
        used.resize(V);
    }

    void add(int from, int to, int cap){
        G[from].push_back({ to, cap, (int)G[to].size(),(int)edges.size(),false });
        G[to].push_back({ from, 0, (int)G[from].size()-1,(int)edges.size(),true });
        edges.push_back(0);
    }

    int dfs(int v, int t, int f){
        if(v == t) return f;
        used[v] = true;
        for(int i=0; i<G[v].size(); i++){
            edge& e = G[v][i];
            if(!used[e.to] && e.cap > 0){
                int d = dfs(e.to, t, min(f, e.cap));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    if(!e.isrev) edges[e.num] += d;
                    else edges[e.num] -= d;
                    return d;
                }
            }
        }
        return 0;
    }

    int calculate(int s, int t){
        int ret = 0;
        while(true){
            used.assign(V, false);
            int f = dfs(s, t, INT_MAX);
            if(f == 0) break;
            ret += f;
        }
        return ret;
    }
};

