const int MAX_V = 20010;
struct MAXFLOW_MINIMUMCUT_FLOW{
	vector<FLOW_EDGE*> G[MAX_V];
	bool used[MAX_V];

	void add_edge(int from,int to,int flow){
		G[from].pb(new FLOW_EDGE);
		G[to].pb(new FLOW_EDGE);
		G[from][G[from].size()-1]->init(to,flow,G[to][G[to].size()-1]);
		G[to][G[to].size()-1]->init(from,0,G[from][G[from].size()-1]);
	}

	int dfs(int v,int t,int f){
		if(v == t)return f;
		used[v] = true;
		for(int i = 0 ; i < G[v].size() ; i ++){
			FLOW_EDGE* ed = G[v][i];
			if(ed->flow > 0 && !used[ed->to]){
				int d = dfs(ed->to,t,min(f,ed->flow));
				//int d = min( ed->flow , dfs(ed->to,t,f) );
				if(d > 0){
					ed->flow -= d;
					ed->rev->flow += d;
					return d;
				}
			}
		}
		return 0;
	}

	int flow(int s,int t){
		int ret = 0;
		int d = 1;
		while(d > 0){
			for(int i = 0 ; i < MAX_V ; i ++){
				used[i] = false;
			}
			d = dfs(s,t,INF);
			ret += d;
		}
		return ret;
	}
};

