bool mat[101][101];

int check(P s, P t, int h, int w) {
  set<int> hset[101];
  set<int> wset[101];
  vector<P> leaves;
  int cnt = 0;
  rep(i, h) {
    if (i == s.first) continue;
    rep(j, w) {
      if (j == s.second) continue;
      if (mat[i][j]) {
        debug(cnt, i, j);
        hset[i].insert(cnt);
        wset[j].insert(cnt);
        leaves.emplace_back(i, j);
        cnt++;
      }
    }
  }
  hset[t.first].insert(cnt);
  wset[t.second].insert(cnt);
  leaves.emplace_back(t.first, t.second);
  cnt++;
  vector<bool> used(cnt);
  vector<bool> hreach(h);
  vector<bool> wreach(w);
  stack<int> st;
  for(auto e: hset[t.first]) {
    st.push(e);
  }
  hset[t.first].clear();
  for(auto e: wset[t.second]) {
    st.push(e);
  }
  wset[t.second].clear();
  while(st.size()) {
    int p = st.top(); st.pop();
    used[p] = true;
    for(auto e: hset[leaves[p].first]) {
      if (!used[e]) {
        st.push(e);
      }
    }
    hset[leaves[p].first].clear();
    for(auto e: wset[leaves[p].second]) {
      if (!used[e]) {
        st.push(e);
      }
    }
    wset[leaves[p].second].clear();
    debug(p, leaves[p].first, leaves[p].second);
    hreach[leaves[p].first] = true;
    wreach[leaves[p].second] = true;
  }

  int ans = 0;
  rep(i, h) {
    if (mat[i][s.second] && hreach[i]) {
      ans++;
    }
  }
  rep(j, w) {
    if (mat[s.first][j] && wreach[j]) {
      ans++;
    }
  }
  return ans;
}

