class NetworkFlow {
public:
	//引数：頂点数
	NetworkFlow(){}
	NetworkFlow(int size) {
		G.resize(size);
		used.resize(size);
	}

	//fromからtoへ向かう容量capの辺をグラフに追加する
	void add_edge(int from, int to, int cap) {
		Edge e1 = { to, cap, (int)G[to].size() };
		Edge e2 = { from, 0, (int)G[from].size() - 1 };
		G[from].push_back(e1);
		G[to].push_back(e2);
	}

	//sからtへの最大流を求める
	int max_flow(int s, int t) {
		int flow = 0;
		while (true) {
			fill(used.begin(), used.end(), false);
			int f = dfs(s, t, INF);
			if (f == 0)return flow;
			flow += f;
		}
	}




private:
	//型と変数
	struct Edge { int to, cap, rev; };//辺を表す構造体（行き先、容量、逆辺）
	vector<vector<Edge>> G;   //グラフの隣接リスト表現
	vector<bool> used;//DFSで既に調べたかのフラグ

					  //関数
					  //増加パスをDFSで探す
	int dfs(int v, int t, int f) {
		if (v == t)return f;
		used[v] = true;
		REP(i, (int)G[v].size()) {
			Edge& e = G[v][i];
			if (!used[e.to] && e.cap > 0) {
				int d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};
using NF = NetworkFlow;




//変数
int H, W;
vector<vector<bool>> exist;
pair<int, int> start, goal;

NF nf;




//サブ関数
//入力
void input()
{
	cin >> H >> W;
	exist = vector<vector<bool>>(H, vector<bool>(W, false));
	nf = NetworkFlow(H*W);

	string tmps;
	REP(i, H) {
		cin >> tmps;
		REP(j,W){
			switch (tmps[j]) {
			case 'S':
				start = make_pair(i, j);
				exist[i][j] = true;
				break;
			case 'T':
				goal = make_pair(i, j);
				exist[i][j] = true;
				break;
			case 'o':
				exist[i][j] = true;
				break;
			}
		}
	}
}

//2次元空間を、1次元空間に変換します
int trans(int i, int j) {
	return i * W + j;
}

int trans(pair<int, int> ij) {
	return trans(ij.first, ij.second);
}

//計算
void calc()
{
	//横の辺を追加
	REP(i, H)REP(j, W)if (exist[i][j])
		FOR(k, j + 1, W)if (exist[i][k])
			nf.add_edge(trans(i, j), trans(i, k), 1);
	//縦の辺を追加
	REP(j, W)REP(i, H)if (exist[i][j])
		FOR(k, i + 1, H)if (exist[k][j])
			nf.add_edge(trans(i, j), trans(k, j), 1);
}


