            if (line[j] == 'S') {
                s = i;
                ss = j + h;
            } else if (line[j] == 'T') {
                t = i;
                tt = j + h;
            }
        }
    }

    if (s == t || ss == tt) {
        cout << -1 << endl;
        return 0;
    }

    int64_t n = h + w;
    vector<vector<pair<int64_t, pair<int64_t, int64_t>>>> edges(n);
    for (auto i : irange(0L, h)) {
        for (auto j : irange(0L, w)) {
            if (table[i][j] == '.') {
                continue;
            }

            auto v = i;
            auto u = h + j;
            if (u == ss) {
                u = s;
            } else if (u == tt) {
                u = t;
            }
