#include <bits/stdc++.h>
using i64 = long long;

class Dinic {
    using i64 = long long;
    struct Edge {
        int to;
        i64 cap;
        int rev;
        Edge(int t, i64 c, int r) : to(t), cap(c), rev(r) {}
    };

    std::vector<std::deque<Edge>> g;
    std::vector<int> level;
    std::vector<unsigned> iter;
    int size;

    void bfs(int s) {
        for (int i = 0; i < size; i++) level[i] = -1;
        level[s] = 0;

        std::deque<int> q { s };

        while (!q.empty()) {
            auto curr = q.front();
            q.pop_front();
            for (auto & e : g[curr]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[curr] + 1;
                    q.push_back(e.to);
                }
            }
        }
    }

    i64 dfs(int v, int t, i64 f) {
        if (v == t) return f;

        for (unsigned i = 0; i < g[v].size(); i++) {
            iter[v] = i;
            auto &e = g[v][i];

            if (e.cap > 0 && level[v] < level[e.to]) {
                i64 d = dfs(e.to, t, std::min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }

        return 0;
    }

public:
    static constexpr i64 inf = 1000000000000000;

    explicit Dinic(int s) :
        g(std::vector<std::deque<Edge>>(s)),
        level(std::vector<int>(s)),
        iter(std::vector<unsigned>(s)),
        size(s) {}

    void add_edge(int from, int to, i64 cap) {
        g[from].emplace_back(to, cap, g[to].size());
        g[to].emplace_back(from, 0, g[from].size() - 1);
    }

    i64 calc(int s, int t) {
        i64 flow = 0;
        while (true) {
            bfs(s);
            if (level[t] < 0) return flow;

            for (auto &el : iter) el = 0;

            i64 f = dfs(s, t, inf);
            while (f > 0) {
                flow += f;
                f = dfs(s, t, inf);
            }
        }
    }
};

int main() {
    int h, w;
    std::cin >> h >> w;

    Dinic d(h + w + 2);

    std::string in;
    for (int i = 0; i < h; i++) {
        std::cin >> in;
        for (int j = 0; j < w; j++) {
            char c = in[j];
            if (c == 'o') {
                d.add_edge(i, h + j, 1);
                d.add_edge(h + j, i, 1);
            } else if (c == 'S') {
                d.add_edge(h + w, i, Dinic::inf);
                d.add_edge(h + w, h + j, Dinic::inf);
            } else if (c == 'T') {
                d.add_edge(i, h + w + 1, Dinic::inf);
                d.add_edge(h + j, h + w + 1, Dinic::inf);
            }
        }
    }

    auto ret = d.calc(h + w, h + w + 1);
    if (ret >= Dinic::inf) ret = -1;
    std::cout << ret << std::endl;

    return 0;
}

