const int MAX_V_flow = 20010;
struct FLOW{
	vector<P1> G[MAX_V_flow];
	bool used[MAX_V_flow];

	void init(){
		rep(i,MAX_V_flow)G[i].clear();
	}

	void add_edge(int from,int to,int flow){
		G[from].pb( mp1 ( to , flow , G[to].size() ) );
		G[to].pb( mp1 ( from , 0 , G[from].size()-1 ) );
	}

	int dfs(int v,int t,int f){
		if(v == t)return f;
		used[v] = true;
		rep(i,G[v].size()){
			if(!used[G[v][i].fr] && G[v][i].sc.fr > 0){
				int d = dfs(G[v][i].fr,t,min(f,G[v][i].sc.fr));
				if(d > 0){
					G[v][i].sc.fr -= d;
					G[G[v][i].fr][G[v][i].sc.sc].sc.fr += d;
					return d;
				}
			}
		}
		return 0;
	}

	int flow(int s,int t){
		int ret = 0,d = 1;
		while(d > 0){
			rep(i,MAX_V_flow)used[i] = false;
			d = dfs(s,t,INF);
			ret += d;
		}
		return ret;
	}
}flow;

