const int MAX=1010;
//Ford-Fulkerson
struct edge{
    int to,cap,rev;
};

vector<edge>G[MAX];
vector<int>level(MAX);
vector<int>iter(MAX);

void add_edge(int from,int to,int cap){
    int ts=G[to].size();
    int fs=G[from].size();
    G[from].push_back((edge){to,cap,ts});
    G[to].push_back((edge){from,0,fs});
}

void bfs(int s){
    for(int i=0;i<MAX;i++)level[i]=-1;
    queue<int>q;
    level[s]=0;
    q.push(s);
    while(!q.empty()){
        int v=q.front();
        q.pop();
        for(auto &e:G[v]){
            if(e.cap>0&&level[e.to]<0){
                level[e.to]=level[v]+1;
                q.push(e.to);
            }
        }
    }
}

int dfs(int v,int t,int f){
    if(v==t)return f;
    for(auto &e:G[v]){
        if(e.cap>0&&level[v]<level[e.to]){
            int d=dfs(e.to,t,min(f,e.cap));
            if(d>0){
                e.cap-=d;
                G[e.to][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s,int t){
    int flow=0;
    while(1){
        bfs(s);
        if(level[t]<0)return flow;
        for(int i=0;i<iter.size();i++)iter[i]=0;
        int f;
        while((f=dfs(s,t,inf))>0){
            flow+=f;
        }
    }
}

