struct Dinic {
   	int n, s, t;
   	struct Edge {
    	int to, cap, flow, rev;
    	Edge(int to = 0, int cap = 0, int flow = 0, int rev = 0) :
     	   to(to), cap(cap), flow(flow), rev(rev) {}
   	};
  	vector<int> d;
  	vector<int> ptr;
  	vector<vector<Edge>> g;
  	Dinic(int n = 0, int s = 0, int t = 0) : n(n), s(s), t(t), d(n), ptr(n), g(n) {}
   	void addEdge(int u, int v, int cap) {
//   			cout << "add edge from " << u << " to " << v << " cap " << cap << "\n";
        	g[u].emplace_back(v, cap, 0, g[v].size());
        	g[v].emplace_back(u, 0, 0, g[u].size() - 1);
    	}
   	bool bfs() {
      		fill(d.begin(), d.end(), -1);
      		fill(ptr.begin(), ptr.end(), 0);
      		queue<int> q;
      		d[s] = 0;
      		q.push(s);
      		while (!q.empty()) {
        		int u = q.front();
         		q.pop();
         		for (auto e : g[u]) {
            			if (d[e.to] == -1 && e.cap > e.flow) {
               				d[e.to] = d[u] + 1;
               				q.push(e.to);
            			}
         		}
      		}
      		return d[t] != -1;
   	}
   	int dfs(int u, int flow) {
      		if (u == t) {
      		    return flow;
      		}
      		for (int &i = ptr[u]; i < g[u].size(); ++i) {
        		auto &e = g[u][i];
       			if (e.cap <= e.flow || d[e.to] != d[u] + 1) continue;
         		int nxt = dfs(e.to, min(flow, e.cap - e.flow));
         		if (nxt) {
           		 	e.flow += nxt;
           	 	g[e.to][e.rev].flow -= nxt;
           			return nxt;
         		}
      		}
      		return 0;
   	}
   	int maxFlow() {
      		int ans = 0;
      		while (bfs()) {
         		while (true) {
        	    		int now = dfs(s, inf);
           	 		if (now) ans += now;
           	 		else break;
         		}
      		}
      		return ans;
   	}
} mf;
