	for(int v, &i = cur[u]; i; i = e[i].nxt)
	{
		v = e[i].to;
		if(e[i].flow && d[v] == d[u] + 1)
		{
			tmp = dfs(v, min(a, e[i].flow));
			f += tmp, a -= tmp, e[i].flow -= tmp, e[i ^ 1].flow += tmp; 
		}
		if(!a) break; 
	}
	if(a) d[u] = -1;
	return f; 
}

