ll dfs(int n, int to, ll f) { if (n==to) return f; used[n] = true; for (auto &x: adj[n]) { if (!used[x.to]&&x.cap) { ll d = dfs(x.to, to, min(f,x.cap)); if (d) { x.cap -= d; adj[x.to][x.rev].cap += d; return d; } } } return 0; }
ll FordFulkerson(int from, int to) { int N = adj.size(); used.resize(N,false); ll flow = 0; while (true) { fill(all(used),false); if (ll f = dfs(from,to,LLINF)) flow += f; else return flow; } }

