int dfs(int v, int dest, int f = 1e9) {
	if (v == dest) return f;
	if (mark[v]++) return 0;
	for (int e = head[v]; ~e; e = prev[e]) {
		int u = to[e];
		if (cap[e]) {
			int x = dfs(u, dest, min(f, cap[e]));
			if (x) {
				cap[e] -= x;
				cap[e ^ 1] += x;
				return x;
			}
		}
	}
	return 0;
}
