template <class T = int>
struct Dinic {
    struct Edge {
        int to, rev;
        T cap;
        Edge(int a, T b, int c) : to(a), cap(b), rev(c) {}
    };
    vector<vector<Edge>> g;
    vector<int> lev;
    int n;

    Dinic() = default;
    Dinic(int n) : n(n) {
        g.assign(n, vector<Edge>());
        lev.resize(n);
    }

    void AddEdge(int u, int v, T cap) {
        g[u].emplace_back(v, cap, g[v].size() - 0);
        g[v].emplace_back(u, 0, g[u].size() - 1);
    }

    bool Bfs(int s, int t) {
        fill(lev.begin(), lev.end(), -1);
        lev[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int x = q.front(); q.pop();
            for (Edge &e : g[x]) {
                if (lev[e.to] == -1 && e.cap > 0) {
                    lev[e.to] = lev[x] + 1;
                    q.push(e.to);
                }
            }
        }
        return lev[t] != -1;
    }

    T Dfs(int x, int t, T flow) {
        if (x == t) return flow;
        T res = 0;
        for (Edge &e : g[x]) {
            if (e.cap > 0 && lev[e.to] == lev[x] + 1) {
                T f = Dfs(e.to, t, min(e.cap, flow - res));
                res += f;
                e.cap -= f;
                g[e.to][e.rev].cap += f;
            }
        }
        if (!res) lev[x] = -1;
        return res;
    }

    T operator()(int s, int t) {
        T res = 0;
        for (; Bfs(s, t); res += Dfs(s, t, kInf));
        return res;
    }
};

int main() {
    int h, w; cin >> h >> w;
    vector<string> grid(h);
    for (int i = 0; i < h; ++i) cin >> grid[i];
    Dinic<int> flow(h + w + 2);
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if (grid[i][j] == 'o') {
                flow.AddEdge(i, j + h, 1);
                flow.AddEdge(j + h, i, 1);
            }
            if (grid[i][j] == 'S') {
                flow.AddEdge(h + w, i, kInf);
                flow.AddEdge(h + w, j + h, kInf);
            }
            if (grid[i][j] == 'T') {
                flow.AddEdge(i, h + w + 1, kInf);
                flow.AddEdge(j + h, h + w + 1, kInf);
            }
        }
    }
    int ans = flow(h + w, h + w + 1);
    if (ans >= kInf) ans = -1;
    cout << ans << "\n";
    return 0;
}

