typedef long long fType;
struct edge { unsigned from, to; fType cap, flow; edge(unsigned from, unsigned to, fType cap, fType flow = 0) : from(from), to(to), cap(cap), flow(flow) {} };
struct PushRelabel
{
	unsigned N;
	vector<edge> E;
	vector<vector<unsigned> > G;
	vector<unsigned> h, count;
	vector<bool> inQ;
	vector<fType> excess;
	queue<unsigned> Q;
	PushRelabel(unsigned N) : N(N), count(N << 1), G(N), h(N), inQ(N), excess(N) {}

	void pb(unsigned from, unsigned to, fType cap) {
		G[from].push_back(E.size());
		E.push_back(edge(from, to, cap));
		G[to].push_back(E.size());
		E.push_back(edge(to, from, 0));
	}

	void enQueue(unsigned u) {
		if (!inQ[u] && excess[u] > 0) Q.push(u), inQ[u] = true;
	}

	void Push(unsigned edgeIdx) {
		edge & e = E[edgeIdx];
		fType toPush = min<fType>(e.cap - e.flow, excess[e.from]);
		if (toPush > static_cast<fType>(0) && h[e.from] > h[e.to]) {
			e.flow += toPush;
			excess[e.to] += toPush;
			excess[e.from] -= toPush;
			E[edgeIdx ^ 1].flow -= toPush;
			enQueue(e.to);
		}
	}

	void Relabel(unsigned u) {
		count[h[u]] -= 1; h[u] = (N << 1) - 2;
		for (unsigned i : G[u]) {
			edge &e = E[i];
			if (e.cap > e.flow) h[u] = min(h[u], h[e.to]);
		}
		count[++h[u]] += 1;
	}

	void gapRelabel(unsigned height) {
		for (unsigned u = 0; u < N; ++u)
			if (h[u] >= height && h[u] < N) {
				count[h[u]]--;
				count[h[u] = N]++;
				enQueue(u);
			}
	}

	void Discharge(unsigned u) {
		for (unsigned i = 0; excess[u] > 0 && i < G[u].size(); ++i) Push(G[u][i]);
		if (excess[u] > 0) {
			if (h[u] < N && count[h[u]] < 2) gapRelabel(h[u]);
			else Relabel(u);
		}
		else if (!Q.empty()) {
			Q.pop();
			inQ[u] = false;
		}
	}

	fType getFlow(unsigned src, unsigned snk) {
		h[src] = N; inQ[src] = inQ[snk] = true;
		count[0] = N - (count[N] = 1);
		for (unsigned i : G[src]) {
			excess[src] += E[i].cap;
			Push(i);
		}
		while (!Q.empty())
			Discharge(Q.front());
		return excess[snk];
	}
};



