int ans,n,first[10007],d[10007],cur[10007],next[2000010],r[2000010],too[2000010];
int num(int x,int y){
	return (x-1) * h + y;
}
queue <int> q;
void addedge(int u,int v) {
	++edge_cnt;
	next[edge_cnt]=first[u];
	first[u]=edge_cnt;
	too[edge_cnt]=v; 
	r[edge_cnt]=1;

	++edge_cnt;
	next[edge_cnt]=first[v];
	first[v]=edge_cnt;
	too[edge_cnt]=u;
	r[edge_cnt]=1;
}
bool bfs(){
	q.push(s);
	fill(d+1,d+t+1,0);
	d[s]=1;
	while (!q.empty()) {
		int u=q.front();
		q.pop();
		for (int e=first[u]; e; e=next[e]) {
			int v=too[e];
			if (d[v]==0 && r[e]>0) d[v]=d[u]+1,q.push(v);
		}
	}
	return d[t]>0;
}
int dfs(int x,int budget){
	if (x==t) return budget;
	int ans=0;
	for (int &e=cur[x]; e; e=next[e]) {
		int v=too[e];
		if (d[v]==d[x]+1 && r[e]>0) {
			int ret=dfs(v,min(budget,r[e]));
			ans    += ret;
			r[e]   -= ret;
			r[e^1] += ret;
			budget -= ret;
			if (budget==0) break;
		}
	}
	return ans;
}
