	G[f].push_back((edge){t,c,(int)G[t].size()});
	G[t].push_back((edge){f,0,(int)G[f].size()-1});
}

int dfs(int v, int t, int f){
	if(v == t) return f;
	used[v] = true;
	for(auto &it: G[v]) if(!used[it.t] && it.c){
		int d = dfs(it.t, t, min(f,it.c));
		if(d){
			it.c -= d;
			G[it.t][it.r].c += d;
			return d;
		}
	}
	return 0;
}

int max_flow(int s, int t){
	int res = 0, f = 1;
	while(f){
		fill(used,used+mx,0);
		f = dfs(s,t,inf);
		res += f;
	}
	return res;
}

