{
	G[from].push_back({ to, cap, (LL)G[to].size() });
	G[to].push_back({ from,0,(LL)G[from].size() - 1 });
}
LL dfs(LL v, LL t, LL f)
{
	if (v == t)return f;
	used[v] = true;
	for (int i = 0; i < (LL)G[v].size(); ++i)
	{
		edge &e = G[v][i];
		if (!used[e.to] && e.cap > 0)
		{
			int d = dfs(e.to, t, min(f, e.cap));
			if (d > 0)
			{
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}
