                                                        st.emplace(place, nplace);
                                                        st.emplace(nplace, place);
                                                }
                                                if (A[ny][nx] == 'o' && !used[ny][nx]) que.emplace(ny, nx);
                                        }
                                        if (place == start && A[ny][nx] == 'T') {
                                                cout << -1 << endl;
                                                exit(0);
                                        }
                                }
                        }
                }
        }
}

