const int INF = std::numeric_limits<int>::max();

class Max_Flow { // 最大フローをDinicで解くクラス
public:
    static const int MAX_V = 20010;
    struct edge { int to, cap, rev; };
    std::vector<edge> G[MAX_V]; // グラフの隣接リスト表現
    int level[MAX_V]; // sからの距離
    int iter[MAX_V]; // vの各辺について、次に調べる辺の番号がiter[v]

    Max_Flow();

    // fromからtoへ向かう容量capの辺をグラフに追加する
    // 容量0の逆辺も追加する。
    void add_edge(const int from, const int to, const int cap);

    // sからの最短距離をBFSで計算し、levelに代入する。
    void bfs(const int s);

    // 増加パスをDFSで探す。v 現在地, t 終点, f 現状流せる最大流
    // 再帰的に呼び出す関数で、dfs(s, t, INF)の形式で利用すると、増加パスの増分を返す。
    int dfs(const int v, const int t, const int f);

    // sからtへの最大流を求める。
    int solve(const int s, const int t);
};

Max_Flow::Max_Flow(){}

// fromからtoへ向かう容量capの辺をグラフに追加する
// 容量0の逆辺も追加する。
void Max_Flow::add_edge(const int from, const int to, const int cap) {
    G[from].push_back((edge){to, cap, (int)G[to].size()});
    G[to].push_back((edge){from, 0, (int)G[from].size() - 1});
}

// sからの最短距離をBFSで計算し、levelに代入する。
void Max_Flow::bfs(const int s) {
    //std::memset(level, INF, sizeof(level)); // 何故かmemsetだと-1が代入されてしまう。
    std::fill(level, level + MAX_V, INF);
    std::queue<int> que;
    level[s] = 0;
    que.push(s);
    while(!que.empty()) {
        const int v = que.front(); que.pop();
        for (int i = 0; i < G[v].size(); i++) {
            const edge& e = G[v][i];
            if (e.cap > 0 && level[e.to] == INF) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

// 増加パスをDFSで探す。v 現在地, t 終点, f 現状流せる最大流
int Max_Flow::dfs(const int v, const int t, const int f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < G[v].size(); i++) {
        edge &e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) { // 距離が増加するパスだけを対象にする。
            const int d = dfs(e.to, t, std::min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

// sからtへの最大流を求める。
int Max_Flow::solve(const int s, const int t) {
    int flow = 0;
    while(true) {
        bfs(s);
        if (level[t] == INF) {
            return flow;
        }
        std::memset(iter, 0, sizeof(iter));
        int f;
        while((f = dfs(s, t, INF)) > 0) { 
            flow += f;
        }
        //距離増加パスに流せるだけ流せたら、最短の増加パスの長さは真に増加する。
    }
}

