void addedge(int u,int v,int w,int rw=0){
    edge[tot].to=v; edge[tot].cap=w; edge[tot].flow=0; edge[tot].next=head[u]; head[u]=tot++;
    edge[tot].to=u; edge[tot].cap=rw; edge[tot].flow=0; edge[tot].next=head[v]; head[v]=tot++;
}
int sap(int st,int en,int N){
    mst(gap,0);
    mst(dep,0);
    memcpy(cur,head,sizeof(head));
    int u=st;
    pre[u]=-1;
    gap[0]=N;
    int ans=0;
    while (dep[st]<N){
        if (u==en){
            int Min=inf;
            for (int i=pre[u];~i;i=pre[edge[i^1].to]){
                Min=min(Min,edge[i].cap-edge[i].flow);
            }
            for (int i=pre[u];~i;i=pre[edge[i^1].to]){
                edge[i].flow+=Min;
                edge[i^1].flow-=Min;
            }
            u=st;
            ans+=Min;
            continue;
        }
        bool flag=false;
        int v;
        for (int i=cur[u];~i;i=edge[i].next){
            v=edge[i].to;
            if (edge[i].cap-edge[i].flow && dep[v]+1==dep[u]){
                flag=true;
                cur[u]=pre[v]=i;
                break;
            }
        }
        if (flag){
            u=v;
            continue;
        }
        int Min=N;
        for (int i=head[u];~i;i=edge[i].next){
            if (edge[i].cap-edge[i].flow && dep[edge[i].to]<Min){
                Min=dep[edge[i].to];
                cur[u]=i;
            }
        }
        gap[dep[u]]--;
        if (!gap[dep[u]]) return ans;
        dep[u]=Min+1;
        gap[dep[u]]++;
        if (u!=st) u=edge[pre[u]^1].to;
    }
    return ans;
}
