using namespace std;
const int N=500;
struct E{
    int v,C,flow,rev;
    E(int V,int c,int F,int R){
        v=V;C=c;flow=F;rev=R;
    }
};
class G{
    public:
    vector<int>lev;
    vector<vector<E>>g;
    G(int n){
        lev=vector<int>(n,0);
        g.resize(n);
    }
    void add(int u,int v,int c){
        E a(v,c,0,(int)g[v].size());
        E b(u,0,0,(int)g[u].size());
        g[u].push_back(a);
        g[v].push_back(b);
    }
    bool bfs(int s,int t);
    int send(int s,int flow,int t,vector<int>&st);
    int DinicMaxflow(int s,int t);
};
bool G::bfs(int s,int t){
    //cout<<s<<' '<<t<<endl;
    lev= vector<int>(N,-1);
    lev[s]=0;
    deque<int>q={s};
    while(q.size()){
        int u=q.front();q.pop_front();
        //cout<<u<<' ';
        for(auto &e:g[u]){
            if(lev[e.v]<0&&e.flow<e.C){
                lev[e.v]=lev[u]+1;
                q.push_back(e.v);
            }
        }
    }
    //cout<<endl;
    return lev[t]>=0;
}
int G::send(int s,int flow,int t,vector<int>&st){
    if(s==t)return flow;
    for(;st[s]<g[s].size();st[s]++){
        auto &e=g[s][st[s]];
        if(lev[e.v]==lev[s]+1&&e.flow<e.C){
            int cur=min(flow,e.C-e.flow);
            int tmp=send(e.v,cur,t,st);
            if(tmp>0){
                e.flow+=tmp;
                g[e.v][e.rev].flow-=tmp;
                return tmp;
            }
        }
    }
}
int G::DinicMaxflow(int s, int t)
{
    if (s == t)
        return 0;
    int total = 0;
    while (bfs(s, t) == true)
    {
        vector<int>st(N,0);
        while (int flow = send(s, INT_MAX, t, st))
            total += flow;
    }
    return total;
}
