      for(int i=0; i<N; i++) level[i] = -1;
      queue<int> que;
      level[s] = 0; que.push(s);
      while(!que.empty()) {
        int v = que.front(); que.pop();
        for(auto& e: graph[v]) {
          if (e.cost > 0 && level[e.to] < 0) {
            level[e.to] = level[v] + 1;
            que.push(e.to);
          }
        }
      }
