      while(true) {
        bfs(s);
        if (level[t] < 0) return flow;
        for(int i=0; i<N; i++) iter[i] = 0;
        ll f;
        while((f = dfs(s, t, LLONG_MAX/4)) > 0) {
          flow += f;
