struct Graph {
	int n, m, fe[mxn], ne[mxm], ev[mxm]; Flow f[mxm];
	void clear(int n)
	{ this->n = n; fill(fe, fe + n + 1, 0); m = 1; }
	void add_(int x, int y, Flow F)
	{ ne[++m] = fe[x]; fe[x] = m; ev[m] = y; f[m] = F; }
	void add1(int x, int y, Flow F)
	{ add_(x, y, F); add_(y, x, 0); }
	int T, arc[mxn], lev[mxn];
	Flow extend(int x, Flow lim) {
		if (x == T) return lim;
		Flow re = 0;
		for (int &e = arc[x]; e; e = ne[e])
			if (f[e] && lev[ev[e]] == lev[x] + 1) { 
				Flow t = extend(ev[e], min(lim - re, f[e]));
				if (t) { 
					f[e] -= t, f[e ^ 1] += t;
					if ((re += t) == lim) break; 
			}}
		if (!re) lev[x] = 0; 
		return re;
	}
	int q[mxn], *qb, *qe;
	Flow dinic(int S, int T) {
		Flow re = 0; this->T = T;
		for (;;) {
			fill(lev, lev + n + 1, 0);
			copy(fe, fe + n + 1, arc);
			for (qb = qe = q, lev[*qe++ = S] = 1; qb != qe;) {
				int x = *qb++;
				if (lev[T]) break;
				for (int e = fe[x]; e; e = ne[e])
					if (f[e] && !lev[ev[e]])
						lev[*qe++ = ev[e]] = lev[x] + 1;
			}
			if (!lev[T]) break;
			re += extend(S, MXL);
		}
		return re;
	}
}G;

