				if(e[i].flow!=0&&dis[e[i].t]==INF){
					dis[e[i].t]=dis[u]+1;
					q.push(e[i].t);
				}
			} 
		}
		return dis[T]!=INF;
	}

	int work(int S1,int T1,int size){
		S=S1,T=T1;sz=size;
		int ret=0;
		while(BFS()){
			memcpy(cur,head,sizeof(int)*(sz+2));
			ret+=DFS(S1,INF);
			if(ret>=INF) return -1;
		}
		return ret;
	}
}

