int getNod(int x, int y) { return x * m + y; }

void addEdge(int x, int y, int flow) {
  edge e1 = {x, y, flow};
  edge e2 = {y, x, 0};

  lde[x].push_back((int)e.size());
  e.push_back(e1);
  lde[y].push_back((int)e.size());
  e.push_back(e2);
}

bool bfs() {
  int qh, qt, to;

  memset(d, -1, sizeof(d));
  d[source] = 0; q[1] = source;

  for(qt = qh = 1; qh <= qt && d[sink] == -1; ++qh)
    for(auto id : lde[q[qh]]) {
      to = e[id].y;
      if(d[to] == -1 && e[id].flow > 0) q[++qt] = to, d[to] = d[q[qh]] + 1;
    }

  return d[sink] != -1;
}

int dfs(int x, int flow) {
  if(!flow) return 0;
  if(x == sink) return flow;

  for(; ptr[x] < (int)lde[x].size(); ++ptr[x]) {
    int id = lde[x][ptr[x]], to = e[id].y;
    if(d[to] != d[x] + 1) continue;

    int pushed = dfs(to, min(flow, e[id].flow));

    if(pushed) {
      e[id].flow -= pushed;
      e[id ^ 1].flow += pushed;
      return pushed;
    }
  }

  return 0;
}

int dinic() {
  int flow, ans = 0;

  while(bfs()) {
    memset(ptr, 0, sizeof(ptr));
    while((flow = dfs(source, INF))) ans += flow;
  }

  if(ans > 1e9) ans = -1;

  return ans;
}

