struct Dinic {
  int n, s, t;
  struct Edge {
    int to, cf;
    Edge(int _to, int _cf) : to(_to), cf(_cf) {}
  };
  vector<Edge> edge;
  vector<vector<int> > gr;
  vector<int> d, iGr;

  Dinic(int _n, int _s, int _t) : n(_n), s(_s), t(_t) {
    edge.clear();
    gr.assign(n, {} );
  }

  void addEdge(int u, int v, int c) {
    gr[u].emplace_back(sz(edge) ); edge.emplace_back(v, c);
    gr[v].emplace_back(sz(edge) ); edge.emplace_back(u, 0);
  }

  bool bfs() {
    d.assign(n, inf); d[s] = 0;
    iGr.assign(n, 0);
    queue<int> q; q.emplace(s);

    while (sz(q) ) {
      int u = q.front(); q.pop();
      for (int i : gr[u]) if (d[ edge[i].to ] == inf && edge[i].cf) {
        d[ edge[i].to ] = d[u] + 1;
        q.emplace(edge[i].to);
      }
    }

    return d[t] != inf;
  }

  int dfs(int u, int flow) {
    if (u == t || !flow) return flow;

    for (; iGr[u] < sz(gr[u]); ++iGr[u]) {
      int i = gr[u][ iGr[u] ];
      if (d[ edge[i].to ] != d[u] + 1 || !edge[i].cf) continue ;

      int nxt = dfs(edge[i].to, min(flow, edge[i].cf) );
      if (nxt) { edge[i].cf -= nxt; edge[i ^ 1].cf += nxt; return nxt; }
    }

    return 0;
  }

  int getMxFlow() {
    int ret = 0;

    while (bfs() ) {
      int tmp;
      while ( (tmp = dfs(s, inf) ) ) ret += tmp;
    }

    return ret;
  }
};

int main() {
