      cin >> grid[i][j];
      if (grid[i][j] == 'S') s = { i, j };
      else if (grid[i][j] == 'T') t = { i, j };
    }
  }

  auto to1D = [&](int x, int y) { return x * m + y; };
  auto in = [&](int x, int y) { return to1D(x, y) << 1; };
  auto out = [&](int x, int y) { return to1D(x, y) << 1 | 1; };

  Dinic dinic(n * m * 2, in(s.first, s.second), out(t.first, t.second) );
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) dinic.addEdge(in(i, j), out(i, j), make_pair(i, j) != s && make_pair(i, j) != t ? 1 : inf);
  }

  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) if (grid[i][j] != '.') {
      for (int x = i + 1, y = j; x < n; ++x) if (grid[x][y] != '.') dinic.addEdge(out(i, j), in(x, y), inf);
      for (int x = i - 1, y = j; ~x; --x) if (grid[x][y] != '.') dinic.addEdge(out(i, j), in(x, y), inf);
      for (int x = i, y = j + 1; y < m; ++y) if (grid[x][y] != '.') dinic.addEdge(out(i, j), in(x, y), inf);
      for (int x = i, y = j - 1; ~y; --y) if (grid[x][y] != '.') dinic.addEdge(out(i, j), in(x, y), inf);
    }
  }

  int ans = dinic.getMxFlow();
  cout << (ans < inf ? ans : -1) << '\n';

  return 0;
}

