int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll H, W;
	cin >> H >> W;

	ll nodeS = H + W;
	ll nodeT = H + W + 1;
	ll inf = H * W * 4;
	string line;
	vector<vector<Edge>> edges(H + W + 2);
	pair<ll, ll> posS, posT;
	for (ll i = 0; i < H; ++i)
	{
		cin >> line;
		for (ll j = H; j < H + W; ++j)
		{
			if (line[j - H] == 'o')
			{
				edges[i].push_back({ j, 1, ll(edges[j].size()) });
				edges[j].push_back({ i, 0, ll(edges[i].size()) - 1 });
				edges[j].push_back({ i, 1, ll(edges[i].size()) });
				edges[i].push_back({ j, 0, ll(edges[j].size()) - 1 });
			}
			else if (line[j - H] == 'S')
			{
				posS = {i, j - H};
				edges[nodeS].push_back({ i, inf, ll(edges[i].size()) });
				edges[i].push_back({ nodeS, 0, ll(edges[nodeS].size()) - 1 });
				edges[nodeS].push_back({ j, inf, ll(edges[j].size()) });
				edges[j].push_back({ nodeS, 0, ll(edges[nodeS].size()) - 1 });
			}
			else if (line[j - H] == 'T')
			{
				posT = { i, j - H };
				edges[i].push_back({ nodeT, inf, ll(edges[nodeT].size()) });
				edges[nodeT].push_back({ i, 0, ll(edges[i].size()) - 1 });
				edges[j].push_back({ nodeT, inf, ll(edges[nodeT].size()) });
				edges[nodeT].push_back({ j, 0, ll(edges[j].size()) - 1 });
			}
		}
	}

	if (posS.first == posT.first || posS.second == posT.second)
	{
		cout << -1 << endl;

		return 0;
	}

	struct Info
	{
		ll node, minCost;
	};

	ll res = 0;
	while (true)
	{
		stack<Info> infoStack;
		vector<pair<ll, ll>> isSelected(H + W + 2, { -1, -1 });
		infoStack.push({ nodeS, inf });
		isSelected[nodeS] = { nodeS, -1 };
		ll finalCost;
		bool canFindPath = false;
		while (!infoStack.empty())
		{
			Info info = infoStack.top();
			infoStack.pop();
			for (auto i = 0; i < edges[info.node].size(); ++i)
			{
				auto e = edges[info.node][i];
				if (e.capacity == 0 || isSelected[e.to].first != -1)
				{
					continue;
				}
				infoStack.push({ e.to, min(info.minCost, e.capacity) });
				isSelected[e.to] = { info.node, i };
				if (e.to == nodeT)
				{
					canFindPath = true;
					finalCost = info.minCost;
					goto LOOP_END;
				}
			}
		}
		break;
	LOOP_END:
		ll currNode = nodeT;
		while (currNode != isSelected[currNode].first)
		{
			auto& edge = edges[isSelected[currNode].first][isSelected[currNode].second];
			edge.capacity -= finalCost;
			edges[edge.to][edge.reverse].capacity += finalCost;
			currNode = isSelected[currNode].first;
		}
		res += finalCost;
	}

	cout << res << endl;

	return 0;
}

