#define MAX_V 1000
#define INF (1 << 29)

using namespace std;

struct edge{
	int to, cap, rev; // 行き先、容量、逆辺
};

vector<edge> G[MAX_V] = {};
bool used[MAX_V];

// from から to へ向かう容量 cap の辺を張る
void add_edge(int from, int to, int cap){
	G[from].push_back((edge){to, cap, G[to].size()});
	// G[to].push_back((edge){from, 0, G[from].size() - 1}); // 有向辺
	G[to].push_back((edge){from, cap, G[from].size() - 1}); // 無向辺
}

// 増加パスを dfs で探す
int dfs(int v, int t, int f){
	if(v == t){
		return f;
	}
	used[v] = true;
	for(int i = 0; i < G[v].size(); i++){
		edge &e = G[v][i];
		if(!used[e.to] && e.cap > 0){
			int d = dfs(e.to, t, min(f, e.cap));
			if(d > 0){
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

// s から t への最大流を求める
int max_flow(int s, int t){
	int flow = 0;
	while(true){
		fill(used, used + MAX_V, 0);
		int f = dfs(s, t, INF);
		if(f == 0){
			return flow;
		}
		flow += f;
	}
}

