int dfs(int x,int flow)
{
  if(x==d || flow == 0) return flow;
  int delta=0;
  for(int k=first[x];k!=-1;k=edge[k].next)
  {
    int y = edge[k].y;
    if(dep[y] == dep[x] + 1 && edge[k].c && flow > delta)
    {
      int minf = dfs(y,min(flow - delta , edge[k].c));
      edge[k].c-=minf; edge[k^1].c+=minf;
      delta+=minf;
    }
  }
  if(delta==0) dep[x] = 0;
  return delta;
}

