	int s = gg.n - 1, t = gg.n;
	REP(i, 0, h) {
		REP(j, 0, w) {
			if (grid[i][j] == 'S') {
				si = i;
				sj = j;
				gg.add_edge(s, ind_row[i], LIM);
				gg.add_edge(s, ind_column[j], LIM);
			} else if (grid[i][j] == 'T') {
				ti = i;
