struct FArc {
    int from, to, cap;
    Cost cost;
    int rev;

    FArc() {}
    FArc(int from, int to, int cap) : from(from), to(to), cap(cap) {}
    FArc(int from, int to, int cap, Cost cost) : from(from), to(to), cap(cap),
                                                 cost(cost) {}
    FArc(int from, int to, int cap, Cost cost, int rev) :
        from(from), to(to), cap(cap), cost(cost), rev(rev) {}
};

using FGraph = vector<vector<FArc>>;

void add_farc(FGraph& fg, int from, int to, int cap, Cost cost = -1) {
    fg[from].push_back(FArc(from, to, cap, cost, fg[to].size()));
    fg[to].push_back(FArc(to, from, 0, -cost, fg[from].size() - 1));
}

namespace FordFulkerson {
    const int MAX_V = 1000;
    const int INF = (1 << 28);

    FGraph fgraph;
    int source, sink;
    array<bool, MAX_V> used;

    void initialize(FGraph& fg, int s, int t) {
        fgraph = fg;
        source = s;
        sink = t;
    }

    int dfs(int v, int flow) {
        if (v == sink) {
            return flow;
        }
        used[v] = true;
        for (FArc& fa : fgraph[v]) {
            if (!used[fa.to] && fa.cap > 0) {
                int d = dfs(fa.to, min(flow, fa.cap));
                if (d > 0) {
                    fa.cap -= d;
                    fgraph[fa.to][fa.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int solve() {
        int flow = 0;
        while (true) {
            used.fill(false);
            int f = dfs(source, INF);
            if (f == 0) {
                break;
            }
            flow += f;
        }
        return flow;
    }
};

