    }

    for(int i=0;i<w;i++){
      if(nodeNum[y][i] != 0 && nodeNum[y][i] != 1 && nodeNum[y][i] != num && i != x){
	push_one(ppos,nodeNum[y][i],1);
      }
    }
  }

  int ans=0;
  ans = maxFlow(1,num);
  if(firstNode.first == endNode.first || firstNode.second == endNode.second) cout << "-1" << endl; 
  else if(ans == 0) cout << "0" << endl;
  else cout << ans << endl;

  return 0;
} 

int dfs(int v,int t,int f)
{
  if(v == t) return f; //ゴールについたらfを流す
  used[v] = true; //訪れた場所をtrue

  for(int i=0;i<g[v].size();i++){
    Edge &e = g[v][i];
    if( !used[ e.to ] && e.cap > 0){
      int d = dfs( e.to , t , min(f,e.cap) ); //今までの経路の最小容量
      if(d > 0){
	e.cap -= d; //容量をdだけ引く
	g[ e.to ][ e.rev ].cap += d; //逆流をdだけたす
	return d;
      }
    }
  }

  return 0;
}

int maxFlow(int s,int t)
{
  int flow=0;
  while(1){
    memset(used,0,sizeof(used));
    int f = dfs(s,t,INF);
    if(f == 0) return flow;
    flow += f;
  }
}

