const int oo = 100000;

int max_flow(int n, int source, int sink) {
  int tot = 0;

  while (true) {
    queue<int> Q;
    vector<int> parent(n+1, -1);
    vector<bool> seen(n+1, false);

    Q.push(source);
    seen[source] = true;
    while (!Q.empty()) {
      int u = Q.front(); Q.pop();
      for (int v = 0; v <= n; v++) {
        if (g[u][v] && !seen[v]) {
          seen[v] = true;
          parent[v] = u;
          Q.push(v);
        }
      }
    }

    if (!seen[sink]) {
      break;
    }

    int cur = sink, cap = oo;
    while (parent[cur] != -1) {
      cap = min(cap, g[parent[cur]][cur]);
      cur = parent[cur];
    }

    cur = sink;
    while (parent[cur] != -1) {
      g[parent[cur]][cur] -= cap;
      g[cur][parent[cur]] += cap;
      cur = parent[cur];
    }

    tot += cap;
  }

  return tot;
}

