    int ecnt = 1; 
    int dis[maxn], cur[maxn];
    int st[maxn], to[maxn], nxt[maxn], cap[maxn];

    void addedge(int u, int v, int c) {
        to[++ecnt] = v; nxt[ecnt] = st[u]; st[u] = ecnt; cap[ecnt] = c;
        to[++ecnt] = u; nxt[ecnt] = st[v]; st[v] = ecnt; cap[ecnt] = 0;
    }

    bool bfs() {
        static int q[maxn];
        int head = 0, tail = 0;
        memset(dis, 0xff, sizeof dis);

        dis[q[tail++] = S] = 0;
        while(head < tail) {
            int x = q[head++];
            for(int i = st[x]; i; i = nxt[i]) 
                if(cap[i] && !~dis[to[i]]) {
                    dis[to[i]] = dis[x] + 1;
                    q[tail++] = to[i];
                }
        }
        return ~dis[T];
    }

    int dfs(int u, int flow) {
        if(u == T || !flow) 
            return flow;

        int res = 0;
        for(int& i = cur[u]; i; i = nxt[i]) {
            int aug, v = to[i];
            if(dis[v] == dis[u] + 1 && (aug = dfs(v, min(flow, cap[i])))) {
                res += aug;
                flow -= aug;
                cap[i] -= aug;
                cap[i^1] += aug;
                if(!flow) return res;
            }
        }
        return res;
    }
    int maxflow() {
        int ans = 0;
        while(bfs()) {
            memcpy(cur, st, sizeof st);
            ans += dfs(S, oo);
        }
        return ans;
    }
}

