int q[2 * 100 * 100];
int qt, qh;

bool bfs(int s, int t)
{
	qt = qh = 0;
	q[qt++] = s;
	memset(d, -1, sizeof(d));
	d[s] = 0;
	while (qh < qt)
	{
		int v = q[qh++];
		for (int i = 0; i < G[v].size(); ++i)
		{
			int e = G[v][i];
			if (E[e].c - E[e].f > 0 && d[E[e].v] == -1)
			{
				d[E[e].v] = d[v] + 1;
				q[qt++] = E[e].v;
			}
		}
	}
	return d[t] != -1;
}

int dfs(int v, int t)
{
	if (v == t)
		return 1;
	for (; p[v] < G[v].size(); p[v]++)
	{
		int e = G[v][p[v]];
		if (E[e].c - E[e].f == 0)
			continue;
		if (d[v] + 1 == d[E[e].v] && dfs(E[e].v, t))
		{
			E[e].f++;
			E[e ^ 1].f--;
			return 1;
		}
	}
	return 0;
}

