struct edge {int to, cap, rev;};

vector<edge> G[202];
bool used[202];

void add_edge(int from, int to, int cap){
    G[from].push_back((edge{to, cap, (int)G[to].size()}));
    G[to].push_back((edge{from, 0, (int)G[from].size()-1}));
}

int dfs(int v, int t, int f, vector<edge> G[]){
    if(v == t) return f;
    used[v] = true;
    for(int i = 0; i < G[v].size(); i++){
        edge &e = G[v][i];
        if(!used[e.to] && e.cap > 0){
            int d = dfs(e.to, t, min(f, e.cap), G);
            if(d > 0){
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int main(){
    int H, W;
    cin >> H >> W;
    int s = H+W;
    int t = H+W+1;
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            char a;
            cin >> a;
            if(a == 'o') {
                add_edge(i, j+H, 1);
                add_edge(j+H, i, 1);
            }
            if(a == 'S') {
                //add_edge(i, j+H, INF);
                //add_edge(j+H, i, INF);
                add_edge(i, s, INF);
                add_edge(s, i, INF);
                add_edge(j+H, s, INF);
                add_edge(s, j+H, INF);
            }
            if(a == 'T') {
                //add_edge(i, j+H, INF);
                //add_edge(j+H, i, INF);
                add_edge(i, t, INF);
                add_edge(t, i, INF);
                add_edge(j+H, t, INF);
                add_edge(t, j+H, INF);
            }
        }
    }

    int flow = 0;

    while(true){
        memset(used, 0, sizeof(used));
        int f = dfs(s, t, INF, G);
        if(f == 0){
            break;
        }
        flow += f;
    }
    if(flow == INF){
        cout << -1 << endl;
    }else{
        cout << flow << endl;
    }
}

