struct TEdge
{
    int u, v, c, f;
    TEdge *rev;
    TEdge(int u_ = 0, int v_ = 0, int c_ = 0, int f_ = 0, TEdge *rev_ = nullptr):
        u(u_), v(v_), c(c_), f(f_), rev(rev_) {}
};

const int N = 102;
const int NN = N * N * 2 + 2;
const int M = NN * 4;
const int INF = 1e9;

int h, w, nn, m, source, sink;
char a[N][N];
TEdge el[M];
vector<TEdge*> g[NN];
TEdge *pre[NN];

bool Bfs(int s, int t)
{
    fill(pre+1, pre+1+nn, nullptr);
    queue<int> q;
    q.push(s);
    while (!q.empty())
    {
        int u = q.front(); q.pop();
        for (auto e: g[u])
            if (!pre[e->v] && e->f < e->c && e->v != s) q.push(e->v), pre[e->v] = e;
    }
    return pre[t] != nullptr;
}

void AddEdge(int u, int v, int c)
{
    el[m]   = {u, v, c, 0, el+m+1};
    el[m+1] = {v, u, c, 0, el+m};
    g[u].push_back(el+m);
    g[v].push_back(el+m+1);
    m += 2;
}

int EdmondsKarp()
{
    int flow = 0;
    while (Bfs(source, sink))
    {
        int maxflow = INF;
        for (auto e = pre[sink]; e != nullptr; e = pre[e->u])
            maxflow = min(maxflow, e->c - e->f);
        for (auto e = pre[sink]; e != nullptr; e = pre[e->u])
            e->f += maxflow, e->rev->f -= maxflow;
        flow += maxflow;
    }
    return flow;
}

void Solve()
{
    source = h + w + 1, sink = h + w + 2;
    for (int i = 1; i <= h; ++i)
        for (int j = 1; j <= w; ++j)
        {
            if (a[i][j] == 'o') AddEdge(i, j + h, 1);
            if (a[i][j] == 'S')
            {
                AddEdge(source, i, INF);
                AddEdge(source, j + h, INF);
            }
            if (a[i][j] == 'T')
            {
                AddEdge(i, sink, INF);
                AddEdge(j + h, sink, INF);
            }
        }

    nn = h + w + 2;

    int mincut = EdmondsKarp();
    if (mincut >= INF) printf("-1");
    else printf("%d",mincut);
}

int main()
{
    scanf("%d %d", &h, &w);
    for (int i = 1; i <= h; ++i) scanf("%s",a[i]+1);
    Solve();
    return 0;
}

