class DinicMethod{
public:
	struct Edge{ ll to, cap, rev; };
	vector<vector<Edge>> G;
private:
	vll level;
	vll iter;
public:
	DinicMethod(ll nodeNum): G(nodeNum){}

	void Link(ll v, ll u, ll cap, ll rcap = 0){//v→uに重みcapで張る、逆辺も張る
		this->G[v].push_back({u,  cap, (ll)this->G[u].size()});
		this->G[u].push_back({v, rcap, (ll)this->G[v].size()-1});
	}

	ll MaxFlow(ll s, ll t){//s→tの最大流を求める
		ll f, flow = 0;
		while (true){
			this->BfsLevelRenew(s);
			if (this->level[t] < 0) return flow;
			iter.assign(this->G.size(), 0);
			while ((f = this->DfsFindPath(s, t, INF)) > 0) { flow += f; }
		}
	}

private:
	void BfsLevelRenew(ll s) {
		this->level.assign(this->G.size(), -1);
		this->level[s] = 0;
		queue<ll> que;
		que.push(s);
		while (!que.empty()){
			ll from = que.front(); que.pop();
			EACH(e, this->G[from]){
				if (e.cap > 0 && this->level[e.to] < 0){
					this->level[e.to] = this->level[from] + 1;
					que.push(e.to);
				}
			}
		}
	}

	ll DfsFindPath(ll v, ll t, ll f){
		if (v == t) return f;

		for (ll &i = iter[v]; i < (ll)this->G[v].size(); i++){
			Edge &e = this->G[v][i];
			if (e.cap > 0  &&  this->level[v] < this->level[e.to]){
				ll d = this->DfsFindPath(e.to, t, min(f, e.cap));
				if (d > 0){
					e.cap -= d;
					this->G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};


ll B = 1000000;

void solve()
{
	ll H, W;  cin >> H >> W;
	vector<string> A = cinv<string>(H);

	vvll AA(H, vll(W));
	ll cnt=1;
	rep(i, 0, H-1)rep(j, 0, W-1){
		char c = A[i][j];
		if (c == '.') continue;
		else if (c == 'S') AA[i][j] = -1;
		else if (c == 'T') AA[i][j] = -2;
		else{
			AA[i][j] = cnt++;
		}
	}
	ll N = cnt*2;
	DinicMethod dinic(N);

	//横に並ぶo、S、Tに1Mリンクする
	rep(i, 0, H-1){
		ll pre = -1;
		ll cur = -1;
		rep(j, 0, W-1){
			ll a = AA[i][j];
			if (a == -1) cur = 0;
			else if (a == -2) cur = 1;
			else if (a != 0) cur = a*2+0;
			else continue;
			//preとcurにリンク張る
			if (pre != -1){
				dinic.Link(pre, cur, B, B);//両方向の辺を張る
			}
			pre = cur;
		}
	}
	//縦に並ぶo,S,Tに1Mリンク
	rep(j, 0, W-1){
		ll pre = -1;
		ll cur = -1;
		rep(i, 0, H-1){
			ll a = AA[i][j];
			if (a == -1) cur = 0;
			else if (a == -2) cur = 1;
			else if (a != 0) cur = a*2+1;
			else continue;
			//preとcurにリンク張る
			if (pre != -1){
				dinic.Link(pre, cur, B, B);//両方向の辺を張る
			}
			pre = cur;
		}
	}

	//o同士に1リンク
	for (ll v=2; v<=N-1; v+=2){
		dinic.Link(v, v+1, 1, 1);
	}

	ll ans = dinic.MaxFlow(0, 1);
	if (ans >= B) ans = -1;
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

