struct edge {
	int to, cap, next;
	edge(int t = 0, int c = 0, int n = 0):to(t), next(n), cap(c) {}
};
edge G[N * N << 1];
int head[N];
int Gcnt, n, m, S, T, clc, cnt, ans;
