    g[++k].next=h[u]; h[u]=k; 
    g[k].to=v; g[k].cap=cap; g[k].rev=k+1; 
    g[++k].next=h[v]; h[v]=k; 
    g[k].to=u; g[k].cap=0; g[k].rev=k-1; 
} 
void bfs(int s){ 
    head=tail=0; 
    q[tail++]=s; level[s]=1; 
    while(head!=tail){ 
        int u=q[head]; 
        for(int i=h[u];i;i=g[i].next){ 
            if(!level[g[i].to]&&g[i].cap){ 
                level[g[i].to]=level[u]+1; 
                q[tail++]=g[i].to; 
            } 
        } 
        head++; 
    } 
} 
int dfs(int u,int t,int f){ 
    if(u==t) return f; 
    for(int &i=iter[u];i;i=g[i].next){ 
        if(level[g[i].to]==level[u]+1&&g[i].cap){ 
            int d=dfs(g[i].to,t,f<g[i].cap?f:g[i].cap); 
            if(d){ 
                g[i].cap-=d; 
                g[g[i].rev].cap+=d; 
                return d; 
            } 
        } 
    } 
    return 0; 
} 
