            for(LL w = 0; w < N; w++){
                LL f1 = G[v][w].first, f2 = G[w][v].first, c = G[v][w].second, r = c - f1 + f2;
                if(r > 0 && used[w] == -1){
                    used[w] = used[v]++;
                    pred[w] = v;
                    cap[w] = min(cap[v], r);
                    Q.push(w);
                }
            }
        }
        if(used[b] == -1) break;
        F += cap[b];
        LL v = b;
        while(v != a){
            LL w = pred[v], f1 = G[w][v].first, f2 = G[v][w].first, c = G[w][v].second, o = min(f2, cap[b]);
            G[v][w].first -= o;
            G[w][v].first += cap[b] - o;
            v = w;
        }
    }
    return F;
}


