            }
            if(s[i][j]=='T'){
                dn.addedge(i,h+w+1, inf);
                dn.addedge(h+j,h+w+1, inf);
            }
            if(s[i][j]=='o'){
                dn.addedge(i, h+j, 1);
                dn.addedge(h+j, i, 1);
            }
        }
    }
    int ans=dn.max_flow(h+w, h+w+1);
    cout<<(ans>=inf?-1:ans)<<endl;
   return 0;
}

