const int MAXV = 3e4 + 5;
const int MAXE = 1e6 + 5;

struct Edge {
	int v, next;
	LL rsd;
	Edge() { }
	Edge(int v_, int next_, LL rsd_): v(v_), next(next_), rsd(rsd_) { }
};

int n, s, t;
int tote, head[MAXV];
Edge edge[MAXE];
int cur[MAXV];
int dis[MAXV];

inline void addEdge(int u, int v, LL cap)
{
	edge[++tote] = Edge(v, head[u], cap);
	head[u] = tote;
	edge[++tote] = Edge(u, head[v], 0);
	head[v] = tote;
}

bool bfs()
{
	static int q[MAXV];
	int front = 0, rear = 0;

	memset(dis + 1, +oo, sizeof(*dis) * n);
	dis[s] = 0;
	q[rear++] = s;
	while (front != rear) {
	    int u = q[front++];
	    for (int i = head[u]; i; i = edge[i].next) {
            const Edge &e = edge[i];
            if (e.rsd > 0 && dis[e.v] == +oo) {
                dis[e.v] = dis[u] + 1;
                q[rear++] = e.v;
            }
	    }
	}

	return dis[t] != +oo;
}

LL dfs(int u, LL rsd)
{
	if (u == t || !rsd) return rsd;
	LL ret = 0;
	for (int &i = cur[u]; i; i = edge[i].next) {
	    Edge &e = edge[i];
	    if (e.rsd > 0 && dis[u] + 1 == dis[e.v]) {
            LL f = dfs(e.v, rsd < e.rsd ? rsd : e.rsd);
            if (f > 0) {
                e.rsd -= f;
                edge[i ^ 1].rsd += f;
                rsd -= f;
                ret += f;
                if (!rsd) break;
            }
	    }
	}
	return ret;
}

inline void init(int n_)
{
	n = n_ + 2;
	s = n_ + 1;
	t = n_ + 2;
	tote = 1;
	memset(head + 1, 0, sizeof(*head) * n);
}

inline LL exec()
{
	LL ret = 0;
	while (bfs()) {
	    memcpy(cur + 1, head + 1, sizeof(*head) * n);
	    ret += dfs(s, +oo);
	}
	return ret;
}

}

#define IDX(i, j, k) ((((i) - 1) * W + (j)) * 2 - 1 + k)

void solve()
{
    int base = H * W * 2;
    Dinic::init(H * W * 2 + H + W);
    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            if (A[i][j] != '.') {
                Dinic::addEdge(IDX(i,j,1), IDX(i,j,0), 1);
                Dinic::addEdge(IDX(i,j,0), base+i, +oo);
                Dinic::addEdge(IDX(i,j,0), base+H+j, +oo);
                Dinic::addEdge(base+i, IDX(i,j,1), +oo);
                Dinic::addEdge(base+H+j, IDX(i,j,1), +oo);
                if (A[i][j] == 'S')
                    Dinic::addEdge(Dinic::s, IDX(i,j,0), +oo);
                else if (A[i][j] == 'T')
                    Dinic::addEdge(IDX(i,j,1), Dinic::t, +oo);
            }
        }
    }
    LL ans = Dinic::exec();
    if (ans >= +oo)
        ans = -1;
    printf("%lld\n", ans);
}

