struct Ford{
	struct edge{
		int to;
		int weight;
		int ind;
	};
	vector<vector<edge>> E;

	Ford(vector<vector<pair<int,int>>> &e){
		E.resize(e.size(),vector<edge>());
		for(int i=0;i<e.size();i++){
			for(int j=0;j<e[i].size();j++){
				edge t = {e[i][j].first,e[i][j].second,0};
				E[i].push_back(t);
			}
		}
		for(int i=0;i<e.size();i++){
			for(int j=0;j<e[i].size();j++){
				E[i][j].ind = E[E[i][j].to].size();
				edge t = {i,0,j};
				E[E[i][j].to].push_back(t);
			}
		}
	}

	int maximum_flow(int s,int t){
		int ret = 0;
		while(true){
			vector<bool> visited(E.size(),false);
			vector<edge> edges;
			dfs(s,t,edges,visited);
			if(edges.size()==0)break;

			int mini = 1000000001;
			for(int i=0;i<edges.size();i++){
				mini = min(mini,edges[i].weight);
			}
			ret += mini;
			for(int i=0;i<edges.size();i++){
				edge &t = E[edges[i].to][edges[i].ind];
				t.weight += mini;
				E[t.to][t.ind].weight -= mini;
			}

		}
		return ret;
	}

	void dfs(int now,int t,vector<edge> &edges,vector<bool> &visited){
		visited[now] = true;
		if(now==t)return;

		for(int i=0;i<E[now].size();i++){
			int to = E[now][i].to;
			int weight = E[now][i].weight;
			if(visited[to])continue;
			if(weight<=0)continue;
			edges.push_back(E[now][i]);
			dfs(to,t,edges,visited);
			if(edges.back().to==t)return;
			edges.pop_back();
		}
	}

};

int main(){

