struct MaxFlow{
  typedef ll weight;
  const weight zero = 0;
  const weight INF_WEIGHT = INFLL;
  struct edge{
    int to, rev;
    weight cap;
    edge(){}
    edge(int to, weight cap, int rev) : to(to), cap(cap), rev(rev){}
  };
  vector<vector<edge>> G;
  vector<int> level, iter;
  int n;
  void init(int size){
    n = size;
    G = vector<vector<edge>>(n, vector<edge>(0));
  }
  void add_edge(int from, int to, weight cap){
    G[from].pb(to, cap, SZ(G[to]));
    G[to].pb(from, zero, SZ(G[from])-1);
  }
  void bfs(int s){
    level = vector<int>(n, -1);
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while(!que.empty()){
      int v = que.front();
      que.pop();
      YYS(e, G[v]){
        if(e.cap > zero && level[e.to] < 0){
          level[e.to] = level[v] + 1;
          que.push(e.to);
        }
      }
    }
  }
  weight dfs(int v, int t, weight f){
    if(v == t){
      return f;
    }
    for(int &i = iter[v]; i < G[v].size(); i++){
      edge &e = G[v][i];
      if(e.cap > zero && level[v] + 1 == level[e.to]){
        weight d = dfs(e.to, t, min(f, e.cap));
        if(d > zero){
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return zero;
  }
  weight max_flow(int s, int t){
    weight flow = zero;
    while(1){
      bfs(s);
      if(level[t] < 0){
        return flow;
      }
      iter = vector<int>(n, 0);
      weight f;
      while((f = dfs(s, t, INF_WEIGHT)) > zero){
        flow += f;
      }
    }
  }
};

