bool bfs() {
	std::memset(dis, 0, sizeof dis), dis[s] = 1;
	std::queue<int> q; q.push(s);
	while (q.size()) {
		int x = q.front(); q.pop();
		for (int i = head[x]; i; i = e[i].nxt)
			if (e[i].rem && !dis[e[i].to])
				dis[e[i].to] = dis[x] + 1, q.push(e[i].to);
	}
	return dis[t] > 0;
}

int dinic(int x, int low) {
	if (x == t) return low;
	int ans = 0, t;
	for (int &i = cur[x]; i; i = e[i].nxt)
		if (e[i].rem && dis[e[i].to] == dis[x] + 1 && (t = dinic(e[i].to, std::min(low, e[i].rem)))) {
			e[i].rem -= t, e[i ^ 1].rem += t, low -= t, ans += t;
			if (!low) break;
		}
	return ans;
}

