template<typename flow_t>
struct Dinic {
  const flow_t INF;

  struct edge {
    int to;
    flow_t cap;
    int rev;
    bool isrev;
    int idx;
  };

  vector<vector<edge>> graph;
  vector<int> min_cost, iter;

  Dinic(int V) : INF(numeric_limits<flow_t>::max()), graph(V) {}

  void add_edge(int from, int to, flow_t cap, bool undirected = false, int idx = -1) {
    graph[from].emplace_back((edge) {to, cap, (int) graph[to].size(), false, idx});
    graph[to].emplace_back((edge) {from, undirected ? cap : 0, (int) graph[from].size() - 1, true, idx});
  }

  bool bfs(int s, int t) {
    min_cost.assign(graph.size(), -1);
    queue<int> que;
    min_cost[s] = 0;
    que.push(s);
    while (!que.empty() && min_cost[t] == -1) {
      int p = que.front(); que.pop();
      for (auto &e : graph[p]) {
        if (e.cap > 0 && min_cost[e.to] == -1) {
          min_cost[e.to] = min_cost[p] + 1;
          que.push(e.to);
        }
      }
    }
    return min_cost[t] != -1;
  }

  flow_t dfs(int idx, const int t, flow_t flow) {
    if (idx == t) return flow;
    for (int &i = iter[idx]; i < graph[idx].size(); ++i) {
      edge &e = graph[idx][i];
      if (e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
        flow_t d = dfs(e.to, t, min(flow, e.cap));
        if (d > 0) {
          e.cap -= d;
          graph[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  flow_t max_flow(int s, int t) {
    flow_t flow = 0;
    while (bfs(s, t)) {
      iter.assign(graph.size(), 0);
      flow_t f = 0;
      while ((f = dfs(s, t, INF)) > 0) flow += f;
    }
    return flow;
  }
};

void solve() {
  int h, w; cin >> h >> w;
  vector<string> g(h); cin >> g;

  Dinic<int> dinic(h + w);
  pii s, t;

  rep(i,h) {
    rep(j,w) {
      if (g[i][j] == 'o') {
        dinic.add_edge(i, h + j, 1, true);
      } else if (g[i][j] == 'S') {
        dinic.add_edge(i, h + j, 1e9, true);
        s = {i, h + j};
      } else if (g[i][j] == 'T') {
        dinic.add_edge(i, h + j, 1e9, true);
        t = {i, h + j};
      }
    }
  }

  if (s.first == t.first || s.second == t.second) {
    cout << -1 << endl;
    return;
  }

  cout << dinic.max_flow(s.first, t.first) << endl;
}


