	dinit_graph(int n=0,int s=0,int t=0):n(n),s(s),t(t)
	{
		graph.assign(n+1,vi());
		edge.clear();
	}
	void add(int v,int u,ll w)
	{
		graph[v].push_back(edge.size());
		edge.emplace_back(v,u,w);
		graph[u].push_back(edge.size());
		edge.emplace_back(u,v,0ll);
	}
