using namespace std;
using ll = long long;
using ld = long double;
using P  = pair<ll,ll>;
//--GLOBAL---------------------------------
struct edge{ll to, cap, rev;}; //to, capacity, 反対エッジ
struct graph{
    ll N;
    vector<vector<edge> > G;
    vector<bool> used;

    graph(ll n): N(n), G(N), used(N,false) {}

    void add_edge(ll s, ll t, ll cap){
        G[s].emplace_back((edge){t, cap, (ll)G[t].size()});
        G[t].emplace_back((edge){s, cap, (ll)G[s].size()-1}); // 無向ならcap
    }

    ll dfs(ll v, ll goal, ll water){
        if(v == goal) return water;
        used[v]=true;
        for(auto& E : G[v]){
            if(!used[E.to] and E.cap > 0){
                ll o_flow = dfs(E.to, goal, min(water, E.cap));
                if(o_flow > 0){
                    E.cap -= o_flow;
                    G[E.to][E.rev].cap += o_flow;
                    return o_flow;
                }
            }
        }
        return 0;
    }

    ll max_flow(ll s, ll g){
        ll flow = 0;
        while(1){
            rep(i,N) used[i] = false;
            ll o_flow = dfs(s, g, INF);
            if (o_flow==0) return flow; //更新がなかったら終了
            flow += o_flow;
        }
    }
};
//--MAIN-----------------------------------
void Main(){
    ll H,W; cin>>H>>W;
    graph g(H+W+2);
    rep(i,H){
        rep(j,W){
            char c; cin>>c;
            if(c=='.') continue;
            if(c=='o'){
                g.add_edge(2+i,2+H+j,1);
            }
            if(c=='S'){
                g.add_edge(0,2+i,INF);
                g.add_edge(0,2+H+j,INF);
            }
            if(c=='T'){
                g.add_edge(1,2+i,INF);
                g.add_edge(1,2+H+j,INF);
            }
        }
    }
    ll ans=g.max_flow(0,1);
    cout<< ( ans>=INF ? -1 : ans )<<"\n";
}
