/* v-v-v-v-v-v-v-v-v Main Part v-v-v-v-v-v-v-v-v */

struct edge {
    int to;
    int cap;
    int rev;  // path[to]中でのfromのイテレータ
    edge(int to_, int cap_, int rev_) : to(to_), cap(cap_), rev(rev_){};
};

class Dinic {
public:
    vector<vector<edge>> path;
    vector<int> level, iter;

    explicit Dinic(int N) {
        path.resize(N);
        level.resize(N);
        iter.resize(N);
    }

    void add_edge(int from, int to, int cap) {
        // fromとtoの間に双方向の辺を加える
        // 有向の場合は後者のcapを0にする
        path[from].push_back(edge(to, cap, path[to].size()));
        path[to].push_back(edge(from, 0, path[from].size() - 1));
    }

    void bfs(int s) {
        // 頂点sからのcap>0の辺のみを通った最短距離を求める
        // 辿り着けなければ-1

        fill(level.begin(), level.end(), -1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty()) {
            int v = que.front();
            que.pop();

            for (auto e : path[v]) {
                int sv = e.to, c = e.cap;
                if (c > 0 && level[sv] < 0) {
                    level[sv] = level[v] + 1;
                    que.push(sv);
                }
            }
        }
    }

    int dfs(int v, int g, int f) {
        if (v == g) return f;

        // iterで事前にどこまで探索したかをセーブ
        for (int& itr = iter[v]; itr < path[v].size(); ++itr) {
            edge e = path[v][itr];

            if (e.cap > 0 && level[v] < level[e.to]) {
                int df = dfs(e.to, g, min(f, e.cap));
                if (df > 0) {
                    path[v][itr].cap -= df;
                    path[e.to][e.rev].cap += df;
                    return df;
                }
            }
        }
        return 0;
    }

    int max_flow(int s, int g) {
        // sからgへの最大フロー(最小カット)を求める

        int flow = 0;
        while (true) {
            bfs(s);
            if (level[g] < 0) {
                return flow;
            }
            fill(iter.begin(), iter.end(), 0);
            int f;
            while (true) {
                f = dfs(s, g, INF);
                if (f == 0) break;
                flow += f;
            }
        }
    }
};


int main() {
    int H, W;
    cin >> H >> W;

    string a[H];
    pair<int, int> s, g;
    for (int i = 0; i < H; ++i) {
        cin >> a[i];
        for (int j = 0; j < W; ++j) {
            if (a[i][j] == 'S') {
                s = make_pair(i, j);
            } else if (a[i][j] == 'T') {
                g = make_pair(i, j);
            }
        }
    }

    if (s.first == g.first || s.second == g.second) {
        cout << -1 << endl;
        return 0;
    }

    Dinic dinic(H + W + 2);
    dinic.add_edge(H + W, s.first, INF);
    dinic.add_edge(H + W, s.second + H, INF);
    dinic.add_edge(g.first, H + W + 1, INF);
    dinic.add_edge(g.second + H, H + W + 1, INF);

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (a[i][j] == 'o') {
                dinic.add_edge(i, j + H, 1);
                dinic.add_edge(j + H, i, 1);
            }
        }
    }

    cout << dinic.max_flow(H + W, H + W + 1) << endl;
    return 0;
}

