                int d = dfs(e.to,t,min(f,e.cap));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(int s,int t,int lim){
        int flow = 0;
        for(; ;){
            bfs(s);
            if(level[t] < 0 || lim == 0){
                return flow;
            }
            iter.assign(iter.size(),0);
            int f;
            while((f = dfs(s,t,INF)) > 0){
                flow += f;
                lim -= f;
            }
        }
    }
};

