		add_edge(S, sx, inf); add_edge(S, sy + h, inf);
		add_edge(tx, T, inf); add_edge(ty + h, T, inf);
		//printf("*");
		int ans = 0, tmp;
		while (bfs()) while(tmp = dfs(S, inf)) ans += tmp;
		printf("%d\n", ans);
	}

	return 0;
}

