template <typename flow_t>
struct Dinic {
   private:
	const flow_t INF = numeric_limits<flow_t>::max();
	struct edge {
		int to;
		flow_t cap;
		int rev;
		bool isrev;
		int idx;
	};
	vector<vector<edge>> graph;
	vector<int> min_cost, iter;

	bool bfs(int s, int t) {
		min_cost.assign(graph.size(), -1);
		queue<int> que;
		min_cost[s] = 0;
		que.push(s);
		while(!que.empty() && min_cost[t] == -1) {
			int p = que.front();
			que.pop();
			for(auto &e : graph[p]) {
				if(e.cap > 0 && min_cost[e.to] == -1) {
					min_cost[e.to] = min_cost[p] + 1;
					que.push(e.to);
				}
			}
		}
		return min_cost[t] != -1;
	}

	flow_t dfs(int idx, const int t, flow_t flow) {
		if(idx == t) return flow;
		for(int &i = iter[idx]; i < (int)graph[idx].size(); i++) {
			edge &e = graph[idx][i];
			if(e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
				flow_t d = dfs(e.to, t, min(flow, e.cap));
				if(d > 0) {
					e.cap -= d;
					graph[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

   public:
	Dinic(int v = 0) : graph(v) {}

	void add_edge(int from, int to, flow_t cap, int idx = -1) {
		graph[from].emplace_back(edge{to, cap, (int)graph[to].size(), false, idx});
		graph[to].emplace_back(edge{from, 0, (int)graph[from].size() - 1, true, idx});
	}

	flow_t max_flow(int s, int t) {
		flow_t flow = 0;
		while(bfs(s, t)) {
			iter.assign(graph.size(), 0);
			flow_t f = 0;
			while((f = dfs(s, t, INF)) > 0) flow += f;
		}
		return flow;
	}

	void resize(int x) { graph.resize(x); }

	int size() { return (int)graph.size(); }
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout << fixed << setprecision(15);
	srand((unsigned)time(NULL));

	using pii = pair<int, int>;
	INT(h, w);
	VVEC(char, c, h, w);
	vvi a(h, vi(w, 0));
	pii start, goal;
	rep(i, h) rep(j, w) {
		if(c[i][j] == 'S') {
			start = {i, j};
		} else if(c[i][j] == 'T') {
			goal = {i, j};
		}
		if(c[i][j] != '.') {
			a[i][j] = 1;
		}
	}

	Dinic<ll> din(h * w * 2);

	int n = h * w;
	int n2 = n * 2;

	auto con = [&](int a, int b) { return a * w + b; };

	rep(i, h) rep(j, w) Rep(k, j + 1, w) if(a[i][j] && a[i][k]) {
		din.add_edge(con(i, j) + n, con(i, k), dekai);
		din.add_edge(con(i, k) + n, con(i, j), dekai);
	}

	rep(i, w) rep(j, h) Rep(k, j + 1, h) if(a[j][i] && a[k][i]) {
		din.add_edge(con(j, i) + n, con(k, i), dekai);
		din.add_edge(con(k, i) + n, con(j, i), dekai);
	}

	rep(i, h) rep(j, w) {
		if(a[i][j]) {
			din.add_edge(con(i, j), con(i, j) + n, 1LL);
		}
	}

	ll ans = din.max_flow(con(start.first, start.second) + n, con(goal.first, goal.second));
	if(ans >= dekai) ans = -1;
	drop(ans);
	return 0;
}

