          dist[e.to]=dist[x]+1;
          q.push(e.to);
        }
      }
    }
  }

  int dfs(int x,int t,int f){
    if(x==t)return f;
    for(int& i=iter[x];i<(int)v[x].size();++i){
      edge& e=v[x][i];
      if(e.cap>0&&dist[x]<dist[e.to]){
        int d=dfs(e.to,t,min(f,e.cap));
        if(d>0){
          e.cap-=d;
          v[e.to][e.rev].cap+=d;
          return d;
        }
      }
    }
    return 0;
  }

  int max_flow(int s,int t){
    int flow=0;
    while(1){
      bfs(s);
