int dfs(int v, int t, int f) {
    if (v==t) return f;
    used[v] = true;
    for (int i = 0; i < (int)edge[v].size(); i++) {
        auto e = edge[v][i];
        if (used[e[0]] || e[1]==0) continue;
        int d = dfs(e[0], t, min(f, e[1]));
        if (d > 0) {
            edge[v][i][1] -= d;
            edge[e[0]][e[2]][1] += d;
            return d;
        }
    }
    return 0;
}

