void add_edge(int v1, int v2, ll cost) {
    g[v1].push_back(edge{v2, (int)g[v2].size(), cost});
    g[v2].push_back(edge{v1, (int)g[v1].size()-1, 0});
}

ll find_augment(int at, int dest, ll curflow) {
    if (at == dest) {
	return curflow;
    }
    viz[at]=true;

    for (auto& ed: g[at]) {
	if (!viz[ed.to] && ed.cap>0) {
	    ll newflow = find_augment(ed.to, dest, min(curflow, ed.cap));
	    if (newflow > 0) {
		ed.cap -= newflow;
		g[ed.to][ed.rev].cap += newflow;
		return newflow;
	    }
	}
    }
    return 0;
}



ll max_flow(int src, int dst) {
    ll res = 0;
    while (1) {
	memset(viz,false,sizeof(viz));
	ll x = find_augment(src, dst, inf);
	if (x==0) break;
	res += x;
	if (res > N) break;
    }
    return res;
}

