    rep(h, H) rep(w, W) if (b[h][w] == 'o') {
        rep(nh, H) if (b[nh][w] == 'o') {
            ff.add_edge(pos(h, w) + 1, pos(nh, w), INF);
        } 
        rep(nw, W) if (b[h][nw] == 'o') {
            ff.add_edge(pos(h, w) + 1, pos(h, nw), INF);
        }
    }


    // src, dst
    rep(h, H) rep(w, W) {
        if (b[h][w] == 'S') {
            rep(nh, H) if (b[nh][w] == 'o') {
                ff.add_edge(src, pos(nh, w), INF);
            } 
