                ff.add_edge(pos(nh, w) + 1, dst, INF);
            } 
            rep(nw, W) if (b[h][nw] == 'o') {
                ff.add_edge(pos(h, nw) + 1, dst, INF);
            }
        }
    }


    //    vizGraph(g, 2, 1);
    cout << ff.maxflow(src, dst) << endl;

    return 0;
}

