struct Maxflow {
	//vec[e.to][e.rev]で逆辺
	vector<vector<edge>>vec;
	bool used[100000];
	Maxflow(LL n):vec(n+1){}
	void addedge(LL from, LL to, LL cap) {
		if (from == to)return;
		vec[from].push_back(edge{ to, cap, (LL)vec[to].size() });
		vec[to].push_back(edge{ from, 0, (LL)vec[from].size() - 1 });
	}
	LL dfs(LL v, LL t, LL f) {
		if (v == t)return f;
		used[v] = true;
		rep(i, vec[v].size()) {
			edge& e = vec[v][i];
		if (!used[e.to] && e.cap > 0) {
				LL d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					vec[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
	LL ford(LL s, LL t) {
		LL flow = 0;
		for (;;) {
			memset(used, 0, sizeof used);
			LL f = dfs(s, t, INF);
			if (f == 0)return flow;
			flow += f;
		}
	}
};
