struct Edge{
	Node *from, *to;
	int limit, rem;
	Edge(Node* from, Node* to, int limit = 1): from(from), to(to), limit(limit), rem(limit){ }
    int remain(bool rev = false){
        return rev ? limit - rem : rem;
    }
    void pour(int f, bool rev = false){
        rem -= rev ? - f : f;
    }
};
