        return {add(dest), dest->add(this)};
    }
};
// int flow(Node* start, Node* goal, set<Node*>& visited, int cur){ }
int flow(Node* start, Node* goal, vector<char>& visited, int cur){
	if(start == goal){ return cur; }
    auto _flow = [&](Node* Edge::* to, vector<Edge*> Node::* edges, bool rev = false){
        for(Edge* e : start->*edges){
            Node* v = e->*to; 
            if(!e->remain(rev) || /*visited.count(v)*/ visited[v->id]){ continue; }
            visited[v->id] = true; // visited.insert(v);
            int lim = min(cur, e->remain(rev));
            if((lim = flow(v, goal, visited, lim))){
                e->pour(lim, rev);
                return lim;
            }
        }
        return 0;
    };
    int ret = 0;
    if((ret = _flow(&Edge::to, &Node::outEdges)) ||
       (ret = _flow(&Edge::from, &Node::inEdges, true))){
        return ret;
    }
	return ret;
}
