  Cap.resize(N);
  for (auto &cap : Cap) cap.resize(N);
  for (ll y = 0; y < H; ++y)
    for (ll x = 0; x < W; ++x) {
      char c;
      cin >> c;
      if (c == 'S')
        Cap[Src][row(y)] = Cap[Src][column(x)] = INF;
      else if (c == 'T')
        Cap[row(y)][Tgt] = Cap[column(x)][Tgt] = INF;
      else if (c == 'o')
        Cap[row(y)][column(x)] = Cap[column(x)][row(y)] = 1;
    }
  while (true) {
    ll flow = -1;
    vector<ll> parent;
    {
      queue<VCap> que;
      vector<bool> visited;
      visited.resize(N);
      parent.resize(N, -1);
      que.push(VCap(Src, INF));
      visited[Src] = true;
      while (!que.empty()) {
        ll v, cap;
