        if (v == Tgt) {
          flow = cap;
          break;
        }
        for (ll w = 0; w < N; ++w) {
          if (!visited[w] && Cap[v][w] > 0) {
            que.push(VCap(w, min(cap, Cap[v][w])));
            parent[w] = v;
            visited[w] = true;
          }
        }
      }
    }
    if (flow < 0) break;
    R += flow;
    for (ll v = Tgt; v != Src; v = parent[v]) {
      ll u = parent[v];
      Cap[u][v] -= flow;
      Cap[v][u] += flow;
    }
  }
  cout << (R == INF ? -1 : R) << endl;
  return 0;
}

