typedef int LL;
int vis[N],ID;
int fromid[N];
int fromnode[N];
int MM;
LL bfs(int src,int snk) {

    queue<int> q ;
    q.push(src);
    vis[src]=ID;
    while(!q.empty()){
        MM=max(MM,(int)q.size());
        int cur=q.front();
        q.pop();
        if(cur==snk){
            while(cur!=src){
                cap[fromid[cur]]-=1;
                cap[fromid[cur]^1]+=1;
                cur=fromnode[cur];
            }
            return 1;
        }
        for (int i = head[cur]; i != -1; i = nxt[i]) {
            int t = to[i];
            if(cap[i]>0 &&vis[t]!=ID){
                fromid[t]=i;
                fromnode[t]=cur;
                vis[t]=ID;
                q.push(t);
            }
        }
    }
    return 0;
}
// +201278474570 tamer :)

LL dfs(int cur,int snk, LL MX) {
//    cout << cur <<' ' ;
    if (vis[cur] == ID || MX == 0)
        return 0;
    vis[cur] = ID;
    if (cur == snk)
        return MX;
    for (int i = head[cur]; i != -1; i = nxt[i]) {
        int t = to[i];
        LL f = dfs(t,snk, min(MX, cap[i]));
        if (!f)
            continue;
        cap[i] -= f;
        cap[i ^ 1] += f;
        return f;
    }

    return 0;
}

