vi bfspath(int s,int t){
  // not dfs but bfs
  vector<bool> used(128*128*2,false);
  vi bef(128*128*2,-1);
  queue<int> Q;
  Q.push(s);
  used[s] = true;
  while(!Q.empty()){
    int p = Q.front(); Q.pop();
    for(pii P : fl[p]){
      int to = P.first;
      int c = P.second;
      if(c==0)continue;
      if(used[to])continue;
      used[to] = true;
      bef[to] = p;
      if(to==t){
        queue<int> dummy;
        swap(Q,dummy);
        break;
      }
      Q.push(to);
    }
  }
  if(bef[t]==-1)return vi();
  vi ret;
  int cur = t;
  ret.push_back(cur);
  while(cur != s){
    cur = bef[cur];
    ret.push_back(cur);
  }
  reverse(ALL(ret));
  return ret;
}

