int dfs(int v, int flow)
{
	if (v == t || !flow) return flow;
	for (; tx[v] < g[v].size(); ++tx[v])
	{
		int to = edges[g[v][tx[v]]].b;
		int tflow = edges[g[v][tx[v]]].cap - edges[g[v][tx[v]]].flow;
		tflow = min(tflow, flow);
