template <class T> struct MaxFlow {
   const T INF = 1e9;
   struct  Edge {
      int to,rev; T cap;
      Edge(){}
      Edge(int _to, int _rev, T _cap){
         to = _to; rev = _rev; cap = _cap;
      }
   };
   vector< vector<Edge> > G;
   vector< bool > used;
   MaxFlow(int size){
      G.resize(size+10);
      used.resize(size+10);
   }
   void add_edge(int from, int to, int cap){
      G[from].push_back(Edge(to,(int)G[to].size(),cap));
      G[to].push_back(Edge(from,(int)G[from].size()-1,0));
   }
   T dfs(int v, int t, T f){
      if(v==t)return f;
      used[v] = true;
      for(int i=0;i<G[v].size();i++){
         Edge &e = G[v][i];
         if(!used[e.to] && e.cap>0){
            T d = dfs(e.to, t, min(f,e.cap));
            if(d>0){
               e.cap -= d;
               G[e.to][e.rev].cap += d;
               return d;
            }
         }
      }
      return 0;
   }
   T getmax(int source, int sink){
      T flow = 0;
      while(true){
         for(int i=0;i<used.size();i++)used[i]=false;
         T f = dfs(source, sink, INF);
         if(f==0)return flow;
         flow += f;
      }
   }
};

