int bfs() {
    fill(d, d + maxn * maxn * maxn, oo);

    d[st] = 0;
    queue < int > q;
    q.push(st);

    while (!q.empty() && d[en] == oo) {
        int u = q.front(); q.pop();

        for (auto i : g[u]) {
            int v = e[i].v;

            if (e[i].cap == e[i].flow) continue;

            if (d[v] == oo) {
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }

    return d[en] != oo;
}

int dfs(int u, int flow) {

    if (u == en || !flow) return flow;

    for (; cur[u] < g[u].size(); ++cur[u]) {
        int i = g[u][cur[u]], v = e[i].v;

        if (e[i].cap == e[i].flow || d[v] != d[u] + 1) continue;

        int newFlow = dfs(v, min(flow, e[i].cap - e[i].flow));

        if (newFlow) {
            e[i].flow += newFlow;
            e[i ^ 1].flow -= newFlow;
            return newFlow;
        }
    }

    return 0;
}

int maxFlow() {
  int cnt = 0;
  while (bfs()) {
    fill(cur, cur + cnt + 1, 0);

    while (dfs(st, 1))
      cnt++;
  }

  return cnt;
}

