template <int MAX_V>  // Max |V|, including s and t
class FordFulkerson {

  struct edge {
      int to;  // destination node
      ll cap;  // capacity
      int rev; // reverse edge
  };

  vector<edge> G[MAX_V]; // adjacency list
  bool used[MAX_V];

public:

  // Add an edge to the graph G.
  //
  // @param from a node
  // @param to a node
  // @param capacity
  void addEdge(const int from, const int to, const ll cap) {
      G[from].push_back(edge{to, cap, (int)G[to].size()});
      // Add a reverse eddge
      G[to].push_back(edge{from, 0, (int)G[from].size() -1});
  }

  // Search for an augument path from v with flow f.
  //    - t is the sink node
  int dfs(const int v, const int t, const ll f) {
      if (v==t) return f;
      used[v] = true;
      for (auto& e : G[v]) {
  	if (used[e.to] || e.cap == 0) continue;

  	const ll d = dfs(e.to, t, min({f, e.cap}));
  	if (d<=0) continue;

  	e.cap -= d;
  	G[e.to][e.rev].cap += d;
  	return d;
      }
      return 0;
  }

  // Return the max flow from s to t for the graph G.
  ll maxFlow(const int s, const int t) {
      ll flow = 0;
      while (true) {
  	fill(used, used+MAX_V, false);

  	const ll f = dfs(s, t, LINF);
  	if (f==0) return flow;
  	flow += f;
      }
  }
};
