inline void add_edge(int u, int v, int _cap)
{
	to[tot] = v; 
	pre[tot] = lst[u]; 
	cap[tot] = _cap; 
	lst[u] = tot++; 
	to[tot] = u; 
	pre[tot] = lst[v]; 
	cap[tot] = 0; 
	lst[v] = tot++; 
}
inline bool bfs(int s, int t)
{
	int he = 0, ta = 1; 
	que[0] = s; 
	memset(dep, -1, sizeof(dep)); 
	dep[s] = 0; 
	while (he < ta)
	{
		int u = que[he++]; 
		for (int i = lst[u]; ~i; i = pre[i])
		{
			if (cap[i] && dep[to[i]] == -1)
			{
				dep[to[i]] = dep[u] + 1; 
				que[ta++] = to[i]; 
			}
		}
	}
	return dep[t] != -1; 
}
int dfs(int u, int t, int mx)
{
	if (u == t)
		return mx; 
	int ans = 0; 
	for (int i = fst[u]; ~i; i = pre[i])
	{
		if (cap[i] && dep[to[i]] == dep[u] + 1)
		{
			int res = dfs(to[i], t, std::min(mx - ans, cap[i])); 
			cap[i] -= res; 
			cap[i ^ 1] += res; 
			if (cap[i])
				fst[u] = i; 
			ans += res; 
			if (ans == mx)
				return ans;
		}
	}
	if (!ans)
		dep[u] = -1; 
	return ans; 
}
