template< typename flow_t >
struct FordFulkerson {
  struct edge {
    int to;
    flow_t cap;
    int rev;
    bool isrev;
    int idx;
  };

  vector< vector< edge > > graph;
  vector< int > used;
  const flow_t INF;
  int timestamp;

  FordFulkerson(int n) : INF(numeric_limits< flow_t >::max()), timestamp(0) {
    graph.resize(n);
    used.assign(n, -1);
  }

  void add_edge(int from, int to, flow_t cap, int idx = -1) {
    graph[from].emplace_back((edge) {to, cap, (int) graph[to].size(), false, idx});
    graph[to].emplace_back((edge) {from, 0, (int) graph[from].size() - 1, true, idx});
  }

  flow_t dfs(int idx, const int t, flow_t flow) {
    if(idx == t) return flow;
    used[idx] = timestamp;
    for(auto &e : graph[idx]) {
      if(e.cap > 0 && used[e.to] != timestamp) {
        flow_t d = dfs(e.to, t, min(flow, e.cap));
        if(d > 0) {
          e.cap -= d;
          graph[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  flow_t max_flow(int s, int t) {
    flow_t flow = 0;
    for(flow_t f; (f = dfs(s, t, INF)) > 0; timestamp++) {
      flow += f;
    }
    return flow;
  }

  void output() {
    for(int i = 0; i < graph.size(); i++) {
      for(auto &e : graph[i]) {
        if(e.isrev) continue;
        auto &rev_e = graph[e.to][e.rev];
        cout << i << "->" << e.to << " (flow: " << rev_e.cap << "/" << e.cap + rev_e.cap << ")" << endl;
      }
    }
  }
};

template <typename Cap, typename Cost>
struct Graph {
  const Cost INF = numeric_limits<Cost>::max();
  struct Edge {
    int to, rev;
    Cap cap;
    Cost cost;
    Edge(int to, Cap cap, Cost cost, int rev)
      : to(to), cap(cap), cost(cost), rev(rev) {}
  };
  vector<vector<Edge>> g;
  int n;
  Graph(int n) : n(n) {
    g.assign(n, vector<Edge>());
  }
  void add_edge(int v, int u, Cap cap = 1, Cost cost = 0) {
    g[v].emplace_back(u, cap, cost, (int) g[u].size());
    g[u].emplace_back(v, 0, -cost, (int) g[v].size() - 1);
  }
  vector<Edge>& operator[](int x) {
    return g[x];
  }
};

