  rep(i, h) rep(j, w) if (a[i][j] != '.') {
    int u = id(i, j);
    rep(k, h) if (k != i && a[k][j] != '.') {
      int v = id(k, j) + h * w;
      g.add_edge(u, v, 1);
    }
    rep(k, w) if (k != j && a[i][k] != '.') {
      int v = id(i, k) + h * w;
      g.add_edge(u, v, 1);
    }
  }
  rep(i, h) rep(j, w) if (a[i][j] != '.') {
    int u = id(i, j) + h * w;
    int v = id(i, j);
    int t = a[i][j] == 'o' ? 1 : h * w * 2;
    g.add_edge(u, v, t);
  }
  int ans = g.max_flow(id(sx, sy), id(tx, ty));
  cout << ans << endl;
}

