#include <queue>
template<typename T>
class Dinic {
    struct Edge {
        int to, rev;
        T cap;
        Edge(int t, int r, T c)
            : to(t), rev(r), cap(c) {}
    };
    int n;
    vector<vector<Edge>> G;
    vector<int> level;
    vector<int> itr;

    bool bfs(int s, int t) {
        queue<int> que;
        level.assign(n, -1);
        level[s] = 0;
        que.emplace(s);
        while (que.size()) {
            int v = que.front();
            que.pop();
            for (auto &edge : G[v]) {
                if (edge.cap > 0 && level[edge.to] == -1) {
                    level[edge.to] = level[v] + 1;
                    que.emplace(edge.to);
                }
            }
        }
        return level[t] != -1;
    }

    T dfs(int v, int t, T flow) {
        if (v == t) return flow;
        for (int &i = itr[v]; i < static_cast<int>(G[v].size()); i++) {
            auto &edge = G[v][i];
            if (edge.cap > 0 && level[v] < level[edge.to]) {
                T d = dfs(edge.to, t, min(flow, edge.cap));
                if (d > 0) {
                    edge.cap -= d;
                    G[edge.to][edge.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

public:
    Dinic(int _n) {
        n = _n;
        G.resize(n);
    }
    void add_edge(int s, int t, T cap) {
        G[s].emplace_back(t, G[t].size(), cap);
        G[t].emplace_back(s, static_cast<int>(G[s].size() - 1), 0);
    }
    T max_flow(int s, int t, T inf) {
        T ans = 0;
        while (bfs(s, t)) {
            itr.assign(n, 0);
            for (T f = 0; (f = dfs(s, t, inf)) > 0; ans += f)
                ;
        }
        return ans;
    }
};

