struct MaxFlow {
  struct Edge {
    i64 v, c, f;
  };

  i64 n;
  vector<vector<i64>> g;
  vector<Edge> es;

  MaxFlow(i64 n) : n(n), g(n + 1) {}
  void add_edge(i64 u, i64 v, i64 c);
  i64 relax(int s, int t);
  i64 max_flow(int s, int t);
};

void MaxFlow::add_edge(i64 u, i64 v, i64 c) {
  g[u].push_back(es.size());
  es.push_back({ v, c, 0 });
  g[v].push_back(es.size());
  es.push_back({ u, 0, 0 });
}

i64 MaxFlow::relax(int s, int t) {
  queue<i64> q;
  vector<i64> route(n + 1, -1);
  q.push(s);
  route[s] = -2;
  while (!q.empty()) {
    i64 u = q.front();
    q.pop();
    for (i64 ei : g[u]) {
      const Edge& e = es[ei];
      if (route[e.v] == -1 && e.c - e.f > 0) {
        q.push(e.v);
        route[e.v] = ei;
        if (e.v == t) goto found;
      }
    }
  }
  return 0;
found:
  i64 mf = 1ll << 62;
  for (i64 u = t; u != s; ) {
    i64 ei = route[u], rei = ei ^ 1;
    const Edge& e = es[ei], &re = es[rei];
    mf = min(mf, e.c - e.f);
    u = re.v;
  }
  for (i64 u = t; u != s; ) {
    i64 ei = route[u], rei = ei ^ 1;
    Edge& e = es[ei], &re = es[rei];
    e.f += mf;
    re.f -= mf;
    u = re.v;
  }
  return mf;
}

i64 MaxFlow::max_flow(int s, int t) {
  i64 f = 0;
  while (true) {
    i64 x = relax(s, t);
    if (x == 0) break;
    f += x;
  }
  return f;
}

