#define MAX_V 10010
struct edge {int to;long long cap;int rev;};
vector<edge> G[MAX_V];	// 最大フロー用の隣接リスト
bool used[MAX_V];
void add_edge(int from,int to,long long cap) {
	G[from].push_back((edge){to,cap,(int)G[to].size()});
	G[to].push_back((edge){from,0,(int)G[from].size()-1});
}
long long dfs(int v,int t,long long f) {
	if(v==t) return f;
	used[v]=true;
	for(int i=0; i<G[v].size(); ++i) {
		edge &e=G[v][i];
		if(!used[e.to]&&e.cap>0) {
			long long d=dfs(e.to,t,min(f,e.cap));
			if(d>0) {
				e.cap-=d;
				G[e.to][e.rev].cap+=d;
				return d;
			}
		}
	}
	return 0;
}
long long FordFulkerson(int s,int t, vector<vector<P>>& adj) {
	// adj は通常の隣接リスト（first: to, second: cost）
	for(int i=0; i<(int)adj.size(); i++) {
		for(int j=0; j<(int)adj[i].size(); j++) {
			add_edge(i,adj[i][j].first,adj[i][j].second);
		}
	}
	long long flow=0;
	while(1) {
		for(int i=0; i<MAX_V; ++i) used[i]=false;
		long long f=dfs(s,t,INF*INF);
		if(f==0) return flow;
		flow+=f;
	}
}

