				dis[a[i].v] = dis[x] + 1;
				q[++ta] = a[i].v;
				if(a[i].v == t) return true;
			}
	}
	return false;
}

int dfs(int x, int flw) {
	if(x == t or flw == 0) return flw;
	int res = 0, tmp;
	for(int&i=cur[x];i;i=a[i].nxt)
		if(dis[a[i].v] == dis[x] + 1 and a[i].w > 0)
		if(tmp = dfs(a[i].v, min(flw - res, a[i].w)))
			a[i].w -= tmp, a[i^1].w += tmp, res += tmp;
	if(!res) dis[x] = -1;
	return res;
}

