		int ret=0;
		for (;relabel();) for (int tmp;tmp=aug(S,INF);ret+=tmp);
		return ret;
	}

	bool build()
	{
		for (int i=1;i<=n;++i)
			for (int j=1;j<=m;++j)
				if (pic[i][j]!='.')
				{
					int x=(i-1)*m+j;
					addedge((x<<1)-1,x<<1,1);
					if (pic[i][j]=='S') S=x<<1;
					if (pic[i][j]=='T') T=(x<<1)-1;
					for (int k=1;k<=n;++k)
						if (i!=k&&pic[k][j]!='.')
						{
							int y=(k-1)*m+j;
							addedge(x<<1,(y<<1)-1,INF);
						}
					for (int k=1;k<=m;++k)
						if (j!=k&&pic[i][k]!='.')
						{
							int y=(i-1)*m+k;
							addedge(x<<1,(y<<1)-1,INF);
						}
				}
		int src=S+1>>1,tar=T+1>>1;
		int srcx=(src-1)/m+1,srcy=(src-1)%m+1;
		int tarx=(tar-1)/m+1,tary=(tar-1)%m+1;
		return srcx!=tarx&&srcy!=tary;
	}
};

