    rep(i, h) rep(j, w) {
        if (a[i][j] == 'S') {
            dinic.add_edge(0, i + 1, iinf);
            dinic.add_edge(0, h + j + 1, iinf);
        }
        else if (a[i][j] == 'T') {
            dinic.add_edge(i + 1, h + w + 1, iinf);
            dinic.add_edge(h + j + 1, h + w + 1, iinf);
        }
        else if (a[i][j] == 'o') {
            dinic.add_edge(i + 1, h + j + 1, 1);
            dinic.add_edge(h + j + 1, i + 1, 1);
        }
    }
    auto ans = dinic.max_flow(0, h + w + 1);
    if (ans == iinf) cout << -1 << endl;
    else cout << ans << endl;
}

