void Add_Edge(int u, int v, int cap)
{
	//cout << u <<" " <<v <<" " << cap << endl;
	e.push_back(Edge(u, v, cap));
	e.push_back(Edge(v, u, 0));
	E[u].push_back(edgecnt++);
	E[v].push_back(edgecnt++);
}

bool BFS(int S, int T, int n)
{
	queue<int> Q;
	Q.push(T);
	for (int i = 0; i <= n; ++i) d[i] = INF;
	d[T] = 0;

	while (!Q.empty())
	{
		int x = Q.front(); Q.pop();
		//cout << x << endl;
		for (int i = 0; i < E[x].size(); ++i)
		{
			int y = e[E[x][i]].v;
			//cout << y <<" " << e[E[x][i] ^ 1].cap << endl;
			if (!e[E[x][i] ^ 1].cap) continue;
			if (d[y] == INF) 
			{
				d[y] = d[x] + 1;
				Q.push(y);
			}
		}
	}
	//cout << "d[S] = " << d[S] << endl;
	return d[S] != INF;
}

int DFS(int x, int T, int lim)
{
	if (x == T || !lim) return lim;

	int flow = 0, tmp;
	for (int &i = cur[x], y; i < E[x].size(); ++i)
	{
		y = e[E[x][i]].v;
		if (d[y] + 1 != d[x] || !e[E[x][i]].cap) continue;
		tmp = DFS(y, T, min(lim, e[E[x][i]].cap));
		if (tmp)
		{
			e[E[x][i]].cap -= tmp;
			e[E[x][i] ^ 1].cap += tmp;
			flow += tmp;
			lim -= tmp;
			if (!lim) break;
		}
	}

	return flow;
}

int MaxFlow(int S, int T, int n)
{
	int flow = 0;
	while (BFS(S, T, n))
	{
		memset(cur, 0, sizeof(cur));
		flow += DFS(S, T, INF);
	}

	return flow;
}

