#include <bits/stdc++.h>
using namespace std;

#define int long long
#define N 2100000
#define INF 1000000000000000000LL
class Dinic
{
private:
	int lt[N], nt[N], bi[N], ci[N], tl;
	int nw[N], dis[N], vis[N];
	queue <int> Q;
public:
	int s, e, tot;
	int oppo(int t) {return t & 1? t + 1: t - 1;}
	void build(int a, int b, int c)
	{
		nt[++ tl] = lt[a]; lt[a] = tl; bi[tl] = b; ci[tl] = c;
		nt[++ tl] = lt[b]; lt[b] = tl; bi[tl] = a; ci[tl] = 0;
        // cout << a << " " << b << " " << c << "\n";
	}
	void flow(int p, int d)
	{
		ci[p] -= d; ci[oppo(p)] += d;
	}
	int dfs(int t, int maxl)
	{
		int nowl = 0;
		if (t == e) return maxl;
		for (int &p = nw[t]; p; p = nt[p])
			if (dis[t] + 1 == dis[bi[p]] && ci[p])
			{
				int d = dfs(bi[p], min(ci[p], maxl - nowl));
				flow(p, d); nowl += d;
				if (nowl == maxl) return maxl;
			}
		return nowl;
	}
	void bfs()
	{
		for (int i = 1; i <= tot; ++ i) vis[i] = 0, dis[i] = tot + 1;
		vis[s] = 1; dis[s] = 0; Q.push(s);
		while (!Q.empty())
		{
			int hd = Q.front(); Q.pop();
			for (int p = lt[hd]; p; p = nt[p])
				if (!vis[bi[p]] && ci[p])
				{
					vis[bi[p]] = 1;
					dis[bi[p]] = dis[hd] + 1;
					Q.push(bi[p]);
				}
		}
	}
	int solve()
	{
		int ans = 0;
		while (1)
		{
			bfs();
			if (!vis[e]) return ans;
			for (int i = 1; i <= tot; ++ i) nw[i] = lt[i];
			ans += dfs(s, INF);
		}
	}
	void init()
	{
		for (int i = 1; i <= tot; ++ i) lt[i] = 0;
		for (int i = 1; i <= tl; ++ i) bi[i] = ci[i] = nt[i] = 0;
		s = e = tot = tl = 0;
	}
}F;


