const lli N=1009, inf=1e9, M=400009;
lli n, m, s, t, c[M], f[M], Time[N], T=1, minn[N], reach[N], dd[M], cnt;
P trace[N];
struct Ed
{
	lli v, id;
};
vector<Ed> D[N];
void Addedge(lli u, lli v, lli w)
{
	D[u].push_back({v, cnt});
	D[v].push_back({u, cnt+1});
	//D[v].push_back({u, cnt+2});
	//D[u].push_back({v, cnt+3});
	c[cnt]=w;
	//c[cnt+2]=w;
	cnt+=2;
}
void Inp()
{
	char ch;
	cin>>m>>n;
	s=m+n+1;
	t=m+n+2;
	for(int i=1;i<=m;i++)
	{
		for(int j=1;j<=n;j++)
		{
			cin>>ch;
			if(ch=='S')
			{
				Addedge(s, i, inf);
				Addedge(s, m+j, inf);
			}
			if(ch=='T')
			{
				Addedge(i, t, inf);
				Addedge(m+j, t, inf);
			}
			if(ch=='o')
			{
				Addedge(i, m+j, 1);
			}
		}
	}
}
bool findpath()
{
	deque<lli> p;
	p.push_back(s);
	minn[s]=inf;
	Time[s]=T;
	while(!p.empty())
	{
		lli u=p.front();
		p.pop_front();
		for(auto i: D[u])
		{
			lli v=i.v, id=i.id;
			if(Time[v]!=T&&c[id]>f[id]) 
			{
				Time[v]=T;
				minn[v]=min(minn[u], c[id]-f[id]);
				trace[v]=mp(u, id);
				if(v==t)
				{
					return 1;
				}
				p.push_back(v);
			}
		}
	}
	return 0;
}
void Solve()
{
	lli kq=0;
	while(findpath())
	{
		lli del=minn[t];
		kq+=del;
		lli u=t;
		while(u!=s)
		{
			f[trace[u].y]+=del;
			f[(trace[u].y^1)]-=del;
			u=trace[u].x;
		}
		T++;
	}
	if(kq>=inf)
	{
		cout<<-1;
		return ;
	}
	cout<<kq;
}
int main()
{
	//freopen("test.inp","r",stdin);
