template<typename T>
struct Dinic {
	struct Edge {
		// cap := 容量
		// rev := 逆辺のID
		const int to;
		T cap;
		const int rev;
		Edge(const int to, const T cap, const int rev) :
			to(to),
			cap(cap),
			rev(rev)
			{}
	};
	const int V;
	static constexpr T INF = numeric_limits<T>::max();
	// G[from][num] := fromから出るnum番目の辺
	vector<vector<Edge>> G;
	Dinic(const int V) :
		V(V),
		G(vector<vector<Edge>>(V, vector<Edge>()))
		{}
	void addEdge(const int from, const int to, const int cap) {
		G[from].emplace_back(to, cap, (int)G[to].size());
		G[to].emplace_back(from, 0, (int)G[from].size() - 1);
	}
	T flow(const int start, const int goal) {
		T ans = 0;
		vector<int> level(V);
		while(bfs(start, goal, level)) {
			vector<int> checked(V);
			while(1) {
				T fmax = dfs(start, goal, level, checked, INF);
				if(fmax <= 0) break;
				ans += fmax;
			}
		}
		return ans;
	}
	bool bfs(const int start, const int goal, vector<int> &level) {
		for(int i = 0; i < V; ++i) level[i] = -1;
		queue<int> que;
		level[start] = 0;
		que.push(start);
		while(que.size() and level[goal] == -1) {
			int from = que.front();
			que.pop();
			for(Edge e : G[from]) {
				if(e.cap > 0 and level[e.to] == -1) {
					level[e.to] = level[from] + 1;
					que.push(e.to);
				}
			}
		}
		return level[goal] != -1;
	}
	T dfs(const int from, const int goal, const vector<int> &level, vector<int> &checked, T fmax) {
		if(from == goal) return fmax;
		for(int &id = checked[from]; id < (int)G[from].size(); ++id) {
			Edge &e = G[from][id];
			if(level[e.to] <= level[from]) continue;
			if(e.cap <= 0) continue;
			T f = dfs(e.to, goal, level, checked, min(e.cap, fmax));
			if(f <= 0) continue;
			e.cap -= f;
			G[e.to][e.rev].cap += f;
			return f;
		}
		return 0;
	}
};

