struct Dinic {
public:
    using Flow = int;
    Dinic(int n_) : n(n_), g(n_) {}
    Flow maximum_flow(int s_, int t_) {
        s = s_;
        t = t_;
        que.resize(n);
        Flow res = 0;
        while (levelize()) {
            prog.assign(n, 0);
            res += augment(s, std::numeric_limits<Flow>::max());
        }
        return res;
    }
    void add_edge(int u, int v, Flow c) {
        if (u == v || c == 0) return;
        g[u].push_back({u, v, c, 0, (int)g[v].size()});
        g[v].push_back({v, u, c, c, (int)g[u].size() - 1});
    }

private:
    struct Edge {
        int s, d;
        Flow c, f;
        int r;
    };
    int n, s, t;
    std::vector<std::vector<Edge>> g;
    std::vector<int> level, prog, que;

    bool levelize() {
        int fst = 0, lst = 0;
        que[lst++] = s;
        level.assign(n, -1);
        level[s] = 0;
        while (fst != lst) {
            int v = que[fst++];
            if (v == t) break;
            for (auto &e : g[v]) {
                if (level[e.d] == -1 && residue(e) != 0) {
                    level[e.d] = level[v] + 1;
                    que[lst++] = e.d;
                }
            }
        }
        return level[t] != -1;
    }
    Flow augment(int v, Flow lim) {
        Flow res = 0;
        if (v == t) return lim;
        for (int &i = prog[v]; i < (int)g[v].size(); ++i) {
            if (lim == 0) break;
            auto &e = g[v][i];
            if (level[v] < level[e.d] && residue(e) != 0) {
                Flow aug = augment(e.d, std::min(lim, residue(e)));
                if (aug == 0) continue;
                e.f += aug;
                reverse(e).f -= aug;
                res += aug;
                lim -= aug;
            }
        }
        return res;
    }
    Flow residue(const Edge &e) { return e.c - e.f; }
    Edge &reverse(const Edge &e) { return g[e.d][e.r]; }

public:
    void show() {
        rep(i, n) {
            for (auto &e : g[i]){
                printf("%2d -> %2d (%2d/%2d)\n", e.s, e.d, e.f, e.c);
            }
        }
    }
};

