            while ((f = dfs(s, t, INF)) > 0) flow += f;
        }
    }
private:
    void bfs(int s) {
        std::fill(level.begin(), level.end(), -1);
        std::queue<int> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty()) {
            auto v = que.front(); que.pop();
            for (int i = 0; i < (int)g[v].size(); ++i) {
                auto& e = g[v][i];
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }
    T dfs(int v, int t, T f) {
        if (v == t) return f;
        for (int& i = iter[v]; i < (int)g[v].size(); ++i) {
            auto& e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                auto d = dfs(e.to, t, std::min<T>(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    struct Edge {
        int to, rev; T cap;
        Edge(int t, T c, int r) :to(t), cap(c), rev(r) {}
    };
    std::vector<std::vector<Edge>> g;
    std::vector<int> level;
    std::vector<int> iter;
};

int h, w;
char a[105][105];
void solve() {
    cin >> h >> w;
    rep(i, h) rep(j, w) cin >> a[i][j];

    Dinic<int, iinf> dinic(h + w + 2);
    rep(i, h) rep(j, w) {
        if (a[i][j] == 'S') {
            dinic.add_edge(0, i + 1, iinf);
            dinic.add_edge(0, h + j + 1, iinf);
        }
        else if (a[i][j] == 'T') {
            dinic.add_edge(i + 1, h + w + 1, iinf);
            dinic.add_edge(h + j + 1, h + w + 1, iinf);
        }
        else if (a[i][j] == 'o') {
            dinic.add_edge(i + 1, h + j + 1, 1);
            dinic.add_edge(h + j + 1, i + 1, 1);
        }
    }
    auto ans = dinic.max_flow(0, h + w + 1);
    if (ans == iinf) cout << -1 << endl;
    else cout << ans << endl;
}

