        //cout<<u<<' ';
        for(auto &e:g[u]){
            if(lev[e.v]<0&&e.flow<e.C){
                lev[e.v]=lev[u]+1;
                q.push_back(e.v);
            }
        }
    }
    //cout<<endl;
    return lev[t]>=0;
}
int G::send(int s,int flow,int t,vector<int>&st){
    if(s==t)return flow;
    for(;st[s]<g[s].size();st[s]++){
        auto &e=g[s][st[s]];
        if(lev[e.v]==lev[s]+1&&e.flow<e.C){
            int cur=min(flow,e.C-e.flow);
            int tmp=send(e.v,cur,t,st);
            if(tmp>0){
                e.flow+=tmp;
                g[e.v][e.rev].flow-=tmp;
                return tmp;
            }
        }
    }
}
int G::DinicMaxflow(int s, int t)
{
    if (s == t)
        return 0;
    int total = 0;
    while (bfs(s, t) == true)
    {
        vector<int>st(N,0);
        while (int flow = send(s, INT_MAX, t, st))
            total += flow;
    }
    return total;
}
