void add(int x, int y, int z1, int z2) {
	ter[++ e] = y, nxt[e] = lnk[x], lnk[x] = e, w[e] = z1, rec[e] = e + 1 ;
	ter[++ e] = x, nxt[e] = lnk[y], lnk[y] = e, w[e] = z2, rec[e] = e - 1 ;
