bool bfs() {
	rep(i, 1, n) dis[i] = inf ;
	int he = 0, ta = 1 ;
	opt[1] = s, dis[s] = 0 ;
	for ( ; he != ta ; ) {
		int u = opt[++ he] ;
		for (int i = lnk[u] ; i; i = nxt[i]) if (w[i] && dis[ter[i]] == inf) {
			dis[ter[i]] = dis[u] + 1 ;
			opt[++ ta] = ter[i] ;
		}
	}
	return dis[t] < inf ;
}
int dfs(int p, int sum) {
	int res = 0 ;
	if (p == t) return sum ;
	for (int i = cur[p] ; i; i = nxt[i]) if (w[i] && dis[ter[i]] == dis[p] + 1) {
		int tmp = dfs(ter[i], min(w[i], sum - res)) ;
		w[i] -= tmp, w[rec[i]] += tmp, res += tmp ;
		if (w[i]) cur[p] = i ;
		if (sum == res) return res ;
	}
	if (!res) dis[p] = - 1 ;
	return res ;
}
