struct ford_fulkerson {
    using Matrix = std::vector<std::vector<Flow>>;
    int n, t;
    std::vector<int> vis;
    std::vector<std::vector<Flow>> cap, flow;
    std::vector<std::vector<int>> g;
    const Flow INF;
    ford_fulkerson(int n)
        : n(n),
          cap(n, std::vector<Flow>(n)),
          flow(n, std::vector<Flow>(n)),
          g(n, std::vector<int>()),
          INF(std::numeric_limits<Flow>::max() / 8) {}
    ford_fulkerson(const Graph &graph) : ford_fulkerson(graph.size()) {
        for (int i = 0; i < n; ++i)
            for (auto &e : graph[i]) add_edge(e.src, e.dst, e.cap);
    }
    void add_edge(int u, int v, Flow c) {
        cap[u][v] += c;
        cap[v][u] += c;
        flow[v][u] += c;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    Flow solve(int s, int t) {
        this->t = t;
        Flow res = 0, aug = 1;
        while (aug > 0) {
            vis.assign(n, false);
            res += (aug = augment(s, INF));
        }
        return res;
    }
    Flow augment(const int &v, const Flow &lim) {
        vis[v] = true;
        if (v == t) return lim;
        for (const int &d : g[v]) {
            if (vis[d] || flow[v][d] == cap[v][d]) continue;
            Flow aug = augment(d, std::min(lim, cap[v][d] - flow[v][d]));
            flow[v][d] += aug;
            flow[d][v] -= aug;
            if (aug > 0) return aug;
        }
        return 0;
    }
};

signed main(){
	int h,w;
	cin>>h>>w;
	char c[100][100];
	int st,go;
	ford_fulkerson ff(h*w*2);
	int base=h*w;
	lp(i,h){
		lp(j,w){
			cin>>c[i][j];
			if(c[i][j]!='.'){
				ff.add_edge(i*w+j+base,(i*w+j),1);
			}
			if(c[i][j]=='S')st=i*w+h;
			if(c[i][j]=='T')go=i*w+j;
		}
	}
	lp(i,h){
		lp(j,w){
			lp(k,h){
				lp(l,w){
					if(c[i][j]!='.'&&c[k][l]!='.'){
						if(i==k||j==l){
							ff.add_edge(i*w+j+base,k*w+l,1000000);

							cout<<i<<j<<" "<<k<<l<<endl;
						}
					}
				}
			}
		}
	}
	int ans=ff.solve(st+base,go);
	if(ans>=1000000)cout<<-1<<endl;
	else cout<<ans<<endl;
	return 0;
}

