struct Edge {
	int u, v;
	int cap, flow;

	Edge(int u_, int v_, int flow_, int cap_) {
		u = u_;
		v = v_;
		cap = cap_;
		flow = flow_;
	}
};

const int INF = 1e9 + 239;	

namespace Flow {
	const int MAX_LOG = 40;

	int n;
	int start;
	int end;

	vector<int> d;
	vector<int> pnt;

	vector<Edge> ed;
	vector<vector<int>> g;

	int dfs(int u, int flow) {
		if (flow == 0) {
			return 0;
		}
		if (u == end) {
			return flow;
		}
		for (; pnt[u] < (int)g[u].size(); pnt[u]++) {
			int ind = g[u][pnt[u]];
			int to = ed[ind].v;
			if (d[to] < d[u] + 1) {
				continue;
			}
			int pushed = dfs(to, min(flow, ed[ind].cap - ed[ind].flow));
			if (pushed > 0) {
				ed[ind].flow += pushed;
				ed[ind ^ 1].flow -= pushed;
				return pushed;
			}
		}
		return 0;
	}

	bool bfs(int lim) {
		for (int i = 0; i < n; i++) {
			d[i] = INF;
		}
		d[start] = 0;
		queue<int> q;
		q.push(start);
		while (!q.empty()) {
			int u = q.front();
			q.pop();
			for (auto ind : g[u]) {
				int to = ed[ind].v;
				if (d[to] > d[u] + 1 && ed[ind].flow + lim <= ed[ind].cap) {
					d[to] = d[u] + 1;
					q.push(to);
				}
			}
		}
		return d[end] != INF;
	}

	void init() {
		pnt.resize(n, false);
		d.resize(n);
		g.resize(n);
	}

	int solve() {
		int ans = 0;
		int cur = (1LL << MAX_LOG);
		for (int i = 0; i < MAX_LOG; i++) {
			cur /= 2;
			while (bfs(cur)) {
				fill(pnt.begin(), pnt.end(), 0);
				while (true) {
					int nw = dfs(start, INF);
					ans += nw;
					if (nw == 0) {
						break;
					}
				}
			}
		}
		return ans;
	}

	void add_edge(int u, int v, int c) {
		int pnt = (int)ed.size();
		ed.push_back(Edge(u, v, 0, c));
		ed.push_back(Edge(v, u, 0, c));
		g[u].push_back(pnt);
		g[v].push_back(pnt + 1);
	}
} // namespace Flow

