template<class T>
class network{
	struct edge{
		int to,rev;
		T capa,flow;
		edge(int to,int rev,const T& capa,const T& flow):to(to),rev(rev),capa(capa),flow(flow){}
	};

	int s,t;
	vector<vector<edge>> G;

public:
	network(int n,int s,int t):s(s),t(t){
		G.resize(n);
	}

	void add_directed_edge(int u,int v,const T& capa){
		G[u].emplace_back(v,G[v].size()  ,capa,0);
		G[v].emplace_back(u,G[u].size()-1,   0,0);
	}

	T maximum_flow(){
		int n=G.size();
		vector<int> pre(n);
		vector<bool> vis(n);

		auto augment=[&](){
			rep(u,n) vis[u]=(u==s);

			queue<pair<int,T>> Q; Q.emplace(s,0);
			for(const edge& e:G[s]){
				Q.front().second=max(Q.front().second,e.capa-e.flow);
			}

			T res=0;
			while(!Q.empty()){
				int u;
				T water; tie(u,water)=Q.front(); Q.pop();

				if(u==t){ res=water; break; }

				for(const edge& e:G[u]) if(!vis[e.to] && e.capa-e.flow>0) {
					vis[e.to]=true;
					pre[e.to]=e.rev;
					Q.emplace(e.to,min(water,e.capa-e.flow));
				}
			}

			if(res>0){
				for(int u=t;u!=s;){
					edge& e1=G[u][pre[u]];
					edge& e2=G[e1.to][e1.rev];
					e1.flow-=res;
					e2.flow+=res;
					u=e1.to;
				}
			}

			return res;
		};

		T res=0;
		for(T water=1;water>0;res+=water) water=augment();
		return res;
	}
};

