	NEXT[tote]=FIR[v];
	CAP[tote]=0;
	FIR[v]=tote;
}

int q[maxn],dis[maxn],_FIR[maxn];

bool build()
{
	memset(dis,0,sizeof(dis));
	int H=0,T=1;
	q[1]=SS; dis[SS]=1;
	while (H-T)
	{
		int u=q[++H];
		for (int p=FIR[u];p;p=NEXT[p]) if (CAP[p])
		{
			int v=TO[p];
			if (!dis[v])
			{
				dis[v]=dis[u]+1;
				q[++T]=v;
			}
		}
	}
	return dis[TT];
}

int dfs(int u,int lim)
{
	if (u==TT||!lim) return lim;
	int res=lim,use=0;
	for (int &p=_FIR[u];p;p=NEXT[p])
	{
		int v=TO[p],w=CAP[p];
		if (dis[u]+1!=dis[v]) continue;
		int flow=dfs(v,min(res,w));
		res-=flow;
		use+=flow;
		CAP[p]-=flow;
		CAP[p^1]+=flow;
		if (!res) break;
	}
	return use;
}

