{
    for (int i = 1; i <= T; ++i)
    {
        dist[i] = oo;
    }
    q.push(S);
    dist[S] = 0;
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for (auto &v : g[u])
        {
            if (dist[v] == oo && f[u][v] < c[u][v])
            {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return (dist[T] < oo);
}

int FindPath(int u, int val)
{
    if (u == T)
    {
        return val;
    }
    if (cl[u] == id)
    {
        return 0;
    }
    cl[u] = id;
    for (auto &v : g[u])
    {
        if (cl[v] != id && dist[v] == dist[u] + 1)
        {
            if (c[u][v] > f[u][v])
            {
                if (int delta = FindPath(v, min(val, c[u][v] - f[u][v])))
                {
                    f[u][v] += delta;
                    f[v][u] -= delta;
                    return delta;
                }
            }
        }
    }
    return 0;
}

int MaxFlow()
{
    id = 0;
    int mf = 0;
    while (BFS())
    {
        int delta = 1;
        do
        {
            ++id;
            delta = FindPath(S, oo);
            mf += delta;
        } while (delta > 0);
    }
    return mf;
}

