bool avail()
{
    for (int i = 1; i <= 241; i++) {
        pre[i] = -1;
    }

    pre[s] = s;
    queue<int> q;
    q.push(s);
    while(!q.empty())
    {
        int u = q.front(); q.pop();
        for (int i = 0; i < ed[u].size(); i++)
        {
            int v = ed[u][i];
            if (pre[v] == -1 && f[u][v] < c[u][v])
            {
                pre[v] = u;
                q.push(v);
            }
        }
    }
    return (pre[t] != -1);
}

void increase()
{
    int pos = t, mn = INF;
    while(pos != s)
    {
        mn = min(mn, c[pre[pos]][pos] - f[pre[pos]][pos]);
        pos = pre[pos];
    }

    pos = t; ans += mn;
    while (pos != s)
    {
        f[pre[pos]][pos] += mn;
        f[pos][pre[pos]] -= mn;
        pos = pre[pos];
    }
}

