struct maxflow{
    int m;
    int st,en;
    int v[M][2],flow[M][2],cap[M];

    int f[M],tr[M];
    vector <int> e[M];
    maxflow(){
        m=st=en=0;
    }
    void add_edge(int x,int y,int _cap){
//        cout<<x<<"->"<<y<<'\n';
        ++m;
        v[m][0]=x;v[m][1]=y;
        e[x].push_back(m);
        e[y].push_back(m);
        cap[m]=_cap;
        flow[m][1]=_cap;
        flow[m][0]=0;
    }

    int q[N];
    bool BFS(int st){

        memset(tr,0,sizeof(tr));
        int top=1,bot=1;
        q[1]=st;
        while (top<=bot){
            int x=q[top++];

            if (x==en) return 1;
            for(auto i:e[x]){
                int dir=(x==v[i][1]);
                int y=v[i][dir^1];
                if (flow[i][dir]==cap[i]||tr[y]) continue;
                tr[y]=i;
                f[y]=min(f[x],cap[i]-flow[i][dir]);
                q[++bot]=y;
            }
        }
        return 0;
    }
    void inc_flow(){
        int cur=en;
        int ans=f[en];
        while (cur!=st){
            int use=tr[cur];
            int dir=(cur==v[use][0]);
            flow[use][dir]+=ans;
            flow[use][dir^1]-=ans;
            cur=v[use][dir];
        }
    }
    int answer(){
        int ans=0;
        f[st]=inf;
        while (BFS(st)){
            ans+=f[en];
            inc_flow();
        }
        return ans;
    }
}mflow;

