const int inf = 123456789;
struct edge { int to, cap, rev; };
int H, W; string s[109]; bool vis[209]; vector<edge> g[209];
void add_edge(int  v1, int v2, int cost) {
	g[v1].push_back(edge{ v2, cost, (int)g[v2].size() });
	g[v2].push_back(edge{ v1, cost, (int)g[v1].size() - 1 });
}
int find_increase(int pos, int target, int cur_cap) {
	if (pos == target) return cur_cap;
	vis[pos] = true;
	for (edge &e : g[pos]) {
		if (!vis[e.to] && e.cap > 0) {
			int res = find_increase(e.to, target, min(cur_cap, e.cap));
			if (res > 0) {
				e.cap -= res;
				g[e.to][e.rev].cap += res;
				return res;
			}
		}
	}
	return 0;
}
int max_flow(int src, int dst) {
	int ret = 0;
	while (true) {
		fill(vis, vis + H + W + 2, false);
		int res = find_increase(src, dst, inf);
		ret += res;
		if (res == 0) break;
	}
	return ret;
}
int main() {
	cin >> H >> W;
	for (int i = 0; i < H; i++) cin >> s[i];
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (s[i][j] != '.') {
				add_edge(i, j + H, s[i][j] == 'o' ? 1 : inf);
				if (s[i][j] == 'S') {
					add_edge(H + W, i, inf);
					add_edge(H + W, j + H, inf);
				}
				if (s[i][j] == 'T') {
					add_edge(H + W + 1, i, inf);
					add_edge(H + W + 1, j + H, inf);
				}
			}
		}
	}
	int ret = max_flow(H + W, H + W + 1);
	cout << (ret >= inf ? -1 : ret) << endl;
	return 0;
}

