#include<bits/stdc++.h>
using namespace std;
const int N=1e5+10;
const int inf=1e9;

int to[N],ww[N],nxt[N],h[N],tt=1,n,m,s,t,x[N],y[N],cnt=0,dep[N],cur[N];
char ch[110];

void adde(int u,int v,int w) {
	to[++tt]=v,ww[tt]=w,nxt[tt]=h[u],h[u]=tt;
	to[++tt]=u,nxt[tt]=h[v],h[v]=tt;
}

bool bfs() {
	memset(dep,0,4*(cnt+1));
	queue<int> q;q.push(s);dep[s]=1;
	while(!q.empty()) {
		int u=q.front();q.pop();
		for(int i=h[u],v;v=to[i],i;i=nxt[i])
			if(!dep[v]&&ww[i]) {
				dep[v]=dep[u]+1,q.push(v);
				if(v==t) return 1;
			}
	}
	return 0;
}

int dfs(int u,int flow) {
	if(u==t) return flow;
	int ret=0;
	for(int &i=cur[u],v;v=to[i],i;i=nxt[i])
		if(dep[v]==dep[u]+1&&ww[i]) {
			int d=dfs(v,min(flow,ww[i]));
			ww[i]-=d,ww[i^1]+=d,ret+=d,flow-=d;
			if(!flow) return ret;
		}
	dep[u]=0;return ret;
}

int dinic() {
	int ret=0;
	while(bfs()) {
		memcpy(cur,h,4*(cnt+1));
		ret+=dfs(s,inf);
	}
	return ret;
}

int main() {
	cin>>n>>m;
	for(int i=1;i<=n;i++) {
		scanf("%s",ch+1);
		for(int j=1;j<=m;j++)
			if(ch[j]!='.') {
				x[++cnt]=i,y[cnt]=j;
				if(ch[j]=='S') s=cnt;
				else if(ch[j]=='T') t=cnt;
			}
	}
	if(x[s]==x[t]||y[s]==y[t]) return cout<<-1,0;
	for(int i=1;i<=cnt;i++) {
		adde(i,i+cnt,(i==s||i==t)?inf:1);
		for(int j=i+1;j<=cnt;j++)
			if(x[i]==x[j]||y[i]==y[j]) adde(i+cnt,j,inf),adde(j+cnt,i,inf);
	}
	t+=cnt;cnt<<=1;
	cout<<dinic();
	return 0;
}

