int dfs(int now, int goal, int flow){
    if(now == goal) return flow;
    used[now] = true;
    for(auto &e: es[now]){
        if(used[e.to] || e.cap == 0) continue;
        int d = dfs(e.to, goal, min(flow, e.cap));
        if(d > 0){
            e.cap -= d;
            es[e.to][e.rev].cap += d;
            return d;
        }
    }
    return 0;
}

