static int left(int nod) {
	return nod; }

static int right(int nod) {
	return nod + n; }

static bool bfs(int src, int snk) {
	static int ptr = 0; ++ptr;
	static deque<int> dq;
	int u;

	dq.push_back(src);
	f[src] = ptr;

	while (!dq.empty()) {
		u = dq.front(); dq.pop_front();

		for (auto v: g[u]) if (f[v] != ptr && cap[u][v] - flw[u][v] > 0) {
			dq.push_back(v);
			far[v] = u;
			f[v] = ptr; } }

	return (f[snk] == ptr); }

static int pump_flow(int src, int snk) {
	int nod, ant, augment;

	ant = 0;
	while (bfs(src, snk)) {
		nod = snk;
		augment = 2e9;
		while (nod != src) {
			augment = min(augment, cap[far[nod]][nod] - flw[far[nod]][nod]);
			nod = far[nod]; }

		nod = snk;
		while (nod != src) {
			flw[far[nod]][nod]+= augment;
			flw[nod][far[nod]]-= augment;
			nod = far[nod]; }

		ant+= augment; }

	return ant; }

