template<class type=int> class flow_graph
{
	public:
		int n,S,T;
	private:
		int *h,*vh;
		struct node
		{
			int way;
			type cap;
			node *next,*rev;
		};
		node** v;
		type max_flow(int x,type flow)
		{
			if (x==T) return flow;
			type now=flow;
			int minh=n-1;
			for (node *it=v[x];it;it=it->next)
				if (it->cap>0)
				{
					if (h[it->way]+1==h[x])
					{
						type tmp=max_flow(it->way,min(now,it->cap));
						now-=tmp;
						it->cap-=tmp;
						it->rev->cap+=tmp;
						if (h[S]>=n) return flow-now;
						if (!now) break;
					}
					minh=min(minh,h[it->way]);
				}
			if (flow==now)
			{
				if (!--vh[h[x]]) h[S]=n;
				++vh[h[x]=minh+1];
			}
			return flow-now;
		}
	public:
		flow_graph (int _n,int _S,int _T)
		{
			n=_n;
			S=_S;
			T=_T;
			h=new int[n+1]();
			vh=new int[n+1]();
			v=new node*[n+1]();
		}
		void addedge(int x,int y,type c)
		{
			//printf("%d %d %d\n", x, y, c);
			node *p=new node;
			node *q=new node;
			*p=(node){y,c,v[x],q};
			*q=(node){x,0,v[y],p};
			v[x]=p;
			v[y]=q;
		}
		type solve()
		{
			type ans=0;
			for (vh[0]=n;h[S]<n;ans+=max_flow(S,INF));
			return ans;
		}
};

