int find(int u,int maxf)
{
	if (u==T) return maxf;
	int ans=0;
	for (int q=last[u];q>-1;q=pre[q])
	{
		int v=other[q];
		if (l[v]==l[u]+1)
		{
			int t=find(v,min(maxf-ans,flow[q]));
			ans+=t;
			flow[q]-=t;
			flow[q^1]+=t;
			if (ans==maxf) return ans;
		}
	}
	if (ans<maxf) l[u]=-1;
	return ans;
