  const int N = 1000;
  int n, cap[N][N];   // INPUT
  int flow[N][N];     // OUTPUT

  int edmonds(int s, int t) {
      int b,e,q[n],p[n],d,FLOW=0;
      REP(i,n) REP(j,n) flow[i][j]=0;
      for(;;) {
          REP(i,n) p[i]=-1;
          for(q[b=e=0]=s;b<=e;b++)
              REP(v,n)
                  if (flow[q[b]][v] < cap[q[b]][v] && p[v]<0)
                      p[q[++e]=v] = q[b];
          if (p[t]<0) break;
          d = cap[p[t]][t] - flow[p[t]][t];
          for(int i=t;i!=s;i=p[i]) d=min(d,cap[p[i]][i]-flow[p[i]][i]);
          for(int i=t;i!=s;i=p[i]) {
              flow[p[i]][i] += d;
              flow[i][p[i]] -= d;
          }
          FLOW += d;
      }
      return FLOW;
  }
}

