#define oo 100000000
#define maxn 105

using namespace std;
typedef long long ll;

struct edge{
    int u, v, cap, flow;
    edge(int _u = 0, int _v = 0, int _cap = 0, int _flow = 0) : u(_u), v(_v), cap(_cap), flow(_flow) {};
};

vector < edge > e;
vector < int > g[maxn * maxn * 2];

int n, m;
int a[maxn][maxn];
int cur[maxn * maxn * 2];
int d[maxn * maxn * 2];
int cnt = 0;
int st, en;

void addEdge(int u, int v) {
    g[u].push_back(e.size());
    e.push_back(edge(u, v, 1, 0));

    g[v].push_back(e.size());
    e.push_back(edge(v, u, 1, 0));
}

int bfs() {
    fill(d, d + cnt + 1, oo);

    d[st] = 0;
    queue < int > q;
    q.push(st);

    while (!q.empty() && d[en] == oo) {
        int u = q.front(); q.pop();

        for (auto i : g[u]) {
            int v = e[i].v;

            if (e[i].cap == e[i].flow) continue;

            if (d[v] == oo) {
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }

    return d[en] != oo;
}

int dfs(int u, int flow) {

    if (u == en || !flow) return flow;

    for (; cur[u] < g[u].size(); ++cur[u]) {
        int i = g[u][cur[u]], v = e[i].v;

        if (e[i].cap == e[i].flow || d[v] != d[u] + 1) continue;

        int newFlow = dfs(v, min(flow, e[i].cap - e[i].flow));

        if (newFlow) {
            e[i].flow += newFlow;
            e[i ^ 1].flow -= newFlow;
            return newFlow;
        }
    }

    return 0;
}

int maxFlow() {
  int cnt = 0;
  while (bfs()) {
    fill(cur, cur + cnt + 1, 0);

    while (dfs(st, 1))
      cnt++;
  }

  return cnt;
}

int main(){
  ios_base::sync_with_stdio(0);

  cin >> n >> m;

  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
      char ch;
      cin >> ch;

      if (ch != '.') {
        cnt += 2;
        a[i][j] = cnt;
        if (ch == 'o') addEdge(a[i][j] - 1, a[i][j]);
      }

      if (ch == 'S')
        st = cnt;

      if (ch == 'T')
        en = cnt - 1;
    }

  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      for (int k = j + 1; k < m; ++k)
        if (a[i][j] && a[i][k])
          addEdge(a[i][j], a[i][k] - 1);

  for (int j = 0; j < m; ++j)
    for (int i = 0; i < n; ++i)
      for (int k = i + 1; k < n; ++k)
        if (a[i][j] && a[k][j])
          addEdge(a[i][j], a[k][j] - 1);

  for (auto i : g[st])
    if (e[i].v == en) {
      cout << -1;
      return 0;
    }

  cout << maxFlow();

  return 0;

}

