ll d[siz];

bool findAns() {
	queue<ll> nxt;
	nxt.push(s);
	for (ll i = 1; i <= t; i++) {
		d[i] = 0;
	}
	d[s] = MAXX;
	while (!nxt.empty()) {
		ll u = nxt.front();
		nxt.pop();
		if (u == t) {	
			return true;
		}
		for (ll i = 0; i < (int)graph[u].size(); i++) {
			ll v = graph[u][i];
			if (d[v] == 0 && cap[u][v] > flow[u][v]) {
				d[v] = u;
				nxt.push(v);
			}
		}
	}
	return false;
}

void rev() {
	ll u, del = MAXX;
	for (ll i = t; (u = d[i]) != MAXX; i = u) {
		del = min(del, cap[u][i] - flow[u][i]);
	}
	for (ll i = t; i != s; i = u) {
		u = d[i];
		flow[u][i] += del;
		flow[i][u] -= del;
	}
}

ll getAns() {
	ll ans = 0;
	for (ll i = 0; i < (int)graph[s].size(); i++) {
		ll v = graph[s][i];
		ans += flow[s][v];
	}
	return ans;
}

