bool bfs()
{
    for (int i=0;i<=n+m+1;i++) d[i]=0;
    d[0]=1;
    queue<int> q;
    q.push(0);
    while (!q.empty())
    {
        int u=q.front(); q.pop();
        if (u==n+m+1) return true;
        for (int i=0;i<g[u].size();i++)
        {
