            q.push(v);
        }
    }
    return false;
}
int dfs(int u, int Min)
{
    if (u==n+m+1) return Min;
    if (vis[u]!=t) vis[u]=t; else return 0;
    for (int i=0;i<g[u].size();i++)
    {
        int v=g[u][i];
        if (f[u][v]<c[u][v] && vis[v]!=t && d[v]==d[u]+1)
        {
            if (int x=dfs(v,min(Min,c[u][v]-f[u][v])))
            {
                f[u][v]+=x;
                f[v][u]-=x;
                return x;
            }
        }
    }
    return 0;
}
