#include<bits/stdc++.h>
using namespace std;

#define INF 1000000000

struct edge
{
    int to,cup,rev;
};

int H,W;
vector<edge> G[210];
int S = 200,T = 201;
bool used[210];

void add_edge(int from,int to,int cap)
{
    G[from].push_back((edge){to, cap, G[to].size()});
    G[to].push_back((edge){from, 0, G[from].size() - 1});
}

int DFS(int v,int t,int f)
{
    if(v == t)return f;
    used[v] = 1;
    for(int i = 0; i < G[v].size(); i++)
    {
        edge &e = G[v][i];
        if(!used[e.to] && e.cup > 0)
        {
            int d = DFS(e.to,t,min(f,e.cup));
            if(d > 0)
            {
                e.cup -= d;
                G[e.to][e.rev].cup += d;
                return d;
            }
        }
    }
    return 0;
}

int main()
{
    scanf("%d%d",&H,&W);
    for(int i = 0; i < H; i++)
    {
        for(int j = 0; j < W; j++)
        {
            char c;
            scanf(" %c",&c);
            if(c == '.')continue;
            if(c == 'S')
            {
                add_edge(S,i,INF);
                add_edge(S,100 + j,INF);
            }
            if(c == 'T')
            {
                add_edge(i,T,INF);
                add_edge(100 + j,T,INF);
            }
            add_edge(i,100 + j,1);
            add_edge(100 + j,i,1);
        }
    }
    int ans = 0;
    while(1)
    {
        memset(used,0,sizeof(used));
        int f = DFS(S,T,INF);
        if(f == 0)break;
        ans += f;
    }

    if(ans >= INF)printf("-1\n");
    else printf("%d\n",ans);
    return 0;
}

