using namespace std;
template<typename T>
class fixed_point : T {
  public:
    explicit constexpr fixed_point (
        T&& t
      ) noexcept
      : T(forward<T>(t))
      {
      }
    template<typename... Args>
    constexpr decltype(auto)
    operator()(
        Args&&... args
      ) const
      {
        return T::operator()(*this, forward<Args>(args)...);
      }
};
template<typename T>
static inline constexpr decltype(auto) fix (T&& t) noexcept {
  return fixed_point<T>{forward<T>(t)};
}
template <typename T>
class ford_fulkerson {
  public:
    const T inf = numeric_limits<T>::max();
  private:
    struct edge {
      int to; T cap;
      weak_ptr<edge> rev;
      edge(int to, T cap) : to(to), cap(cap) {}
    };
    const int n, source, sink;
    vector<bool> ckd;
    vector<vector<shared_ptr<edge>>> grh;
    T dfs () {
      return fix ([&](auto dfs, int crr, int f) -> T {
        if (crr == sink) return f;
        ckd[crr] = true;
        for (auto& e : grh[crr]) {
          if (ckd[e->to] || !e->cap) continue;
          T d = dfs(e->to, min(f, e->cap));
          if (d) {
            e->cap -= d;
            e->rev.lock()->cap += d;
            return d;
          }
        }
        return 0;
      })(source, inf);
    }
  public:
    ford_fulkerson (int n, int source, int sink) :
      n(n), source(source), sink(sink), grh(n)
      {}
    void insert(int u, int v, T c) {
      auto e = make_shared<edge>(v, c);
      auto r = make_shared<edge>(u, 0);
      e->rev = r;
      r->rev = e;
      grh[u].push_back(e);
      grh[v].push_back(r);
    }
    T cal() {
      T ret = 0;
      while (true) {
        ckd.assign(n, false);
        T f = dfs();
        if (f == inf) return -1;
        if (!f) return ret;
        ret += f;
      }
    }
};
int main() {
  cin.tie(0); cin.sync_with_stdio(false);
  int h, w;
  cin >> h >> w;
  vector<vector<int>> grh(1 + h + w + 1);
  int source = 0, sink = 1 + h + w;
  ford_fulkerson<int> ffk(sink + 1, source, sink);
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      char c;
      cin >> c;
      if (c == 'o') {
        ffk.insert(1 + i,     1 + h + j, 1);
        ffk.insert(1 + h + j, 1 + i,     1);
      }
      if (c == 'S') {
        ffk.insert(source, 1 + i,     ffk.inf);
        ffk.insert(source, 1 + h + j, ffk.inf);
      }
      if (c == 'T') {
        ffk.insert(1 + i,     sink, ffk.inf);
        ffk.insert(1 + h + j, sink, ffk.inf);
      }
    }
  }
  auto ret = ffk.cal();
  cout << ret << endl;
  return 0;
}

