            else if (tmp[j] == 'S') AddEdge(s, i, maxC), AddEdge(s, j + h, maxC);
            else if (tmp[j] == 'T') AddEdge(i, t, maxC), AddEdge(j + h, t, maxC);
    }
}

inline bool FindAumentingPath()
{
    memset(trace, -1, sizeof trace);
    queue<int> q({s});
    trace[s] = -2;
    while (!q.empty())
    {
        int u = q.front(), v; q.pop();
        for (int i : adj[u])
        {
            if (e[i].cf == 0 || trace[v = e[i].v] != -1) continue;
            trace[v] = i;
            if (v == t) return 1;
            q.push(v);
        }
    }
    return 0;
}

inline void AugmentFlow()
{
    int del = maxC, i;
    for (int u = t; (i = trace[u]) != -2; u = e[i].u) del = min(del, e[i].cf);
    for (int u = t; (i = trace[u]) != -2; u = e[i].u)
        e[i].cf -= del, e[i ^ 1].cf += del;
    flowVal += del;
}

void Solve()
{
    flowVal = 0;
    while (FindAumentingPath()) AugmentFlow();
    cout << (flowVal >= maxC ? -1 : flowVal);
}

