#include <bits/stdc++.h>

using namespace std;

const int inf = 1e9;

struct Dinic {
   int n, s, t;
   struct Edge {
      int to, cap, flow, rev;
      Edge(int to = 0, int cap = 0, int flow = 0, int rev = 0) :
         to(to), cap(cap), flow(flow), rev(rev) {}
   };
   vector<int> d;
   vector<int> ptr;
   vector<vector<Edge>> g;
   Dinic(int n = 0, int s = 0, int t = 0) :
      n(n), s(s), t(t), d(n), ptr(n), g(n) {}
   void addEdge(int u, int v, int cap) {
      g[u].emplace_back(v, cap, 0, g[v].size());
      g[v].emplace_back(u, 0, 0, g[u].size() - 1);
   }
   bool bfs() {
      fill(d.begin(), d.end(), -1);
      fill(ptr.begin(), ptr.end(), 0);
      queue<int> q;
      d[s] = 0;
      q.push(s);
      while (!q.empty()) {
         int u = q.front();
         q.pop();
         for (auto e : g[u]) {
            if (d[e.to] == -1 && e.cap > e.flow) {
               d[e.to] = d[u] + 1;
               q.push(e.to);
            }
         }
      }
      return d[t] != -1;
   }
   int dfs(int u, int flow) {
      if (u == t) {
         return flow;
      }
      for (int &i = ptr[u]; i < g[u].size(); ++i) {
         auto &e = g[u][i];
         if (e.cap <= e.flow || d[e.to] != d[u] + 1) continue;
         int nxt = dfs(e.to, min(flow, e.cap - e.flow));
         if (nxt) {
            e.flow += nxt;
            g[e.to][e.rev].flow -= nxt;
            return nxt;
         }
      }
      return 0;
   }
   int maxFlow() {
      int ans = 0;
      while (bfs()) {
         while (true) {
            int now = dfs(s, inf);
            if (now) ans += now;
            else break;
         }
      }
      return ans;
   }
   vector<int> path;
   void trace(int v) {
      path.emplace_back(v);
      for (auto &e : g[v]) {
         if (e.flow > 0) {
            e.flow--;
            return trace(e.to);
         }
      }
   }
   vector<int> getPath() {
      path.clear();
      trace(s);
      return path;
   }
};

int main() {
   ios_base::sync_with_stdio(false);
   int N, M; cin >> N >> M;
   vector<string> A(N);
   Dinic dn(N + M + 2, N + M, N + M + 1);
   for (int i = 0; i < N; ++i) {
      cin >> A[i];
      for (int j = 0; j < M; ++j) {
         if (A[i][j] == 'S') {
            dn.addEdge(N + M, i, inf);
            dn.addEdge(N + M, j + N, inf);
         } else if (A[i][j] == 'T') {
            dn.addEdge(i, N + M + 1, inf);
            dn.addEdge(j + N, N + M + 1, inf);
         } else if (A[i][j] == 'o') {
            dn.addEdge(i, j + N, 1);
            dn.addEdge(j + N, i, 1);
         }
      }
   }
   int ans = dn.maxFlow();
   if (ans >= inf) ans = -1;
   cout << ans << "\n";
   return 0;
}

