// 最小カット=最大フローが答え

int main() {
	int H, W; cin >> H >> W;
	mf_graph<int> g(H + W + 2); // s=H+W,t=H+W+1
	int si, sj, ti, tj;
	rep(i, H) {
		string a; cin >> a;
		rep(j, W) {
			if (a[j] == 'S') {
				si = i; sj = j;
