				ti = i; tj = j;
			}
			if (a[j] != '.') {
				g.add_edge(i, H + j, 1);
				g.add_edge(H + j, i, 1);
			}

		}
	}
	g.add_edge(H + W, si, H + W);
	g.add_edge(H + W, sj, H + W);
	g.add_edge(H + ti, H + W + 1, H + W);
	g.add_edge(H + tj, H + W + 1, H + W);
	if (si == ti or sj == tj) cout << -1 << endl;
	else cout << g.flow(H + W, H + W + 1) << endl;
