                ok[i][j] = true;
            }
            if (c[i][j] == 'o') ok[i][j] = true;
        }
    }
    assert(s != -1 && t != -1);
    if (s % w == t % w || ((s - 1) / w == (t - 1) / w)) {
        cout << -1;
        return 0;
    }
    DinitzFlow ds(2 * h * w + 3, s + h * w, t);
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            if (!ok[i][j]) continue;
            if (c[i][j] != 'S' && c[i][j] != 'T') {
                ds.addEdge((i - 1) * w + j, (i - 1) * w + j + h * w, 1);
