                int q = (k - 1) * w + j;
                if (c[i][j] == 'T') continue;
                if (c[k][j] == 'S') continue;
                ds.addEdge(p + h * w, q, 1);
            }
        }
    }
    cout << ds.flow() << '\n';
    return 0;
}

