};

struct maxflow
{
	int n, s, t;
	vector<int> pt, Q, D;
	vector<edge*> E;
	vector< vector<edge> > g;
	maxflow() { }

	maxflow(int n)
	{
		s = 0, t = n - 1;
		g.resize(n);
		pt.resize(n);
		Q.resize(n);
		D.resize(n);
	}

	void add_edge(int u, int v, int cap)
	{
		g[u].push_back(edge(u, v, cap, 0, size(E)));
		g[v].push_back(edge(v, u, 0, 0, size(E) + 1));
		E.push_back(&g[u][size(g[u]) - 1]);
		E.push_back(&g[v][size(g[v]) - 1]);
	}

	bool bfs()
	{
		int qh = 0, qt = 0;
		Q[qt++] = s;
		fill(D.begin(), D.end(), -1);
		D[0] = 0;

		for (; qh < qt && D[t] == -1; )
		{
			int v = Q[qh++];

			for (auto to : g[v])
				if (D[to.v] == -1 && to.flow < to.cap)
					D[to.v] = D[v] + 1, Q[qt++] = to.v;
		}

		return D[t] != -1;
	}

	llong dfs(int v, int mrg)
	{
		if (mrg == 0) return 0;
		if (v == t) return mrg;

		for (; pt[v] < size(g[v]); ++pt[v])
		{
			edge& to = g[v][pt[v]];

			if (D[to.v] == D[v] + 1)
			{
				llong pushed = dfs(to.v, min(mrg, to.cap - to.flow));
				to.flow += pushed;
				E[to.i ^ 1]->flow -= pushed;
				if (pushed) return pushed;
			}
		}

		return 0;
	}

	llong dinic()
	{
		llong flow = 0, pushed = 0;

		for (;;)
		{
			if (!bfs())
				break;

			fill(pt.begin(), pt.end(), 0);

			while (pushed = dfs(s, inf))
				flow += pushed;
		}

		return flow;
	}
};

