    rep(i,h){
        rep(j,w){
            if(g[i][j]=='S'){
                sx=i,sy=j;
                add_edge(0,i+1,inf);
                add_edge(0,h+j+1,inf);
            }
            if(g[i][j]=='T'){
                tx=i,ty=j;
                add_edge(i+1,h+w+1,inf);
                add_edge(j+h+1,h+w+1,inf);
            }
            if(g[i][j]=='o'){
                add_edge(i+1,h+j+1,1);
                add_edge(h+j+1,i+1,1);
            }
        }
    }
    if(sx==tx||sy==ty){
        cout<<-1<<endl;
        return 0;
    }
    ll ans=max_flow(s,t);
    cout<<ans<<endl;
}

#include <bits/stdc++.h>
using namespace std;

const int maxn = 20010;
int n, m, cnt, st, ed, lev[maxn], head[maxn];
char mp[110][110];
struct edge { int to, cap, nxt; } e[5000010];

int id(int x, int y, int z) {
    return z * n * m + (x - 1) * m + y;
}

void add(int from, int to, int cap) {
    e[cnt] = (edge){to, cap, head[from]}, head[from] = cnt++;
    e[cnt] = (edge){from, 0, head[to]}, head[to] = cnt++;
}

int bfs(int s, int t) {
    memset(lev, 0, sizeof(lev));
    queue<int> q; q.push(s), lev[s] = 1;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int i = head[v]; ~i; i = e[i].nxt) {
            if (e[i].cap && !lev[e[i].to]) {
                q.push(e[i].to), lev[e[i].to] = lev[v] + 1;
            }
        }
    }
    return lev[t];
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    int add = 0;
    for (int i = head[v]; ~i && add < f; i = e[i].nxt) {
        if (e[i].cap && lev[e[i].to] == lev[v] + 1) {
            int d = dfs(e[i].to, t, min(e[i].cap, f - add));
            if (d) e[i].cap -= d, e[i ^ 1].cap += d, add += d;
            else lev[e[i].to] = -1;
        }
    }
    return add;
}

int dinic(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) flow += dfs(s, t, INT_MAX);
    return flow;
}

int main() {
    memset(head, -1, sizeof(head));
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= n; i++) {
        scanf("%s", mp[i] + 1);
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (mp[i][j] == '.') continue;
            if (mp[i][j] == 'S') st = id(i, j, 0);
            else if (mp[i][j] == 'T') ed = id(i, j, 1);
            add(id(i, j, 0), id(i, j, 1), mp[i][j] == 'o' ? 1 : INT_MAX);
            for (int k = 1; k <= n; k++) if (i ^ k) {
                if (mp[k][j] ^ '.') add(id(i, j, 1), id(k, j, 0), INT_MAX);
            }
            for (int k = 1; k <= m; k++) if (j ^ k) {
                if (mp[i][k] ^ '.') add(id(i, j, 1), id(i, k, 0), INT_MAX);
            }
        }
    }
    int ans = dinic(st, ed);
    printf("%d\n", ans > 1e9 ? -1 : ans);
    return 0;
}

