		for (int j = 1; j <= m; j++)
			if (mp[i][j] == 'S') {
				AddEdge(S, r[i], INF);
				AddEdge(S, c[j], INF);
			} else if (mp[i][j] == 'T') {
				AddEdge(r[i], T, INF);
				AddEdge(c[j], T, INF);
			} else if (mp[i][j] == 'o') {
				AddEdge(r[i], in[i][j], INF);
				AddEdge(c[j], in[i][j], INF);
				AddEdge(in[i][j], out[i][j], 1);
				AddEdge(out[i][j], r[i], INF);
				AddEdge(out[i][j], c[j], INF);
			}
	ans = MaxFlow(S, T);
	if (ans > n * m) ans = -1;
	cout << ans << endl;
	return 0;
}

