class Network{
	private:
	int V;
	struct edge{
		int to,cap,rev;
	};
	vector<vector<edge> > List;
	int DFSplus(int v,int t,int f,vi& iter,vi level){
		if(v==t) return f;
		for(int &i=iter[v];i<List[v].size();i++){
			edge &e=List[v][i];
			if(e.cap>0&&level[v]<level[e.to]){
				int d=DFSplus(e.to,t,min(f,e.cap),iter,level);
				if(d>0){
					e.cap-=d;
					List[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}
	void BFSplus(int s,vi& level){
		level=vi(V,-1);
		queue<int> que;
		level[s]=0;
		que.push(s);
		while(!que.empty()){
			int v=que.front();
			que.pop();
			for(int i=0;i<List[v].size();i++){
				edge &e=List[v][i];
				if(e.cap>0&&level[e.to]<0){
					level[e.to]=level[v]+1;
					que.push(e.to);
				}
			}
		}
	}
	public:
	Network(int v){
		V=v;
		List=vector<vector<edge> >(v);
	}
	void add_edge(int s,int t,int c){
		List[s].push_back(edge{t,c,(int)List[t].size()});
		List[t].push_back(edge{s,0,(int)List[s].size()-1});
	}
	int MFplus(int s,int t){
		int ans=0;
		while(1){
			vi iter(V),level;
			BFSplus(s,level);
			if(level[t]<0) return ans;
			int f;
			while((f=DFSplus(s,t,inf,iter,level))>0) ans+=f;
		}
	}
};

