char g[N];
int n, m;
int level[N], q[N], head, tail;

struct Edge {
	int v, w, nxt;
}e[M];
int first[N], used[N], eCnt;

inline void AddEdge(int u, int v, int w) {
	e[++eCnt].v = v;
	e[eCnt].w = w;
	e[eCnt].nxt = first[u];
	first[u] = eCnt;
}

inline void Add(int u, int v, int w) {
	AddEdge(u, v, w);
	AddEdge(v, u, 0);
}

bool Layer() {
	for (int i=1;i<=T;++i) {
		level[i] = -1;
		used[i] = first[i];
	}
	level[S] = 0;
	q[head=tail=1] = S;
	while (head <= tail) {
		int u = q[head++];
		if (u == T) return 1;
		for (int i=first[u];i;i=e[i].nxt) {
			int v = e[i].v;
			if (e[i].w > 0 && level[v] == -1) {
				level[v] = level[u] + 1;
				q[++tail] = v;
			}
		}
	}
	return 0;
}

int DFS(int u, int flow) {
	if (u == T) return flow;
	int ret = 0;
	for (int i=used[u];i;i=e[i].nxt, used[u]=i) {
		int v = e[i].v;
		if (e[i].w > 0 && level[v] == level[u] + 1) {
			int tmp = DFS(v, min(flow, e[i].w));
			e[i].w -= tmp;
			e[i^1].w += tmp;
			flow -= tmp;
			ret += tmp;
			if (!flow) break;
		}
	}
	return ret;
}

void init() {
	read(n); read(m);
	eCnt = 1;
	for (int i=1;i<=n;++i) {
		scanf("%s", g + 1);
		for (int j=1;j<=m;++j) {
			if (g[j] == '.') continue;
			Add(i, n+j, 1);
			Add(n+j, i, 1);
			if (g[j] == 'S') {
				Add(S, i, INF);
				Add(S, n+j, INF);
			} else if (g[j] == 'T') {
				Add(i, T, INF);
				Add(n+j, T, INF);
			}
		}
	}
}

void solve() {
	int ans = 0;
	while (Layer()) {
		ans += DFS(S, INF);
	}
	printf("%d\n", (ans > n*m)? -1 : ans);
}

int main() {
	init();
	solve();
	return 0;
}

