struct MaxFlow
{
    const int maxr = 1e5 + 7;
    int source, sink, h[maxn];
    vector<Edge> e;
    vector<int> adj[maxn];
    vector<int>::iterator cur[maxn];
    void Reset(int u, int v)
    {
        source = u, sink = v;
        for(int i = source; i <= sink; i++) adj[i] = {};
        e = {};
    }
    void AddEdge(int u, int v, int flow)
    {
        adj[u].push_back(e.size());
        e.push_back(Edge(u, v, flow));
        adj[v].push_back(e.size());
        e.push_back(Edge(v, u, 0));

    }
    bool BFS()
    {
        for(int i = source; i <= sink; i++) h[i] = 1e9;
        h[sink] = 0;
        queue<int> q;
        q.push(sink);
        while(!q.empty())
        {
            int gau = q.front();
            q.pop();
            for(auto i: adj[gau])
            {
                i ^= 1;
                int meo = e[i].u;
                if(e[i].flow == 0 || h[meo] != 1e9) continue;
                h[meo] = h[gau] + 1;
                if(meo == source) return true;
                q.push(meo);
            }
        }
        return false;
    }
    int DFS(int u, int FlowIn)
    {
        if(u == sink) return FlowIn;
        int FlowOut = 0;
        for(; cur[u] != adj[u].end(); cur[u]++)
        {
            int i = *cur[u];
            int v = e[i].v;
            if(e[i].flow == 0 || h[v] + 1 != h[u]) continue;
            int maxFlow = DFS(v, min(e[i].flow, FlowIn));
            FlowIn -= maxFlow;
            FlowOut += maxFlow;
            e[i].flow -= maxFlow;
            e[i ^ 1].flow += maxFlow;
            if(FlowIn == 0) break;
        }
        return FlowOut;
    }
    int FindMaxFLow()
    {
        int ans = 0;
        while(BFS())
        {
            for(int i = source; i <= sink; i++) cur[i] = adj[i].begin();
            ans += DFS(source, Inf);
        }
        return ans;
    }
} Dinitz;
