struct maxflow
{
	int n, s, t, z;
	vector<int> pt, Q, D;
	vector<edge> E;
	vector< vector<int> > g;
	maxflow() { }

	maxflow(int n) : n(n)
	{
		s = 0, t = n - 1;
		g.resize(n + 2);
		pt.resize(n + 2);
		Q.resize(n + 2);
		D.resize(n + 2);
	}

	void add_edge(int u, int v, int cap)
	{
		edge e1 = edge(u, v, cap, 0);
		edge e2 = edge(v, u, 0, 0);
		g[u].push_back(size(E));
		g[v].push_back(size(E) + 1);
		E.push_back(e1);
		E.push_back(e2);
	}

	bool bfs()
	{
		int qh = 0, qt = 0, cnt = 1;
		Q[qt++] = s;
		fill(D.begin(), D.end(), -1);
		D[s] = 0;

		for (; qh < qt && D[t] == -1; )
		{
			int v = Q[qh++];

			for (auto to : g[v])
				if (D[E[to].v] == -1 && E[to].flow < E[to].cap)
					D[E[to].v] = D[v] + 1, Q[qt++] = E[to].v, ++cnt;
		}

		return D[t] != -1;
	}

	llong dfs(int v, int mrg)
	{
		if (mrg == 0) return 0;
		if (v == t) return mrg;

		for (int& j = pt[v]; j < size(g[v]); ++j)
		{
			int i = g[v][j];

			if (D[E[i].u] + 1 == D[E[i].v])
			{
				llong pushed = dfs(E[i].v, min(mrg, E[i].cap - E[i].flow));
				E[i].flow += pushed;
				E[i ^ 1].flow -= pushed;
				if (pushed) return pushed;
			}
		}

		return 0;
	}

	llong dinic()
	{
		llong flow = 0, pushed = 0;

		for (;;)
		{
			if (!bfs())
				break;

			fill(pt.begin(), pt.end(), 0);

			while (pushed = dfs(s, inf))
				flow += pushed, ++z;
		}

		return flow;
	}
};

