struct FordFulkerson{
  struct edge {
    int to, rev;
    ll cap;
  };
  int n;
  vector<vector<edge>> G;
  vector<bool> used;
  void init(int m){
    n = m;
    G.resize(n);
    used.resize(n);
  }
  void add_edge(int a, int b, ll c, bool undirected=false){
    G[a].push_back((edge){b, (int)G[b].size()  , c});
    G[b].push_back((edge){a, (int)G[a].size()-1, undirected ? c : 0ll});
  }
  ll solve(int s,int t){
    ll ret = 0;
    function<ll (int, int, ll)> dfs = [&](int v, int t, ll f){
      if (v==t) return f;
      used[v] = true;
      for(int i=0; i<G[v].size(); ++i) {
        edge &e = G[v][i];
        if (used[e.to] || !e.cap) continue;
        ll d = dfs(e.to, t, min(f, e.cap));
        if (d) {
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
      return 0ll;
    };
    while(true){
      fill(used.begin(), used.end(), false);
      ll f = dfs(s, t, 1e18);
      if(!f) return ret;
      ret += f;
    }
  }
}f;
