        break;
      case 'o':
        add_edge(i, j + maxsize, 1);
        add_edge(j + maxsize, i, 1);
        break;
    }
  }
  int ans = max_flow(S, T);
  if (ans == noans) ans = -1;
  printf("%d\n", ans);
