{
	int head=0,tail=0;
	for (i=0;i<=maxx;i++) dep[i]=0;
	dep[S]=1;q[++tail]=S;
	while (head!=tail)
	{
		int x=q[++head];
		for (int k=g[x];k;k=e[k].next)
		{
			int y=e[k].to;
			if (dep[y]==0&&e[k].f)
			{
				dep[y]=dep[x]+1;
				q[++tail]=y;
			}
		}
	}
	return dep[T]!=0;
}
int dfs(int x,int flow)
{
	if (x==T) return flow;
	int used=0,now=0;
	for (int k=he[x];k;k=e[k].next)
	{
		int y=e[k].to;
		if (dep[y]==dep[x]+1&&e[k].f)
		{	
			now=dfs(y,min(flow-used,e[k].f));
			used+=now;
			e[k].f-=now;
			e[k^1].f+=now;
			if (e[k].f) he[x]=k;
			if (used==flow) break;
		}
	}
	if (used==0) dep[x]=-1;
	return used;
}
