      G.insert({SOURCE, i, FLOW_INF, 0});
      G.insert({SOURCE, H+j, FLOW_INF, 0});
    }
    if(S[i][j]=='T') {
      G.insert({i, SINK, FLOW_INF, 0});
      G.insert({H+j, SINK, FLOW_INF, 0});
    }
    if(S[i][j]=='o') {
      G.insert({i, H+j, 1, 1});
      G.insert({H+j, i, 1, 1});
    }
    if(S[i][j]=='S' || S[i][j]=='T') {
      for(auto y=i+1; y<H; ++y) if(S[y][j]=='S' || S[y][j]=='T') ng();
      for(auto x=j+1; x<W; ++x) if(S[i][x]=='S' || S[i][x]=='T') ng();
    }
  }

  cout << G.maximum_flow(SOURCE, SINK) << endl;
}

