    for(;;){ 
        for(int i=1;i<=m+n+2;++i) iter[i]=h[i]; 
        memset(level,0,sizeof(level)); 
        bfs(s); 
        if(level[t]==0) return flow; 
        int d=dfs(s,t,INF); 
        while(d>0){ 
            flow+=d; 
            d=dfs(s,t,INF); 
        } 
    } 
} 
