const int inf = 1e8;
struct Dinic {
    int n;
    vector<int> dist;
    vector<vector<int>> go;
    vector<int> it;
    void init(int N) {
        n = N;
        dist.resize(n);
        go.resize(n, vector<int>(n, 0));
        it.resize(n);
    }
    void add_edge(int x, int y, int f) {
        go[x][y] = go[y][x] = f;
    }
    bool bfs(int S, int E) {
        for (int i = 0; i < n; ++i) dist[i] = inf;
        queue<int> q;
        dist[S] = 0;
        q.push(S);
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            for (int i = 0; i < n; ++i) {
                if (dist[i] < inf) continue;
                if (go[x][i] <= 0) continue;
                dist[i] = dist[x] + 1;
                q.push(i);
            }
        }
        return dist[E] < inf;
    }
    int dfs(int x, int f, int E) {
        if (x == E) return f;
        for (int &i = it[x]; i < n; ++i) {
            if (go[x][i] <= 0) continue;
            if (dist[i] != dist[x] + 1) continue;
            int ret = dfs(i, min(f, go[x][i]), E);
            if (ret == 0) continue;
            go[x][i] -= ret;
            go[i][x] += ret;
            return ret;
        }
        return 0;
    }
    int maximum_flow(int S, int E) {
        int ret = 0;
        while (bfs(S, E)) {
            for (int i = 0; i < n; ++i) it[i] = 0;
            int f = 1;
            while (f > 0) {
                f = dfs(S, inf + inf, E);
                ret += f;
            }
        }
        return ret;
    }
} d;

