            if (in[j] == 'S') d.add_edge(S, i, inf), d.add_edge(S, h + j, inf);
            if (in[j] == 'T') d.add_edge(E, i, inf), d.add_edge(E, h + j, inf);
        }
    }
    int ans = d.maximum_flow(S, E);
    printf("%d\n", ans < inf ? ans : -1);
    return 0;
}

