        if (c[u][v] - f[u][v] < D || d[v] != d[u] + 1)
            continue;
        int x = dfs(v, min(mi, c[u][v] - f[u][v]));
        if (x > 0)
        {
            f[u][v] += x;
            f[v][u] -= x;
            return x;
        }
    }
    return 0;
}

bool bfs()
{
