template<typename T = ll>
struct FordFulkerson {
    struct Edge { int to, rev; T cap; Edge(int t, int r, T c) : to(t), rev(r), cap(c) {} };
    vector<vector<Edge>> graph;
    vector<bool> used;

    void add_edge(int from, int to, T cap) {
        graph[from].emplace_back(to, graph[to].size(), cap);
        graph[to].emplace_back(from, graph[from].size() - 1, 0);
    }

    T dfs(int v, int t, T f) {
        if (v == t) return f;
        used[v] = true;
        for (auto& e : graph[v]) {
            if (!used[e.to] && e.cap > 0) {
                T ret = dfs(e.to, t, min(f, e.cap));
                if (ret > 0) {
                    e.cap -= ret;
                    graph[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }

    T max_flow(int s, int t) {
        T flow = 0;
        for (;;) {
            used.assign(graph.size(), false);
            T f = dfs(s, t, numeric_limits<T>::max());
            if (f == 0) return flow;
            flow += f;
        }
    }
};

