            if(!visited[e.to] && e.cap > 0){
                int d = dfs(e.to, t, min(f, e.cap));
                if(d>0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    void print_graph(int V){
        for(int i=0;i<V;i++){
            printf("vertex: %d\n", i);
            for(int j=0;j<G[i].size();j++){
                printf("to: %d, cap: %d\n", G[i][j].to, G[i][j].cap);
            }
            cout << endl;
        }
    }
};

