  cin >> h >> w;
  int num=1;
  P endNode = P(0,0),firstNode = P(0,0);
  queue<P>que;
  for(int i=0;i<h;i++){
    cin >> maze[i];
    for(int j=0;j<w;j++){
      if(maze[i][j] == 'S'){
	nodeNum[i][j] = 1;
	firstNode = P(i,j);
      } else if(maze[i][j] == 'T'){
