template <typename T = lnt>
struct Dinic
{
	struct Edge
	{
		int a,b;
		T c,f;
		Edge(int a, int b, T c) : a(a),b(b),c(c),f(0) {}
	};
	const T INF;
	int n,m=0;
	std::vector<std::vector<int> > G,Gf;
	std::vector<Edge> E;
	Dinic(int n) : n(n),INF(std::numeric_limits<T>::max()),G(n),Gf(n) {}
	void add_edge(int i, int j, int c) {
		E.emplace_back(i,j,c);
		E.emplace_back(j,i,0);
		G[i].emplace_back(m);
		G[j].emplace_back(m|1);
		m+=2;
	}
	bool bfs(int s, int t) {
		Gf.clear();
		std::queue<int> que; que.emplace(s);
		std::vector<int> dist(n,INF);
		dist[s]=0;
		while(!que.empty()) {
			int i=que.front(); que.pop();
			for(int to:G[i]) {
				if(dist[E[to].b]!=INF || E[to].c==E[to].f) continue;
				dist[E[to].b]=dist[E[to].a]+1;
				que.emplace(E[to].b);
			}
		}
		if(dist[t]==INF) return true;
		for(int i=0;i<m;i++) {
			if(dist[E[i].a]+1!=dist[E[i].b] || E[i].c==E[i].f) continue;
			Gf[E[i].a].emplace_back(i);
		}
		return false;
	}
	T dfs(int i, T max_flow, const int& t) {
		if(i==t || max_flow==0) {
			return max_flow;
		}
		T v_flow=0;
		for(int to:Gf[i]) {
			T f=dfs(E[to].b,std::min(max_flow,E[to].c-E[to].f),t);
			if(f>0) {
				if(to&1) {
					E[to].c-=f;
					E[to^1].f-=f;
				} else {
					E[to].f+=f;
					E[to^1].c+=f;
				}
				v_flow+=f;
				max_flow-=f;
			}
		}
		return v_flow;
	}
	T flow(int s, int t) {
		T max_flow=0;
		while(true) {
			if(bfs(s,t)) break;
			T f = dfs(s,INF,t);
			if(f==0) break;
			max_flow+=f;
		}
		return max_flow;
	}
};

