const int MAX=20000;
const int MAX_half=10000;
const long long inf=20001;

struct max_flow {
    struct edge { long long to, cap, rev; };
    long long V;
    vector<vector<edge>> G;
    vector<long long> itr, level;

    max_flow(long long V) : V(V) { G.assign(V,vector<edge>()); }

    void add_edge(long long from, long long to, long long cap) {
        G[from].push_back((edge) {to, cap, (long long) G[to].size()});
        G[to].push_back((edge) {from, 0, (long long) G[from].size()-1});
    }

    void bfs(long long s) {
        level.assign(V,-1);
        queue<long long> q;
        level[s] = 0; q.push(s);
        while (!q.empty()) {
            long long v = q.front(); q.pop();
            for(auto &e: G[v]){
                if (e.cap > 0 and level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }

    long long dfs(long long v, long long t, long long f) {
        if (v == t) return f;
        for (long long& i = itr[v]; i < (long long) G[v].size(); ++i) {
            edge& e = G[v][i];
            if (e.cap > 0 and level[v] < level[e.to]) {
                long long d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    long long run(long long s, long long t) {
        long long ret = 0, f;
        while (bfs(s), level[t] >= 0) {
            itr.assign(V,0);
            while ((f = dfs(s, t, inf)) > 0) ret += f;
        }
        return ret;
    }
};

