// https://ei1333.github.io/luzhiled/snippets/graph/dinic.html
template< typename flow_t >
struct Dinic {
  const flow_t INF;

  struct edge {
    int to;
    flow_t cap;
    int rev;
    bool isrev;
  };

  vector< vector< edge > > graph;
  vector< int > min_cost, iter;

  Dinic(int V) : INF(numeric_limits< flow_t >::max()), graph(V) {}

  void add_edge(int from, int to, flow_t cap) {
    graph[from].emplace_back((edge) {to, cap, (int) graph[to].size(), false});
    graph[to].emplace_back((edge) {from, 0, (int) graph[from].size() - 1, true});
  }

  bool bfs(int s, int t) {
    min_cost.assign(graph.size(), -1);
    queue< int > que;
    min_cost[s] = 0;
    que.push(s);
    while(!que.empty() && min_cost[t] == -1) {
      int p = que.front();
      que.pop();
      for(auto &e : graph[p]) {
        if(e.cap > 0 && min_cost[e.to] == -1) {
          min_cost[e.to] = min_cost[p] + 1;
          que.push(e.to);
        }
      }
    }
    return min_cost[t] != -1;
  }

  flow_t dfs(int idx, const int t, flow_t flow) {
    if(idx == t) return flow;
    for(int &i = iter[idx]; i < graph[idx].size(); i++) {
      edge &e = graph[idx][i];
      if(e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
        flow_t d = dfs(e.to, t, min(flow, e.cap));
        if(d > 0) {
          e.cap -= d;
          graph[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  flow_t max_flow(int s, int t) {
    flow_t flow = 0;
    while(bfs(s, t)) {
      iter.assign(graph.size(), 0);
      flow_t f = 0;
      while((f = dfs(s, t, INF)) > 0) flow += f;
    }
    return flow;
  }

  void output() {
    for(int i = 0; i < graph.size(); i++) {
      for(auto &e : graph[i]) {
        if(e.isrev) continue;
        auto &rev_e = graph[e.to][e.rev];
        cout << i << "->" << e.to << " (flow: " << rev_e.cap << "/" << e.cap + rev_e.cap << ")" << endl;
      }
    }
  }
};

int main()
{
    int H, W; cin >> H >> W;
    vector<string> A(H);
    for (auto &a : A) cin >> a;
    Dinic<int> graph(H*W*2);
    const int INF = 1e9;
    int S = -1, T = -1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (A[i][j] == 'S') S = (i*W+j)*2;
            if (A[i][j] == 'T') T = (i*W+j)*2+1;
            if (A[i][j] != '.') {
                graph.add_edge((i*W+j)*2+1, (i*W+j)*2, 1);
                for (int k = 0; k < H; k++) {
                    if (i != k && A[k][j] != '.') {
                        graph.add_edge((i*W+j)*2, (k*W+j)*2+1, INF);
                    }
                }
                for (int k = 0; k < W; k++) {
                    if (j != k && A[i][k] != '.') {
                        graph.add_edge((i*W+j)*2, (i*W+k)*2+1, INF);
                    }
                }
            }
        }
    }
    int ans = graph.max_flow(S, T);
    cout << (ans >= INF ? -1 : ans) << '\n';
    return 0;
}

