	int ret=0;
	int pre[S];
	int Q[S];
	while(1){
		memset(pre,-1,sizeof(int)*sz);
		int qs=0;
		Q[0]=s;
		pre[s]=-2;
		int qe=1;
		while(qs<qe&&pre[t]==-1){
			int p=Q[qs++];
			for(int i=0;i<edges[p].size();i++){
				int j=edges[p][i];
				int nex;
				if(es[j].a==p){
					if(es[j].f==es[j].c){
						continue;
					}
					nex=es[j].b;
				}
				else{
					if(es[j].f==0){
						continue;
					}
					nex=es[j].a;
				}
				if(pre[nex]==-1){
					Q[qe++]=nex;
					pre[nex]=j;
