  Vll sid(2), tid(2);
  rep(i, h) rep(j, w) {
    if (s[i][j] == 'S') sid = {i, j};
    if (s[i][j] == 'T') tid = {i, j};
  }

  if (sid[0] == tid[0] || sid[1] == tid[1]) {
    cout << -1 << "\n";
    return 0;
  }

  rep(i, h) rep(j1, w) rep(j2, w) {
    if (j1 == j2 && s[i][j1] == 'o') {
      G.add_edge(nid(i, j1, 0), nid(i, j2, 1), 1);
    }
    if ((s[i][j1] == 'S' || s[i][j1] == 'o') && (s[i][j2] == 'T' || s[i][j2] == 'o')) {
      G.add_edge(nid(i, j1, 1), nid(i, j2, 0), INFll);
    }
  }
  rep(j, w) rep(i1, h) rep(i2, h) {
    if (i1 == i2 && s[i1][j] == 'o') {
      G.add_edge(nid(i1, j, 0), nid(i2, j, 1), 1);
    }
    if ((s[i1][j] == 'S' || s[i1][j] == 'o') && (s[i2][j] == 'T' || s[i2][j] == 'o')) {
      G.add_edge(nid(i1, j, 1), nid(i2, j, 0), INFll);
    }
  }

  ll ans = G.max_flow(nid(sid[0], sid[1], 1), nid(tid[0], tid[1], 0)) / 2;
  cout << ans << "\n";
  return 0;
}

