		if (dep[y]==dep[x]+1&&e[k].f)
		{
			now=dfs(y,min(flow-used,e[k].f));
			used+=now;
			e[k].f-=now;
			e[k^1].f+=now;
			if (e[k].f) he[x]=k;
			if (used==flow) break;
		}
	}
	if (used==0) dep[x]=-1;
	return used;
}
