#include <bits/stdc++.h>

using flow_type = int;

struct dinic {
    struct edge {
        int src, dst;
        flow_type cap, flow;
        edge *next, *rev;

        flow_type residue() const {
            return cap - flow;
        }

        void *operator new (std::size_t) {
            constexpr std::size_t MAX_E = 100*100*100*4 + 10;
            static edge pool[MAX_E];
            static std::size_t p = 0;
            return pool + p++;
        }
    };
    int n, source, sink;
    edge **g;
    int *level, *queue;
    edge **prog;

    dinic(int n_ = 0) :
        n(n_), g(new edge*[n]()), level(new int[n]), queue(new int[n]), prog(new edge*[n]) { }

    ~dinic() {
        delete[] g;
        delete[] level;
        delete[] queue;
        delete[] prog;
    }

    flow_type maximum_flow(int source_, int sink_) {
        source = source_;
        sink = sink_;
        flow_type res = 0;
        while (levelize()) {
            std::copy(g, g + n, prog);
            res += augment(source, std::numeric_limits<flow_type>::max());
        }
        return res;
    }

    edge *add_edge1(int u, int v, flow_type c, flow_type f) {
        return g[u] = new edge { u, v, c, f, g[u], nullptr };
    }

    std::pair<edge*, edge*> add_edge(int u, int v, flow_type c) {
        if (u == v || c == 0) return { nullptr, nullptr };
        auto uv = add_edge1(u, v, c, 0);
        auto vu = add_edge1(v, u, c, c);
        uv->rev = vu;
        vu->rev = uv;
        return {uv, vu};
    }

    bool levelize() {
        int fst = 0, lst = 0;
        queue[lst++] = source;
        std::fill(level, level + n, -1);
        level[source] = 0;
        while (fst != lst) {
            int v = queue[fst++];
            if (v == sink) break;
            for (auto e = g[v]; e; e = e->next) {
                if (level[e->dst] == -1 && e->residue() != 0) {
                    level[e->dst] = level[v] + 1;
                    queue[lst++] = e->dst;
                }
            }
        }
        return level[sink] != -1;
    }

    flow_type augment(int v, flow_type lim) {
        flow_type res = 0;
        if (v == sink) return lim;
        for (auto &e = prog[v]; e; e = e->next) {
            if (lim == 0) break;
            if (level[v] < level[e->dst] && e->residue() != 0) {
                flow_type aug = augment(e->dst, std::min(lim, e->residue()));
                if (aug == 0) continue;
                e->flow += aug;
                e->rev->flow -= aug;
                res += aug;
                lim -= aug;
            }
        }
        return res;
    }
};

