                g.add_edge(i,h+w+1,h*w+1);
                g.add_edge(h+j,h+w+1,h*w+1);
            }
            else if (s[i][j] == 'o') {
                g.add_edge(i,h+j,1);
                g.add_edge(h+j,i,1);
            }
        }
    }
    auto ans = g.max_flow(h+w,h+w+1);
    if (ans >= h*w+1) cout << -1 << endl;
