//ライブラリ予定
//ネットワークフロー：蟻本p188～
class NetworkFlow {
public:
	//引数：頂点数
	NetworkFlow(){}
	NetworkFlow(int size) {
		G.resize(size);
		used.resize(size);
	}

	//fromからtoへ向かう容量capの辺をグラフに追加する
	void add_edge(int from, int to, int cap) {
		Edge e1 = { to, cap, (int)G[to].size() };
		G[from].push_back(e1);
		Edge e2 = { from, 0, (int)G[from].size() - 1 };
		G[to].push_back(e2);
	}

	//sからtへの最大流を求める
	int max_flow(int s, int t) {
		int flow = 0;
		while (true) {
			fill(used.begin(), used.end(), false);
			int f = dfs(s, t, INF);
			if (f == 0)return flow;
			flow += f;
		}
	}




private:
	//型と変数
	struct Edge { int to, cap, rev; };//辺を表す構造体（行き先、容量、逆辺）
	vector<vector<Edge>> G;   //グラフの隣接リスト表現
	vector<bool> used;//DFSで既に調べたかのフラグ

					  //関数
					  //増加パスをDFSで探す
	int dfs(int v, int t, int f) {
		if (v == t)return f;
		used[v] = true;
		REP(i, (int)G[v].size()) {
			Edge& e = G[v][i];
			if (!used[e.to] && e.cap > 0) {
				int d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};
