bool Layer() {
	for (int i=1;i<=T;++i) {
		level[i] = -1;
		used[i] = first[i];
	}
	level[S] = 0;
	q[head=tail=1] = S;
	while (head <= tail) {
		int u = q[head++];
		if (u == T) return 1;
		for (int i=first[u];i;i=e[i].nxt) {
			int v = e[i].v;
			if (e[i].w > 0 && level[v] == -1) {
				level[v] = level[u] + 1;
				q[++tail] = v;
			}
		}
	}
	return 0;
}

int DFS(int u, int flow) {
	if (u == T) return flow;
	int ret = 0;
	for (int i=used[u];i;i=e[i].nxt, used[u]=i) {
		int v = e[i].v;
		if (e[i].w > 0 && level[v] == level[u] + 1) {
			int tmp = DFS(v, min(flow, e[i].w));
			e[i].w -= tmp;
			e[i^1].w += tmp;
			flow -= tmp;
			ret += tmp;
			if (!flow) break;
		}
	}
	return ret;
}

