}

ll dfs(int s, int t, ll cap){
	int i;
	ll f;
	edge e;
	if(s == t){
		return cap;
	}
	used[s] = true;
	for(i=(g[s].l_ength()-1); i>=0; --i){
		e = g[s][i];
		if((!used[e.to]) && e.cap > 0ll){
			f = dfs(e.to, t, min(cap, e.cap));
			if(f > 0ll){
				g[s][i].cap -= f;
				g[e.to][e.rev].cap += f;
				return f;
			}
		}
	}
	return 0ll;
}

