void addEdge(int from, int to, int cap) {
  edge* fwd = new edge;
  edge* rev = new edge;
  fwd->to = to;
  fwd->cap = cap;
  fwd->rev = rev;
  rev->to = from;
  rev->cap = 0;
  rev->rev = fwd;
  edges[from].push_back(fwd);
  edges[to].push_back(rev);
}

int dp[20005];
edge* used[20005];
const int INF = 1 << 14;

int maxFlow(int s, int t) {
  int ret = 0;
  while(true) {
    memset(dp, 0, sizeof(dp));
    queue<int> q;
    q.push(s);
    dp[s] = INF;
    while(!q.empty() && dp[t] == 0) {
      int curr = q.front();
      q.pop();
      for(edge* out: edges[curr]) {
        if(out->cap == 0) continue;
        if(dp[out->to]) continue;
        dp[out->to] = min(dp[curr], out->cap);
        used[out->to] = out;
        q.push(out->to);
      }
    }
    if(dp[t] == 0) break;
    ret += dp[t];
    int curr = t;
    while(curr != s) {
      int par = used[curr]->rev->to;
      used[curr]->cap -= dp[t];
      used[curr]->rev->cap += dp[t];
      curr = par;
    }
  }
  return ret;
}

