}

void solve() {
  int r, c;
  cin >> r >> c;
  for(int i = 0; i < r; i++) {
    cin >> g[i];
  }
  /*
  construction is
  0 to r*c-1 is begin gadget
  r*c to 2*r*c-1 is end gadget
  2*r*c is source
  2*r*c+1 is sink
  */
  for(int i = 0; i < r; i++) {
    for(int j = 0; j < c; j++) {
      if(!canUse(i, j)) continue;
      addEdge(i*c+j, i*c+j + r*c, 1);
      if(g[i][j] == START_CHAR) {
        addEdge(2*r*c, i*c+j + r*c, INF);
      }
      if(g[i][j] == END_CHAR) {
        addEdge(i*c+j, 2*r*c+1, INF);
      }
      for(int k = 0; k < c; k++) {
        if(j != k && canUse(i, k)) addEdge(i*c+j + r*c, i*c+k, INF);
      }
      for(int k = 0; k < r; k++) {
        if(i != k && canUse(k, j)) addEdge(i*c+j + r*c, k*c+j, INF);
      }
    }
  }
  int ret = maxFlow(2*r*c, 2*r*c+1);
  if(ret >= INF) ret = -1;
  cout << ret << "\n";
}

void casesolve() {
  int t;
  cin >> t; cin.ignore();
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << ": ";
    solve();
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);
  solve();
  // casesolve();
}

