// Ford-Fulkerson
template<typename T>
struct FordFulkerson {
    vector<vector<Graph<T>>> g;
    vector<bool> used;
    int sz;

    FordFulkerson(int N) : sz(N) {
        g.resize(N);
        used.resize(N);
    }

    void add_edge(int from, int to, T cap) {
        g[from].eb(to, (int) g[to].size(), cap);
        g[to].eb(from, (int) g[from].size() - 1, 0);
    }

    T dfs(int v, int t, T flow) {
        if (v == t) return flow;
        if (used[v] || flow == 0) return 0;
        used[v] = true;

        for (auto &e: g[v]) {
            if (used[e.to] || e.cap == 0) continue;

            if (T f = dfs(e.to, t, min(flow, e.cap)) > 0) {
                e.cap -= f;
                g[e.to][e.rev].cap += f;
                return f;
            }
        }

        return 0;
    }

    T max_flow(int start, int end) {
        T flow = 0;
        while (true) {
            used.assign(sz, false);
            int f = dfs(start, end, inf);
            if (f == 0) break;
            flow += f;
        }
        return flow;
    }
};

