inline char readchar()
{
	char ch=' ';
	for(;ch!='S'&&ch!='T'&&ch!='.'&&ch!='o';ch=getchar());
	return ch;
}

inline int min(int a,int b)
{return a<b?a:b;}

int net(int o,int u)
{
	if(o==T)return u;
	int minh=point+1;
	fo(i,1,g[o]<<1){
		d[o]=d[o]==g[o]?1:d[o]+1;
		int k=lb[o][d[o]];
		if(flow[k][o]){		
			if(h[o]==h[k]+1){
				int uu=net(k,min(u,flow[k][o]));
				if(uu>0){
					flow[k][o]-=uu;
					flow[o][k]+=uu;
					return uu;
				}
				if(h[S]>point)return 0;
			}
			minh=min(minh,h[k]+1);
		}
	}
	--vh[h[o]];
	if(vh[h[o]]==0){
		h[S]=point+1;
		return 0;
	}
	h[o]=minh;
	++vh[h[o]];
	return 0;
}
