			flow[i][l]=flow[l][i]=1;
			lb[i][++g[i]]=l; lb[l][++g[l]]=i;
		}
		if(ch=='S'){
			flow[i][S]=inf;	flow[l][S]=inf;
			lb[S][++g[S]]=i; lb[S][++g[S]]=l;
		}
		if(ch=='T'){
			flow[T][i]=inf; flow[T][l]=inf;
			lb[i][++g[i]]=T; lb[l][++g[l]]=T;
		}
	}
	vh[0]=point; ll ans=0;
	while(h[S]<=point)ans+=net(S,inf<<3);
	if(ans>limit)puts("-1");else printf("%lld",ans);
}

