template<typename V, typename E>
class Graph
{
	std::map<V, std::map<V, E>> graph;
	bool isGraphValid() const;
public:
	Graph() noexcept { }
	Graph(std::map<V, std::map<V, E>> graph) : graph(graph)
	{
		assert(isGraphValid());
	}
	void add_vertex(const V& v);
	bool has_vertex(const V& v);
	void link(const V& src, const V& dst, const E& edge);
	E update_edge(const V& src, const V& dst, const std::function<E(const E&)>& updater);
	bool are_linked(const V& src, const V& dst) const;
	void cut(const V& src, const V& dst);
	E edge_between(const V& src, const V& dst) const;
	void cut_branches(const std::function<bool(const V&, const V&, const E&)>);
	std::map<V, E> adjacencies(const V& src) const;
	template<typename T, typename Iterator>
	T track(Iterator begin, Iterator end, T initialValue, const std::function<T(const T&, const E&)>& accumulator);
	template<typename Iterator>
	void update_on_track(Iterator begin, Iterator end, const std::function<E(const E&)>& updater);
	Graph<V, E> clone() const;
	template<typename U, typename F>
	Graph<U, F> map(const std::function<U(const V&)>& vertexMapper, const std::function<F(const E&)>& edgeMapper) const;
	Graph<V, E> as_non_directed(const E& defaultEdge, const std::function<E(const E&)>& edgeMapper) const;
	std::string pretty() const;
};

template<typename V, typename E>
inline bool Graph<V, E>::isGraphValid() const
{
	for (auto it = graph.begin(); it != graph.end(); ++it) {
		for (auto itr = it->second.begin(); itr != it->second.end(); ++itr) {
			if (!graph.count(it->first)) {
				// Destination is NOT contained in map!
				return false;
			}
			if (it->first == itr->first) {
				// This is a LOOP!
				return false;
			}
		}
	}
	return true;
}
template<typename V, typename E>
inline void Graph<V, E>::add_vertex(const V & v)
{
	assert(!graph.count(v));
	graph[v] = std::map<V, E>();
}

template<typename V, typename E>
inline bool Graph<V, E>::has_vertex(const V & v)
{
	return graph.count(v);
}

template<typename V, typename E>
inline void Graph<V, E>::link(const V & src, const V & dst, const E & edge)
{
	assert(!are_linked(src, dst));
	graph.at(dst);
	graph.at(src)[dst] = edge;
}

template<typename V, typename E>
inline E Graph<V, E>::update_edge(const V & src, const V & dst, const std::function<E(const E&)>& updater)
{
	assert(are_linked(src, dst));
	E old = graph[src][dst];
	graph[src][dst] = updater(old);
	return old;
}

template<typename V, typename E>
inline bool Graph<V, E>::are_linked(const V & src, const V & dst) const
{
	assert(graph.count(dst));
	return graph.at(src).count(dst);
}

template<typename V, typename E>
inline void Graph<V, E>::cut(const V & src, const V & dst)
{
	assert(are_linked(src, dst));
	return graph.at(src).erase(dst);
}

template<typename V, typename E>
inline E Graph<V, E>::edge_between(const V & src, const V & dst) const
{
	assert(are_linked(src, dst));
	return graph.at(src).at(dst);
}

template<typename V, typename E>
inline void Graph<V, E>::cut_branches(const std::function<bool(const V&src, const V&dst, const E&edge)> predicate)
{
	for (auto it = graph.begin(); it != graph.end(); ++it) {
		const V& src = it->first;
		for (auto itr = it->second.begin(); itr != it->second.end(); ) {
			if (predicate(src, itr->first, itr->second)) {
				itr = it->second.erase(itr);
			} else {
				++itr;
			}
		}
	}
}

template<typename V, typename E>
inline std::map<V, E> Graph<V, E>::adjacencies(const V & src) const
{
	return graph.at(src);
}

template<typename V, typename E>
inline Graph<V, E> Graph<V, E>::clone() const
{
	std::map<V, std::map<V, E>> copied;
	for (auto it = graph.begin(); it != graph.end(); ++it) {
		copied[it->first] = std::map<V, E>(it->second);
	}
	return Graph<V, E>(copied);
}

template<typename V, typename E>
inline Graph<V, E> Graph<V, E>::as_non_directed(const E & defaultEdge, const std::function<E(const E&)>& edgeMapper) const
{
	std::map<V, std::map<V, E>> mapped;
	for (auto it = graph.begin(); it != graph.end(); ++it) {
		V src = it->first;
		for (auto itr = it->second.begin(); itr != it->second.end(); ++itr) {
			V dst = itr->first;
			E edge = itr->second;
			mapped[src][dst] = edgeMapper(edge);
			if (!mapped[dst].count(src)) {
				if (graph.at(dst).count(src)) {
					mapped[dst][src] = edgeMapper(edge);
				} else {
					mapped[dst][src] = defaultEdge;
				}
			}
		}
	}
	return Graph<V, E>(mapped);
}

template<typename V, typename E>
inline std::string Graph<V, E>::pretty() const
{
	std::stringstream ss;

	bool isHead = true;
	for (const auto& vertex : graph) {
		for (const auto& edge : vertex.second) {
			if (isHead) isHead = false;
			else ss << std::endl;
			ss << vertex.first << " -> " << edge.first << " : " << edge.second;
		}
	}

	return ss.str();
}

template<typename V, typename E>
template<typename T, typename Iterator>
inline T Graph<V, E>::track(Iterator begin, Iterator end, T initialValue, const std::function<T(const T&, const E& edge)>& accumulator)
{
	Iterator it = begin;
	T ret = initialValue;
	V last = *it;
	++it;
	for ( ;it != end; ++it) {
		V dst = *it;
		ret = accumulator(ret, graph.at(last).at(dst));
		last = dst;
	}
	return ret;
}

template<typename V, typename E>
template<typename Iterator>
inline void Graph<V, E>::update_on_track(Iterator begin, Iterator end, const std::function<E(const E&)>& updater)
{
	Iterator it = begin;
	V last = *it;
	++it;
	for (; it != end; ++it) {
		V dst = *it;
		graph[last][dst] = updater(graph[last][dst]);
		last = dst;
	}
}

template<typename V, typename E>
template<typename U, typename F>
inline Graph<U, F> Graph<V, E>::map(const std::function<U(const V&)>& vertexMapper, const std::function<F(const E&)>& edgeMapper) const
{
	std::map<U, std::map<U, F>> mapped;
	for (auto it = graph.begin(); it != graph.end(); ++it) {
		U newVertex = vertexMapper(it->first);
		for (auto itr = it->second.begin(); itr != it->second.end(); ++itr) {
			mapped[newVertex][vertexMapper(itr->first)] = edgeMapper(itr->second);
		}
	}
	return Graph<U, F>(mapped);
}

template<typename V>
std::list<V> back_track(const std::map<V, V>& dstSrcMap, V src, V terminal)
{
	std::list<V> ls;
	ls.push_front(terminal);
	const auto& end = dstSrcMap.end();
	V last = terminal;
	for (auto s = dstSrcMap.find(terminal); s != end; s = dstSrcMap.find(last)) {
		ls.push_front(s->second);
		last = s->second;
	}
	return ls;
}

// 吸収元との演算を行う
template<typename T>
std::function<T(const T&)> absorbing(const T& x)
{
	return [&](const T& y) { return x; };
}

template<typename T>
std::string to_string_for_debug(const std::list<T>& ls)
{
	ls.begin();
	std::stringstream ss;
	ss << "[";
	bool isHead = true;
	for (const auto& x : ls) {
		if (isHead) isHead = false;
		else ss << ", ";
		ss << x;
	}
	ss << "]";
	return ss.str();
}

template<typename T, typename V, typename Iterator>
inline T sequence(Iterator begin, Iterator end, T initialValue, const std::function<T(const T&, const V&, const V&)>& accumulator)
{
	Iterator it = begin;
	T ret = initialValue;
	V last = *it;
	++it;
	for (; it != end; ++it) {
		V dst = *it;
		ret = accumulator(ret, last, dst);
		last = dst;
	}
	return ret;
}

template<typename V, typename E>
std::list<V> bfs(const Graph<V, E>& graph, const V& src, const V& dst)
{
	if (src == dst) std::list<V>();
	std::queue<V> que;
	std::map<V, V> dstSrcMap;
	que.push(src);
	while (!que.empty()) {
		V v = que.front(); que.pop();
		for (const auto& adj : graph.adjacencies(v)) {
			if (!dstSrcMap.count(adj.first)) {
				dstSrcMap[adj.first] = v;
				if (adj.first == dst) {
					return back_track(dstSrcMap, src, dst);
				}
				que.push(adj.first);
			}
		}
	}
	return std::list<V>();
}

template<typename V, typename E>
std::list<V> bfs(const Graph<V, E>& graph, const V& src, const V& dst, const std::function<bool(const V&, const V&)>& predicate)
{
	if (src == dst) std::list<V>();
	std::queue<V> que;
	std::map<V, V> dstSrcMap;
	que.push(src);
	while (!que.empty()) {
		V v = que.front(); que.pop();
		for (const auto& adj : graph.adjacencies(v)) {
			if (!dstSrcMap.count(adj.first) && predicate(v, adj.first)) {
				// std::cout << "TODO visit " << adj.first << std::endl;
				dstSrcMap[adj.first] = v;
				if (adj.first == dst) {
					// std::cout << "Find out terminal[" << adj.first << "]" << std::endl;
					dstSrcMap.erase(src);
					return back_track(dstSrcMap, src, dst);
				}
				que.push(adj.first);
			}
		}
	}
	return std::list<V>();
}

template<typename V, typename E>
Graph<V, E> ford_fulkerson(const Graph<V, E>& graph, const V& src, const V& dst, const E& max, const E& zero)
{
	Graph<V, E> flow = graph.as_non_directed(zero, absorbing(zero));
	std::function<bool(const V&, const V&)> predicate = [&](const V& s, const V& d) {
		E cap = graph.are_linked(s, d)? graph.edge_between(s, d) : zero;
		E flw = flow.edge_between(s, d);
		// std::cout << "Can visit " << d << " from " << s << "? "<< std::endl;
		// std::cout << "  residue : " << cap << " - " << flw << " = " << (cap - flw) << " > " << zero << std::endl;
		return cap - flw > zero;
//		return flow.edge_between(s, d) > zero;
	};
	std::function<E(const E&, const V&, const V&)> minExtractor = [&](const E& old, const V& s, const V& d) {
		E cap = graph.are_linked(s, d) ? graph.edge_between(s, d) : zero;
		E flw = flow.edge_between(s, d);
		E residue = cap - flw;
		// std::cout << "Residue[" << residue << "] = Capacity[" << cap << "] - Flow[" << flw << "]" << std::endl;
		E min = std::min(old, residue);
		// std::cout << "Which is min of " << old << ", and " << residue << "? : " << min << std::endl;
		return min;
	};
	while (true) {
		std::list<V> trail = bfs(flow, src, dst, predicate);
		if (trail.empty()) {
			// std::cout << "Finish. ford-fulkerson." << std::endl;
			flow.cut_branches([&](const V& src, const V& dst, const E& edge) { return edge <= zero; });
			return flow;
		}
		// std::cout << "  find a path : " << to_string_for_debug(trail) << std::endl;
//		E min = flow.track(trail.begin(), trail.end(), max, minExtractor);
		E min = sequence(trail.begin(), trail.end(), max, minExtractor);
		// std::cout << "MINIMUM RESIDUE : " << min << std::endl;
		flow.update_on_track(trail.begin(), trail.end(), [&](const E& old) { return old + min; });
		flow.update_on_track(trail.rbegin(), trail.rend(), [&](const E& old) { return old - min; });
	}
}

template<typename V, typename E>
E max_flow(const Graph<V, E>& graph, const V& src, const V& dst, const E& max, const E& zero)
{
	Graph<V, E> flow = graph.as_non_directed(zero, absorbing(zero));
	std::function<bool(const V&, const V&)> predicate = [&](const V& s, const V& d) {
		E cap = graph.are_linked(s, d) ? graph.edge_between(s, d) : zero;
		E flw = flow.edge_between(s, d);
		// std::cout << "Can visit " << d << " from " << s << "? " << std::endl;
		// std::cout << "  residue : " << cap << " - " << flw << " = " << (cap - flw) << " > " << zero << std::endl;
		return cap - flw > zero;
	};
	std::function<E(const E&, const V&, const V&)> minExtractor = [&](const E& old, const V& s, const V& d) {
		E cap = graph.are_linked(s, d) ? graph.edge_between(s, d) : zero;
		E residue = cap - flow.edge_between(s, d);
		E min = std::min(old, residue);
		// std::cout << "Which is min of " << old << ", and " << residue << "? : " << min << std::endl;
		return min;
	};
	E ret = E(zero);
	while (true) {
		std::list<V> trail = bfs(flow, src, dst, predicate);
		if (trail.empty()) {
			// std::cout << "Finish. ford-fulkerson." << std::endl;
			return ret;
		}
		// std::cout << "  find a path : " << to_string_for_debug(trail) << std::endl;
//		E min = flow.track(trail.begin(), trail.end(), max, minExtractor);
		E min = sequence(trail.begin(), trail.end(), max, minExtractor);
		ret += min;
		// std::cout << "MINIMUM RESIDUE : " << min << std::endl;
		flow.update_on_track(trail.begin(), trail.end(), [&](const E& old) { return old + min; });
		flow.update_on_track(trail.rbegin(), trail.rend(), [&](const E& old) { return old - min; });
	}
}

