struct Point
{
	const int x;
	const int y;
	Point(int x = 0, int y = 0) : x(x), y(y) { }
	int compareTo(const Point& p)
	{
		if(x < p.x) return -1;
		if(x > p.x) return  1;
		if(y < p.y) return -1;
		if(y > p.y) return  1;
		return 0;
	}
	bool operator==(const Point& p) { return compareTo(p) == 0; }
	bool operator> (const Point& p) { return compareTo(p) >  0; }
