// Ford-Fulkerson
// O(FV)
struct MaxFlow {
  struct Edge{
    int to; ll cap; int rev;
    Edge(int to, ll cap, int rev): to(to), cap(cap), rev(rev) {}
  };
  int n;
  vector<vector<Edge> > g; // direcrted
  ll inf;
  MaxFlow(int n, ll inf = LINF): n(n), g(n), inf(inf) {}
  void addEdge(int from, int to, ll cap) {
    // cap >= 0
    g[from].emplace_back(to, cap, g[to].size());
    g[to].emplace_back(from, 0, g[from].size()-1);
  }
  ll solve(int s, int t) {
    ll flow = 0;
    while(1) {
      VI used(n, 0);
      ll x = mfDFS(used, s, t, inf);
      if(x == 0) break;
      flow += x;
    }
    return flow;
  }
  private:
  int mfDFS(VI &used, int v, int t, ll od) {
    if(v == t) return od;
    used[v] = 1;
    for(Edge &edge : g[v]) if(!used[edge.to] && edge.cap > 0) {
      ll d = mfDFS(used, edge.to, t, min(od, edge.cap));
      if(d == 0) continue; ////
      edge.cap -= d;
      g[edge.to][edge.rev].cap += d;
      return d;
    }
    return 0;
  }
};

