using T = int;
struct Flow{
    struct E{
        int dest;
        T orig, *lim, *rev;
    };
    int zr,uj,n=0;
    vector<unique_ptr<T>> ts;
    vector<vector<E>> graf;
    vector<int> ptr, odl;
    void vert(int v){
        n = max(n,v+1);
        graf.resize(n);
        ptr.resize(n);
        odl.resize(n);
    }
    bool iszero(T v){
        return !v; //zmien dla doubli
    }
    void bfs(){
        fill(odl.begin(),odl.end(),0);
        vector<int> kol = {zr};
        odl[zr] = 1;
        for(int i = 0; i < (int)kol.size(); ++i){
            for(E &e: graf[kol[i]]){
                if(!odl[e.dest] && !iszero(*e.lim)){
                    odl[e.dest] = odl[kol[i]]+1;
                    kol.push_back(e.dest);
                }
            }
        }
    }
    T dfs(int v, T lim){
        if(v == uj) return lim;
        T ret = 0, wez;
        for(int &i = ptr[v] ; i < (int) graf[v].size(); ++i){
            E& e = graf[v][i];
            if(odl[e.dest] == odl[v]+1 && !iszero(*e.lim) && !iszero(wez = dfs(e.dest,min(*e.lim,lim)))){
                ret += wez;
                *e.lim -= wez;
                *e.rev += wez;
                lim -= wez;
                if(iszero(lim)) break;
            }
        }
        return ret;
    }
    void add_edge(int u, int v, T lim, bool bi = false /* bidirectional?*/){
        vert(max(u,v));
        T *a = new T(lim), *b = new T(lim*bi);
        ts.emplace_back(a);
        ts.emplace_back(b);
        graf[u].push_back(E{v,lim,a,b});
        graf[v].push_back(E{u,lim*bi,b,a});
    }
    T dinic(int zr_, int uj_){
        zr = zr_; uj = uj_;
        vert(max(zr,uj));
        T ret = 0;
        while(true){
            bfs();
            fill(ptr.begin(),ptr.end(),0);
            const T sta = dfs(zr,numeric_limits<T>::max());
            if(iszero(sta)) break;
            ret += sta;
        }
        return ret;
    }
    vector<int> cut(){
        vector<int> ret;
        bfs();
        for(int i = 0; i < n; ++i)
            if(odl[i])
                ret.push_back(i);
        return ret;
    }
    map<pair<int,int>,T> get_flowing(){
        map<pair<int,int>,T> ret;
        for(int i = 0; i < n; ++i)
            for(E& e: graf[i])
                if(*e.lim < e.orig)
                    ret[make_pair(i,e.dest)] += e.orig - *e.lim;
        for(auto &i: ret){
            const pair<int,int> rev(i.first.second,i.first.first);
            const T x = min(i.second,ret[rev]);
            i.second -= x;
            ret[rev] -= x;
        }
        return ret;
    }
};
