typedef long long ll;typedef vector<int> vi;typedef pair<int,int> pi;const int inf = (int)1e9;const double INF = 1e12, EPS = 1e-9;
struct FlowGraph{
	struct edge{ int to, cap, rev; };

	int n, *level, *iter;
	vector<vector<edge> > G;

	FlowGraph(int sz) : n(sz){
		G.resize(n);
		iter = new int[n]; level = new int[n];
	}
	~FlowGraph(){
		delete [] iter; delete [] level;
	}

	void add(int s, int t, int cap){
		G[s].pb((edge){t, cap, (int)G[t].size()});
		G[t].pb((edge){s, 0, (int)G[s].size() - 1});
	}
	void bfs(int s){
		rep(i, n) level[i] = -1;
		queue<int> q;
		level[s] = 0;
		q.push(s);
		while(!q.empty()){	
			int v = q.front();
			q.pop();
			rep(i, G[v].size()){
				edge &e = G[v][i];
				if(e.cap > 0 && level[e.to] < 0){
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}
	int dfs(int v, int t, int f){
		if(v == t) return f;
		for(int &i = iter[v]; i < (int)G[v].size(); i++){
			edge &e = G[v][i];
			if(e.cap > 0 && level[v] < level[e.to]){
				int d = dfs(e.to, t, min(f, e.cap));
				if(d > 0){
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
	int max_flow(int s, int t){
		int flow = 0;
		while(1){
			bfs(s);
			if(level[t] < 0) return flow;
			rep(i, n) iter[i] = 0;
			int f;
			while((f = dfs(s, t, inf)) > 0) flow += f;
		}
	}
};
int main(){
	cin.tie(0); cin.sync_with_stdio(0);

	int h, w; cin >> h >> w;
	vector<string> m(h);
	int s, t;
	FlowGraph g(h * w * 2);

	rep(i, h){
		cin >> m[i];
		auto in = [&](int i, int j){
			return (i * w + j) * 2;
		};
		auto out = [&](int i, int j){
			return (i * w + j) * 2 + 1;
		};

		rep(j, w){
			if(m[i][j] == 'S') s = out(i, j);
			if(m[i][j] == 'T') t = in(i, j);
			if(m[i][j] != '.'){
				rep(k, j) if(m[i][k] != '.'){
					g.add(out(i, j), in(i, k), 1);
					g.add(out(i, k), in(i, j), 1);
				}
				rep(k, i) if(m[k][j] != '.'){
					g.add(out(i, j), in(k, j), 1);
					g.add(out(k, j), in(i, j), 1);
				}
			}
			if(m[i][j] == 'o') g.add(in(i, j), out(i, j), 1);
		}
	}
	if(s / 2 % w == t / 2 % w || s / 2 / w == t / 2 / w){
		cout << -1 << endl;
		return 0;
	}
	cout << g.max_flow(s, t) << endl;

	return 0;
}

