#include <iostream>
#include <vector>
#include <queue>
using namespace std;

struct edge{
    int to, cap, rev;
    edge(int to, int cap, int rev) : to(to), cap(cap), rev(rev){}
};

struct Dinic{
    int size;
    vector< vector<edge> > edg;
    vector< int > dst, mem;

    void init(int n){
        size = n;
        edg.assign(size, vector<edge>());
    }

    void add_edge(int from, int to, int cap){
        edg[from].push_back(edge(to, cap, edg[to].size()));
        edg[to].push_back(edge(from, 0, edg[from].size() - 1));
    }

    void cal_dist(int s){
        dst.assign(size, -1);
        queue<int> q;
        dst[s] = 0;
        q.push(s);
        while(!q.empty()){
            int v = q.front();
            q.pop();
            for(int i=0;i<edg[v].size();i++){
                edge &e = edg[v][i];
                if(e.cap > 0 && dst[e.to] < 0){
                    dst[e.to] = dst[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }

    int flow(int v, int t, int f){
        if(v == t) return f;
        for(int &i = mem[v]; i < edg[v].size(); i++){
            edge &e = edg[v][i];
            if(e.cap > 0 && dst[v] < dst[e.to]){
                int d = flow(e.to, t, min(f, e.cap));
                if(d > 0){
                    e.cap -= d;
                    edg[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(int s, int t){
        int res = 0;
        for(;;){
            cal_dist(s);
            if(dst[t] < 0) return res;
            mem.assign(size, 0);
            int f = 0;
            do{
                res += f;
                f = flow(s, t, 1e9);
            }while(f > 0);
        }
    }
};

int main(void){
    int h, w, source, sink;
    string brd[100];
    Dinic f;
    cin >> h >> w;
    for(int i=0;i<h;i++){
        cin >> brd[i];
    }
    f.init(h*w*2);
    for(int i=0;i<h;i++){
        for(int j=0;j<w;j++){
            int id = i*w+j;
            if(brd[i][j] == '.') continue;
            if(brd[i][j] == 'S') source = id;
            if(brd[i][j] == 'T') sink = id;
            f.add_edge(id+h*w, id, 1);
            for(int k=0;k<h;k++){
                if(k != i && brd[k][j] != '.'){
                    f.add_edge(id, k*w+j+h*w, h+w);
                }
            }
            for(int k=0;k<w;k++){
                if(k != j && brd[i][k] != '.'){
                    f.add_edge(id, i*w+k+h*w, h+w);
                }
            }
        }
    }
    int ans = f.max_flow(source, sink+h*w);
    if(ans >= h+w) ans = -1;
    cout << ans << endl;
}

