struct node{
	int nxt,to;
	ll f;
}road[M];
int head[N],cur[N],cnt=1;
void add(int u,int v,ll f)
{
	road[++cnt]=(node){head[u],v,f};
	head[u]=cnt;
	road[++cnt]=(node){head[v],u,0};
	head[v]=cnt;
}
queue<int>q;
int dep[N];
bool bfs(int s,int t)
{
	memcpy(cur,head,sizeof(cur));
	memset(dep,127,sizeof(dep));
	dep[s]=0;
	q.push(s);
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		for(int i=head[u];i;i=road[i].nxt)
		if(road[i].f>0)
		{
			int v=road[i].to;
			if(dep[v]>=inf)
			{
				dep[v]=dep[u]+1;
				q.push(v);
			}
		}
	}
	return dep[t]<=inf;
}
ll dfs(int u,int t,ll flow)
{
	if(u==t || !flow) return flow;
	ll ans=0;
	for(int i=cur[u];i;i=road[i].nxt)
	{
		cur[u]=i;
		int v=road[i].to,f=0;
		if(dep[v]==dep[u]+1 && (f=dfs(v,t,min(flow,road[i].f))))
		{
			flow-=f;
			ans+=f;
			road[i].f-=f;
			road[i^1].f+=f;
			if(!flow) break;
		}
	}
	return ans;
}
ll dinic(int s,int t)
{
	ll ans=0;
	while(bfs(s,t)) ans+=dfs(s,t,inf);
	return ans;
}
