    for (auto i=0; i<H; ++i)
        std::cin >> tile[i];

    const int S = 0;
    const int T = 1;

    // S と T で id を先約してる分ずらす
    auto ToXNode = [&](int x) { return x + H + 2; };
    auto ToYNode = [&](int y) { return y + 2; };
    auto Connect = [&](int from, int to, int capacity)
            {
                graph[from].push_back(Edge(to, capacity, graph[to].size()));
                graph[to].push_back(Edge(from, 0, graph[from].size() - 1));
            };
    for (auto i=0; i<H; ++i)
    {
        for (auto j=0; j<W; ++j)
        {
            // S からや、 T へ直接飛んだら達成不可能(= cap is INF)
