template<unsigned int size>
class Index{
public:
	array<int,size> sizes;
	Index(int first, ...){
		va_list args;
		va_start(args, first);
		int arg = first;
		for(int i = 0; i < (int)size; ++i) {
			sizes[i] = arg;
			arg = va_arg(args,int);
		}
	}
	int operator()(int first, ...){
		va_list args;
		va_start(args, first);
		int arg = first;
		int res = 0;
		int d = 1;
		for(int i = 0; i < (int)size; ++i) {
			res += arg*d;
			d *= sizes[i];
			arg = va_arg(args,int);
		}
		return res;
	}
};


