			used[v] = true;
			for(auto&& e : g[v]) {
				if(!used[e.to] and e.cap > 0){
					cost_t d = dfs(e.to, t, min(f, e.cap));
					if(d > 0){
						e.cap -= d;
						g[e.to][e.rev].cap += d;
						return d;
					}
				}
			}
			return 0;
		};

		cost_t f = dfs(s,t,INF);
		if(f == 0) return flow;
		flow += f;
	}
}

