const int MAXN = 102;
const ll MOD = 1000000007;
const int iNF = 0x3f3f3f3f;
/*
s = 0
row = [1, n]
col = [n+1, n+m]
t = n+m+1
*/

int n, m, head[MAXN*2], s, t;
struct Edge {
    int t, flow, cap, nxt;
} edge[MAXN * MAXN * 4];
int edge_cnt;

void add_edge (int f, int T, int cap) {
    edge[edge_cnt++] = {T, 0, cap, head[f]};
    head[f] = edge_cnt - 1;
    edge[edge_cnt++] = {f, 0, 0, head[T]};
    head[T] = edge_cnt - 1;
}

int lev[MAXN*2];
int dfs (int nd, int lim) {
    if (nd == t || lim == 0) {
        return lim;
    }

    for (int i=head[nd]; i!=-1; i=edge[i].nxt) {
        int x = edge[i].t;
        if (lev[x] == lev[nd]+1 && edge[i].cap > edge[i].flow) {
            int df = 0;
            if (df = dfs(x, min(lim, edge[i].cap - edge[i].flow))) {
                edge[i].flow += df;
                edge[i^1].flow -= df;
                return df;
            }
        }
    }

    return 0;
}

bool bfs () {
    memset(lev, -1, (n+m+2) * sizeof(int));
    lev[s] = true;
    queue<int> que;
    que.emplace(s);

    while (SZ(que)) {
        int cur = que.front();
        que.pop();

        for (int i=head[cur]; i!=-1; i=edge[i].nxt) {
            int x = edge[i].t;
            if (lev[x] == -1 && edge[i].cap > edge[i].flow) {
                lev[x] = lev[cur] + 1;
                que.emplace(x);
            }
        }
    }

    return lev[t] != -1;
}

int dinic (int x, int y) {
    s = x, t = y;
    int ret = 0;
    while (bfs()) {
        int df = 0;
        while (df = dfs(s, iNF)) {
            ret += df;
        }
    }
    return ret;
}

