// Dinic法
class Dinic {
private:
	struct Edge {
		int to, cap, rev;
		Edge(int t, int c, int r) :to(t), cap(c), rev(r) {}
	};
	int V;
	std::vector<std::vector<Edge>> graph;
	std::vector<int> level, iter;

public:
	Dinic(int v) : V(v) {
		graph.resize(v);
		level.resize(v, -1);
		iter.resize(v, 0);
	}
	// fromからtoへ向かう容量capの辺をグラフに追加する
	void addEdge(int from, int to, int cap) {
		graph[from].emplace_back(to, cap, graph[to].size());
		graph[to].emplace_back(from, 0, graph[from].size() - 1);
	}

	// sからの最短距離をBFSで計算する
	void bfs(int s) {
		std::fill(level.begin(), level.end(), -1);
		std::queue<int> queue;
		level[s] = 0;
		queue.push(s);
		while (!queue.empty()) {
			int v = queue.front(); queue.pop();
			for (int i = 0; i < graph[v].size(); ++i) {
				Edge& e = graph[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					queue.push(e.to);
				}
			}
		}
	}

	// 増加パスをDFSで探す
	int dfs(int v, int t, int f) {
		if (v == t) return f;
		for (int& i = iter[v]; i < graph[v].size(); ++i) {
			Edge& e = graph[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				int d = dfs(e.to, t, std::min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					graph[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	// sからtへの最大流を求める
	int maxFlow(int s, int t) {
		int res = 0;
		while (true) {
			bfs(s);
			if (level[t] < 0) return res;
			std::fill(iter.begin(), iter.end(), 0);
			int f;
			while ((f = dfs(s, t, (1LL << 31) - 1)) > 0) {
				res += f;
			}
		}
	}
};

signed main() {
	INIT;
	VAR(int, h, w);
	MAT(char, a, h, w);
	int sy, sx, ty, tx;
	REP(i, h) REP(j, w) {
		if (a[i][j] == 'S') {
			sy = i;
			sx = j;
			a[i][j] = 'o';
		}
		if (a[i][j] == 'T') {
			ty = i;
			tx = j;
			a[i][j] = 'o';
		}
	}
	if (sy == ty || tx == sx) {
		OUT(-1)BR;
		return 0;
	}
	Dinic dn(h*w*2);
	REP(i, h) {
		std::vector<int> vj;
		REP(j, w) {
			if (a[i][j] == 'o') {
				dn.addEdge(j + i*w, j+i*w+h*w, 1);
				vj.emplace_back(j);
			}
		}
		REP(j1, vj.size()) FOR(j2, j1 + 1, vj.size()) {
			dn.addEdge(vj[j1] + i*w + h*w, vj[j2] + i*w, INFINT);
			dn.addEdge(vj[j2] + i*w + h*w, vj[j1] + i*w, INFINT);
		}
	}
	REP(j, w) {
		std::vector<int> vi;
		REP(i, h) {
			if (a[i][j] == 'o') {
				dn.addEdge(j + i*w, j + i*w + h*w, 1);
				vi.emplace_back(i);
			}
		}
		REP(i1, vi.size()) FOR(i2, i1 + 1, vi.size()) {
			dn.addEdge(j + vi[i1] * w + h*w, j + vi[i2] * w, INFINT);
			dn.addEdge(j + vi[i2] * w + h*w, j + vi[i1] * w, INFINT);
		}
	}
	OUT(dn.maxFlow(sx + sy*w+h*w, tx + ty*w)/2)BR;
	return 0;
}

