using namespace std;
#define ll long long

vector<vector<vector<int>>> edge;
vector<bool> used;
void add_edge(int u, int v, int c) {
    edge[u].push_back({v, c, (int)edge[v].size()});
    edge[v].push_back({u, 0, (int)edge[u].size()-1});
}

int dfs(int v, int t, int f) {
    if (v==t) return f;
    used[v] = true;
    for (int i = 0; i < (int)edge[v].size(); i++) {
        auto e = edge[v][i];
        if (used[e[0]] || e[1]==0) continue;
        int d = dfs(e[0], t, min(f, e[1]));
        if (d > 0) {
            edge[v][i][1] -= d;
            edge[e[0]][e[2]][1] += d;
            return d;
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int res = 0;
    int M = (int)edge.size();
    while (true) {
        used = vector<bool>(M, false);
        int f = dfs(s, t, 99999999);
        if (f == 0) break;
        else res += f;
    }
    return res;
}

int main() {
    int INF = 999;
    int H,W;
    cin >> H >> W;
    vector<string> grid(H);
    for (int i = 0; i < H; i++) cin >> grid[i];
    edge.resize(H+W+2);
    int start, goal;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '.') continue;
            if (grid[i][j] == 'S') {
                start = i*W+j;
                add_edge(H+W, i, INF);
                add_edge(H+W, H+j, INF);
            }
            else if (grid[i][j] == 'T') {
                goal = i*W+j;
                add_edge(i, H+W+1, INF);
                add_edge(H+j, H+W+1, INF);
            }
            else if (grid[i][j] == 'o') {
                add_edge(i, H+j, 1);
                add_edge(H+j, i, 1);
            }
        }
    }
    if (start / W == goal / W || (goal-start) % W == 0) cout << -1 << endl;
    else cout << max_flow(H+W, H+W+1) << endl;
    return 0;
}

