    d[0]=0;
    vis[0]=true;
    q.push(0);
    while(!q.empty())
    {
        int t=q.front();q.pop();
        for(int i=head[t];i;i=e[i].next)
        {
            if(!vis[e[i].v]&&e[i].flow<e[i].cap)
            {
                d[e[i].v]=d[t]+1;
                vis[e[i].v]=true;
                q.push(e[i].v);
            }
        }
    }
    return vis[T];
