int dfs(int x,int a)
{
    if(x==T||a==0)return a;
    int flow=0;
    for(int &i=cur[x];i;i=e[i].next)
    {
        if(d[e[i].v]==d[x]+1)
        {
            int t=dfs(e[i].v,min(a,e[i].cap-e[i].flow));
            if(t>0)
            {
                e[i].flow+=t;
                e[i^1].flow-=t;
                flow+=t;
                a-=t;
                if(a==0)break;
            }
        }
    }
    return flow;
}

