#define MAX_V 10000
const int INF = 1 << 30;

//辺を表す構造体(行先，容量，逆辺)
struct edge{
  int to, cap, rev;
};

vector<edge> G[MAX_V];
bool used[MAX_V];

//辺の追加
void add_edge(int from, int to, int cap){
  G[from].push_back(edge{to, cap, (int)G[to].size()});
  G[to].push_back(edge{from, 0, (int)G[from].size() - 1});
}

//増加パスをDFSで探す
int dfs(int v, int t, int f){
  if(v == t) return f;
  used[v] = true;
  for(int i = 0; i < (int)G[v].size(); i++){
    edge &e = G[v][i];
    if(!used[e.to] && e.cap > 0){
      int d = dfs(e.to, t, min(f, e.cap));
      if(d > 0){
        e.cap -= d;
        G[e.to][e.rev].cap += d;
        return d;
      }
    }
  }
  return 0;
}

//sからtへの最大流を求める
int max_flow(int s, int t){
  int flow = 0;
  for(;;){
    fill(used, used + MAX_V, false);
    int f = dfs(s, t, INF);
    if(f == 0) return flow;
    flow += f;
  }
}

