// >>> Dinic
template <class Flow>
struct Dinic {
    static constexpr Flow INF = numeric_limits<Flow>::max();
    static constexpr Flow EPS = 1e-10; //

    struct edge {
        int32_t to,rev;
        Flow cap;
        edge(int to, int rev, Flow cap) : to(to), rev(rev), cap(cap) {}
    };
    vector<vector<edge>> g;
    vector<pair<int32_t,int32_t>> es;
    vector<int32_t> level, iter;
    int n,s,t;

    Dinic(int n) : g(n),n(n) {}
    void add_edge(int from, int to, Flow cap) {
        es.emplace_back(from, g[from].size());
        g[from].emplace_back(to, g[to].size(), cap);
        g[to].emplace_back(from, g[from].size()-1, 0);
    }

    bool bfs() {
        level.assign(n,-1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (q.size() && level[t] < 0) {
            int x = q.front(); q.pop();
            for (auto const& e : g[x]) {
                if (e.cap > EPS && level[e.to] < 0) {
                    level[e.to] = level[x] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    Flow dfs(int x, Flow f = INF) {
        if (x == t) return f;
        Flow res = 0;
        for (auto &i = iter[x]; i < int(g[x].size()); ++i) {
            auto &e = g[x][i];
            if (e.cap > EPS && level[x] < level[e.to]) {
                Flow d = dfs(e.to, min(f,e.cap));
                e.cap -= d;
                g[e.to][e.rev].cap += d;
                res += d;
                f -= d;
                if (f == 0) break;
            }
        }
        return res;
    }

    Flow max_flow(int s, int t) {
        assert(0 <= s); assert(s < n);
        assert(0 <= t); assert(t < n);
        this-> s = s; this->t = t;
        Flow flow = 0;
        while (bfs()) {
            iter.assign(n,0);
            for (Flow f = 0; (f = dfs(s)); flow += f) {}
        }
        return flow;
    }

    void output() const {
        cerr << "dinic output:" << endl;
        for (auto const& p : es) {
            auto const& e = g[p.first][p.second];
            auto const& r = g[e.to][e.rev];
            cerr << p.first << "->" << e.to << " : "
                 << r.cap << "/" << e.cap+r.cap << endl;
        }
    }

};
