int h , w, num[101][101][2], cnt = 1, SINK, SOURCE, last[N],sx,sy,tx,ty;
char g[102][102];
struct edge {
	int from , to , cap, nxt;
	edge() {
		from = to = cap = nxt = -1;
	}
};
vector<edge> E;
void addEdge(int u , int v,  int cap) {
	E.pb(edge());
	E.back().from = u;
	E.back().to = v;
	E.back().cap = cap;
	E.back().nxt = last[u];
	last[E.back().from] = E.size() - 1;
}
void add(int u , int v , int cap) {
	addEdge(u, v, cap);
	addEdge(v, u, 0);
}

int cost[N], p[N];
bool getPath() {
	for (int i = 0; i < cnt; ++i) {
		cost[i] = oo;
		p[i] = -1;
	}
	cost[SOURCE] = 0;
	queue<int> q;
	q.push(SOURCE);
	while (q.size()) {
		int src = q.front();
		q.pop();
		if(src==SINK)break;
		for (int i = last[src]; i != -1; i = E[i].nxt) {
			int newCost = cost[src] + 1;
			if (E[i].cap && newCost < cost[E[i].to]) {
				cost[E[i].to] = newCost;
				p[E[i].to] = i;
				q.push(E[i].to);
			}
		}
	}
	return cost[SINK] != oo;
}


int main() {
	memset(last, -1, sizeof last);
	memset(num, -1, sizeof num);
	cin >> h >> w;
	for (int i = 0; i < h; ++i) {
		scanf("%s",g[i]);
		for (int j = 0 ; j < w ; ++j) {
			if (g[i][j] == 'o') {
				num[i][j][0] = cnt++;
				num[i][j][1] = cnt++;
				add(num[i][j][0], num[i][j][1], 1);
			}
			if (g[i][j] == 'S') {
				SOURCE = cnt++;
				sx = i;
				sy = j;
			}
			if (g[i][j] == 'T') {
				SINK = cnt++;
				tx = i;
				ty = j;
			}
		}
	}
	if(tx == sx || ty == sy){
		puts("-1");
		return 0;
	}
	for (int i = 0; i < h; ++i){
		for(int j = 0 ; j < w; ++j){
			if(num[i][j][0]==-1)continue;
			for(int k = 0 ; k < h ; ++k){
				if(k == i)continue;
				if(g[k][j] == 'S'){
					add(SOURCE,num[i][j][0],oo);
				}
				if(g[k][j] == 'T'){
					add(num[i][j][1],SINK,oo);
				}
				if(num[k][j][0] == -1)continue;
				add(num[i][j][1],num[k][j][0],oo);
			}
			for(int k = 0 ; k < w ; ++k){
				if(k == j)continue;
				if(g[i][k] == 'S'){
					add(SOURCE,num[i][j][0],oo);
				}
				if(g[i][k] == 'T'){
					add(num[i][j][1],SINK,oo);
				}
				if(num[i][k][0] == -1)continue;
				add(num[i][j][1],num[i][k][0],oo);
			}
		}
	}
	int mxFlow = 0;
	while(getPath()){
		int mn = oo;
		int cur = p[SINK];
		while(cur != -1){
			mn = min(mn,E[cur].cap);
			cur = p[E[cur].from];
		}
		mxFlow += mn;
		cur = p[SINK];
		while(cur != -1){
			E[cur].cap -= mn;
			E[cur^1].cap += mn;
			cur = p[E[cur].from];
		}
	}
	cout << mxFlow << endl;
	return 0;
}

