				if (k == j) continue;
				if (s[i][k] == 'o') {
					AddEdge(id[i][k] + ID, T, inf);
				}
			}
		}
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			if (s[i][j] != 'T') continue;
			//AddEdge(id[i][j], id[i][j] + ID, 1);
			for (int k = 1; k <= n; k++) {
				if (k == i) continue;
				if (s[k][j] == 'o') {
					AddEdge(id[k][j] + ID, T, inf);
				}
			}
		}
	}
	cout << MaxFlow();
	return 0;
}

