template <class Flow>class MaxFlow {
private:

	struct Edge {
		int to;
		Flow cap;
		int rev;
		Edge(int to, Flow cap, int rev) : to(to), cap(cap), rev(rev) {}
	};

	Flow INF;
	Flow EPS;
	int size;
	vector<int>level;
	vector<int>iter;
	vector<int>que;
	vector<vector<Edge>>graph;
public:

	MaxFlow(const int n, Flow eps = 0, Flow inf = 1e9) :
		level(n), iter(n), que(n), size(n), graph(n), EPS(eps), INF(inf) {}

	void add_edge(const int from, const int to, const Flow cap) {
		graph[from].push_back(Edge(to, cap, graph[to].size()));
		graph[to].push_back(Edge(from, 0, graph[from].size() - 1));
	}

	void add_undirected_edge(const int from, const int to, const Flow cap) {
		graph[from].push_back(Edge(to, cap, graph[to].size()));
		graph[to].push_back(Edge(from, cap, graph[from].size() - 1));
	}

	Flow max_flow(const int source, const int sink) {
		Flow flow = 0;

		while (1) {
			bfs(source, sink);

			if (level[sink] == -1) return flow;

			for (int i = 0; i < size; i++) iter[i] = 0;

			flow += dfs(source, sink, INF);
		}
	}

private:

	void bfs(const int from, const int to) {
		int qs = 0, qt = 0;

		for (int i = 0; i < size; i++) level[i] = -1;

		level[from] = 0;
		que[qt++] = from;

		while (qs < qt && level[to] == -1) {
			int now = que[qs++];

			for (int i = 0; i < graph[now].size(); i++) {
				int next = graph[now][i].to;

				if (graph[now][i].cap > EPS && level[next] == -1) {
					level[next] = level[now] + 1;
					que[qt++] = next;
				}
			}
		}
	}

	Flow dfs(const int from, const int to, const Flow cap) {
		Flow flow = 0;

		if (from == to || cap <= EPS) return cap;

		for (int &i = iter[to]; i < graph[to].size(); i++) {
			int next = graph[to][i].to;
			Edge &edge = graph[next][graph[to][i].rev];
			Flow res;

			if (edge.cap <= EPS || level[next] >= level[to]) continue;

			res = dfs(from, next, min(cap - flow, edge.cap));

			if (res <= EPS) continue;

			edge.cap -= res;
			graph[to][i].cap += res;
			flow += res;

			if (abs(flow - cap) <= EPS) break;
		}

		return flow;
	}
};


