inline void add(int x, int y, int z) {
	a[++_].v = y, a[_].w = z, a[_].nxt = head[x], head[x] = _;
	a[++_].v = x, a[_].w = 0, a[_].nxt = head[y], head[y] = _;
}

bool bfs() {
	static int q[N], he, ta;
	memset(dis, -1, t + 1 << 2);
	dis[q[he = ta = 1] = s] = 0;
	while(he <= ta) {
		int x = q[he++];
		for(int i=head[x];i;i=a[i].nxt)
			if(a[i].w > 0 and dis[a[i].v] == -1) {
				dis[a[i].v] = dis[x] + 1;
				q[++ta] = a[i].v;
				if(a[i].v == t) return true;
			}
	}
	return false;
}

int dfs(int x, int flw) {
	if(x == t or flw == 0) return flw;
	int res = 0, tmp;
	for(int&i=cur[x];i;i=a[i].nxt)
		if(dis[a[i].v] == dis[x] + 1 and a[i].w > 0)
		if(tmp = dfs(a[i].v, min(flw - res, a[i].w)))
			a[i].w -= tmp, a[i^1].w += tmp, res += tmp;
	if(!res) dis[x] = -1;
	return res;
}

