using namespace std;

using ll = long long;

const int MAX_V = 256;
const ll INF = 1e16;

char lake[MAX_V][MAX_V];

struct edge {
    int  to;
    ll  cap;
    ll  rev;
};

vector<edge> G[MAX_V];
vector<bool> used(MAX_V);

void add_edge(int from, int to, ll cap) {
    G[from].emplace_back((edge){to, cap, (ll)G[to].size()});
    G[to].emplace_back((edge){from, 0, (ll)(G[from].size() - 1)});
}

ll dfs(int v, int t, ll f) {
    if(v == t) return f;
    used[v] = true;
    for(edge& e : G[v]) {
        if(!used[e.to] && e.cap > 0) {
            ll d = dfs(e.to, t, min(f, e.cap));
            if(d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

ll max_flow(int s, int t) {
    ll flow = 0;
    while(true) {
        fill(used.begin(), used.end(), 0);
        ll f = dfs(s, t, INF);
        flow += f;
        if(f == 0) break;
    }

    return flow;
}

int main() {
    int H, W;
    cin >> H >> W;

    int S = H+W;
    int T = H+W+1;

    for(int i = 0; i < H; i++) {
        for(int j = 0; j < W; j++) {
            cin >> lake[i][j];

            if(lake[i][j] == 'o') {
                add_edge(i, H+j, 1);
                add_edge(H+j, i, 1);
            }

            if(lake[i][j] == 'S') {
                add_edge(S, i, INF);
                add_edge(S, H+j, INF);
            }

            if(lake[i][j] == 'T') {
                add_edge(i, T, INF);
                add_edge(H+j, T, INF);
            }
        }
    }

    ll ans = max_flow(S, T);
    if(ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
}

