inline void init(int n) {
    memset(head, -1, sizeof(int)*n);
    V = n; E = 0;
}


inline void add_edge(int u, int v, int c) {
  //  cout << u << " " << v << endl;
    to[E] = v; cap[E] = c; nxt[E] = head[u]; head[u] = E++;
    to[E] = u; cap[E] = 0; nxt[E] = head[v]; head[v] = E++;
}


inline void add_edge(int u, int v, int l, int r) {
    if (l) {
        Sx[v] += l, xT[u] += l;
    }
    add_edge(u, v, r - l);
}


inline bool bfs() {
    memset(dis, -1, sizeof(dis));
    qf = qb =0;
    q[qb++] = src; dis[src] = 0;
    while (qf < qb && dis[tar] == -1) {
        int u = q[qf++];
       // cout << u << endl;
        for (int i = head[u]; i >= 0; i = nxt[i]) {
            int v=to[i];
         //   cout << "v = " << v << endl;
            if (dis[v] == -1 && cap[i] > 0) {
                dis[v] = dis[u]+1;
                q[qb++] = v;
            }
        }
    }
    return dis[tar] >= 0;
}


int dfs(int u, int &bot) {
    if (u == tar) {
        return bot;
    }
    for (int &i = work[u]; i >= 0; i = nxt[i]) {
        int v = to[i];
        if (dis[v] != dis[u] + 1 || cap[i] == 0) {
            continue;
        }
        int bot1 = min(bot, cap[i]);
        if (int flow = dfs(v, bot1)) {
            cap[i] -= flow;
            cap[i ^ 1] += flow;
            bot = bot1;
            return flow;
        }
    }
    return 0;
}


int dinic() {
    int ans = 0, bot;
   // cout << "!" << endl;
    while (bfs()) {
    //    cout << tar << " " << src << " " << n << endl;
        memcpy(work, head, sizeof(int)*V);
        int flow = mod;
        while (flow = dfs(src, bot = mod)) {
            ans += flow;
        }
    }
    return ans;
}
