const int MAX_N = 205, INF = 10000;

class Edge {
public:
  int nxt, to, cap;
} e[1000005];

int head[MAX_N], cnt, iter[MAX_N], level[MAX_N];
void addedge(int u, int v, int cap) {
  e[++cnt] = (Edge){head[u], v, cap}, head[u] = cnt;
  e[++cnt] = (Edge){head[v], u, 0}, head[v] = cnt;
}

void add_biedge(int u, int v, int cap) {
  e[++cnt] = (Edge){head[u], v, cap}, head[u] = cnt;
  e[++cnt] = (Edge){head[v], u, cap}, head[v] = cnt;
}

void bfs(int s) {
  static int q[MAX_N];
  memset(level, -1, sizeof level);
  memcpy(iter, head, sizeof iter);

  int l = 1, r = 1;
  q[1] = s, level[s] = 0;

  while (l <= r) {
    int u = q[l++];
    for (int i = head[u]; i; i = e[i].nxt)
      if (e[i].cap > 0 && level[e[i].to] == -1) {
	level[e[i].to] = level[u] + 1;
	q[++r] = e[i].to;
      }
  }
}

#define rev(x) (x & 1 ? x + 1 : x - 1)

int dfs(int u, int t, int f) {
  if (u == t) return f;
  for (int &i = iter[u]; i; i = e[i].nxt)
    if (e[i].cap > 0 && level[e[i].to] > level[u]) {
      int d = dfs(e[i].to, t, min(f, e[i].cap));
      if (d > 0) {
	e[i].cap -= d;
	e[rev(i)].cap += d;
	return d;
      }
    }
  return 0;
}

int dinic(int s, int t) {
  int flow = 0;
  while (true) {
    bfs(s);
    if (level[t] == -1) return flow;
    static int f;
    while ((f = dfs(s, t, INF)) > 0) flow += f; 
  }
}


