const int INF = 1000000000;

template<class FT>
struct Dinic {
  const FT INF;

  struct edge {
    int to;
    FT cap;
    int rev;
    bool is_rev;
  };

  vector<vector<edge>> graph;
  vector<int> min_cost, iter;

  Dinic(int V) : INF(numeric_limits<FT>::max()), graph(V) {};

  void add_edge(int from, int to, FT cap, int idx = -1) {
    graph[from].emplace_back((edge) {to, cap, (int) graph[to].size(), false});
    graph[to].emplace_back((edge) {from, 0, (int) graph[from].size() - 1, true});
  }

  bool bfs(int s, int t) {
    min_cost.assign(graph.size(), -1);
    min_cost[s] = 0;
    queue<int> Q;
    Q.push(s);
    while(Q.size() && min_cost[t] == -1) {
      int v = Q.front();
      Q.pop();
      for(auto &e: graph[v]) {
        if(e.cap > 0 && min_cost[e.to] == -1) {
          min_cost[e.to] = min_cost[v] + 1;
          Q.push(e.to);
        }
      }
    }
    return min_cost[t] != -1;
  }

  FT dfs(const int v, const int t, FT flow) {
    if(v == t) return flow;
    for(int &i = iter[v]; i < graph[v].size(); i++) {
      edge &e = graph[v][i];
      if(e.cap > 0 && min_cost[v] < min_cost[e.to]) {
        FT d = dfs(e.to, t, min(flow, e.cap));
        if(d > 0) {
          e.cap -= d;
          graph[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  FT max_flow(int s, int t) {
    FT flow = 0;
    while(bfs(s, t)) {
      iter.assign(graph.size(), 0);
      FT f = 0;
      while((f = dfs(s, t, INF)) > 0) flow += f;
    }
    return flow;
  }

  void print() {
    for(int i = 0; i < graph.size(); i++) {
      for(auto &e: graph[i]) {
        if(e.isrev) continue;
        auto &rev_e = graph[e.to][e.rev];
        cout << i << "->" << e.to << " (flow:" << rev_e.cap << "/" << e.cap + rev_e.cap << ")" << endl;
      }
    }
  }
};

