int e = 0;

void addEdge(int v, int u, int c) {
    E[v].push_back(e);
    E[u].push_back(e ^ 1);

    cap[e] = c;
    cap[e ^ 1] = 0;

    to[e] = u;
    to[e ^ 1] = v;

    e += 2;
}

int push(int v, int cur_flow) {
    if (v == t || cur_flow == 0) {
        return cur_flow;
    }

    used[v] = true;
    for (int edge : E[v]) {
        if (!used[to[edge]]) {
            int a = push(to[edge], min(cur_flow, cap[edge] - flow[edge]));
            if (a > 0) {
                flow[edge] += a;
                flow[edge ^ 1] -= a;
                return a;
            }
        }
    }
    return 0;
}

