const int inf = 1e8+7;
struct Edge{
    int u,v;
    int c;
    int rev;
    Edge(int u,int v,int c,int rev):u(u),v(v),c(c),rev(rev){}
};
char s[105][105];
int depth[30005]; 
vector<Edge>g[30005];
int queue[30005];

void addEdge(int u,int v,int c){
    //printf("u = %d, v = %d, c = %d\n",u,v,c);
    int ur = g[u].size(), vr = g[v].size();
    g[u].push_back(Edge(u,v,c,vr));
    g[v].push_back(Edge(v,u,0,ur));
}

void buildRow(int r,int n,int m,int all){
    int mid = r+all;
    for(int i = 1; i <= m; i++){
        if(s[r][i]!='.'){
            int u = (r-1)*m+i;
            if(s[r][i]!='T') addEdge(n*m+u,mid,inf);
            if(s[r][i]!='S') addEdge(mid,u,inf);
        }
    }
}

void buildCow(int c,int n,int m,int all){
    int mid = all+c;
    for(int i = 1; i <= n; i++){
        if(s[i][c]!='.'){
            int u = (i-1)*m+c;
            if(s[i][c]!='T') addEdge(n*m+u,mid,inf);
            if(s[i][c]!='S') addEdge(mid,u,inf);
        }
    }
}

int bfs(int s,int e,int n){
    for(int i = 1; i <= n; i++) depth[i] = 0;
    int h = 1, t = 0;
    depth[s] = 1; queue[++t] = s;
    while(h<=t){
        int u = queue[h++];
        for(Edge edge: g[u]){
            if(edge.c!=0 && depth[edge.v]==0){
                depth[edge.v] = depth[u]+1;
                queue[++t] = edge.v;
            }
        }
    }
    return depth[e]!=0;
}

int min(int a,int b){ return a>b?b:a; }

int dfs(int s,int e,int upper){
    if(s==e || upper==0) return upper;
    else{
        int sumFlow = 0;
        for(Edge& edge: g[s]){
            if(upper==0) break;
            if(edge.c!=0 && depth[edge.v]==depth[s]+1){
                int v = edge.v;
                int add = dfs(v,e,min(edge.c,upper));
                if(add!=0) depth[v] = 0;
                Edge& revE = g[edge.v][edge.rev];
                sumFlow += add, revE.c += add;
                upper -= add, edge.c -= add;
            }
        }
        return sumFlow;
    }
}

int dinic(int s,int e,int n){
    int res = 0;
    while(bfs(s,e,n)!=0){
        int add = -1;
        while(add!=0){
            add = dfs(s,e,inf);
            res += add;
        }
    }
    return res;
}

