int main()
{
	int i, H, W;
	char a[102][102] = {};
	scanf("%d %d", &H, &W);
	for (i = 1; i <= H; i++) scanf("%s", &(a[i][1]));

	int j, k, m, s, t;
	list *adj[10001] = {}, d[2000001];
	edge e[2000001];
	for (i = 1, m = 2; i <= H; i++) {
		for (j = 1; j <= W; j++) {
			if (a[i][j] == '.') continue;
			else if (a[i][j] == 'S') s = (i - 1) * W + j;
			else if (a[i][j] == 'T') t = (i - 1) * W + j;

			for (k = i + 1; k <= H; k++) {
				if (a[k][j] != '.') {
					e[m].head = (k - 1) * W + j;
					e[m+1].head = (i - 1) * W + j;
					e[m].tail = e[m+1].head;
					e[m+1].tail = e[m].head;
					e[m].flow = 0;
					e[m+1].flow = 0;
					e[m].cap = 1;
					e[m+1].cap = 1;
					d[m].id = m;
					d[m+1].id = m + 1;
					d[m].next = adj[e[m].tail];
					d[m+1].next = adj[e[m+1].tail];
					adj[e[m].tail] = &(d[m]);
					adj[e[m+1].tail] = &(d[m+1]);
					m += 2;
				}
			}
			for (k = j + 1; k <= W; k++) {
				if (a[i][k] != '.') {
					e[m].head = (i - 1) * W + k;
					e[m+1].head = (i - 1) * W + j;
					e[m].tail = e[m+1].head;
					e[m+1].tail = e[m].head;
					e[m].flow = 0;
					e[m+1].flow = 0;
					e[m].cap = 1;
					e[m+1].cap = 1;
					d[m].id = m;
					d[m+1].id = m + 1;
					d[m].next = adj[e[m].tail];
					d[m+1].next = adj[e[m+1].tail];
					adj[e[m].tail] = &(d[m]);
					adj[e[m+1].tail] = &(d[m+1]);
					m += 2;
				}
			}
		}
	}
	if (s % W == t % W || (s - 1) / W == (t - 1) / W) {
		printf("-1\n");
		fflush(stdout);
		return 0;
	}

	int u, w, ans = 0, used[10001] = {}, prev[10001] = {}, q[10001], head, tail;
	list *p;
	q[0] = s;
	while (1) {
		for (head = 0, tail = 1; head < tail; head++) {
			u = q[head];
			for (p = adj[u]; p != NULL; p = p->next) {
				i = p->id;
				if (e[i].flow == e[i].cap || prev[e[i].head] != 0) continue;
				w = e[i].head;
				if (used[u] == 0 || used[e[prev[u]].tail] == 1 || e[i^1].flow == e[i^1].cap) {
					prev[w] = i;
					q[tail++] = w;
					if (w == t) break;
				}
			}
			if (p != NULL) break;
		}
		if (head == tail) break;
		else ans++;

		for (u = t; u != s; u = e[prev[u]].tail) {
			i = prev[u];
			if (e[i^1].flow == e[i^1].cap) e[i^1].flow--;
			else e[i].flow++;
		}
		for (tail--; tail > 0; tail--) prev[q[tail]] = 0;
		for (u = 1; u <= H * W; u++) {
			if (u == s || u == t) continue;
			for (p = adj[u]; p != NULL; p = p->next) if (e[p->id].flow > 0) break;
			if (p != NULL) used[u] = 1;
			else used[u] = 0;
		}
	}
	printf("%d\n", ans);
	fflush(stdout);
	return 0;
}

