// 内部定数
#define D_ON			1										// 汎用フラグ - ON
#define D_OFF			0										// 汎用フラグ - OFF
#define D_VTX_MAX		205										// 最大頂点数

// 内部構造体 - 頂点情報
typedef struct Vtx {
	int mi1Cap[D_VTX_MAX];										// 容量[接続先頂点]
	int miDone;													// 処理済フラグ
} Vtx;

// 内部変数
static FILE *szpFpI;											// 入力
static Vtx sz1Vtx[D_VTX_MAX];									// 頂点 [0]:開始 [1～H]:縦 [H+1～H+W]:横 [H+W+1]:終点
static int siVCnt;												// 頂点数

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
	static FILE *szpFpA;
#endif

// 最大流 - 取得 - １フロー
int
fGetMaxFlowOne(
	int piVSNo					// <I> 始点
	, int piVENo				// <I> 終点
	, int piFlow				// <I> 流量
)
{
	int i;

	// 処理済フラグ
	if (sz1Vtx[piVSNo].miDone != D_OFF) {
		return 0;
	}
	sz1Vtx[piVSNo].miDone = D_ON;

	// 到着チェック
	if (piVSNo == piVENo) {
		return piFlow;
	}

	// 移動
	for (i = 0; i < siVCnt; i++) {

		// 流量
		int liFlow = sz1Vtx[piVSNo].mi1Cap[i];
		if (liFlow < 1) {								// なし
			continue;
		}
		if (liFlow > piFlow) {
			liFlow = piFlow;
		}

		// 下位へ
		liFlow = fGetMaxFlowOne(i, piVENo, liFlow);
		if (liFlow < 1) {								// なし
			continue;
		}

		// 流量 - 加算・減算
		sz1Vtx[piVSNo].mi1Cap[i] -= liFlow;
		sz1Vtx[i].mi1Cap[piVSNo] += liFlow;

		return liFlow;
	}

	return 0;
}

// 最大流 - 取得
int
fGetMaxFlow(
	int piVSNo					// <I> 始点
	, int piVENo				// <I> 終点
)
{
	int i;

	int liSum = 0;
	while (1) {

		// 処理済フラグ - 初期化
		for (i = 0; i < siVCnt; i++) {
			sz1Vtx[i].miDone = D_OFF;
		}

		// １フロー - 取得
		int liFlow = fGetMaxFlowOne(piVSNo, piVENo, INT_MAX);
		if (liFlow < 1) {											// なし
			break;
		}

		// 流量 - 加算
		liSum += liFlow;
	}

	return liSum;
}

