					e[m+1].head = (i - 1) * W + j;
					e[m].tail = e[m+1].head;
					e[m+1].tail = e[m].head;
					e[m].flow = 0;
					e[m+1].flow = 0;
					e[m].cap = 1;
					e[m+1].cap = 1;
					d[m].id = m;
					d[m+1].id = m + 1;
					d[m].next = adj[e[m].tail];
					d[m+1].next = adj[e[m+1].tail];
					adj[e[m].tail] = &(d[m]);
					adj[e[m+1].tail] = &(d[m+1]);
					m += 2;
				}
			}
		}
	}
	if (s % W == t % W || (s - 1) / W == (t - 1) / W) {
		printf("-1\n");
		fflush(stdout);
		return 0;
	}

	int u, w, ans = 0, used[10001] = {}, prev[10001] = {}, q[10001], head, tail;
	list *p;
	q[0] = s;
	while (ans < H + W - 2) {
		for (head = 0, tail = 1; head < tail; head++) {
			u = q[head];
			for (p = adj[u]; p != NULL; p = p->next) {
				i = p->id;
				if (e[i].flow == e[i].cap || prev[e[i].head] != 0) continue;
				w = e[i].head;
				if (used[u] == 0 || used[e[prev[u]].tail] == 1 || e[i^1].flow == e[i^1].cap) {
					prev[w] = i;
					q[tail++] = w;
					if (w == t) break;
				}
			}
			if (p != NULL) break;
		}
		if (head == tail) break;
		else ans++;

		for (u = t; u != s; u = e[prev[u]].tail) {
			i = prev[u];
			if (e[i^1].flow == e[i^1].cap) e[i^1].flow--;
			else e[i].flow++;
		}
		for (tail--; tail > 0; tail--) prev[q[tail]] = 0;
		for (u = 1; u <= H * W; u++) {
			if (u == s || u == t) continue;
			for (p = adj[u]; p != NULL; p = p->next) if (e[p->id].flow > 0) break;
			if (p != NULL) used[u] = 1;
			else used[u] = 0;
		}
	}
	printf("%d\n", ans);
	fflush(stdout);
	return 0;
}

#include<stdio.h>
#include<stdlib.h>
#include<stdint.h>
#include<inttypes.h>
#include<string.h>

typedef int32_t flow_type;

const flow_type flow_inf=200;

typedef struct flow_edge{
  int vertex;
  int next;
  flow_type capacity;
} flow_edge;

typedef struct maxFlowGraph{
  flow_edge *edge;
  int *start;
  int vertex_num;
  int pointer;
  int edge_length;
} graph;

graph* newGraph(const int vertex_num){
  graph *g=(graph *)calloc(1,sizeof(graph));
  g->vertex_num=vertex_num;
  const int initial_length=4;
  g->edge=(flow_edge *)calloc(initial_length,sizeof(flow_edge));
  g->start=(int *)calloc(vertex_num,sizeof(int));
  g->pointer=0;
  g->edge_length=initial_length;
  for(int i=0;i<vertex_num;i++) g->start[i]=-1;
  return g;
}

void freeGraph(graph *g){
  free(g->edge);
  free(g->start);
  free(g);
}

void addEdge(graph *g,int from,int to,flow_type capa){
  if(g->pointer==g->edge_length){
    g->edge_length*=2;
    g->edge=(flow_edge *)realloc(g->edge,sizeof(flow_edge)*g->edge_length);
  }
  int p=g->pointer;
  g->edge[p]=(flow_edge){to,g->start[from],capa};
  g->start[from]=p;
  g->edge[p+1]=(flow_edge){from,g->start[to],0};
  g->start[to]=p+1;
  g->pointer+=2;
}

flow_type dinic_dfs(int v,graph *g,int dst,int *level,int *iter,flow_type e){
  if(v==dst) return e;
  for(int p=iter[v];p!=-1 && e>0;p=g->edge[p].next,iter[v]=p){
    int u=g->edge[p].vertex;
    flow_type capa=g->edge[p].capacity;
    if(level[u]<=level[v] || capa<=0) continue;
    flow_type f=dinic_dfs(u,g,dst,level,iter,capa<e?capa:e);
    if(f>0){
      g->edge[p].capacity-=f;
      g->edge[p^1].capacity+=f;
      return f;
    }
  }
  return 0;
}

flow_type dinic(const graph *input_graph,const int src,const int dst){
  const int vertex_num=input_graph->vertex_num;
  const int edge_num=input_graph->pointer;
  graph *g=(graph *)calloc(1,sizeof(graph));
  g->edge=(flow_edge *)malloc(sizeof(flow_edge)*edge_num);
  g->start=(int *)malloc(sizeof(int)*vertex_num);
  memcpy(g->edge,input_graph->edge,sizeof(flow_edge)*edge_num);
  memcpy(g->start,input_graph->start,sizeof(int)*vertex_num);
  int *level=(int *)calloc(vertex_num,sizeof(int));
  int *rvLevel=(int *)calloc(vertex_num,sizeof(int));
  int *queue=(int *)calloc(vertex_num,sizeof(int));
  int *iter=(int *)calloc(vertex_num,sizeof(int));
  flow_type flow=0;
  while(1){
    memset(level,0,sizeof(int)*vertex_num);
    int front=0,last=0;
    level[src]=1;
    queue[last++]=src;
    while(front<last && level[dst]==0){
      const int v=queue[front++];
      for(int p=g->start[v];p!=-1;p=g->edge[p].next){
	int u=g->edge[p].vertex;
	if(g->edge[p].capacity>0 && level[u]==0){
	  level[u]=level[v]+1;
	  queue[last++]=u;
	}
      }
    }
    if(level[dst]==0) break;
    memset(rvLevel,0,sizeof(int)*vertex_num);
    front=last=0;
    rvLevel[dst]=1;
    queue[last++]=dst;
    while(rvLevel[src]==0){
      const int v=queue[front++];
      for(int p=g->start[v];p!=-1;p=g->edge[p].next){
	const int u=g->edge[p].vertex;
	if(g->edge[p^1].capacity>0 && rvLevel[u]==0){
	  rvLevel[u]=rvLevel[v]+1;
	  queue[last++]=u;
	}
      }
    }
    for(int i=0;i<vertex_num;i++){
      if(level[i]>0 && level[i]+rvLevel[i]!=level[dst]+1){
	level[i]=0;
      }
    }
    memcpy(iter,g->start,sizeof(int)*vertex_num);
    while(1){
      flow_type f=dinic_dfs(src,g,dst,level,iter,flow_inf);
      if(f<=0) break;
      flow+=f;
    }
  }
  freeGraph(g);
  free(level);
  free(rvLevel);
  free(queue);
  free(iter);
  return flow;
}

typedef int32_t i32;

void run (void) {
  i32 h, w;
  scanf ("%" SCNi32 "%" SCNi32, &h, &w);
  char *a = (char *) calloc (h * w + 1, sizeof (char));
  for (i32 i = 0; i < h; ++i) {
    scanf ("%s", a + i * w);
  }
  graph *g = newGraph (2 * h * w + 2);
  i32 src = 2 * h * w;
  i32 dst = src + 1;
  for (i32 i = 0; i < h; ++i) {
    for (i32 j = 0; j < w; ++j) {
      if (a[i * w + j] == '.') continue;
      if (a[i * w + j] == 'S') {
	addEdge (g, src, i * w + j, flow_inf);
	addEdge (g, h * w + i * w + j, i * w + j, flow_inf);
      } else if (a[i * w + j] == 'T') {
	addEdge (g, i * w + j, dst, flow_inf);
	addEdge (g, h * w + i * w + j, i * w + j, flow_inf);
      } else {
	addEdge (g, h * w + i * w + j, i * w + j, 1);
      }
      for (i32 k = 0; k < h; ++k) {
	if (k == i || a[k * w + j] == '.') continue;
	addEdge (g, i * w + j, h * w + k * w + j, flow_inf);
      }
      for (i32 k = 0; k < w; ++k) {
	if (k == j || a[i * w + k] == '.') continue;
	addEdge (g, i * w + j, h * w + i * w + k, flow_inf);
      }
    }
  }
  i32 ans = dinic (g, src, dst);
  if (ans >= flow_inf) {
    puts("-1");
  } else {
    printf ("%" PRIi32 "\n",ans);
  }
}

int main (void) {
  run ();
  return 0;
}

