			if (u == s || u == t) continue;
			for (p = adj[u]; p != NULL; p = p->next) if (e[p->id].flow > 0) break;
			if (p != NULL) used[u] = 1;
			else used[u] = 0;
		}
	}
	printf("%d\n", ans);
	fflush(stdout);
	return 0;
}

#include <stdio.h>
