#define N	100
#define M	100
#define N_	(1 + N + M + 1)
#define M_	(2 + N * M + 2)

int *oh[N_], oo[N_], n_;
int ij[M_], cc[M_], m_;

void link(int i, int h) {
	int o = oo[i]++;

	if (o >= 2 && (o & o - 1) == 0)
		oh[i] = (int *) realloc(oh[i], o * 2 * sizeof *oh[i]);
	oh[i][o] = h;
}

void link_(int i, int j, int c1, int c2) {
	int h = m_++;

	ij[h] = i ^ j, cc[h << 1] = c1, cc[h << 1 | 1] = c2;
	link(i, h << 1), link(j, h << 1 | 1);
}

int dd[N_];

int bfs(int s, int t) {
	static int qu[N_];
	int i, head, cnt;

	for (i = 0; i < n_; i++)
		dd[i] = n_;
	head = cnt = 0;
	dd[s] = 0, qu[head + cnt++] = s;
	while (cnt) {
		int d, o;

		i = qu[cnt--, head++], d = dd[i] + 1;
		for (o = 0; o < oo[i]; o++) {
			int h_ = oh[i][o];

			if (cc[h_]) {
				int h = h_ >> 1, j = i ^ ij[h];

				if (dd[j] > d) {
					dd[j] = d;
					if (j == t)
						return 1;
					qu[head + cnt++] = j;
				}
			}
		}
	}
	return 0;
}

int dfs(int i, int t) {
	int d, o;

	if (i == t)
		return 1;
	d = dd[i] + 1;
	for (o = 0; o < oo[i]; o++) {
		int h_ = oh[i][o];

		if (cc[h_]) {
			int h = h_ >> 1, j = i ^ ij[h];

			if (dd[j] == d && dfs(j, t)) {
				cc[h_]--, cc[h_ ^ 1]++;
				return 1;
			}
		}
	}
	dd[i] = n_;
	return 0;
}

int dinic(int s, int t) {
	int sum;

	sum = 0;
	while (bfs(s, t))
		while (dfs(s, t))
			sum++;
	return sum;
}

int main() {
	static char cc[N][M + 1];
	int n, m, i, j, is, js, it, jt;

	scanf("%d%d", &n, &m), n_ = 1 + n + m + 1;
	for (i = 0; i < n; i++)
		scanf("%s", cc[i]);
	for (i = 0; i < n_; i++)
		oh[i] = (int *) malloc(2 * sizeof *oh[i]);
	is = js = it = jt = 0;
	for (i = 0; i < n; i++)
		for (j = 0; j < m; j++) {
			if (cc[i][j] == '.')
				continue;
			link_(1 + i, 1 + n + j, 1, 1);
			if (cc[i][j] == 'S')
				is = i, js = j;
			else if (cc[i][j] == 'T')
				it = i, jt = j;
		}
	if (is == it || js == jt) {
		printf("-1\n");
		return 0;
	}
	link_(0, 1 + is, n * m + 1, 0);
	link_(0, 1 + n + js, n * m + 1, 0);
	link_(1 + it, n_ - 1, n * m + 1, 0);
	link_(1 + n + jt, n_ - 1, n * m + 1, 0);
	printf("%d\n", dinic(0, n_ - 1));
	return 0;
}

