            for(int j=0;j<w;++j){
                int src=2+h+j;
                int dst=2+h+w+2*(i*w+j);
                add(g,src,dst,I);
            }
        // vertex->row/col
        for(int i=0;i<h;++i)
            for(int j=0;j<w;++j){
                int src=2+h+w+2*(i*w+j)+1;
                int dst=2+i;
                add(g,src,dst,I);
            }
        for(int i=0;i<h;++i)
            for(int j=0;j<w;++j){
                int src=2+h+w+2*(i*w+j)+1;
                int dst=2+h+j;
