class Main {

	public static void main(String[] args) {
		final Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		char[][] a = new char[h][w];
		for (int i = 0; i < h; i++) {
			a[i] = sc.next().toCharArray();
		}

		for (int i = 0; i < h; i++) {
			int count = 0;
			for (int j = 0; j < w; j++) {
				if (a[i][j] == 'S' || a[i][j] == 'T') count++;
			}
			if (count >= 2) {
				System.out.println(-1);
				return;
			}
		}


		for (int j = 0; j < w; j++) {
			int count = 0;
			for (int i = 0; i < h; i++) {
				if (a[i][j] == 'S' || a[i][j] == 'T') count++;
			}
			if (count >= 2) {
				System.out.println(-1);
				return;
			}
		}

		Dinic dinic = new Dinic(h + w + 2);
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				switch (a[i][j]) {
					case '.':
						break;
					case 'o':
						dinic.addEdge(i, h + j, 1);
						dinic.addEdge(h + j, i, 1);
						break;
					case 'S':
						dinic.addEdge(h + w, h + j, Integer.MAX_VALUE);
						dinic.addEdge(h + w, i, Integer.MAX_VALUE);
						break;
					case 'T':
						dinic.addEdge(h + j, h + w + 1, Integer.MAX_VALUE);
						dinic.addEdge(i, h + w + 1, Integer.MAX_VALUE);
						break;
				}
			}
		}

		long f = dinic.maxFlow(h + w, h + w + 1);
		System.out.println(f);
	}

	static class Dinic {
		private List<Edge>[] g;
		private int[] level;
		private int[] iterator;

		class Edge {
			int to;
			int cap;
			int residualId;

			public Edge(int to, int cap, int residualId) {
				this.to = to;
				this.cap = cap;
				this.residualId = residualId;
			}
		}

		public Dinic(int n) {
			g = new ArrayList[n];
			level = new int[n];
			iterator = new int[n];
			for (int i = 0; i < g.length; i++) {
				g[i] = new ArrayList<>();
			}
		}

		public void addEdge(int from, int to, int cap) {
			g[from].add(new Edge(to, cap, g[to].size()));
			g[to].add(new Edge(from, 0, g[from].size() - 1)); // residual path
		}

		public long maxFlow(int s, int t) {
			long flow = 0;
			while (true) {
				bfs(s);
				if (level[t] < 0) break;
				Arrays.fill(iterator, 0);
				while (true) {
					long f = dfs(s, t, Long.MAX_VALUE);
					if (f == 0) break;
					flow += f;
				}
			}
			return flow;
		}

		private void bfs(int s) {
			Arrays.fill(level, -1);
			Queue<Integer> q = new LinkedList<>();
			level[s] = 0;
			q.offer(s);
			while (!q.isEmpty()) {
				int v = q.poll();
				for (int i = 0; i < g[v].size(); i++) {
					Edge e = g[v].get(i);
					if (e.cap > 0 && level[e.to] < 0) {
						level[e.to] = level[v] + 1;
						q.offer(e.to);
					}

				}
			}
		}

		private long dfs(int s, int t, long f) {
			if (s == t) return f;
			for (int i = iterator[s]; i < g[s].size(); i = ++iterator[s]) {
				Edge e = g[s].get(i);
				if (e.cap > 0 && level[s] < level[e.to]) {
					long d = dfs(e.to, t, Math.min(e.cap, f));
					if (d > 0) {
						e.cap -= d;
						g[e.to].get(e.residualId).cap += d;
						return d;
					}
				}
			}
			return 0;
		}
	}
}

import java.util.*;

public class Main {
	static class MaxFlow {
		//dinic
		public class Edge {
			int to, cap, rev;

			public Edge(int to, int cap, int rev) {
				this.to = to;
				this.cap = cap;
				this.rev = rev;
			}
		}

		int V;
		ArrayList<ArrayList<Edge>> G;
		int[] level;
		int[] iter;
		public final int INF = 1000000000;

		public MaxFlow(int V) {
			this.V = V;
			G = new ArrayList<ArrayList<Edge>>();
			for(int i=0; i<V; i++)
				G.add(new ArrayList<Edge>());
			level = new int[V];
			iter = new int[V];
		}

		public void addEdge(int from, int to, int cap) {
			G.get(from).add(new Edge(to, cap, G.get(to).size()));
			G.get(to).add(new Edge(from, 0, G.get(from).size()-1));
		}

		void bfs(int s) {
			Arrays.fill(level, -1);
			Queue<Integer> que = new LinkedList<Integer>();
			level[s] = 0;
			que.add(s);
			while(!que.isEmpty()) {
				int v = que.remove();
				for(int i=0; i<G.get(v).size(); i++) {
					Edge e = G.get(v).get(i);
					if(e.cap>0 && level[e.to]<0) {
						level[e.to] = level[v] + 1;
						que.add(e.to);
					}
				}
			}
		}

		int dfs(int v, int t, int f) {
			if(v==t) return f;
			for(; iter[v]<G.get(v).size(); iter[v]++) {
				Edge e = G.get(v).get(iter[v]);
				if(e.cap>0 && level[v] < level[e.to]) {
					int d = dfs(e.to, t, Math.min(f, e.cap));
					if(d>0) {
						e.cap -= d;
						G.get(e.to).get(e.rev).cap += d;
						return d;
					}
				}
			}
			return 0;
		}

		int getMaxFlow(int s, int t) {
			int flow = 0;
			while(true) {
				bfs(s);
				if(level[t]<0)
					return flow;

				Arrays.fill(iter, 0);
				int f;
				while((f = dfs(s, t, INF)) > 0) {
					flow += f;
				}
			}
		}
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int H = sc.nextInt();
		int W = sc.nextInt();

		boolean[][] leaf = new boolean[H][W];
		int sx=0,sy=0,tx=0,ty=0;
		for(int i=0; i<H; i++) {
			char[] c = sc.next().toCharArray();
			for(int j=0; j<W; j++) {
				if(c[j]!='.') {
					leaf[i][j] = true;
					if(c[j]=='S') {
						sy = i;
						sx = j;
					} else if(c[j]=='T') {
						ty = i;
						tx = j;
					}
				}
			}
		}
		if(sx==tx || sy==ty) {
			System.out.println(-1);
			sc.close();
			return;
		}

		MaxFlow mf = new MaxFlow(H*W*2);

		for(int i=0; i<H; i++) {
			ArrayList<Integer> list = new ArrayList<>();
			for(int j=0; j<W; j++)
				if(leaf[i][j])
					list.add(j);
			for(int j : list)
				for(int k : list)
					if(j!=k)
						mf.addEdge((i*W+j)*2+1, (i*W+k)*2, 1);
		}
		for(int i=0; i<W; i++) {
			ArrayList<Integer> list = new ArrayList<>();
			for(int j=0; j<H; j++)
				if(leaf[j][i])
					list.add(j);
			for(int j : list)
				for(int k : list)
					if(j!=k)
						mf.addEdge((j*W+i)*2+1, (k*W+i)*2, 1);
		}
		for(int i=0; i<H; i++) {
			for(int j=0; j<W; j++)
				if(leaf[i][j])
					mf.addEdge((i*W+j)*2, (i*W+j)*2+1, 1);
		}

		System.out.println(mf.getMaxFlow((sy*W+sx)*2+1, (ty*W+tx)*2));
		sc.close();
	}
}

