import java.io.InputStream;
import java.util.Arrays;
import java.util.BitSet;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    public static void main(String[] args) throws Exception {
        ExtendedScanner sc = new ExtendedScanner();
        FastPrintStream pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(ExtendedScanner sc, FastPrintStream pw) {
        int h = sc.nextInt();
        int w = sc.nextInt();
        int si = -1, sj = -1, ti = -1, tj = -1;
        BitSet[] grid = new BitSet[w];
        for (int i = 0; i < h; i++) {
            grid[i] = new BitSet();
            char[] gi = sc.nextChars();
            for (int j = 0; j < w; j++) {
                if (gi[j] == 'S') {
                    si = i; sj = j;
                    grid[i].set(j);
                } else if (gi[j] == 'T') {
                    ti = i; tj = j;
                    grid[i].set(j);
                } else if (gi[j] == 'o') {
                    grid[i].set(j);
                }
            }
        }
        int hw = h * w;
        int s = si * w + sj;
        int t = ti * w + tj + hw;
        Digraph<CapEdge> g = new Digraph<>(2 * h * w);
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (!grid[i].get(j)) continue;
                int u = i * w + j;
                g.addEdge(new CapEdge(u + hw, u, 1));
                for (int r = 0; r < h; r++) {
                    if (r == i) continue;
                    if (grid[r].get(j)) {
                        g.addEdge(new CapEdge(u, r * w + j + hw, hw));
                    }
                }
                for (int c = 0; c < w; c++) {
                    if (c == j) continue;
                    if (grid[i].get(c)) {
                        g.addEdge(new CapEdge(u, i * w + c + hw, hw));
                    }
                }
            }
        }
        MaxFlow mf = new MaxFlow(g);
        int flow = mf.flow(s, t, hw);
        pw.println(flow >= hw ? -1 : flow);
    }
}

