	int gen() {
		final int LEAF = -4;
		final int LINE = -1;
		final int NONE = -2;
		final int INVALID = -3;
		int[][] mp2 = new int[2*h+1][2*w+1];
		int[][] mp3 = new int[2*h+1][2*w+1];
		for (int[] m : mp2) Arrays.fill(m, NONE);
