	void make_graph(V[][][] vs) {
		int[] q = new int[H * W * 2];
		boolean[][] vis = new boolean[H][W];

		int a = 0, b = 0;
		q[b++] = 0;
		q[b++] = 0;
		vis[0][0] = true;
		while (a < b) {
			int r = q[a++];
			int c = q[a++];
			if (s[r][c] == 'T') continue;
			for (int i = 0; i < H; i++) if (s[i][c] == 'o' || s[i][c] == 'T') {
				vs[r][c][1].add(vs[i][c][0], INF);
				if (!vis[i][c]) {
					vis[i][c] = true;
					q[b++] = i; q[b++] = c;
				}
			}
			for (int j = 0; j < W; j++) if (s[r][j] == 'o' || s[r][j] == 'T') {
				vs[r][c][1].add(vs[r][j][0], INF);
				if (!vis[r][j]) {
					vis[r][j] = true;
					q[b++] = r; q[b++] = j;
				}
				dfs(r, j, vis);
			}
		}
	}

	void dfs(int r, int c, boolean[][] vis) {
		if (vis[r][c]) return;
		vis[r][c] = true;
		for (int i = 0; i < H; i++) if (s[i][c] == 'o') {
			dfs(i, c, vis);
		}
		for (int j = 0; j < W; j++) if (s[r][j] == 'o') {
			dfs(r, j, vis);
		}
	}

	static final int INF = 1001001001;


	int dinic(V s, V t) {
		int flow = 0;
		for (int p = 1;; p++) {
			Queue<V> que = new LinkedList<V>();
			s.level = 0;
			s.p = p;
			que.offer(s);
			while (!que.isEmpty()) {
				V v = que.poll();
				v.iter = v.es.size() - 1;
				for (E e : v.es)
					if (e.to.p < p && e.cap > 0) {
						e.to.level = v.level + 1;
						e.to.p = p;
						que.offer(e.to);
					}
			}
			if (t.p < p) return flow;
			for (int f; (f = dfs(s, t, INF)) > 0;) flow += f;
		}
	}

	int dfs(V v, V t, int f) {
		if (v == t) return f;
		for (; v.iter >= 0; v.iter--) {
			E e = v.es.get(v.iter);
			if (v.level < e.to.level && e.cap > 0) {
				int d = dfs(e.to, t, Math.min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					e.rev.cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	class V {
		ArrayList<E> es = new ArrayList<E>();
		int level, p, iter;

		void add(V to, int cap) {
			E e = new E(to, cap);
			E rev = new E(this, 0);
			e.rev = rev;
			rev.rev = e;
			es.add(e);
			to.es.add(rev);
		}
	}

	class E {
		V to;
		E rev;
		int cap;

		E(V to, int cap) {
			this.to = to;
			this.cap = cap;
		}
	}
