                    {
                        fd.AddEdge(i * W + o[f], i * W + o[t] + L, INF);
                        fd.AddEdge(i * W + o[t], i * W + o[f] + L, INF);
                    }
                }
            }
            for (int i = 0; i < W; i++)
            {
                List<int> o = new List<int>();
                for (int j = 0; j < H; j++)
                {
                    if (map[j, i] == 'o' || map[j, i] == 'S' || map[j, i] == 'T') o.Add(j);
                }

                //エッジ追加
                for (int f = 0; f < o.Count; f++)
                {
                    for (int t = f + 1; t < o.Count; t++)
                    {
                        fd.AddEdge(o[f] * W + i, o[t] * W + i + L, INF);
                        fd.AddEdge(o[t] * W + i, o[f] * W + i + L, INF);
                    }
                }
            }

            var ans = fd.MaxFlow(sh * W + sw, th * W + tw + L);
            if (sh == th || sw == tw) ans = -1;

            Console.WriteLine(ans);
            Console.ReadKey();
        }

        static int[] ReadInt()
        {
            int[] ret = Console.ReadLine().Split().Select(int.Parse).ToArray();
            return ret;
        }
        static long[] ReadLong()
        {
            long[] ret = Console.ReadLine().Split().Select(long.Parse).ToArray();
            return ret;
        }
    }
    class FordFulkerson//最大流
    {
        public struct Edge
        {
            public int to, cap, rev;
        }

        public List<Edge>[] G;
        bool[] used;
        int INF = 1000000009;

        public FordFulkerson(int V) //頂点数
        {
            G = new List<Edge>[V].Select(x => new List<Edge>()).ToArray();
            used = new bool[V];
        }

        public void AddEdge(int from, int to, int cap)
        {
            G[from].Add(new Edge() { to = to, cap = cap, rev = G[to].Count });
            G[to].Add(new Edge() { to = from, cap = 0, rev = G[from].Count - 1 });
        }

        int Dfs(int v, int t, int f)
        {
            if (v == t)
                return f;
            used[v] = true;

            for (int i = 0; i < G[v].Count; i++)
            {
                var e = G[v][i];
                if (!used[e.to] && e.cap > 0)
                {
                    int d = Dfs(e.to, t, Math.Min(f, e.cap));
                    if (d > 0)
                    {
                        e.cap -= d;
                        G[v][i] = e;

                        var temp = G[e.to][e.rev];
                        temp.cap += d;
                        G[e.to][e.rev] = temp;

                        return d;
                    }
                }
            }
            return 0;
        }

        public int MaxFlow(int s, int t)
        {
            int flow = 0;
            while (true)
            {
                used = new bool[used.Length];
                int f = Dfs(s, t, INF);
                if (f == 0) return flow;
                flow += f;
            }
        }
    }
}

