		for(int i=0;i<n;i++){
			li[i]=new List<int>();
			h[i]=new Dictionary<int,int>();
		}
	}
	public void Edge1(int a,int b,int c){
		li[a].Add(b);
		li[b].Add(a);
		h[a].Add(b,c);
		h[b].Add(a,0);
	}
	public int Dinic(int st,int gl){
		this.gl=gl;
		ans=0;
		int z=1;
		while(z>0){
			l=new int[n];
			var qu=new Queue<Tuple<int,int>>();
			qu.Enqueue(Tuple.Create(st,1));
			l[st]=1;
			while(qu.Count>0){
				var e=qu.Dequeue();
				for(int i=0;i<li[e.Item1].Count;i++){
					if(l[li[e.Item1][i]]==0&&h[e.Item1][li[e.Item1][i]]!=0){
						l[li[e.Item1][i]]=e.Item2+1;
						qu.Enqueue(Tuple.Create(li[e.Item1][i],e.Item2+1));
					}
				}
			}
			b=new bool[n];
			z=Fu3(st,int.MaxValue);
			ans+=z;
		}
		return ans;
	}
	private int Fu3(int a,int p){
		if(a==gl){return p;}
		int u=0;
		for(int i=0;i<li[a].Count&&p>u;i++){
			if(!b[li[a][i]]&&l[li[a][i]]>l[a]&&h[a][li[a][i]]!=0){
				int z=Fu3(li[a][i],Min(p-u,h[a][li[a][i]]));
				h[a][li[a][i]]-=z;
				h[li[a][i]][a]+=z;
				u+=z;

			}
		}
		if(u==0){b[a]=true;}
		return u;
	}
