		ans=0;
		int z=1;
		while(z>0){
			b2=new int[n];
			z=Fu2(st,int.MaxValue);
			ans+=z;
		}
		return ans;
	}
	private int Fu2(int a,int p){
		if(a==gl){return p;}
		int u=0;
		b2[a]|=1;
		for(int i=0;i<li[a].Count&&p>u;i++){
