				int z=Fu2(li[a][i],Min(p-u,h[a][li[a][i]]));
				h[a][li[a][i]]-=z;
				h[li[a][i]][a]+=z;
				u+=z;

			}
		}
		b2[a]&=-2;
		if(u==0){b2[a]=2;}
		return u;
	}
	private void Fu1(int a,int g,int p){
		b[a]=true;
		r[g]=a;
		if(a==gl){
			for(int i=0;i<g;i++){
				h[r[i]][r[i+1]]-=p;
				h[r[i+1]][r[i]]+=p;
			}
			ans+=p;
			bo=false;
			return;
		}
		for(int i=0;i<li[a].Count&&bo;i++){
			if(!b[li[a][i]]&&h[a][li[a][i]]!=0){Fu1(li[a][i],g+1,Min(p,h[a][li[a][i]]));}
		}
	}
}

