                    else { G.AddDirectedEdge(i * m + j, n * m + i * m + j, 1); }
                    G.AddDirectedEdge(n * m + i * m + j, 2 * n * m + i, 1000000000);
                    G.AddDirectedEdge(2 * n * m + i, i * m + j, 1000000000);
                    G.AddDirectedEdge(n * m + i * m + j, 2 * n * m + n + j, 1000000000);
                    G.AddDirectedEdge(2 * n * m + n + j, i * m + j, 1000000000);
                }
