	{
		N2 = 1;
		while (N2 < a.Length) N2 <<= 1;
		seg = new long[2 * N2 - 1];
		unif = new long[2 * N2 - 1];
		for (var i = a.Length + N2 - 1; i < 2 * N2 - 1; i++) seg[i] = Unit;
		for (var i = 0; i < a.Length; i++) seg[i + N2 - 1] = a[i];
		for (var i = N2 - 2; i >= 0; i--) Update(i);
	}
