						if (i == s.i) {
							Flow.AddEdge(edges, h + w, i, inf);
						}

						if (j == s.j) {
							Flow.AddEdge(edges, h + w, h + j, inf);
						}

						if (i == t.i) {
							Flow.AddEdge(edges, i, h + w + 1, inf);
						}

						if (j == t.j) {
							Flow.AddEdge(edges, h + j, h + w + 1, inf);
						}
					}
				}
			}

			long ans = Flow.GetMaxFlowByDinic(n, edges, h + w, h + w + 1);
			Console.WriteLine(ans);
		}
