	public static class Flow
	{
		private static readonly long INF = long.MaxValue;

		public static void AddEdge(List<Flow.Edge>[] edges, int from, int to, long capacity, long cost = 1)
		{
			edges[from].Add(new Edge(to, capacity, cost, edges[to].Count));
			edges[to].Add(new Edge(from, 0, -1 * cost, edges[from].Count - 1));
		}

		public static long GetMaxFlowByFordFulkerson(int n, List<Flow.Edge>[] edges, int s, int t)
		{
			long flow = 0;
			while (true) {
				var done = new bool[n];
				long f = DfsOfFordFulkerson(edges, s, t, INF, done);
				if (f == 0 || f == INF) {
					break;
				}

				flow += f;
			}

			return flow;
		}

		private static long DfsOfFordFulkerson(List<Flow.Edge>[] edges, int s, int t, long f, bool[] done)
		{
			if (s == t) {
				return f;
			}

			done[s] = true;
			foreach (var edge in edges[s]) {
				if (done[edge.To] == false && edge.Capacity > 0) {
					long d = DfsOfFordFulkerson(edges, edge.To, t, Math.Min(f, edge.Capacity), done);
					if (d > 0) {
						edge.Capacity -= d;
						edges[edge.To][edge.ReverseEdgeIndex].Capacity += d;
						return d;
					}
				}
			}

			return 0;
		}

		public static long GetMaxFlowByDinic(int n, List<Flow.Edge>[] edges, int s, int t)
		{
			long flow = 0;
			while (true) {
				var distance = BfsOfDinic(n, edges, s);
				if (distance[t] < 0) {
					break;
				}

				var done = new int[n];
				while (true) {
					long f = DfsOfDinic(n, edges, s, t, INF, done, distance);
					if (f == 0 || f == INF) {
						break;
					}

					flow += f;
				}
			}

			return flow;
		}

		private static long[] BfsOfDinic(int n, List<Flow.Edge>[] edges, int s)
		{
			var d = new long[n];
			for (int i = 0; i < n; i++) {
				d[i] = -1;
			}

			var q = new Queue<int>();
			d[s] = 0;
			q.Enqueue(s);
			while (q.Count > 0) {
				int v = q.Dequeue();
				foreach (var edge in edges[v]) {
					if (edge.Capacity > 0 && d[edge.To] < 0) {
						d[edge.To] = d[v] + 1;
						q.Enqueue(edge.To);
					}
				}
			}

			return d;
		}

		private static long DfsOfDinic(
			int n, List<Flow.Edge>[] edges, int s, int t, long f, int[] done, long[] distance)
		{
			if (s == t) {
				return f;
			}

			for (; done[s] < edges[s].Count; done[s]++) {
				var edge = edges[s][done[s]];
				if (edge.Capacity > 0 && distance[s] < distance[edge.To]) {
					long d = DfsOfDinic(n, edges, edge.To, t, Math.Min(f, edge.Capacity), done, distance);
					if (d > 0) {
						edge.Capacity -= d;
						edges[edge.To][edge.ReverseEdgeIndex].Capacity += d;
						return d;
					}
				}
			}

			return 0;
		}

		public static long GetMinCostFlowByBellmanFord(int n, List<Flow.Edge>[] edges, int s, int t, long f)
		{
			var prevVertexes = new int[n];
			var prevEdgeIndexes = new int[n];

			long minCost = 0;
			while (f > 0) {
				var distances = new long[n];
				for (int i = 0; i < n; i++) {
					distances[i] = INF;
				}

				distances[s] = 0;
				for (int i = 0; i < n; i++) {
					bool changes = false;
					for (int v = 0; v < n; v++) {
						if (distances[v] == INF) {
							continue;
						}

						for (int j = 0; j < edges[v].Count; j++) {
							var edge = edges[v][j];
							long newDistance = distances[v] + edge.Cost;
							if (edge.Capacity > 0 && distances[edge.To] > newDistance) {
								distances[edge.To] = newDistance;
								prevVertexes[edge.To] = v;
								prevEdgeIndexes[edge.To] = j;
								changes = true;
							}
						}
					}

					if (i == n - 1 && changes) {
						return -1;
					}

					if (changes == false) {
						break;
					}
				}

				if (distances[t] == INF) {
					return -1;
				}

				long d = f;
				for (int v = t; v != s; v = prevVertexes[v]) {
					d = Math.Min(d, edges[prevVertexes[v]][prevEdgeIndexes[v]].Capacity);
				}

				f -= d;
				minCost += d * distances[t];
				for (int v = t; v != s; v = prevVertexes[v]) {
					edges[prevVertexes[v]][prevEdgeIndexes[v]].Capacity -= d;
					edges[v][edges[prevVertexes[v]][prevEdgeIndexes[v]].ReverseEdgeIndex].Capacity += d;
				}
			}

			return minCost;
		}

		public static long GetMinCostFlowByDijkstra(int n, List<Flow.Edge>[] edges, int s, int t, long f)
		{
			var potentials = new long[n];
			var prevVertexes = new int[n];
			var prevEdgeIndexes = new int[n];

			long minCost = 0;
			while (f > 0) {
				var distances = new long[n];
				for (int i = 0; i < n; i++) {
					distances[i] = INF;
				}

				distances[s] = 0;
				var pq = new PriorityQueueP<long, int>(true);
				pq.Enqueue(0, s);
				while (pq.Count > 0) {
					var current = pq.Dequeue();
					int v = current.Item;
					if (distances[v] < current.Priority) {
						continue;
					}

					for (int j = 0; j < edges[v].Count; j++) {
						var edge = edges[v][j];
						long newDistance = distances[v] + edge.Cost + potentials[v] - potentials[edge.To];
						if (edge.Capacity > 0 && distances[edge.To] > newDistance) {
							distances[edge.To] = newDistance;
							prevVertexes[edge.To] = v;
							prevEdgeIndexes[edge.To] = j;
							pq.Enqueue(newDistance, edge.To);
						}
					}
				}

				if (distances[t] == INF) {
					return -1;
				}

				for (int v = 0; v < n; v++) {
					potentials[v] += distances[v];
				}

				long d = f;
				for (int v = t; v != s; v = prevVertexes[v]) {
					d = Math.Min(d, edges[prevVertexes[v]][prevEdgeIndexes[v]].Capacity);
				}

				f -= d;
				minCost += d * potentials[t];
				for (int v = t; v != s; v = prevVertexes[v]) {
					edges[prevVertexes[v]][prevEdgeIndexes[v]].Capacity -= d;
					edges[v][edges[prevVertexes[v]][prevEdgeIndexes[v]].ReverseEdgeIndex].Capacity += d;
				}
			}

			return minCost;
		}

