				var e=qu.Dequeue();
				for(int i=0;i<li[e.Item1].Count;i++){
					if(l[li[e.Item1][i]]==0&&h[e.Item1][li[e.Item1][i]]!=0){
						l[li[e.Item1][i]]=e.Item2+1;
						qu.Enqueue(Tuple.Create(li[e.Item1][i],e.Item2+1));
					}
				}
			}
			b=new bool[n];
			z=Fu3(st,int.MaxValue);
			ans+=z;
		}
		return ans;
	}
	private int Fu3(int a,int p){
		if(a==gl){return p;}
		int u=0;
		for(int i=0;i<li[a].Count&&p>u;i++){
			if(!b[li[a][i]]&&l[li[a][i]]>l[a]&&h[a][li[a][i]]!=0){
				int z=Fu3(li[a][i],Min(p-u,h[a][li[a][i]]));
				h[a][li[a][i]]-=z;
				h[li[a][i]][a]+=z;
				u+=z;

			}
		}
		if(u==0){b[a]=true;}
		return u;
	}
	public int Ff(int st,int gl){
		this.gl=gl;
		ans=0;
		while(!bo){
			b=new bool[n];
			bo=true;
			Fu1(st,0,int.MaxValue);
		}
		return ans;
	}
	public int Ff2(int st,int gl){
		this.gl=gl;
		ans=0;
		int z=1;
		while(z>0){
			b2=new int[n];
			z=Fu2(st,int.MaxValue);
			ans+=z;
		}
		return ans;
	}
	private int Fu2(int a,int p){
		if(a==gl){return p;}
		int u=0;
		b2[a]|=1;
		for(int i=0;i<li[a].Count&&p>u;i++){
			if(b2[li[a][i]]==0&&h[a][li[a][i]]!=0){
				int z=Fu2(li[a][i],Min(p-u,h[a][li[a][i]]));
				h[a][li[a][i]]-=z;
				h[li[a][i]][a]+=z;
				u+=z;

			}
		}
		b2[a]&=-2;
		if(u==0){b2[a]=2;}
		return u;
	}
	private void Fu1(int a,int g,int p){
		b[a]=true;
		r[g]=a;
		if(a==gl){
			for(int i=0;i<g;i++){
				h[r[i]][r[i+1]]-=p;
				h[r[i+1]][r[i]]+=p;
			}
			ans+=p;
			bo=false;
			return;
		}
		for(int i=0;i<li[a].Count&&bo;i++){
			if(!b[li[a][i]]&&h[a][li[a][i]]!=0){Fu1(li[a][i],g+1,Min(p,h[a][li[a][i]]));}
		}
	}
}

