				if (a[i][j] == 'o')
				{
					dag.Add(new[] { i + 1, h + j + 1, 1L });
					dag.Add(new[] { h + j + 1, i + 1, 1L });
				}
				else if (a[i][j] == 'S')
				{
					s = (i, j);
					dag.Add(new[] { 0, i + 1, 1L << 60 });
