public class Flow{
	private List<int>[] li;
	private Dictionary<int,int>[] h;
	private bool[] b;
	private int[] l;
	private int n,ans,go;
	private const int inf=int.MaxValue;
	public Flow(int n){
		this.n=n;
		li=new List<int>[n];
		h=new Dictionary<int,int>[n+1];
		for(int i=0;i<n;i++){
			li[i]=new List<int>();
			h[i]=new Dictionary<int,int>();
		}
	}
	public void Edge(int a,int b,int c){
		//if(!h[a].ContainsKey(b)){
			li[a].Add(b);
			li[b].Add(a);
			h[a].Add(b,c);
			h[b].Add(a,0);
		//}
		//else{h[a][b]=c;}
	}
	public int Dinic(int st,int go){
		this.go=st;
		ans=0;
		int z=1;
		while(z>0){
			l=new int[n];
			var qu=new Queue<Tuple<int,int>>();
			qu.Enqueue(Tuple.Create(st,1));
			l[st]=1;
			while(qu.Count>0){
				var e=qu.Dequeue();
				for(int i=0;i<li[e.Item1].Count;i++){
					if(l[li[e.Item1][i]]==0&&h[e.Item1][li[e.Item1][i]]!=0){
						l[li[e.Item1][i]]=e.Item2+1;
						qu.Enqueue(Tuple.Create(li[e.Item1][i],e.Item2+1));
					}
				}
				if(e.Item1==go){break;}
			}
			b=new bool[n];
			z=Fu3(go,inf);
			ans+=z;
		}
		return ans;
	}
	private int Fu3(int a,int p){
		if(a==go){return p;}
		int u=0;
		for(int i=0;i<li[a].Count&&p>u;i++){
			if(!b[li[a][i]]&&l[li[a][i]]<l[a]&&h[li[a][i]][a]!=0){
				int z=Fu3(li[a][i],Min(p-u,h[li[a][i]][a]));
				h[li[a][i]][a]-=z;
				h[a][li[a][i]]+=z;
				u+=z;
			}
		}
		if(u==0){b[a]=true;}
		return u;
	}
	public int Ff(int st,int go){
		this.go=go;
		ans=0;
		int z=1;
		while(z>0){
			b=new bool[n];
			z=Fu2(st,inf);
			ans+=z;
		}
		return ans;
	}
	private int Fu2(int a,int p){
		if(a==go){return p;}
		int u=0;
		b[a]=true;
		for(int i=0;i<li[a].Count&&p>u;i++){
			if(!b[li[a][i]]&&h[a][li[a][i]]!=0){
				int z=Fu2(li[a][i],Min(p-u,h[a][li[a][i]]));
				h[a][li[a][i]]-=z;
				h[li[a][i]][a]+=z;
				u+=z;
			}
		}
		if(u!=0){b[a]=false;}
		return u;
	}
}

