using System.Text;

namespace ARC074
{
    public class F
    {
        public class Edge
        {
            public int From;
            public int To;
            public int Weight;
        }
        public static void AddEdge(List<List<Edge>> graph, int from, int to, int w)
        {
            graph[from].Add(new Edge() { From = from, To = to, Weight = w, });
        }
        public static int Dinic(List<List<Edge>> graph, int s, int t)
        {
            int N = graph.Count();
            var cap = Enumerable.Repeat(0, N).Select(_ => new int[N]).ToArray();
            var flow = Enumerable.Repeat(0, N).Select(_ => new int[N]).ToArray();
            var level = new int[N];
            var finished = new bool[N];

            foreach (var u in graph) foreach (var e in u) cap[e.From][e.To] += e.Weight;

            Func<int, int, int> argument = null;
            argument = (u, cur) =>
            {
                if (u == t || cur == 0) { return cur; }
                if (finished[u]) { return 0; }
                finished[u] = true;

                foreach (var e in graph[u])
                {
                    if (level[e.To] <= level[u]) { continue; }
                    int f = argument(e.To, Math.Min(cur, cap[u][e.To] - flow[u][e.To]));
                    if (f <= 0) { continue; }

                    flow[u][e.To] += f;
                    flow[e.To][u] -= f;
                    finished[u] = false;
                    return f;
                }
                return 0;
            };

            int total = 0;
            while (true)
            {
                bool next = false;
                var queue = new Queue<int>();
                queue.Enqueue(s);

                Array.Clear(level, 0, level.Length);
                level[s] = 1;
                for (int d = N + 1; queue.Count > 0 && level[queue.Peek()] < d;)
                {
                    int u = queue.Dequeue();
                    if (u == t) { d = level[u]; }
                    foreach (var e in graph[u])
                    {
                        if (cap[u][e.To] - flow[u][e.To] <= 0 || level[e.To] > 0) { continue; }
                        level[e.To] = level[u] + 1;
                        queue.Enqueue(e.To);
                    }
                }

                Array.Clear(finished, 0, finished.Length);
                while (true)
                {
                    int f = argument(s, int.MaxValue);
                    if (f == 0) { break; }
                    total += f;
                    next = true;
                }
                if (!next) { break; }
            }
            return total;
        }

        private void Run()
        {
            var input = Console.ReadLine().Trim().Split();
            var H = int.Parse(input[0]);
            var W = int.Parse(input[1]);

            var field = Enumerable.Range(0, H)
                .Select(_ => Console.ReadLine().Trim().ToCharArray())
                .ToArray();
            var sy = Array.FindIndex(field, line => line.Contains('S'));
            var sx = Array.IndexOf(field[sy], 'S');
            var ty = Array.FindIndex(field, line => line.Contains('T'));
            var tx = Array.IndexOf(field[ty], 'T');
            const char LeafChar = 'o';
            field[sy][sx] = LeafChar;
            field[ty][tx] = LeafChar;

            var dict = new Dictionary<int, int>();
            Func<int, int, int> pointToIndex = (x, y) =>
            {
                var index = y * W + x;
                int value = 0;
                if (dict.TryGetValue(index, out value)) { return value; }

                int result = dict.Count;
                dict.Add(index, result);
                return result;
            };

            Func<int> solve = () =>
            {
                if (sx == tx || sy == ty) { return -1; }

                var vertexCount = field.SelectMany(line => line).Count(c => c == LeafChar) * 2;
                var graph = Enumerable.Range(0, vertexCount).Select(_ => new List<Edge>()).ToList();

                var capInf = H * W;

                for (int y1 = 0; y1 < H; ++y1)
                {
                    for (int x1 = 0; x1 < W; ++x1)
                    {
                        if (field[y1][x1] != LeafChar) { continue; }
                        var i1 = pointToIndex(x1, y1) * 2;

                        for (int y2 = y1 + 1; y2 < H; ++y2)
                        {
                            if (field[y2][x1] != LeafChar) { continue; }
                            var i2 = pointToIndex(x1, y2) * 2;
                            AddEdge(graph, i1, i2 + 1, capInf);
                            AddEdge(graph, i2, i1 + 1, capInf);
                        }
                        for (int x2 = x1 + 1; x2 < W; ++x2)
                        {
                            if (field[y1][x2] != LeafChar) { continue; }
                            var i2 = pointToIndex(x2, y1) * 2;
                            AddEdge(graph, i1, i2 + 1, capInf);
                            AddEdge(graph, i2, i1 + 1, capInf);
                        }
                    }
                }

                foreach (var i in dict.Values)
                {
                    AddEdge(graph, i, i + 1, 1);
                }

                return Dinic(graph, pointToIndex(sx, sy) * 2, pointToIndex(tx, ty) * 2 + 1);
            };
            Console.WriteLine(solve());
        }

        public static void Main()
        {
            var old = Console.Out;
            using (var writer = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Console.SetOut(writer);
                new F().Run();
                Console.Out.Flush();
                Console.SetOut(old);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class F
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var z = Read();
		int h = z[0], w = z[1];
		var a = new int[h].Select(_ => Console.ReadLine()).ToArray();

		int sv = h + w, ev = sv + 1;
		var s = (i: 0, j: 0);
		var t = (i: 0, j: 0);

		var dag = new List<long[]>();
		for (int i = 0; i < h; i++)
			for (int j = 0; j < w; j++)
				if (a[i][j] == 'o')
				{
					dag.Add(new[] { i, h + j, 1L });
					dag.Add(new[] { h + j, i, 1L });
				}
				else if (a[i][j] == 'S')
				{
					s = (i, j);
					dag.Add(new[] { sv, i, 1L << 60 });
					dag.Add(new[] { sv, h + j, 1L << 60 });
				}
				else if (a[i][j] == 'T')
				{
					t = (i, j);
					dag.Add(new[] { i, ev, 1L << 60 });
					dag.Add(new[] { h + j, ev, 1L << 60 });
				}

		Console.WriteLine(s.i == t.i || s.j == t.j ? -1 : MaxFlow(ev, sv, ev, dag.ToArray()));
	}

	static long MaxFlow(int n, int sv, int ev, long[][] dag)
	{
		var map = Array.ConvertAll(new int[n + 1], _ => new List<long[]>());
		foreach (var e in dag)
		{
			map[e[0]].Add(new[] { e[1], e[2], map[e[1]].Count });
			map[e[1]].Add(new[] { e[0], 0, map[e[0]].Count - 1 });
		}

		long Bfs()
		{
			var from = new long[n + 1][];
			var u = new bool[n + 1];
			var minFlow = Enumerable.Repeat(long.MaxValue, n + 1).ToArray();
			var q = new Queue<long>();
			q.Enqueue(sv);

			while (q.TryDequeue(out var v))
			{
				if (v == ev) break;
				foreach (var e in map[v])
				{
					if (u[e[0]] || e[1] == 0) continue;
					from[e[0]] = e;
					u[e[0]] = true;
					minFlow[e[0]] = Math.Min(minFlow[v], e[1]);
					q.Enqueue(e[0]);
				}
			}

			if (from[ev] == null) return 0;
			long tv = ev;
			while (true)
			{
				from[tv][1] -= minFlow[ev];
				var rev = map[from[tv][0]][(int)from[tv][2]];
				rev[1] += minFlow[ev];
				if ((tv = rev[0]) == sv) break;
			}
			return minFlow[ev];
		}

		long M = 0, t;
		while ((t = Bfs()) > 0) M += t;
		return M;
	}
}

