  AdjList [][]int16
}

func (G *Graph) FordFulkerson(s, t int) int16 {
  N := len((*G).Capacity)
  P := make([]int, N)
  for {
    for i := range P {
      P[i] = -1
    }
    P[s] = s
    Q := make([]int, 0)
    Q = append(Q, s)
    for 0 < len(Q) {
      q := Q[0]
      Q = Q[1:]
      for _, adj := range (*G).AdjList[q] {
        if 0 <= P[adj] || (*G).Capacity[q][adj] <= 0 { continue }
        P[adj] = q
        Q = append(Q, int(adj))
      }
    }
    if P[t] < 0 { break }
    Dst := t
    Src := P[t]
    C := (*G).Capacity[Src][Dst]
    for Src != s {
      Dst = Src
      Src = P[Src]
      C = MinInt((*G).Capacity[Src][Dst], C)
    }
    Dst = t
    Src = P[t]
    for Dst != s {
      (*G).Capacity[Src][Dst] -= C
      (*G).Capacity[Dst][Src] += C
      Dst = Src
      Src = P[Src]
    }
  }
  F := int16(0)
  for _, Cap := range (*G).Capacity {
    F += Cap[s]
  }
  return F
}

