func BFS(G *[][]int, V *[]int, s, t int) int {
  N := len((*V))
  D := make([]int, N)
  for i := range D {
    if 0 < (*V)[i] { D[i] = N }
  }
  D[s] = 1
  Q := make([]int, 0)
  Q = append(Q, s)
  for 0 < len(Q) {
    q := Q[0]
    Q = Q[1:]
    for _, adj := range (*G)[q] {
      if D[adj] < N { continue }
      D[adj] = D[q] + 1
      Q = append(Q, adj)
    }
  }
  if D[t] == N { return N }
  for v := t; v != s; {
    for _, adj := range (*G)[v] {
      if D[adj] == D[v] - 1 {
        v = adj
        if v != s { (*V)[v] = -1 }
        break
      }
    }
  }
  return D[t]
}

