            G[i * W + j] = append(G[i * W + j], i * W + k)
          }
        }
        for k := 0; k < i; k++ {
          if 0 < V[k * W + j] {
            G[k * W + j] = append(G[k * W + j], i * W + j)
            G[i * W + j] = append(G[i * W + j], k * W + j)
          }
        }
      }
    }
  }
  for _, adj := range G[s] {
    if adj == t {
      Write(-1)
      return
    }
  }
  cnt := 0
  for BFS(&G, &V, s, t) < H * W { cnt++ }
  Write(cnt)
  return
}

