type Edge struct {
  To int
  Capacity int
  Rev int
}
type Graph struct {
  V []int
  E [][]Edge
}
func InitGraph(N int) Graph {
  V := make([]int, N)
  E := make([][]Edge, N)
  for i := range E {
    E[i] = make([]Edge, 0)
  }
  return Graph{V, E}
}
func (G *Graph) AddEdge(From, To, Cap int) {
  (*G).E[From] = append((*G).E[From], Edge{To, Cap, len((*G).E[To])})
  (*G).E[To] = append((*G).E[To], Edge{From, 0, len((*G).E[From]) - 1})
}

func (G *Graph) FordFulkerson(s, t int) int {
  N := len((*G).E)
  P := make([][]int, N)
  Q := make([]int, 0)
  for {
    for i := range P {
      P[i] = []int{-1, -1}
    }
    P[s] = []int{s, -1}
    Q = append(Q, s)
    for 0 < len(Q) {
      q := Q[0]
      Q = Q[1:]
      for i, e := range (*G).E[q] {
        if 0 <= P[e.To][0] || e.Capacity <= 0 { continue }
        P[e.To] = []int{q, i}
        Q = append(Q, e.To)
      }
    }
    if P[t][0] < 0 { break }
    Dst := t
    Src := P[t][0]
    C := (*G).E[P[t][0]][P[t][1]].Capacity
    for Src != s {
      Dst = Src
      Src = P[Src][0]
      C = MinInt((*G).E[P[Dst][0]][P[Dst][1]].Capacity, C)
    }
    Dst = t
    Src = P[t][0]
    for Dst != s {
      e := (*G).E[P[Dst][0]][P[Dst][1]]
      (*G).E[P[Dst][0]][P[Dst][1]].Capacity -= C
      (*G).E[e.To][e.Rev].Capacity += C
      Dst = Src
      Src = P[Src][0]
    }
  }
  F := 0
  for _, e := range (*G).E[s] {
    F += (*G).E[e.To][e.Rev].Capacity
  }
  return F
}
func (G *Graph) DFS(L, S *[]int, s, t, f int) int {
  if s == t { return f }
  for _, e := range (*G).E[s][(*S)[s]:] {
    (*S)[s]++
    if e.Capacity < 1 || (*L)[e.To] <= (*L)[s] { continue }
    d := G.DFS(L, S, e.To, t, MinInt(e.Capacity, f))
    if 0 < d {
      (*G).E[s][(*S)[s] - 1].Capacity -= d
      (*G).E[e.To][e.Rev].Capacity += d
      return d
    }
  }
  return 0
}
func (G *Graph) Dinic(s, t int) int {
  N := len((*G).E)
  L := make([]int, N)
  Q := make([]int, 0)
  S := make([]int, N)
  F := 0
  for {
    for i := range L {
      L[i] = -1
    }
    L[s] = 0
    Q = append(Q, s)
    for 0 < len(Q) {
      q := Q[0]
      Q = Q[1:]
      for _, e := range (*G).E[q] {
        if 0 <= L[e.To] || e.Capacity <= 0 { continue }
        L[e.To] = L[q] + 1
        Q = append(Q, e.To)
      }
    }
    if L[t] < 0 { break }
    f := G.DFS(&L, &S, s, t, Inf)
    for 0 < f {
      F += f
      f = G.DFS(&L, &S, s, t, Inf)
    }
  }
  return F
}
const Inf = 16383

func Solve() {
  HW := NextIntVec()
  H, W := HW[0], HW[1]
  G := InitGraph(H * W + H + W)
  s, t := 0, 0
  for i := 0; i < H; i++ {
