int FordFulkerson(Edge[][] adj, int s, int t) {
    int n = adj.length.to!int;
    bool[] visited = new bool[](n);

    int dfs (int u, int f) {
        if (u == t) {
            debug {
                writef("%d ", t);
            }
            return f;
        }

        visited[u] = 1;

        foreach (ref e ; adj[u]) {
            if (e.cost > 0 && !visited[e.to]) {
                int d = dfs(e.to, min(f, e.cost));

                if (d > 0) {
                    e.cost -= d;
                    adj[e.to][e.rev].cost += d;

                    debug {
                        writef("%d ", u);
                    }

                    return d;
                }
            }
        }

        return 0;
    }

    int F;

    while (true) {
        visited[] = 0;

        int f = dfs(s, inf);

        debug {
            writeln("flow: ", f);
        }

        if (f == 0) break;

        F += f;
    }

    return F;
}

