    g[t.idup][(t ~ 0).idup] = 0;
    g[t.idup][(t ~ 1).idup] = 0;

    long dfs(const Node n, const Node m, ref bool[Node] used, long maxFlow) {
        if(n == m) {
            return maxFlow;
        }

        if(n in used) {
            return 0;
        }
        used[n] = true;
        foreach(l, ref c; g[n]) {
            if(c == 0) {
                continue;
            }
            long flow = dfs(l, m, used, min(maxFlow, c));
            if(flow > 0) {
                c -= flow;
                g[l][n] += flow;
                return flow;
            }
        }
        return 0;
    }

