    let n = g.len()
    for u in 0..<n:
      if g[v][u] <= 0 or visited[u]:
        continue

      let ret = dfs(g, u, t, min(f, g[v][u]), visited)
      if ret > 0:
        g[v][u] -= ret
        g[u][v] += ret
        return ret

    visited[v] = false

    return 0

  let n = g.len()
  var g = g

  result = 0
  var visited = newSeq[bool](n)

  while true:
    visited.fill(false)
    let flow = dfs(g, s, t, 1e9.int(), visited)
    if flow == 0:
      break
    result += flow

