def dfs2(start, finish, graph):
    Flow = [-1]*len(graph)
    used = [False]*len(graph)
    Flow[start] = INF
    Par = [None]*len(graph)
    stack = [start]
    while stack:
        v = stack.pop()
        if v == finish:
            d = Flow[v]
            while v != start:
                nv, i, nrev = Par[v]
                graph[nv][i][1] -= d
                graph[v][nrev][1] += d
                v = nv
            return d
        used[v] = True
        for i, (nv, ncap, nrev) in enumerate(graph[v]):
            if not used[nv] and ncap > 0:
                stack.append(nv)
                Par[nv] = (v, i, nrev)
                Flow[nv] = min(Flow[v], ncap)
    return 0


