INF = 10**18

H, W = map(int, input().split())
V = H*W

def make():
    state = [list(input().rstrip()) for _ in range(H)]
    graph = [[] for _ in range(2*V)]

    start = -1
    finish = -1

    for h in range(H):
        Node = []
        for w in range(W):
            if state[h][w] != ".":
                Node.append(h*W+w)
            if state[h][w] == "S":
                start = h*W + w
            if state[h][w] == "T":
                finish = h*W + w
        L = len(Node)
        for i in range(L):
            v = Node[i]
            for j in range(i+1, L):
                u = Node[j]
                graph[u].append([v, 1, len(graph[v])])
                graph[v].append([u, 1, len(graph[u])-1])


    for w in range(W):
        Node = []
        for h in range(H):
            if state[h][w] != ".":
                Node.append(h*W+w)
        L = len(Node)
        for i in range(L):
            v = Node[i]
            if v not in {start, finish}: v += V
            for j in range(i+1, L):
                u = Node[j]
                if u not in {start, finish}: u += V
                graph[u].append([v, 1, len(graph[v])])
                graph[v].append([u, 1, len(graph[u])-1])

    for i in range(V):
        if i != start and i != finish:
            u, v = i, i+V
            graph[u].append([v, 1, len(graph[v])])
            graph[v].append([u, 1, len(graph[u])-1])

    return graph, start, finish


used = [False]*V




def dfs2(start, finish, graph):
    Flow = [-1]*len(graph)
    Flow[start] = INF
    Par = [-1]*len(graph)
    stack = [start]
    while stack:
        v = stack.pop()
        if v == finish:
            d = Flow[v]
            while v != start:
                nv, i, nrev = Par[v]
                graph[nv][i][1] -= d
                graph[v][nrev][1] += d
                v = nv
            return d
        used[v] = True
        for i, (nv, ncap, nrev) in enumerate(graph[v]):
            if not used[nv] and ncap > 0:
                stack.append(nv)
                Par[nv] = (v, i, nrev)
                Flow[nv] = min(Flow[v], ncap)
    return 0


# solve
def max_flow(start, finish, graph):
    flow = 0
    while True:
        global used
        used = [False]*len(graph)
        f = dfs2(start, finish, graph)
        if f == 0: return flow
        flow += f


def main():
    graph, start, finish = make()
    ans = max_flow(start, finish, graph)

    if start//W == finish//W or start%W == finish%W:
        print(-1)
    else:
        print(ans)


if __name__ == "__main__":
    main()

