    # row = 0, ..., m - 1, col = m, ..., m + n - 1, source = m + n, terminartion = m + n + 1
    G = nx.Graph()
    G.add_nodes_from(range(m + n + 2))
    grid = [input() for _ in range(m)]
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 'S':
                si, sj = i, j
            elif grid[i][j] == 'T':
                ti, tj = i, j

    G.add_edge(m + n, si, capacity = INF)
    G.add_edge(m + n, m + sj, capacity = INF)
    G.add_edge(ti, m + n + 1, capacity = INF)
    G.add_edge(m + tj, m + n + 1, capacity = INF)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '.':
                continue
            for nj in range(n):
                if grid[i][nj] != '.':
                    G.add_edge(i, m + nj, capacity = 1)
            for ni in range(m):
                if grid[ni][j] != '.':
                    G.add_edge(ni, m + j, capacity = 1)

    ans = nx.algorithms.flow.maximum_flow_value(G, m + n, m + n + 1)
    if ans >= INF:
        ans = -1
    print(ans)
