                    dinitz.add_edge(source, h + j, INF);
                }
                'T' => {
                    dinitz.add_edge(i, sink, INF);
                    dinitz.add_edge(h + j, sink, INF);
                }
                'o' => {
                    dinitz.add_edge(i, h + j, 1);
                    dinitz.add_edge(h + j, i, 1);
                }
                _ => {}
