const M: usize = std::usize::MAX / 2;

fn dfs(g: &Vec<Vec<usize>>, s: usize, t: usize, parents: &mut Vec<usize>) -> bool {
    let n = g.len();
    let mut stack = vec![s];
    let mut seen = vec![false; n];
    seen[s] = true;
    while let Some(u) = stack.pop() {
        if u == t {
            return true;
        }
        for v in 0..n {
            if !seen[v] && g[u][v] > 0 {
                parents[v] = u;
                seen[v] = true;
                stack.push(v)
            }
        }
    }
    false
}

fn calc_max_flow(g: &Vec<Vec<usize>>, s: usize, t: usize) -> usize {
    let n = g.len();
    let mut rg = g.clone();
    let mut ret = 0;
    let mut parents = vec![0; n];
    while dfs(&rg, s, t, &mut parents) {
        let mut v = t;
        let mut d = std::usize::MAX;
        while v != s {
            let u = parents[v];
            d = min(d, rg[u][v]);
            v = u
        }
        ret += d;
        let mut v = t;
        while v != s {
            let u = parents[v];
            rg[u][v] -= d;
            rg[v][u] += d;
            v = u
        }
    }
    ret
}

