        for (j, c) in line.chars().enumerate() {
            let gi = i + 1;
            let gj = j + 1 + w;
            match c {
                'o' => {
                    g[gi][gj] += 1;
                    g[gj][gi] += 1
                }
                'S' => {
                    g[0][gi] = M;
                    g[0][gj] = M;
                    g[gi][0] = M;
                    g[gj][0] = M
                }
                'T' => {
                    g[gi][n - 1] = M;
                    g[gj][n - 1] = M;
                    g[n - 1][gi] = M;
                    g[n - 1][gj] = M;
                }
                _ => (),
            }
        }
    }
    let ret = calc_max_flow(&g, 0, n - 1);
    if ret == M {
        println!("{}", -1);
    } else {
