    solver.add_edge_both(goal_x, h + w + 1, inf);
    solver.add_edge_both(w + goal_y, h + w + 1, inf);

    for y in 0..h {
        for x in 0..w {
            if grid[y][x] == 'o' {
                solver.add_edge_both(x, w + y, 1);
            }
        }
    }

    let ans = solver.max_flow(h + w, h + w + 1);
    if ans >= inf {
        println!("-1");
        return;
    }
    println!("{:?}", ans);
}

