const MOD: u32 = 1_000_000_007;
const INF: i64 = std::i64::MAX/3;

#[derive(Copy,Clone)]
struct Edge {
	to: usize,
	cap: i64,
	rev: usize,
}

struct Dinic {
	edge: Vec<Vec<Edge>>,
	level: Vec<i64>,
	iter: Vec<usize>,
	n: usize,
}

impl Dinic {
	pub fn new(n: usize) -> Self {
		Dinic {
			edge: vec![vec![];n],
			level: vec![-1;n],
			iter: vec![0;n],
			n: n,
		}
	}

	pub fn push(&mut self, s: usize, t: usize, c: i64) {
		let mut tmp = self.edge[t].len();
		self.edge[s].push(Edge{to: t, cap: c, rev: tmp});
		let mut tmp = self.edge[s].len();
		self.edge[t].push(Edge{to: s, cap: 0, rev: tmp-1});
	}

	pub fn bfs(&mut self, s: usize) {
		self.level = vec![-1;self.n];
		self.level[s] = 0;
		let mut q = VecDeque::new();
		q.push_back(s);
		while let Some(cur) = q.pop_front() {
			for &e in &self.edge[cur] {
				if e.cap > 0 && self.level[e.to] < 0 {
					self.level[e.to] = self.level[cur] + 1;
					q.push_back(e.to);
				}
			}
		}
	} 

	pub fn dfs(&mut self, v: usize, t: usize, val: i64) -> i64{
		if v==t {
			return val;
		}
		for i in self.iter[v]..self.edge[v].len() {
			let e = self.edge[v][i];
			if e.cap > 0 && self.level[v] < self.level[e.to] {
				let d = self.dfs(e.to,t,min(val,e.cap));
				if d > 0 {
					self.edge[v][i].cap -= d;
					self.edge[e.to][e.rev].cap += d;
					return d;
				}
			}
			self.iter[v] += 1;
		}
		return 0;
	}

	pub fn calc(&mut self, s: usize, t: usize) -> i64{
		let mut flow = 0;
		loop {
			self.bfs(s);
			if self.level[t] < 0 {
				return flow;
			}
			self.iter = vec![0;self.n];
			let mut f = 0;
			loop {
				let ret = self.dfs(s,t,INF);
				if ret == 0 {
					break;
				}
				f += ret;
			}
			flow += f;
		}
	}

}

fn solve() {
	let (h,w) = read!(usize,usize);
	let a = read!(String;h);
	let mut board = vec![vec![' ';w];h];
	for i in 0..h {
		for (j,c) in a[i].chars().enumerate() {
			board[i][j] = c;
		}
	}
	let mut s = 0;
	let mut t = 0;
	let mut dinic = Dinic::new(5*(h*w+1));
	let mut count = 0;
	for i in 0..h {
		for j in 0..w {
			let id = calc_id(i,j,h,w);
			let mut val = 1;
			if board[i][j]=='.' {
				continue;
			}
			count += 1;
			if board[i][j]=='S' {
				s = id;
				val = INF;
			}
			if board[i][j]=='T' {
				t = id;
				val = INF;
			}
			for k in 1..5 {
				dinic.push(id,id+k,val);
				dinic.push(id+k,id,val);
			}
			for x in i+1..h {
				if board[x][j]=='.' {
					continue;
				}
				dinic.push(id+3,calc_id(x,j,h,w)+1,1);
				dinic.push(calc_id(x,j,h,w)+1,id+3,1);
			}
			for y in j+1..w {
				if board[i][y]=='.' {
					continue;
				}
				dinic.push(id+2,calc_id(i,y,h,w)+4,1);
				dinic.push(calc_id(i,y,h,w)+4,id+2,1);
			}
		}
	}
	let mut val = dinic.calc(s,t);
	if val>count-2 {
		println!("-1");
	}
	else{
		println!("{}",val);
	}
}

fn calc_id(x: usize, y: usize, h: usize, w: usize) -> usize {
	(x*w + y + 1)*5
}

fn run() {
    solve();
}

