fn dfs(
    g: &Vec<Vec<usize>>,
    u: usize,
    t: usize,
    parents: &mut Vec<usize>,
    seen: &mut Vec<bool>,
) -> bool {
    let n = g.len();
    if u == t {
        return true;
    }
    for v in 0..n {
        if !seen[v] && g[u][v] > 0 {
            seen[v] = true;
            if dfs(g, v, t, parents, seen) {
                parents[v] = u;
                return true;
            }
        }
    }
    false
}

fn calc_max_flow(g: &Vec<Vec<usize>>, s: usize, t: usize) -> usize {
    let n = g.len();
    let mut rg = g.clone();
    let mut ret = 0;
    let mut parents = vec![0; n];
    let mut seen = vec![false; n];
    while dfs(&rg, s, t, &mut parents, &mut seen) {
        let mut v = t;
        let mut d = std::usize::MAX;
        while v != s {
            let u = parents[v];
            d = min(d, rg[u][v]);
            v = u
        }
        ret += d;
        let mut v = t;
        while v != s {
            let u = parents[v];
            rg[u][v] -= d;
            rg[v][u] += d;
            v = u
        }
        seen = vec![false; n];
    }
    ret
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut it = s.split_whitespace();
    let (h, w): (usize, usize) = parse!(it, 2);
    let n = h + w + 2;
    let mut g = vec![vec![0; n]; n];
    for i in 0..h {
        let line = it.next().unwrap();
        for (j, c) in line.chars().enumerate() {
            let gi = i + 1;
            let gj = j + 1 + w;
            match c {
                'o' => {
                    g[gi][gj] += 1;
                    g[gj][gi] += 1
                }
                'S' => {
                    g[0][gi] = M;
                    g[0][gj] = M;
                    g[gi][0] = M;
                    g[gj][0] = M
                }
                'T' => {
                    g[gi][n - 1] = M;
                    g[gj][n - 1] = M;
                    g[n - 1][gi] = M;
                    g[n - 1][gj] = M;
                }
                _ => (),
            }
        }
    }
    let ret = calc_max_flow(&g, 0, n - 1);
    if ret == M {
        println!("{}", -1);
    } else {
        println!("{}", ret);
    }
}

#![allow(non_snake_case)]
#![allow(unused_variables)]
#![allow(dead_code)]

fn main() {
    let (H, W): (usize, usize) = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        let mut iter = line.split_whitespace();
        (
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
        )
    };
    let a: Vec<Vec<char>> = (0..H)
        .map(|_| {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().chars().collect()
        })
        .collect();

    const INF: i64 = 1e15 as i64;
    let N = 2 * H * W + H + W;
    let mut M = 0;
    let mut A = vec![];
    let mut B = vec![];
    let mut C = vec![];
    let s = H * W + (0..(H * W)).find(|&k| a[k / W][k % W] == 'S').unwrap();
    let t = (0..(H * W)).find(|&k| a[k / W][k % W] == 'T').unwrap();
    for i in 0..H {
        for j in 0..W {
            if a[i][j] == 'o' || a[i][j] == 'S' || a[i][j] == 'T' {
                A.push(W * i + j);
                B.push(H * W + W * i + j);
                C.push(1);

                A.push(H * W + W * i + j);
                B.push(2 * H * W + i);
                C.push(INF);

                A.push(H * W + W * i + j);
                B.push(2 * H * W + H + j);
                C.push(INF);

                A.push(2 * H * W + i);
                B.push(W * i + j);
                C.push(INF);

                A.push(2 * H * W + H + j);
                B.push(W * i + j);
                C.push(INF);

                M += 5;
            }
        }
    }

    fn dfs(
        i: usize,
        t: usize,
        f: i64,
        G: &mut Vec<Vec<(usize, i64, usize)>>,
        next_edge: &mut Vec<usize>,
        level: &Vec<usize>,
    ) -> Option<i64> {
        if i == t {
            Some(f)
        } else {
            for k in next_edge[i]..G[i].len() {
                let (j, c, l) = G[i][k];
                if c > 0 && level[i] < level[j] {
                    if let Some(d) = dfs(j, t, std::cmp::min(f, c), G, next_edge, level) {
                        G[i][k] = (j, c - d, l);
                        let (_, w, _) = G[j][l];
                        G[j][l] = (i, w + d, k);
                        next_edge[i] = k;
                        return Some(d);
                    }
                }
            }
            next_edge[i] = G[i].len();
            None
        }
    }

    let flow = |s, t| {
        let mut G = vec![vec![]; N + 1];
        for i in 0..M {
            let k = G[B[i]].len();
            let l = G[A[i]].len();
            G[A[i]].push((B[i], C[i], k));
            G[B[i]].push((A[i], 0, l));
        }
        let mut res = 0;
        loop {
            let mut level = vec![0; N + 1];
            let mut q = std::collections::VecDeque::new();
            level[s] = 1;
            q.push_back(s);
            while let Some(i) = q.pop_front() {
                for &(j, c, _) in &G[i] {
                    if c > 0 && level[j] == 0 {
                        level[j] = level[i] + 1;
                        q.push_back(j);
                    }
                }
            }
            if level[t] == 0 {
                break;
            }
            let mut next_edge = vec![0; N + 1];
            while let Some(f) = dfs(s, t, INF, &mut G, &mut next_edge, &level) {
                res += f;
            }
        }
        res
    };

    let res = flow(s, t);
    let ans = if res < INF { res } else { -1 };

    println!("{}", ans);
}
